const $ = (id) => document.getElementById(id);
// Tope de filas en Chat / Regalos / Eventos. Más allá se borran las más viejas (FIFO)
// para no hinchar el DOM ni la RAM en lives largos. No afecta spawns ni lógica del live.
const MAX_ROWS = 50;
// App de escritorio (.exe): preload de Electron + sello que inyecta el servidor local (DESKTOP=1).
function detectDesktopPanel() {
  if (window.desktopAPI?.isDesktop) return true;
  if (window.__LIVECOINS_DESKTOP__ || window.__LIVECOINS_PC_BUILD__) return true;
  if (document.querySelector('meta[name="livecoins-app"][content="desktop"]')) return true;
  // El .exe siempre sirve el panel desde 127.0.0.1; la versión web usa el dominio remoto.
  if (/^127\.|^localhost$/i.test(location.hostname || '')) return true;
  return false;
}
let IS_DESKTOP = detectDesktopPanel();
const IS_LOCALHOST = /^127\.|^localhost$/i.test(location.hostname || '');
/** Cache-bust arte de insignias (mismo valor que badges.js BADGE_IMG_VER). */
const BADGE_IMG_VER = '20260728a';
function badgeArtUrl(id) {
  const clean = String(id || '').replace(/[^\w-]/g, '');
  return clean ? `/img/badges/${clean}.png?v=${BADGE_IMG_VER}` : '';
}

function syncDesktopPanelMode() {
  IS_DESKTOP = detectDesktopPanel();
  if (IS_DESKTOP) {
    document.documentElement.classList.add('is-desktop');
    const btn = document.getElementById('pc-install-btn');
    if (btn) btn.hidden = true;
    const navAcc = document.getElementById('navAcciones');
    if (navAcc) navAcc.style.display = '';
    try { revealJuegosTab(); } catch {}
    try { revealWebhookTab(); } catch {}
    try { revealConfigTab(); } catch {}
    try { syncNavSections(); } catch {}
  }
}

async function confirmDesktopPanelFromServer() {
  if (!IS_LOCALHOST) return;
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      const r = await fetch('/api/desktop-build');
      if (r.ok) {
        const d = await r.json();
        if (d && d.pc) {
          window.__LIVECOINS_DESKTOP__ = true;
          if (d.version) window.INSTALLED_APP_VERSION = String(d.version).trim();
          syncDesktopPanelMode();
          try { setupAccionesUI(); } catch {}
          try { setupProfiles(); } catch {}
          try { setupEmoteFetchDock(); } catch {}
          try { setupTikTokAccountBtn(); } catch {}
          try { setupJuegosUI(); } catch {}
          try { setupWebhookUI(); } catch {}
          return;
        }
      }
    } catch {}
    await new Promise((r) => setTimeout(r, 400));
  }
}
function isPcBuildMarkup() {
  return !!(window.__LIVECOINS_PC_BUILD__ || document.querySelector('meta[name="livecoins-app"][content="desktop"]'));
}
function setupPanelModeWarning() {
  if (document.getElementById('panel-mode-banner')) return;
  if (IS_DESKTOP) return;
  const brokenLocal = isPcBuildMarkup() || IS_LOCALHOST;
  if (!brokenLocal) return;
  const banner = document.createElement('div');
  banner.id = 'panel-mode-banner';
  banner.style.cssText = 'margin:0 14px 10px;padding:10px 12px;border-radius:10px;font:600 11.5px/1.45 system-ui;color:#ffe8f0;background:linear-gradient(135deg,rgba(255,43,214,.22),rgba(255,80,120,.12));border:1px solid rgba(255,43,214,.45)';
  banner.innerHTML = '<b>App PC sin módulo de escritorio.</b><br>Cierra Livecoins por completo y ábrelo otra vez desde el menú Inicio. Si sigue igual, reinstala el .exe más reciente.';
  const side = document.querySelector('.sidebar');
  const nav = side?.querySelector('.nav');
  if (nav) side.insertBefore(banner, nav);
  else document.body.prepend(banner);
}

let ws;
let reconnectTimer;
let settings = null;       // copia local de los ajustes del servidor
let applyingSettings = false; // evita loops al rellenar los controles
let lastGameActionEditAt = 0;
let lastSoundAlertEditAt = 0;
const SOUND_ALERT_EDIT_ECHO_MS = 8000;
let lastSlotMediaEditAt = 0;
let _saveAfterSettingsApply = null; // 'full' | 'patch' | null — no tirar guardados durante el eco
let lastMediaVolEditAt = 0;
let lastTtsSliderEditAt = 0;
let ttsSliderDrag = false;
const MEDIA_VOL_ECHO_MS = 8000;
const mediaVolPending = new Map();
const cardVolDragActive = new Set();
const mediaListRenderDeferred = { soundAlerts: false, videos: false, battleAlerts: false };

function mediaVolPendingKey(listKey, id) {
  return `${listKey}:${String(id || '')}`;
}
function noteMediaVolEdit(listKey, id, volume) {
  if (!listKey || id == null || id === '') return;
  mediaVolPending.set(mediaVolPendingKey(listKey, id), { volume, at: Date.now() });
  lastMediaVolEditAt = Date.now();
}
function mediaVolRecent() {
  return Date.now() - lastMediaVolEditAt < 2500;
}
function setListItemVolume(listKey, id, n) {
  const vol = Math.max(0, Math.min(100, Number(n) || 0));
  if (listKey === 'screens') {
    const sid = String(id || '').replace(/^scr-/, '');
    const item = (settings.screens || []).find((x) => String(x.id) === sid);
    if (item) item.volume = vol;
  } else if (listKey === 'levelVideos') {
    if (!settings.levelVideos) settings.levelVideos = { enabled: false, screen: 1, volume: 100 };
    settings.levelVideos.volume = vol;
  } else {
    const item = Array.isArray(settings[listKey])
      ? settings[listKey].find((x) => String(x.id) === String(id))
      : null;
    if (item) item.volume = vol;
  }
  noteMediaVolEdit(listKey, id, vol);
  return vol;
}
function applyPendingMediaVolumes(listKey) {
  if (!settings || !listKey) return;
  const now = Date.now();
  if (listKey === 'screens' && Array.isArray(settings.screens)) {
    settings.screens.forEach((s) => {
      const pend = mediaVolPending.get(mediaVolPendingKey('screens', 'scr-' + s.id));
      if (pend && now - pend.at < MEDIA_VOL_ECHO_MS) s.volume = pend.volume;
    });
    return;
  }
  if (listKey === 'levelVideos' && settings.levelVideos) {
    const pend = mediaVolPending.get(mediaVolPendingKey('levelVideos', 'levelvid'));
    if (pend && now - pend.at < MEDIA_VOL_ECHO_MS) settings.levelVideos.volume = pend.volume;
    return;
  }
  const list = settings[listKey];
  if (!Array.isArray(list)) return;
  list.forEach((item) => {
    if (!item || item.id == null) return;
    const pend = mediaVolPending.get(mediaVolPendingKey(listKey, item.id));
    if (pend && now - pend.at < MEDIA_VOL_ECHO_MS) item.volume = pend.volume;
  });
}
function flushDeferredMediaListRenders() {
  if (cardVolDragActive.size) return;
  if (mediaListRenderDeferred.soundAlerts) {
    mediaListRenderDeferred.soundAlerts = false;
    try { refreshSoundAlertsFromSettings(); } catch { /* ignore */ }
  }
  if (mediaListRenderDeferred.videos) {
    mediaListRenderDeferred.videos = false;
    try { refreshVideosFromSettings(); } catch { /* ignore */ }
  }
  if (mediaListRenderDeferred.battleAlerts) {
    mediaListRenderDeferred.battleAlerts = false;
    try { refreshBattleAlertsFromSettings(); } catch { /* ignore */ }
  }
}
function saveMediaVolumePatch(listKey) {
  applyPendingMediaVolumes(listKey);
  saveSettingsKeysPatch(listKey, { flush: true });
}
function syncMediaCardVolumesInPlace(container, list, opts = {}) {
  if (!container || !Array.isArray(list)) return false;
  const cardSel = opts.cardSel || '.sa-card';
  const volSel = opts.volSel || '.sa-volrange';
  const cards = [...container.querySelectorAll(cardSel)];
  if (!cards.length) return false;
  const ids = new Set(list.map((a) => String(a?.id)));
  if (cards.every((c) => !ids.has(String(c.dataset.id || '')))) return false;
  cards.forEach((card) => {
    const id = String(card.dataset.id || '');
    if (cardVolDragActive.has(id) || mediaVolRecent()) {
      const pend = mediaVolPending.get(mediaVolPendingKey(opts.listKey || '', id));
      if (pend) {
        const vr = card.querySelector(volSel);
        const pct = card.querySelector('.pct');
        if (vr) vr.value = String(pend.volume);
        if (pct) pct.textContent = `${pend.volume}%`;
      }
      return;
    }
    const item = list.find((x) => String(x.id) === id);
    if (!item) return;
    const v = Math.max(0, Math.min(100, Number(item.volume ?? 100)));
    const vr = card.querySelector(volSel);
    const pct = card.querySelector('.pct');
    if (vr) vr.value = String(v);
    if (pct) pct.textContent = `${v}%`;
    if (opts.syncEnabled) {
      const tog = card.querySelector(opts.toggleSel || '.sa-toggle');
      if (tog) tog.checked = item.enabled !== false;
      const st = card.querySelector('.toggle .state');
      if (st) st.textContent = item.enabled !== false ? 'ON' : 'OFF';
      card.classList.toggle('on', item.enabled !== false);
    }
  });
  return true;
}
function refreshSoundAlertsFromSettings() {
  if (cardVolDragActive.size || mediaVolRecent()) {
    mediaListRenderDeferred.soundAlerts = true;
    syncMediaCardVolumesInPlace($('saList'), settings.soundAlerts || [], { syncEnabled: true, listKey: 'soundAlerts' });
    return;
  }
  const el = $('saList');
  if (!el) return;
  const list = settings.soundAlerts || [];
  if (!list.length || !el.querySelector('.sa-card')) { renderSoundAlerts(); return; }
  if (!syncMediaCardVolumesInPlace(el, list, { syncEnabled: true, listKey: 'soundAlerts' })) renderSoundAlerts();
}
function refreshVideosFromSettings() {
  if (cardVolDragActive.size || mediaVolRecent()) {
    mediaListRenderDeferred.videos = true;
    syncMediaCardVolumesInPlace($('videoCards'), settings.videos || [], { cardSel: '.vid-card', volSel: '.v-volrange', toggleSel: '.v-toggle', syncEnabled: true, listKey: 'videos' });
    return;
  }
  const el = $('videoCards');
  if (!el) return;
  const list = settings.videos || [];
  if (!list.length || !el.querySelector('.vid-card')) { renderVideos(); return; }
  if (!syncMediaCardVolumesInPlace(el, list, { cardSel: '.vid-card', volSel: '.v-volrange', toggleSel: '.v-toggle', syncEnabled: true, listKey: 'videos' })) renderVideos();
}
function refreshBattleAlertsFromSettings() {
  if (cardVolDragActive.size || mediaVolRecent()) {
    mediaListRenderDeferred.battleAlerts = true;
    syncMediaCardVolumesInPlace($('battleCards'), settings.battleAlerts || [], { cardSel: '.vid-card', volSel: '.b-volrange', toggleSel: '.b-toggle', syncEnabled: true, listKey: 'battleAlerts' });
    return;
  }
  const el = $('battleCards');
  if (!el) return;
  const list = settings.battleAlerts || [];
  if (!list.length || !el.querySelector('.vid-card')) { renderBattleAlerts(); return; }
  if (!syncMediaCardVolumesInPlace(el, list, { cardSel: '.vid-card', volSel: '.b-volrange', toggleSel: '.b-toggle', syncEnabled: true, listKey: 'battleAlerts' })) renderBattleAlerts();
}

function lcVolume01(raw) {
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return 1;
  const lin = n > 1 ? Math.min(1, n / 100) : Math.min(1, n);
  return lin * lin;
}
function applyMediaVolume(el, raw) {
  if (!el) return;
  const v = lcVolume01(raw);
  const set = () => {
    try { el.volume = v; el.muted = v <= 0; } catch { /* ignore */ }
  };
  set();
  el.addEventListener('loadedmetadata', set);
  el.addEventListener('canplay', set);
  el.addEventListener('playing', set);
}
function bindCardVolumeSlider(vr, card, listKey, onVolume, onSave) {
  if (!vr || vr.dataset.volBound === '1') return;
  vr.dataset.volBound = '1';
  const itemId = String(card.dataset?.id || '');
  const dragId = itemId || `vol-${Math.random().toString(36).slice(2)}`;
  let committed = false;
  let winUpHandler = null;
  const readN = () => Math.max(0, Math.min(100, +vr.value || 0));
  const syncPct = (n) => {
    const pct = card.querySelector('.pct');
    if (pct) pct.textContent = `${n}%`;
  };
  const applyLocal = () => {
    const n = readN();
    syncPct(n);
    setListItemVolume(listKey, itemId, n);
    onVolume(n);
    try { if (previewAudio && !previewAudio.paused) applyMediaVolume(previewAudio, n); } catch { /* ignore */ }
  };
  const commitSave = () => {
    if (committed) return;
    committed = true;
    const n = readN();
    syncPct(n);
    setListItemVolume(listKey, itemId, n);
    onVolume(n);
    onSave?.();
  };
  const clearWinUp = () => {
    if (!winUpHandler) return;
    window.removeEventListener('pointerup', winUpHandler, true);
    winUpHandler = null;
  };
  const finishDrag = (save) => {
    if (!cardVolDragActive.has(dragId)) return;
    cardVolDragActive.delete(dragId);
    clearWinUp();
    if (save && !committed) commitSave();
    flushDeferredMediaListRenders();
  };
  vr.addEventListener('pointerdown', (e) => {
    cardVolDragActive.add(dragId);
    committed = false;
    setListItemVolume(listKey, itemId, readN());
    clearWinUp();
    try { vr.setPointerCapture(e.pointerId); } catch { /* ignore */ }
    winUpHandler = () => finishDrag(true);
    window.addEventListener('pointerup', winUpHandler, true);
  });
  vr.addEventListener('lostpointercapture', () => finishDrag(true));
  vr.addEventListener('input', applyLocal);
  vr.addEventListener('change', () => {
    if (cardVolDragActive.has(dragId)) finishDrag(true);
    else commitSave();
  });
}
function preserveLocalMediaVolumeOnSettingsEcho(incoming) {
  if (applyingProfileSwitch) return incoming;
  if (!incoming || !settings) return incoming;
  const out = { ...incoming };
  const now = Date.now();
  for (const key of ['soundAlerts', 'videos', 'battleAlerts']) {
    const remote = incoming[key];
    if (!Array.isArray(remote)) continue;
    out[key] = remote.map((a) => {
      if (!a?.id) return a;
      const pend = mediaVolPending.get(mediaVolPendingKey(key, a.id));
      if (pend && now - pend.at < MEDIA_VOL_ECHO_MS) return { ...a, volume: pend.volume };
      return a;
    });
  }
  if (now - lastMediaVolEditAt < MEDIA_VOL_ECHO_MS) {
    for (const key of ['soundAlerts', 'videos', 'battleAlerts']) {
      const local = settings[key];
      const remote = out[key];
      if (!Array.isArray(local) || !Array.isArray(remote)) continue;
      const volById = new Map(local.map((a) => [String(a?.id), a?.volume]));
      out[key] = remote.map((a) => {
        if (!a) return a;
        const v = volById.get(String(a.id));
        return v == null ? a : { ...a, volume: v };
      });
    }
    if (incoming.levelVideos && settings.levelVideos) {
      const pendLv = mediaVolPending.get(mediaVolPendingKey('levelVideos', 'levelvid'));
      const vol = pendLv && now - pendLv.at < MEDIA_VOL_ECHO_MS
        ? pendLv.volume
        : settings.levelVideos.volume;
      if (vol != null) out.levelVideos = { ...incoming.levelVideos, volume: vol };
    }
    if (Array.isArray(incoming.screens) && Array.isArray(settings.screens)) {
      out.screens = incoming.screens.map((s) => {
        if (!s) return s;
        const pend = mediaVolPending.get(mediaVolPendingKey('screens', 'scr-' + s.id));
        const local = settings.screens.find((x) => Number(x.id) === Number(s.id));
        const vol = pend && now - pend.at < MEDIA_VOL_ECHO_MS ? pend.volume : local?.volume;
        return vol == null ? s : { ...s, volume: vol };
      });
    }
  }
  if (incoming.tts && settings.tts && now - lastTtsSliderEditAt < MEDIA_VOL_ECHO_MS) {
    out.tts = {
      ...incoming.tts,
      volume: settings.tts.volume,
      rate: settings.tts.rate,
      pitch: settings.tts.pitch,
    };
  }
  return out;
}

/* ====================== WebSocket ====================== */
let localWs, localReconnectTimer;

async function postLocalMedia(action, body = {}) {
  try {
    await fetch('/api/desktop/local-media', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, ...body }),
    });
  } catch {}
}

function connectLocalWS() {
  if (!relayActive()) {
    if (localWs) { try { localWs.close(); } catch {} localWs = null; }
    return;
  }
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  let url = `${proto}://${location.host}/ws`;
  const k = window.ROOM_KEY || '';
  if (k) url += `?room=${encodeURIComponent(k)}`;
  if (localWs) {
    if (wsUrlsMatch(localWs.url, url) && (localWs.readyState === WebSocket.OPEN || localWs.readyState === WebSocket.CONNECTING)) return;
    try { localWs.close(); } catch {}
    localWs = null;
  }
  const sock = new WebSocket(url);
  localWs = sock;
  sock.onclose = () => {
    if (localWs !== sock) return;
    clearTimeout(localReconnectTimer);
    localReconnectTimer = setTimeout(connectLocalWS, 1500);
  };
  sock.onopen = () => {
    if (localWs !== sock) return;
    clearTimeout(localReconnectTimer);
    buildKeepAliveWorker();
  };
  sock.onmessage = (ev) => {
    if (localWs !== sock) return;
    let msg;
    try { msg = JSON.parse(ev.data); } catch { return; }
    if (msg.type === 'screens') {
      onScreens(msg.payload);
      refreshLevelVideoScreenLink();
    } else if (msg.type === 'sound') {
      // Stream Deck / webhook :3199 emiten en la room local; el panel en relay
      // está en la nube y solo oye estos sonidos por este WS local.
      playPanelSound(msg.payload);
    } else if (msg.type === 'stopSound') {
      stopPanelSoundById(msg.payload?.id);
    } else if (msg.type === 'log' && msg.payload) {
      const p = msg.payload;
      if (p.text) addEvent(p.text, p.level || 'info');
    }
  };
}
// Mantiene la conexión SIEMPRE viva, incluso con la pestaña minimizada o en segundo
// plano. Los navegadores ralentizan setTimeout/setInterval en pestañas ocultas, así que
// usamos un Web Worker (no se ralentiza) como "latido" para reconectar al instante si la
// conexión se cae, y reconectamos también al volver a la pestaña o recuperar la red.
let keepWorker = null;

function buildKeepAliveWorker() {
  if (keepWorker) return keepWorker;
  try {
    const code = 'setInterval(function(){ postMessage(1); }, 5000);';
    const blob = new Blob([code], { type: 'application/javascript' });
    keepWorker = new Worker(URL.createObjectURL(blob));
    keepWorker.onmessage = () => {
      // El worker late aunque la pestaña esté oculta: si el WS está cerrado, reconecta ya.
      if (!ws || ws.readyState === WebSocket.CLOSED || ws.readyState === WebSocket.CLOSING) {
        connectWS();
      } else if (ws.readyState === WebSocket.OPEN) {
        try { ws.send(JSON.stringify({ action: 'ping', deviceId: liveDeviceId() })); } catch {}
      }
      if (relayActive()) {
        if (!localWs || localWs.readyState === WebSocket.CLOSED || localWs.readyState === WebSocket.CLOSING) {
          connectLocalWS();
        } else if (localWs.readyState === WebSocket.OPEN) {
          try { localWs.send('{"action":"ping"}'); } catch {}
        }
      }
    };
  } catch { keepWorker = null; }
  return keepWorker;
}

// ¿El .exe usa modo relay (TikTok en Render)? Opt-in vía desktopAPI.relayMode.
// Por defecto el .exe conecta TikTok en esta PC (relayMode=false) para no gastar egress en la nube.
function relayActive() {
  return IS_DESKTOP && !!(window.desktopAPI && window.desktopAPI.relayMode && window.desktopAPI.cloudBase);
}

/** Aviso único: overlays pasan a URLs locales al dejar el relay. */
function maybeNotifyLocalTikTokOverlays() {
  if (!IS_DESKTOP || relayActive()) return;
  try {
    if (localStorage.getItem('livecoins_local_tiktok_overlay_note_v1') === '1') return;
    localStorage.setItem('livecoins_local_tiktok_overlay_note_v1', '1');
  } catch { /* ignore */ }
  try {
    toast(
      'TikTok corre en esta PC (ahorro de nube). Si tus overlays de OBS apuntaban a Render, vuelve a copiar las URLs de este panel.',
      'ok',
    );
  } catch { /* ignore */ }
}

// En modo relay, uploads/audios viven en esta PC (userData). Solo rutas /uploads locales.
function mediaUrl(u) {
  if (!u || typeof u !== 'string') return u || '';
  if (/^https?:\/\//i.test(u)) {
    try {
      const p = new URL(u);
      if (/^\/(uploads|audios|video)\//.test(p.pathname)) return p.pathname + (p.search || '');
    } catch {}
    return u;
  }
  return u;
}

function normalizeRelayMedia(s) {
  if (!s || !relayActive()) return;
  const fix = (u) => mediaUrl(u);
  for (const a of (s.soundAlerts || [])) if (a.sound) a.sound = fix(a.sound);
  for (const v of (s.videos || [])) if (v.url) v.url = fix(v.url);
  for (const b of (s.battleAlerts || [])) if (b.url) b.url = fix(b.url);
  for (const a of (s.actions || [])) if (a.sound) a.sound = fix(a.sound);
  for (const a of (s.mcActions || [])) if (a.sound) a.sound = fix(a.sound);
  for (const r of (s.screenFx?.rules || [])) if (r && r.sound) r.sound = fix(r.sound);
  for (const key of ['bedrockActions', 'parkourActions', 'oneblockActions', 'sandwallActions', 'kothActions', 'farmActions', 'sandboxActions', 'mcshooterActions', 'marioActions', 'mari0Actions', 'smb3Actions', 'pvzActions', 'pvzHybridActions', 'pvzFusionActions', 'repoActions', 'l4dActions', 'unturnedActions', 'gtavKothActions', 'gtavChaosActions', 'gtavChiliadActions', 'ctrActions', 'flappyActions', 'mk64Actions', 'stackActions', 'crossyActions', 'pvzgeActions', 'mslugActions', 'gdashActions', 'smwActions', 'robloxActions', 'roblox3Actions', 'robloxtkActions']) {
    for (const a of (s[key] || [])) if (a && a.sound) a.sound = fix(a.sound);
  }
}

function relativizeMediaUrlForSave(u) {
  if (!u || typeof u !== 'string') return u;
  if (u.startsWith('/')) return u;
  try {
    const p = new URL(u);
    if (/^\/(uploads|audios|video)\//.test(p.pathname)) return p.pathname + (p.search || '');
  } catch {}
  return u;
}
function stripSettingsMediaForSave(s) {
  if (!s) return;
  const rel = relativizeMediaUrlForSave;
  for (const a of (s.soundAlerts || [])) if (a.sound) a.sound = rel(a.sound);
  for (const v of (s.videos || [])) if (v.url) v.url = rel(v.url);
  for (const b of (s.battleAlerts || [])) if (b.url) b.url = rel(b.url);
  for (const a of (s.actions || [])) if (a.sound) a.sound = rel(a.sound);
  for (const a of (s.mcActions || [])) if (a.sound) a.sound = rel(a.sound);
  for (const r of (s.screenFx?.rules || [])) if (r && r.sound) r.sound = rel(r.sound);
  for (const key of ['bedrockActions', 'parkourActions', 'oneblockActions', 'sandwallActions', 'kothActions', 'farmActions', 'sandboxActions', 'mcshooterActions', 'marioActions', 'mari0Actions', 'smb3Actions', 'pvzActions', 'pvzHybridActions', 'pvzFusionActions', 'repoActions', 'l4dActions', 'unturnedActions', 'gtavKothActions', 'gtavChaosActions', 'gtavChiliadActions', 'ctrActions', 'flappyActions', 'mk64Actions', 'stackActions', 'crossyActions', 'pvzgeActions', 'mslugActions', 'gdashActions', 'smwActions', 'robloxActions', 'roblox3Actions', 'robloxtkActions']) {
    for (const a of (s[key] || [])) if (a && a.sound) a.sound = rel(a.sound);
  }
}

function buildWsUrl() {
  if (relayActive()) {
    if (!window.CLOUD_ROOM_KEY) return null;
    const base = String(window.desktopAPI.cloudBase).replace(/\/+$/, '').replace(/^http/i, 'ws');
    return `${base}/ws?room=${encodeURIComponent(window.CLOUD_ROOM_KEY)}&role=relay`;
  }
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  let url = `${proto}://${location.host}/ws`;
  const k = window.ROOM_KEY || '';
  if (k) url += `?room=${encodeURIComponent(k)}`;
  return url;
}

function wsUrlsMatch(a, b) {
  if (!a || !b) return false;
  try {
    const ua = new URL(a);
    const ub = new URL(b);
    return ua.origin === ub.origin && ua.pathname === ub.pathname && ua.search === ub.search;
  } catch {
    return a === b;
  }
}

function connectWS() {
  const url = buildWsUrl();
  if (!url) {
    clearTimeout(reconnectTimer);
    reconnectTimer = setTimeout(connectWS, 600);
    return;
  }
  if (ws) {
    if (wsUrlsMatch(ws.url, url) && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING)) return;
    try { ws.close(); } catch {}
    ws = null;
  }
  const sock = new WebSocket(url);
  ws = sock;
  sock.onopen = () => {
    if (ws !== sock) return;
    clearTimeout(reconnectTimer);
    setConnBadge(true);
    buildKeepAliveWorker();
    connectLocalWS();
    if (relayActive()) {
      try { sock.send(JSON.stringify({ action: 'relayHello', localOrigin: location.origin })); } catch {}
    }
    try { requestProfiles(); } catch {}
  };
  sock.onclose = () => {
    if (ws !== sock) return;
    setConnBadge(false);
    clearTimeout(reconnectTimer);
    reconnectTimer = setTimeout(connectWS, 1500);
  };
  sock.onerror = () => { if (ws === sock) try { sock.close(); } catch {} };
  sock.onmessage = (ev) => {
    if (ws !== sock) return;
    let msg;
    try { msg = JSON.parse(ev.data); } catch { return; }
    const { type, payload, touchedKeys } = msg;
    if (type === 'pong') return;
    if (type === 'accountPending') { location.href = '/'; return; }
    if (type === 'settings') {
      try { onSettings(payload, Array.isArray(touchedKeys) ? touchedKeys : null); } catch (err) { console.error('[settings] ws', err); }
      return;
    }
    handle(type, payload);
  };
}

function waitForWsOpen(maxMs = 8000) {
  return new Promise((resolve) => {
    if (ws?.readyState === WebSocket.OPEN) return resolve(true);
    const deadline = Date.now() + maxMs;
    const tick = () => {
      if (ws?.readyState === WebSocket.OPEN) return resolve(true);
      if (Date.now() >= deadline) return resolve(false);
      if (!ws || ws.readyState === WebSocket.CLOSED || ws.readyState === WebSocket.CLOSING) connectWS();
      setTimeout(tick, 250);
    };
    connectWS();
    tick();
  });
}

// Reconexión al volver a la pestaña (solo si el WS no está abierto).
function overlayStudioItemCount(os) {
  if (!os || typeof os !== 'object') return 0;
  const presets = Array.isArray(os.presets) ? os.presets : [];
  let n = 0;
  for (const p of presets) n += Array.isArray(p && p.items) ? p.items.length : 0;
  return n;
}
function overlayStudioPresetCount(os) {
  if (!os || typeof os !== 'object') return 0;
  return Array.isArray(os.presets) ? os.presets.length : 0;
}
function preserveLocalOverlayStudioOnSettingsEcho(incoming) {
  if (!incoming || !settings) return incoming;
  const local = settings.overlayStudio;
  if (!local || typeof local !== 'object') return incoming;
  const inc = incoming.overlayStudio;
  const localN = overlayStudioItemCount(local);
  const incN = overlayStudioItemCount(inc);
  const editAt = Number(window.__overlayStudioEditAt || local.updatedAt || 0);
  const recent = editAt && (Date.now() - editAt < 12000);
  const pending = (settingsKeysSavePending && settingsKeysSavePending.has('overlayStudio')) || !!_saveAfterSettingsApply;
  if ((pending || recent) && localN >= incN) return { ...incoming, overlayStudio: local };
  if (localN > incN) return { ...incoming, overlayStudio: local };
  if (localN > 0 && incN === 0) {
    // Vaciar a propósito (última fuente borrada): respetar el eco con clearedAt
    if (Number(incoming?.overlayStudio?.clearedAt) > 0) return incoming;
    return { ...incoming, overlayStudio: local };
  }
  if (localN === incN && overlayStudioPresetCount(local) > overlayStudioPresetCount(inc)) {
    return { ...incoming, overlayStudio: local };
  }
  return incoming;
}
function flushOverlayStudioOnLeave() {
  if (!settings || !settings.overlayStudio) return;
  const n = overlayStudioItemCount(settings.overlayStudio);
  const edited = Number(window.__overlayStudioEditAt || 0);
  if (n <= 0 && !edited) return;
  try { window.__overlayStudioFlush?.(); } catch {}
  try { flushSaveSettingsKeysPatch(); } catch {}
}
function flushAllPendingSavesOnLeave() {
  try { flushOverlayStudioOnLeave(); } catch {}
  try { if (typeof flushSaveSettingsKeysPatch === 'function') flushSaveSettingsKeysPatch(); } catch {}
  try { if (typeof flushSaveSettings === 'function') flushSaveSettings(); } catch {}
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') flushAllPendingSavesOnLeave();
  if (document.visibilityState === 'visible') {
    if (ws?.readyState !== WebSocket.OPEN) connectWS();
    if (relayActive() && localWs?.readyState !== WebSocket.OPEN) connectLocalWS();
  }
});
window.addEventListener('pagehide', flushAllPendingSavesOnLeave);
window.addEventListener('beforeunload', flushAllPendingSavesOnLeave);
window.addEventListener('focus', () => {
  if (ws?.readyState !== WebSocket.OPEN) connectWS();
  if (relayActive() && localWs?.readyState !== WebSocket.OPEN) connectLocalWS();
});
window.addEventListener('online', () => {
  if (ws?.readyState !== WebSocket.OPEN) connectWS();
  if (relayActive() && localWs?.readyState !== WebSocket.OPEN) connectLocalWS();
});
window.addEventListener('pageshow', () => {
  if (ws?.readyState !== WebSocket.OPEN) connectWS();
  if (relayActive() && localWs?.readyState !== WebSocket.OPEN) connectLocalWS();
});

