function applyLimitUI() {
  const defs = [
    { kind: 'soundAlerts', key: 'soundAlerts', btn: 'sa-create', view: 'view-alertas', noun: 'alertas sonoras' },
    { kind: 'videos', key: 'videos', btn: 'vid-create', view: 'view-videos', noun: 'videos' },
    { kind: 'battleAlerts', key: 'battleAlerts', btn: 'ba-create', view: 'view-batallas', noun: 'animaciones de batalla' },
    { kind: 'actions', key: 'actions', btn: 'acc-new', view: 'view-acciones', noun: 'acciones' },
  ];
  for (const d of defs) {
    let lim = capLimit(d.key);
    if (window.IS_ADMIN || lim >= 9999) lim = Infinity; // ilimitado: sin aviso ni bloqueo
    const count = planCountOf(d.kind);
    const reached = count >= lim;
    const btn = document.getElementById(d.btn);
    if (btn) {
      btn.disabled = reached;
      btn.style.opacity = reached ? '.5' : '';
      btn.style.cursor = reached ? 'not-allowed' : '';
    }
    const view = document.getElementById(d.view);
    if (view) {
      let note = view.querySelector('.limit-note');
      if (Number.isFinite(lim)) {
        if (!note) {
          note = document.createElement('div');
          note.className = 'limit-note';
          const host = view.querySelector('.view-sub') || view.firstElementChild;
          if (host && host.nextSibling) host.parentNode.insertBefore(note, host.nextSibling);
          else view.insertBefore(note, view.children[1] || null);
        }
        note.textContent = `Plan ${window.CAPS.plan === 'premium' ? 'Premium' : 'Gratis'}: ${count}/${lim} ${d.noun}.` +
          (reached ? ' Has llegado al límite.' : '');
        note.style.display = '';
      } else if (note) {
        note.style.display = 'none';
      }
    }
  }
}

/* ====================== Toast ====================== */
function toast(msg, kind) {
  let wrap = document.querySelector('.toast-wrap');
  if (!wrap) { wrap = document.createElement('div'); wrap.className = 'toast-wrap'; document.body.appendChild(wrap); }
  const el = document.createElement('div');
  el.className = 'toast' + (kind === 'warn' ? ' warn' : kind === 'success' ? ' ok' : kind === 'error' ? ' err' : '');
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(() => { el.style.transition = 'opacity .3s'; el.style.opacity = '0'; setTimeout(() => el.remove(), 320); }, 3200);
}

// Modo relay (.exe): el chat de TikTok llega desde la nube. Spotify y YouTube corren
// LOCAL (cola/audio en esta PC). Reenviamos !play/!skip/!revoke y los !yt* al servidor local.
const knownChatMods = new Set();
function chatModKeys(p) {
  return [
    String(p?.uniqueId || '').trim().toLowerCase().replace(/^@/, ''),
    String(p?.nickname || '').trim().toLowerCase().replace(/^@/, ''),
  ].filter(Boolean);
}
function noteChatMod(p) {
  if (!p || !(p.isMod || p.isModerator)) return;
  for (const k of chatModKeys(p)) knownChatMods.add(k);
}
function chatUserLooksMod(p) {
  if (p?.isMod || p?.isModerator) return true;
  return chatModKeys(p).some((k) => knownChatMods.has(k));
}
function ytChatShouldForward(comment) {
  const lower = String(comment || '').trim().toLowerCase().replace(/[\u200B-\u200D\uFEFF\u2060]/g, '');
  if (!lower) return false;
  if (/^!yt/i.test(lower)) return true;
  const keys = [
    ['cmdPlay', 'yt-cmd-play', '!yt'],
    ['cmdSkip', 'yt-cmd-skip', '!ytsalta'],
    ['cmdRevoke', 'yt-cmd-revoke', '!ytquita'],
    ['cmdVolUp', 'yt-cmd-volup', '!ytvolup'],
    ['cmdVolDown', 'yt-cmd-voldown', '!ytvoldown'],
    ['cmdVol', 'yt-cmd-vol', '!ytvol'],
  ];
  const yt = (typeof settings !== 'undefined' && settings && settings.youtube) || {};
  for (const [key, id, fb] of keys) {
    let t = String(document.getElementById(id)?.value || yt[key] || fb).trim().toLowerCase().replace(/\s+/g, '');
    if (!t) continue;
    if (!t.startsWith('!')) t = '!' + t.replace(/^!+/, '');
    if (t.length < 2) continue;
    if (lower === t || lower.startsWith(t + ' ') || lower.startsWith(t + '\t')) return true;
  }
  return false;
}
function maybeForwardSpotifyChat(p) {
  try {
    if (!relayActive()) return;
    const comment = String(p?.comment || '').trim();
    // !stop solo importa con LiveCoinSong; Spotify no lo usa.
    const lcsOn = typeof spotifyUnlocked === 'function'
      && spotifyUnlocked()
      && !!(settings?.livecoinsong && settings.livecoinsong.enabled === true);
    const spotifyHit = lcsOn
      ? /^(?:!(?:play|skip|revoke|stop)(?:\s|$))/i.test(comment)
      : /^(?:!(?:play|skip|revoke)(?:\s|$))/i.test(comment);
    if (!spotifyHit && !ytChatShouldForward(comment)) return;
    if (!p?.uniqueId) return;
    noteChatMod(p);
    fetch('/api/desktop/spotify-chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        comment,
        user: { uniqueId: p.uniqueId, nickname: p.nickname || p.uniqueId, photo: p.photo || '' },
        roles: {
          isMod: chatUserLooksMod(p),
          isSub: !!p.isSub,
          isSuperFan: !!p.isSuperFan,
          isFollower: !!p.isFollower,
          isTeam: !!p.isTeam,
          memberLevel: Number(p.memberLevel) || 0,
          gifterLevel: Number(p.gifterLevel) || Number(p.donorLevel) || 0,
        },
      }),
    }).catch(() => {});
  } catch {}
}

function maybeForwardMusicChat(p) {
  try {
    if (!relayActive()) return;
    const comment = String(p?.comment || '').trim();
    const cmd = String(settings?.musicRequests?.command || '!sr').trim().toLowerCase();
    const re = new RegExp(`^(${cmd}|!queue|!current|!credits|!skip|!clearqueue|!remove)\\b`, 'i');
    if (!re.test(comment)) return;
    if (!p?.uniqueId) return;
    fetch('/api/desktop/music-chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        comment,
        user: { uniqueId: p.uniqueId, nickname: p.nickname || p.uniqueId, photo: p.photo || '' },
        roles: {
          isMod: chatUserLooksMod(p), isSub: !!p.isSub, isFollower: !!p.isFollower,
          memberLevel: Number(p.memberLevel) || 0,
        },
      }),
    }).catch(() => {});
  } catch {}
}

// En modo relay (.exe), TikTok va por la nube pero las 5 pantallas de video van
// SIEMPRE al servidor local (127.0.0.1) — archivos en userData/uploads.
function roomUrl(path) {
  const p = String(path || '');
  const isLocalOnly = /\/studio-overlay\.html/.test(p) || /^\/spotify-/.test(p) || /^\/youtube-overlay/.test(p) || /^\/editor-rapido-overlay/.test(p) || (relayActive() && /^\/video\.html/.test(p));
  const useCloud = relayActive() && !isLocalOnly;
  const base = useCloud ? String(window.desktopAPI.cloudBase).replace(/\/+$/, '') : location.origin;
  const k = useCloud ? (window.CLOUD_ROOM_KEY || '') : window.ROOM_KEY;
  let url = base + p;
  if (k) url += (p.includes('?') ? '&' : '?') + 'room=' + encodeURIComponent(k);
  if (/\/habibi-top\.html/.test(p)) url += (url.includes('?') ? '&' : '?') + 'v=20';
  if (/\/studio-overlay\.html/.test(p)) url += (url.includes('?') ? '&' : '?') + 'v=os59';
  return url;
}

// Browser Source para pantallas 1–10 y videos de nivel: local en .exe relay.
const SCREEN_COUNT = 10;
function clampScreenId(screenId) {
  return Math.max(1, Math.min(SCREEN_COUNT, Number(screenId) || 1));
}
function ensureScreens() {
  if (!settings) return [];
  const prev = Array.isArray(settings.screens) ? settings.screens : [];
  const byId = new Map();
  for (const s of prev) {
    const id = clampScreenId(s?.id);
    if (!byId.has(id)) byId.set(id, {
      id,
      size: Math.max(10, Math.min(100, Number(s?.size) || 100)),
      volume: Math.max(0, Math.min(100, Number(s?.volume ?? 100))),
    });
  }
  const next = [];
  for (let i = 1; i <= SCREEN_COUNT; i++) {
    next.push(byId.get(i) || { id: i, size: 100, volume: 100 });
  }
  settings.screens = next;
  return settings.screens;
}
function fillScreenSelect(selectEl, selected) {
  if (!selectEl) return;
  const cur = clampScreenId(selected != null ? selected : selectEl.value);
  selectEl.innerHTML = Array.from({ length: SCREEN_COUNT }, (_, i) => {
    const n = i + 1;
    return `<option value="${n}"${n === cur ? ' selected' : ''}>Pantalla ${n}</option>`;
  }).join('');
}
function videoScreenUrl(screenId) {
  const id = clampScreenId(screenId);
  const k = window.ROOM_KEY || '';
  let u = `${location.origin}/video.html?screen=${id}`;
  if (k) u += `&room=${encodeURIComponent(k)}`;
  return u;
}

function videoScreenUrlFromPath(path) {
  const m = /[?&]screen=(\d+)/i.exec(String(path || ''));
  if (m) return videoScreenUrl(Number(m[1]));
  return roomUrl(path);
}

// Alias histórico (niveles de miembro)
function levelVideoScreenUrl(screenId) { return videoScreenUrl(screenId); }

function refreshLevelVideoScreenLink() {
  const cfg = settings?.levelVideos || {};
  const scr = Number(cfg.screen) || 1;
  const urlEl = $('levelvid-screen-url');
  if (urlEl) {
    urlEl.dataset.url = levelVideoScreenUrl(scr);
    urlEl.textContent = '';
  }
  const tip = document.querySelector('.levelvid-copy-tip');
  if (tip) tip.textContent = `Copia y pega el URL de la pantalla que elegiste`;
  const st = $('levelvid-screen-status');
  if (st) {
    const on = connectedScreens.has(scr);
    st.textContent = on ? '● Fuente conectada' : '';
    st.className = 'levelvid-url-status ' + (on ? 'on' : 'off');
    st.hidden = !on;
  }
}

function refreshAccMediaScreenUrl() {
  const scr = Math.max(1, parseInt($('acc-media-screen')?.value, 10) || 1);
  const urlEl = $('acc-media-ls-url');
  if (urlEl) urlEl.textContent = videoScreenUrl(scr);
  const st = $('acc-media-ls-status');
  if (st) {
    const on = connectedScreens.has(scr);
    st.textContent = on ? '● Fuente conectada' : '○ Pega el link en Live Studio y recarga la fuente';
    st.className = 'levelvid-url-status ' + (on ? 'on' : 'off');
  }
  refreshAccAnimOverlayUrl();
}
function refreshAccAnimOverlayUrl() {
  const url = isOverlayUrlLocked($('acc-anim-ov-url') || $('acc-alert-ov-url')) ? OV_URL_MASK : roomUrl('/overlay.html');
  if ($('acc-anim-ov-url')) $('acc-anim-ov-url').textContent = url;
  if ($('acc-alert-ov-url')) $('acc-alert-ov-url').textContent = url;
}

// Refresca el texto y enlaces de todas las URLs de overlay ya pintadas.
function refreshOverlayUrls() {
  document.querySelectorAll('.ov-url').forEach((code) => {
    if (!code.dataset.path) return;
    const path = code.dataset.path;
    if (IS_DESKTOP && /\/video\.html/i.test(path)) {
      code.textContent = isOverlayUrlLocked(code) ? OV_URL_MASK : videoScreenUrlFromPath(path);
      return;
    }
    code.textContent = isOverlayUrlLocked(code) ? OV_URL_MASK : roomUrl(path);
  });
  document.querySelectorAll('.overlay-item').forEach((item) => {
    const code = item.querySelector('.ov-url');
    const a = item.querySelector('a');
    if (code && a && code.dataset.path) {
      const path = code.dataset.path;
      a.href = isOverlayUrlLocked(code) ? '#'
        : (IS_DESKTOP && /\/video\.html/i.test(path) ? videoScreenUrlFromPath(path) : roomUrl(path));
    }
  });
  renderAccScreenUrls();
}

function updateDockUserAvatar({ photo, nickname, username } = {}) {
  const img = document.getElementById('dock-user-img');
  const ph = document.getElementById('dock-user-ph');
  if (!img || !ph) return;
  if (photo) connectStreamerPhoto = photo;
  const name = nickname || username || window.MY_USER || '';
  const url = connectAvatarUrl(photo || connectStreamerPhoto);
  const applyPair = (imageEl, phEl) => {
    if (!imageEl || !phEl) return;
    if (url) {
      imageEl.referrerPolicy = 'no-referrer';
      imageEl.src = url;
      imageEl.hidden = false;
      phEl.hidden = true;
      imageEl.onerror = () => {
        imageEl.hidden = true;
        phEl.hidden = false;
        phEl.textContent = (typeof initial === 'function' ? initial(name) : (name[0] || '?')).toString().toUpperCase();
      };
    } else {
      imageEl.hidden = true;
      phEl.hidden = false;
      phEl.textContent = (typeof initial === 'function' ? initial(name || '?') : (name[0] || '?')).toString().toUpperCase();
    }
  };
  applyPair(img, ph);
  applyPair(document.getElementById('dock-menu-img'), document.getElementById('dock-menu-ph'));
}

function lastTikTokStorageKey() {
  const u = String(window.MY_USER || '').trim().toLowerCase();
  return u ? `lastTikTokUser:${u}` : '';
}
function getLastTikTokUserPref() {
  try {
    const key = lastTikTokStorageKey();
    if (!key) return '';
    return localStorage.getItem(key) || '';
  } catch {}
  return '';
}
function setLastTikTokUserPref(name) {
  const n = String(name || '').trim();
  if (!n) return;
  try {
    const key = lastTikTokStorageKey();
    if (key) localStorage.setItem(key, n);
  } catch {}
}

function setDockUserMenuOpen(open) {
  const chip = document.getElementById('user-chip');
  const btn = document.getElementById('dock-user-btn');
  const menu = document.getElementById('dock-user-menu');
  if (!chip || !btn || !menu) return;
  menu.hidden = !open;
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  chip.classList.toggle('is-open', !!open);
}

/** Plan + días restantes en el menú del avatar (datos de /api/me). */
function refreshDockPlanUi(me) {
  const label = document.getElementById('dock-user-plan-label');
  const upBtn = document.getElementById('dock-plan-upgrade');
  if (!label) return;
  const plan = String((me && me.plan) || window.MY_PLAN || window.CAPS?.plan || 'free').toLowerCase();
  const until = Number(
    me && me.premiumUntil != null ? me.premiumUntil : (window.MY_PREMIUM_UNTIL || 0),
  ) || 0;
  if (me && me.premiumUntil != null) window.MY_PREMIUM_UNTIL = until;
  let text = 'Plan Gratis';
  if (window.IS_ADMIN || plan === 'admin') text = 'Admin · acceso total';
  else if (plan === 'founder') text = '👑 Founder';
  else if (plan === 'premium') {
    if (until > 0) {
      const days = Math.max(0, Math.ceil((until - Date.now()) / 86400000));
      text = days > 0
        ? `⭐ Premium · ${days} día${days === 1 ? '' : 's'}`
        : '⭐ Premium · vencido';
    } else {
      text = '⭐ Premium · fijo';
    }
  }
  label.textContent = text;
  if (upBtn) {
    const showUp = !window.IS_ADMIN && plan !== 'premium' && plan !== 'founder' && plan !== 'admin';
    upBtn.hidden = !showUp;
  }
}

// Chip de usuario con menú (avatar junto al logo).
function mountUserChip() {
  const chip = document.getElementById('user-chip');
  const nameEl = document.getElementById('user-chip-name');
  if (!chip || !nameEl) return;
  nameEl.textContent = window.MY_USER || 'usuario';
  const verEl = document.getElementById('user-chip-ver');
  if (verEl) verEl.hidden = !IS_DESKTOP;
  const subEl = document.querySelector('.dock-user-menu-sub');
  if (subEl) subEl.hidden = !IS_DESKTOP;
  try { refreshDockPlanUi(); } catch {}
  updateDockUserAvatar({ username: window.MY_USER });
  try {
    const lastU = getLastTikTokUserPref();
    const userInp = $('username');
    let ttAcc = '';
    try { ttAcc = localStorage.getItem('lcTikTokAccount') || ''; } catch {}
    ttAcc = String(ttAcc).replace(/^@/, '').trim();
    if (ttAcc && userInp) {
      userInp.value = ttAcc;
      updateConnectAvatar({ username: ttAcc });
    } else if (lastU && userInp && !userInp.value) {
      userInp.value = lastU;
      updateConnectAvatar({ username: lastU });
    }
  } catch {}
  const btn = document.getElementById('dock-user-btn');
  const menu = document.getElementById('dock-user-menu');
  if (btn && menu && !btn.dataset.wired) {
    btn.dataset.wired = '1';
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      setDockUserMenuOpen(menu.hidden);
    };
    document.addEventListener('click', (e) => {
      if (!chip.contains(e.target)) setDockUserMenuOpen(false);
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') setDockUserMenuOpen(false);
    });
  }
  const planUp = document.getElementById('dock-plan-upgrade');
  if (planUp && !planUp.dataset.wired) {
    planUp.dataset.wired = '1';
    planUp.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      setDockUserMenuOpen(false);
      document.querySelector('.nav-item[data-view="planes"]')?.click();
    };
  }
  const logout = document.getElementById('logout-btn');
  if (logout && !logout.dataset.wired) {
    logout.dataset.wired = '1';
    logout.onclick = () => { performLogout(); };
  }
  applyPcInstallButton();
  if (IS_DESKTOP) applyInstalledAppVersionBadge();
  setupDesktopAutostartToggle();
  setupDesktopResourceControls();
}

async function setupDesktopAutostartToggle() {
  const row = document.getElementById('dock-autostart-row');
  const box = document.getElementById('lc-autostart');
  if (!row || !box) return;
  if (!IS_DESKTOP || !window.desktopAPI?.getAutoStart || !window.desktopAPI?.setAutoStart) {
    row.hidden = true;
    return;
  }
  row.hidden = false;
  try {
    const r = await window.desktopAPI.getAutoStart();
    box.checked = !!(r && r.enabled);
  } catch {}
  if (box.dataset.wired) return;
  box.dataset.wired = '1';
  row.addEventListener('click', (e) => e.stopPropagation());
  box.onchange = async () => {
    try {
      const r = await window.desktopAPI.setAutoStart(!!box.checked);
      box.checked = !!(r && r.ok ? r.enabled : box.checked);
      if (typeof toast === 'function') {
        toast(box.checked ? 'El panel se abrirá al encender. Live Studio no pierde los overlays.' : 'El panel ya no se abre solo. Los overlays siguen listos para Live Studio.', 'ok');
      }
    } catch {
      /* ignore */
    }
  };
}

function setupDesktopResourceControls() {
  if (!IS_DESKTOP || !window.desktopAPI) return;

  window.__lcPauseResources = () => {
    try { if (typeof send === 'function') send({ action: 'pauseResources' }); } catch { /* ignore */ }
    try { window.__lcStopAviz?.(); } catch { /* ignore */ }
    try { toast && toast('Recursos pausados (TikTok / Baile / visualizador).', 'ok'); } catch { /* ignore */ }
  };

  try {
    window.desktopAPI.onPauseResources?.(() => {
      try { window.__lcPauseResources(); } catch { /* ignore */ }
    });
  } catch { /* ignore */ }

  const closeRow = document.getElementById('dock-close-action-row');
  const closeSel = document.getElementById('lc-close-action');
  if (closeRow && closeSel && window.desktopAPI.getDesktopPrefs) {
    closeRow.hidden = false;
    closeRow.addEventListener('click', (e) => e.stopPropagation());
    window.desktopAPI.getDesktopPrefs().then((r) => {
      if (r && r.closeAction) closeSel.value = r.closeAction;
    }).catch(() => {});
    if (!closeSel.dataset.wired) {
      closeSel.dataset.wired = '1';
      closeSel.onchange = async () => {
        try {
          const r = await window.desktopAPI.setDesktopPrefs({ closeAction: closeSel.value });
          if (r && r.closeAction) closeSel.value = r.closeAction;
          const msg = closeSel.value === 'quit'
            ? 'Al cerrar la X se cerrará Livecoins por completo.'
            : closeSel.value === 'pause'
              ? 'Al cerrar la X se pausará TikTok/Baile y se ocultará el panel.'
              : 'Al cerrar la X solo se oculta el panel (overlays siguen).';
          toast && toast(msg, 'ok');
        } catch { /* ignore */ }
      };
    }
  }

  const banner = document.getElementById('lc-gpu-banner');
  const clearBtn = document.getElementById('lc-gpu-clear');
  if (banner) banner.hidden = true;
  if (banner && window.desktopAPI.getDesktopPrefs) {
    const refresh = async () => {
      try {
        const r = await window.desktopAPI.getDesktopPrefs();
        banner.hidden = true;
      } catch { banner.hidden = true; }
    };
    refresh();
    if (clearBtn && !clearBtn.dataset.wired) {
      clearBtn.dataset.wired = '1';
      clearBtn.onclick = async () => {
        try {
          const r = await window.desktopAPI.clearGpuSafeMode();
          if (r && r.ok) {
            banner.hidden = true;
            toast && toast('GPU reactivada. Cierra Livecoins (bandeja → Salir) y ábrelo de nuevo.', 'ok');
          } else {
            toast && toast('No se pudo quitar el modo sin GPU.', 'err');
          }
        } catch {
          toast && toast('No se pudo quitar el modo sin GPU.', 'err');
        }
      };
    }
  }

  const repairBanner = document.getElementById('lc-repair-banner');
  const repairBtn = document.getElementById('lc-repair-conn');
  const repairDock = document.getElementById('lc-repair-conn-dock');
  const refreshRepair = async () => {
    try {
      const r = await window.desktopAPI.getDesktopPrefs();
      const need = !!(r && r.repairNeeded);
      if (repairBanner) repairBanner.hidden = !need;
      if (repairDock) repairDock.hidden = !need;
    } catch {
      if (repairBanner) repairBanner.hidden = true;
      if (repairDock) repairDock.hidden = true;
    }
  };
  if (window.desktopAPI.getDesktopPrefs) refreshRepair();
  const runRepair = async () => {
    if (!window.desktopAPI?.repairConnection) return;
    const okAsk = typeof askConfirm === 'function'
      ? await askConfirm({
        title: 'Reparar conexión',
        message: 'Limpia caché y cookies de la app para volver a conectar tras una actualización. No borra puntos, perfiles ni videos.',
        confirmText: 'Reparar',
        cancelText: 'Cancelar',
        icon: '🔧',
        danger: false,
      })
      : true;
    if (!okAsk) return;
    try {
      toast && toast('Reparando… un momento.', 'ok');
      const r = await window.desktopAPI.repairConnection();
      if (r && r.ok) {
        if (repairBanner) repairBanner.hidden = true;
        if (repairDock) repairDock.hidden = true;
        toast && toast('Listo. Si no conecta, cierra (bandeja → Salir) y abre de nuevo. Tus puntos siguen ahí.', 'ok');
      } else {
        toast && toast('No se pudo reparar: ' + (r?.error || 'error'), 'err');
      }
    } catch (e) {
      toast && toast('No se pudo reparar la conexión.', 'err');
    }
  };
  if (repairBtn && !repairBtn.dataset.wired) {
    repairBtn.dataset.wired = '1';
    repairBtn.onclick = () => { runRepair(); };
  }
  if (repairDock && !repairDock.dataset.wired) {
    repairDock.dataset.wired = '1';
    repairDock.onclick = () => { runRepair(); };
  }
}

let pcInstallUrl = '';
async function applyPcInstallButton() {
  const btn = document.getElementById('pc-install-btn');
  const openInstall = (e) => {
    if (e) e.preventDefault();
    if (!pcInstallUrl) {
      try { toast && toast('Aún no hay enlace de descarga configurado.', 'warn'); } catch {}
      return;
    }
    if (IS_DESKTOP && window.desktopAPI?.openExternal) window.desktopAPI.openExternal(pcInstallUrl);
    else window.open(pcInstallUrl, '_blank', 'noopener');
  };
  if (btn) {
    if (IS_DESKTOP || IS_LOCALHOST) { btn.hidden = true; }
    else {
      try {
        const r = await fetch('/api/web-install');
        if (!r.ok) { btn.hidden = true; }
        else {
          const d = await r.json();
          pcInstallUrl = String(d.url || '').trim();
          btn.hidden = !pcInstallUrl;
          btn.onclick = openInstall;
        }
      } catch {
        btn.hidden = true;
      }
    }
  }
}

/* ====================== Confirmación (borrado / avisos) ====================== */
function askConfirm({ title = '¿Estás seguro?', message = '', confirmText = 'Borrar', cancelText = 'Cancelar', icon = '🗑️', danger = true, modalClass = '' } = {}) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal confirm-modal' + (modalClass ? (' ' + modalClass) : '');
    const okClass = danger ? 'btn danger c-ok' : 'btn primary c-ok';
    back.innerHTML = `
      <div class="confirm-box">
        <div class="confirm-ico">${icon || '🗑️'}</div>
        <h3>${title}</h3>
        ${message ? `<p>${message}</p>` : ''}
        <div class="confirm-btns">
          <button type="button" class="btn ghost c-cancel">${cancelText}</button>
          <button type="button" class="${okClass}">${confirmText}</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    let done = false;
    const close = (val) => {
      if (done) return;
      done = true;
      try { document.removeEventListener('keydown', onEsc); } catch {}
      try { back.remove(); } catch {}
      resolve(val);
    };
    const onEsc = (e) => { if (e.key === 'Escape') close(false); };
    back.querySelector('.c-cancel').onclick = () => close(false);
    back.querySelector('.c-ok').onclick = () => close(true);
    back.addEventListener('click', (e) => { if (e.target === back) close(false); });
    document.addEventListener('keydown', onEsc);
    // Si el modal se quita desde fuera (cerrar biblioteca), resolver como cancelar
    const obs = new MutationObserver(() => {
      if (!document.body.contains(back)) {
        try { obs.disconnect(); } catch {}
        close(false);
      }
    });
    try { obs.observe(document.body, { childList: true }); } catch {}
    setTimeout(() => back.querySelector('.c-ok')?.focus(), 30);
  });
}

/** Pide Channel ID de TikFinity e importa puntos (el .tfc cifrado no trae la lista). */
function askTikfinityPointsImport({ reason = '', needPassword = false, title = 'Importar de TikFinity' } = {}) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal confirm-modal';
    const savedId = (() => { try { return localStorage.getItem('lc_tikfinity_channel_id') || ''; } catch { return ''; } })();
    back.innerHTML = `
      <div class="confirm-box" style="max-width:480px;text-align:left">
        <div class="confirm-ico">📥</div>
        <h3>${title}</h3>
        <p style="margin:0 0 10px;opacity:.9;font-size:13px;line-height:1.45">
          ${reason || 'Usa tu User ID de TikFinity (Setup → Tu cuenta).'}
        </p>
        <div style="margin:0 0 12px;padding:10px 12px;border-radius:10px;border:1px solid rgba(255,180,80,.45);background:rgba(255,160,40,.12);font-size:12.5px;line-height:1.45;color:#ffe6c2">
          <b style="color:#ffb84d">Importante — ¿Dónde está el User ID?</b><br>
          1. Abre <b>TikFinity</b><br>
          2. Ve a <b>Setup</b><br>
          3. Baja hasta <b>Tu cuenta / Your account</b><br>
          4. Copia el <b>User-ID</b> (número) y pégalo abajo
        </div>
        <label style="display:block;font-size:12px;margin:0 0 4px;opacity:.8">Channel / User ID</label>
        <input type="text" class="tf-ch-input" placeholder="Ej. 590698" autocomplete="off" value="${String(savedId).replace(/"/g, '')}"
          style="width:100%;box-sizing:border-box;padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.2);background:#0c1322;color:#fff;font-size:15px;margin-bottom:10px">
        ${needPassword ? `
          <label style="display:block;font-size:12px;margin:0 0 4px;opacity:.8">Contraseña del export (si TikFinity te la pidió; si no, déjala vacía)</label>
          <input type="password" class="tf-pass-input" placeholder="Opcional" autocomplete="off"
            style="width:100%;box-sizing:border-box;padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.2);background:#0c1322;color:#fff;font-size:15px;margin-bottom:10px">
        ` : ''}
        <label class="switch-row plain" style="margin:0 0 14px">
          <input type="checkbox" class="tf-ch-replace" checked>
          <span>Reemplazar listas actuales (alertas/acciones/puntos…)</span>
        </label>
        <div class="confirm-btns">
          <button type="button" class="btn ghost c-cancel">Cancelar</button>
          <button type="button" class="btn primary c-ok">Continuar</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    const input = back.querySelector('.tf-ch-input');
    let done = false;
    const close = (val) => {
      if (done) return;
      done = true;
      try { document.removeEventListener('keydown', onKey); } catch {}
      try { back.remove(); } catch {}
      resolve(val);
    };
    const onKey = (e) => {
      if (e.key === 'Escape') close(null);
      if (e.key === 'Enter' && document.activeElement === input) back.querySelector('.c-ok')?.click();
    };
    back.querySelector('.c-cancel').onclick = () => close(null);
    back.querySelector('.c-ok').onclick = () => {
      const channelId = String(input?.value || '').trim();
      if (!/^\d+$/.test(channelId)) {
        input?.focus();
        toast('Pon el User ID numérico (Setup → Account en TikFinity).', 'warn');
        return;
      }
      try { localStorage.setItem('lc_tikfinity_channel_id', channelId); } catch {}
      close({
        channelId,
        password: String(back.querySelector('.tf-pass-input')?.value || ''),
        replace: !!back.querySelector('.tf-ch-replace')?.checked,
      });
    };
    back.addEventListener('click', (e) => { if (e.target === back) close(null); });
    document.addEventListener('keydown', onKey);
    setTimeout(() => input?.focus(), 40);
  });
}

let tikfinityDecryptWaiters = [];
function onTikfinityDecryptResult(p) {
  const waiters = tikfinityDecryptWaiters.splice(0);
  waiters.forEach((w) => {
    clearTimeout(w.timer);
    w.resolve(p || { ok: false, error: 'sin respuesta' });
  });
}
function requestTikfinityDecrypt({ ciphertext, channelId, password, username }, timeoutMs) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      tikfinityDecryptWaiters = tikfinityDecryptWaiters.filter((w) => w.timer !== timer);
      resolve({ ok: false, error: 'Tiempo agotado al descifrar el .tfc' });
    }, timeoutMs || 20000);
    tikfinityDecryptWaiters.push({ resolve, timer });
    send({ action: 'decryptTikfinityTfc', ciphertext, channelId, password, username });
  });
}

let tikfinityCloudSettingsWaiters = [];
function onTikfinityCloudSettingsResult(p) {
  if (p && p.pending) {
    try {
      if (typeof window.setPtsTfStatus === 'function') window.setPtsTfStatus(p.text || 'Descargando…');
    } catch {}
    return;
  }
  const waiters = tikfinityCloudSettingsWaiters.splice(0);
  waiters.forEach((w) => {
    clearTimeout(w.timer);
    w.resolve(p || { ok: false, error: 'sin respuesta' });
  });
}
function requestTikfinityCloudSettings({ channelId, events }, timeoutMs) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      tikfinityCloudSettingsWaiters = tikfinityCloudSettingsWaiters.filter((w) => w.timer !== timer);
      resolve({ ok: false, error: 'Tiempo agotado al descargar acciones de TikFinity' });
    }, timeoutMs || 60000);
    tikfinityCloudSettingsWaiters.push({ resolve, timer });
    send({ action: 'importTikfinityCloudSettings', channelId, events });
  });
}

/** Descarga Actions de TikFinity (sonidos/videos/teclas) con el User ID y las aplica. */
async function importTikfinityCloudSettingsFlow(channelId, { replace = true, events = null } = {}) {
  const id = String(channelId || '').trim();
  if (!/^\d+$/.test(id)) {
    toast('User ID inválido.', 'warn');
    return false;
  }
  const mode = replace ? 'replace' : 'merge';
  if (replace) toast('Descargando acciones/alertas de TikFinity…', 'ok');
  const res = await requestTikfinityCloudSettings({ channelId: id, events });
  if (!res || !res.ok || !res.data) {
    if (replace) toast(res?.error || 'No se pudieron descargar las acciones', 'warn');
    return false;
  }
  // En merge: no duplicar por misma URL de audio/video.
  if (mode === 'merge' && settings) {
    const haveSound = new Set((settings.soundAlerts || []).map((a) => String(a.sound || '').trim()).filter(Boolean));
    const haveVid = new Set((settings.videos || []).map((v) => String(v.url || '').trim()).filter(Boolean));
    if (Array.isArray(res.data.alertas)) {
      res.data.alertas = res.data.alertas.filter((a) => {
        const u = String(a.audioUrl || a.sound || '').trim();
        return u && !haveSound.has(u);
      });
    }
    if (Array.isArray(res.data.videos)) {
      res.data.videos = res.data.videos.filter((v) => {
        const u = String(v.videoUrl || v.url || '').trim();
        return u && !haveVid.has(u);
      });
    }
  }
  const n =
    (res.data.alertas?.length || 0) + (res.data.videos?.length || 0) + (res.data.interacciones?.length || 0);
  if (!n) return false;
  const applied = applyTikfinitySettingsBundle(res.data, mode);
  if (applied.ok && applied.summary) {
    toast((replace ? 'Desde nube TikFinity: ' : 'Extra nube TikFinity: ') + applied.summary, 'ok');
    return true;
  }
  if (replace) toast(applied.error || 'Sin alertas/videos convertibles', 'warn');
  return false;
}

function hydrateImportedAccionesToInteractive() {
  if (!settings || typeof settings !== 'object') return;
  try {
    if (typeof migrateVideosToAccionesBag === 'function') migrateVideosToAccionesBag(settings);
  } catch {}
  try { migrateAccionesLegacyEvents(settings); } catch {}
  try {
    if (typeof markMcPresetDirty === 'function') markMcPresetDirty('acciones');
    if (typeof syncMcPresetFromActions === 'function') syncMcPresetFromActions('acciones');
  } catch {}
}

let accLocalMediaResolveTried = false;
async function restoreImportedLocalMedia(obj, { overwrite = false, toastMissing = false } = {}) {
  if (!IS_DESKTOP || !obj || typeof obj !== 'object') return { restored: 0, missing: 0 };
  if (!window.SettingsTransfer || typeof window.SettingsTransfer.collectLocalMediaRefs !== 'function') {
    return { restored: 0, missing: 0 };
  }
  let refs;
  try {
    refs = window.SettingsTransfer.collectLocalMediaRefs(obj);
  } catch {
    return { restored: 0, missing: 0 };
  }
  if (!refs || !refs.urls || !refs.urls.length) return { restored: 0, missing: 0 };
  try {
    const r = await fetch('/api/settings-transfer/resolve-media', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ urls: refs.urls, names: refs.names, overwrite: !!overwrite }),
    });
    if (!r.ok) return { restored: 0, missing: 0 };
    const data = await r.json();
    if (toastMissing && Number(data.missing) > 0) {
      toast('Hay videos de otra PC que no están en este equipo. En la otra PC vuelve a Exportar: ahora sale un .zip con los archivos.', 'warn');
    } else if (toastMissing && Number(data.restored) > 0) {
      toast(data.restored + ' video(s) copiados a este PC.', 'ok');
    }
    return data;
  } catch {
    return { restored: 0, missing: 0 };
  }
}

function applyTikfinitySettingsBundle(raw, mode) {
  if (!raw || typeof raw !== 'object' || !window.SettingsTransfer) {
    return { ok: false, error: 'Sin datos de ajustes' };
  }
  let result;
  try {
    // Reusa el parser (legacy / livecoins / puntos).
    result = window.SettingsTransfer.parseFile(JSON.stringify(raw));
  } catch (e) {
    try {
      result = window.SettingsTransfer.convertLegacy(raw, { includeActions: true });
    } catch (e2) {
      const keys = Object.keys(raw).slice(0, 12).join(', ');
      return { ok: false, error: (e2.message || e.message || String(e)) + (keys ? ` [claves: ${keys}]` : '') };
    }
  }
  if (result.multi && Array.isArray(result.profiles)) {
    return { ok: false, error: 'Este dump trae varios perfiles; impórtalo desde Transferencia de datos.' };
  }
  if (result.format === 'points-users') {
    return { ok: true, pointsOnly: true, result };
  }
  const patch = result.patch || {};
  const counts = result.counts || {};
  const hasLists = (counts.soundAlerts || 0) + (counts.videos || 0) + (counts.actions || 0) + (counts.mcActions || 0) + (counts.tts || 0) + (counts.timer || 0);
  if (!hasLists && !Object.keys(patch).length) {
    const keys = Object.keys(raw).slice(0, 16).join(', ');
    return { ok: false, error: `El archivo se abrió pero no trae alertas/videos/acciones reconocibles.${keys ? ' Claves: ' + keys : ''}` };
  }
  const merged = window.SettingsTransfer.applyPatch(settings || {}, patch, mode);
  settings = merged;
  // Quitar de Acciones del directo los stubs viejos de Minecraft ([MC] sin teclas).
  try {
    if (Array.isArray(settings.actions) && settings.actions.length) {
      const before = settings.actions.length;
      settings.actions = settings.actions.filter((a) => {
        if (!a) return false;
        const name = String(a.name || '');
        const keys = String(a.keys || '').trim();
        if (/\[MC\]\s*$/i.test(name) && !keys) return false;
        if (!keys && !a.webhookCmd?.on && !a.obsCmd?.on && !a.sbCmd?.on && /\[MC\]/i.test(name)) return false;
        return true;
      });
      if (settings.actions.length !== before && counts.mcActions) {
        /* cleaned leftovers from older imports */
      }
    }
  } catch {}
  try { hydrateImportedAccionesToInteractive(); } catch {}
  try {
    if (typeof markMcPresetDirty === 'function' && Array.isArray(settings.actions)) {
      markMcPresetDirty('acciones');
    }
  } catch {}
  saveSettings();
  applySettingsToUI();
  applyLimitUI();
  try { seedEmoteCatalogFromImport(collectEmotesFromLivecoinsSettings(settings)); } catch {}
  return { ok: true, result, summary: window.SettingsTransfer.summarize(counts) };
}

async function applyTikfinityLoginResult(r, { replace = true, importPoints = true } = {}) {
  if (!r || !r.ok || !r.channelId) return false;
  try { localStorage.setItem('lc_tikfinity_channel_id', String(r.channelId)); } catch {}
  try {
    const ch = $('pts-tf-channel');
    if (ch) ch.value = r.channelId;
  } catch {}
  const mode = replace ? 'replace' : 'merge';
  let appliedSettings = false;
  if (r.settings) {
    const applied = applyTikfinitySettingsBundle(r.settings, mode);
    if (applied.ok && applied.summary) {
      toast('Ajustes desde sesión TikFinity: ' + applied.summary, 'ok');
      appliedSettings = true;
    } else if (applied.error) {
      toast('Sesión OK, pero sin alertas en caché: ' + applied.error, 'warn');
    }
  } else {
    // Sin ajustes en caché del navegador: traer Actions desde la API pública.
    try {
      await importTikfinityCloudSettingsFlow(r.channelId, { replace });
      appliedSettings = true;
    } catch {
      toast('Cuenta detectada. No había alertas en la sesión. Prueba Copia de seguridad → .tfc o “Importar con este ID” + nube.', 'warn');
    }
  }
  if (importPoints) {
    send({ action: 'importTikfinityPoints', channelId: String(r.channelId), mode });
  }
  return appliedSettings;
}

async function runTikfinityPointsImportFlow(opts) {
  const ans = await askTikfinityPointsImport(opts);
  if (!ans) return false;
  try {
    const ch = $('pts-tf-channel');
    if (ch) ch.value = ans.channelId;
    const rep = $('pts-tf-replace');
    if (rep) rep.checked = !!ans.replace;
  } catch {}
  try {
    const nav = document.querySelector('[data-view="points"]');
    if (nav) nav.click();
  } catch {}
  if (typeof window.setPtsTfStatus === 'function') window.setPtsTfStatus('Descargando desde TikFinity…');
  send({
    action: 'importTikfinityPoints',
    channelId: ans.channelId,
    mode: ans.replace ? 'replace' : 'merge',
  });
  toast('Importando puntos desde tu cuenta TikFinity…', 'ok');
  return true;
}

/** .tfc cifrado → descifrar con User ID → alertas/acciones/TTS + puntos. */
async function runTikfinityTfcFullImport(ciphertext, opts = {}) {
  const ans = await askTikfinityPointsImport({
    title: 'Importar .tfc de TikFinity',
    needPassword: true,
    reason: opts.reason || 'El .tfc está cifrado. Con tu User ID intentamos abrirlo e importar alertas, videos, acciones, TTS y puntos.',
  });
  if (!ans) return false;
  try { localStorage.setItem('lc_tikfinity_channel_id', ans.channelId); } catch {}
  const mode = ans.replace ? 'replace' : 'merge';
  toast('Descifrando .tfc…', 'ok');
  const dec = await requestTikfinityDecrypt({
    ciphertext,
    channelId: ans.channelId,
    password: ans.password,
  });
  if (!dec || !dec.ok || !dec.data) {
    toast(dec?.error || 'No se pudo descifrar el .tfc', 'warn');
    if (ans.settings) {
      const fromSession = applyTikfinitySettingsBundle(ans.settings, mode);
      if (fromSession.ok && fromSession.summary) {
        toast('Ajustes desde sesión TikFinity: ' + fromSession.summary, 'ok');
      }
    }
    const choice = await askConfirm({
      title: 'El .tfc no se pudo abrir',
      message: 'TikFinity cifra el .tfc con una clave que no es solo el User ID.\n\n• Nube + puntos: descarga sonidos/videos/acciones de tu cuenta e importa puntos.\n• Solo puntos: solo la lista de puntos.',
      confirmText: 'Nube + puntos',
      cancelText: 'Solo puntos',
      danger: false,
      icon: '📥',
    });
    if (choice) {
      await importTikfinityCloudSettingsFlow(ans.channelId, { replace: ans.replace });
    }
    send({ action: 'importTikfinityPoints', channelId: ans.channelId, mode });
    toast(choice ? 'Importando nube + puntos…' : 'Importando solo puntos…', 'ok');
    return false;
  }
  const applied = applyTikfinitySettingsBundle(dec.data, mode);
  if (!applied.ok && !applied.pointsOnly) {
    toast(applied.error || 'No había ajustes compatibles en el .tfc', 'warn');
    if (ans.settings) {
      const fromSession = applyTikfinitySettingsBundle(ans.settings, mode);
      if (fromSession.ok && fromSession.summary) {
        toast('Fallback sesión: ' + fromSession.summary, 'ok');
      }
    }
  } else if (applied.summary) {
    toast('Ajustes TikFinity: ' + applied.summary, 'ok');
  } else if (dec.counts) {
    toast(`Ajustes TikFinity: ${dec.counts.alertas || 0} sonidos, ${dec.counts.videos || 0} videos, ${dec.counts.interacciones || 0} acciones`, 'ok');
  }
  if (Array.isArray(applied.result?.pointsUsers) && applied.result.pointsUsers.length) {
    send({ action: 'importPointsBulk', users: applied.result.pointsUsers, mode });
  }
  // Sembrar selector "Elegir sticker" con IDs del .tfc.
  try {
    const fromDec = Array.isArray(dec.emotes) ? dec.emotes : [];
    const fromSettings = collectEmotesFromLivecoinsSettings(settings);
    seedEmoteCatalogFromImport([...fromDec, ...fromSettings]);
  } catch {}
  const channelForCloud = String(dec.sourceChannelId || ans.channelId || '').trim();
  // Complementar con Actions de la nube (pueden tener más audios que el .tfc del perfil).
  if (/^\d+$/.test(channelForCloud)) {
    try {
      await importTikfinityCloudSettingsFlow(channelForCloud, { replace: false });
    } catch {}
    send({ action: 'importTikfinityPoints', channelId: channelForCloud, mode });
  } else {
    send({ action: 'importTikfinityPoints', channelId: ans.channelId, mode });
  }
  try {
    const nav = document.querySelector('[data-view="alertas"]') || document.querySelector('[data-view="points"]');
    if (nav) nav.click();
  } catch {}
  if (typeof window.setPtsTfStatus === 'function') {
    window.setPtsTfStatus('Importados ajustes del .tfc (+ nube si había más).');
  }
  return true;
}

function handle(type, p) {
  if (type === 'ttsClaimResult') { onTtsClaimResult(p); return; }
  if (type === 'ttsClaimed') { onTtsClaimed(p); return; }
  if (type === 'liveLockDenied') { showLiveLockDenied(p?.message); return; }
  switch (type) {
    case 'state': renderState(p); break;
    case 'followerCounter':
      updateConnectAvatar({ photo: p.photo, nickname: p.nickname, username: p.uniqueId });
      break;
    case 'settings': onSettings(p); break;
    case 'screens':
      if (!relayActive()) onScreens(p);
      refreshLevelVideoScreenLink();
      break;
    case 'chat': addChat(p); noteChatMod(p); void ttsSpeak(p); maybeForwardSpotifyChat(p); maybeForwardMusicChat(p); break;
    case 'botReply': handleBotReply(p); break;
    case 'streamDeckCmd': onStreamDeckCmd(p); break;
    case 'gift': addGift(p); ttsTrackChatUser(p); ttsOnGift(p); relayRepoOnGift(p); relayL4dOnGift(p); relayUnturnedOnGift(p); relayGtavKothOnGift(p); relayGtavChaosOnGift(p); relayGtavChiliadOnGift(p); relayMslugOnGift(p); relayCtrOnGift(p); relaySmwOnGift(p); break;
    case 'screenFx': if (typeof onScreenFxEvent === 'function') onScreenFxEvent(p); break;
    case 'screenFxStop': if (typeof stopScreenFxLocal === 'function') stopScreenFxLocal(); break;
    case 'like': ttsTrackChatUser(p); ttsOnLike(p); relayRepoOnLike(p); relayL4dOnLike(p); relayUnturnedOnLike(p); relayGtavKothOnLike(p); relayGtavChaosOnLike(p); relayGtavChiliadOnLike(p); relayMslugOnLike(p); relayCtrOnLike(p); relaySmwOnLike(p); break;
    case 'member': addEvent(`🙋 ${p.nickname} entró`, ''); ttsTrackChatUser(p); break;
    case 'follow': addEvent(`➕ ${p.nickname} te siguió`, 'ok'); ttsTrackChatUser(p); ttsOnFollow(p); relayGtavKothOnFollow(p); relayGtavChaosOnFollow(p); relayGtavChiliadOnFollow(p); break;
    case 'share': addEvent(`🔁 ${p.nickname} compartió el live`, 'ok'); ttsTrackChatUser(p); ttsOnShare(p); relayGtavKothOnShare(p); relayGtavChaosOnShare(p); relayGtavChiliadOnShare(p); break;
    case 'subscribe': break;
    case 'fan': addEvent(`💛 ${p.nickname || p.uniqueId || 'Alguien'} se hizo Fan`, 'ok'); break;
    case 'superfan': break;
    case 'superfanjoin': break;
    case 'log':
      addEvent(p.text, p.level === 'ok' ? 'ok' : p.level === 'error' ? 'error' : '');
      break;
    case 'liveSummary': onLiveSummary(p); break;
    case 'liveSummaries': onLiveSummaries(p); break;
    case 'discordResult': onDiscordResult(p); break;
    case 'sound': playPanelSound(p); break;
    case 'stopSound': stopPanelSoundById(p?.id); break;
    case 'media':
      // Con relay el servidor ya manda playMedia a la PC. Reenviar 'media' aquí
      // encola el mismo clip 2 veces en video.html local.
      break;
    case 'studioMedia':
      try { window.__overlayStudioMedia?.(p); } catch {}
      break;
    case 'studioStopMedia':
      try { window.__overlayStudioStop?.(p?.screen); } catch {}
      break;
    case 'stopMedia':
      // Con relay el stop llega por stopMediaLocal (igual que playMedia).
      break;
    case 'panic':
      stopPanelSounds();
      if (typeof ttsHardStop === 'function') ttsHardStop();
      if (typeof bumpLocalGamePanic === 'function') bumpLocalGamePanic();
      if (IS_DESKTOP && window.desktopAPI?.bumpMcPanic) {
        window.desktopAPI.bumpMcPanic().catch(() => {});
      }
      // Con relay el panic local llega por panicLocal (evitar doble).
      break;
    case 'timer': renderTimerState(p); break;
    case 'timerBeep': break;
    case 'pointsList': onPointsList(p); break;
    case 'pointsUpdate': onPointsUpdate(p); break;
    case 'sorteosVidasPlayers': if (typeof window.renderSorteosVidasPeople === 'function') window.renderSorteosVidasPeople(p); break;
    case 'fanLevelState': if (typeof window.onFanLevelState === 'function') window.onFanLevelState(p); break;
    case 'fanLevelUp': if (typeof window.onFanLevelState === 'function') {
      const cur = Array.isArray(settings?.fanLevelOverlay?.entries) ? settings.fanLevelOverlay.entries.slice() : [];
      if (p && p.username) {
        const want = String(p.username).replace(/^@+/, '').toLowerCase();
        const i = cur.findIndex((e) => String(e?.username || '').replace(/^@+/, '').toLowerCase() === want);
        if (i >= 0) cur[i] = { ...cur[i], ...p };
        else cur.unshift(p);
        if (settings?.fanLevelOverlay) settings.fanLevelOverlay.entries = cur;
      }
      window.onFanLevelState({ entries: settings?.fanLevelOverlay?.entries || cur });
    } break;
    case 'donorLevelState': if (typeof window.onDonorLevelState === 'function') window.onDonorLevelState(p); break;
    case 'donorLevelUp': if (typeof window.onDonorLevelState === 'function') {
      const cur = Array.isArray(settings?.donorLevelOverlay?.entries) ? settings.donorLevelOverlay.entries.slice() : [];
      if (p && p.username) {
        const want = String(p.username).replace(/^@+/, '').toLowerCase();
        const i = cur.findIndex((e) => String(e?.username || '').replace(/^@+/, '').toLowerCase() === want);
        if (i >= 0) cur[i] = { ...cur[i], ...p };
        else cur.unshift(p);
        if (settings?.donorLevelOverlay) settings.donorLevelOverlay.entries = cur;
      }
      window.onDonorLevelState({ entries: settings?.donorLevelOverlay?.entries || cur });
    } break;
    case 'giftSentState': if (typeof window.onGiftSentState === 'function') window.onGiftSentState(p); break;
    case 'giftSentUp': if (typeof window.onGiftSentState === 'function') {
      const cur = Array.isArray(settings?.giftSentOverlay?.entries) ? settings.giftSentOverlay.entries.slice() : [];
      if (p && (p.username || p.id)) {
        const stack = !!(settings?.giftSentOverlay?.stackSameUser) || !!p.manual;
        const id = String(p.id || '').trim();
        let i = -1;
        if (id) i = cur.findIndex((e) => String(e?.id || '') === id);
        if (i < 0 && !stack) {
          const want = String(p.username || '').replace(/^@+/, '').toLowerCase();
          i = cur.findIndex((e) => !e?.manual && String(e?.username || '').replace(/^@+/, '').toLowerCase() === want);
        }
        if (i >= 0) cur[i] = { ...cur[i], ...p };
        else cur.unshift(p);
        if (settings?.giftSentOverlay) settings.giftSentOverlay.entries = cur;
      }
      window.onGiftSentState({ entries: settings?.giftSentOverlay?.entries || cur });
    } break;
    case 'pointsTx': onPointsTx(p); break;
    case 'pointsImportResult': onPointsImportResult(p); break;
    case 'tikfinityDecryptResult': onTikfinityDecryptResult(p); break;
    case 'tikfinityCloudSettingsResult': onTikfinityCloudSettingsResult(p); break;
    case 'spotifyHistory': if (typeof renderSpotifyHistory === 'function') renderSpotifyHistory(p.history || []); break;
    case 'spotifyQueue': break;
    case 'spotifyNowPlaying':
      try { if (typeof onSpotifyNowPlayingWs === 'function') onSpotifyNowPlayingWs(p); } catch {}
      break;
    case 'spotifyCommand': break;
    case 'youtubeState': if (typeof paintYoutubeState === 'function') paintYoutubeState(p); break;
    case 'youtubeProgress': if (typeof onYoutubeProgress === 'function') onYoutubeProgress(p); break;
    case 'youtubeSeek': if (typeof onYoutubeSeek === 'function') onYoutubeSeek(p); break;
    case 'musicState': if (typeof handleMusicWs === 'function') handleMusicWs('musicState', p); break;
    case 'queueUpdated': if (typeof handleMusicWs === 'function') handleMusicWs('queueUpdated', p); break;
    case 'currentSongUpdated': if (typeof handleMusicWs === 'function') handleMusicWs('currentSongUpdated', p); break;
    case 'creditsUpdated': if (typeof handleMusicWs === 'function') handleMusicWs('creditsUpdated', p); break;
    case 'songAdded': case 'songStarted': case 'songFinished': case 'songSkipped':
    case 'queueCleared': case 'playerPaused': case 'playerResumed': case 'playerStopped':
    case 'musicAlert':
      if (typeof handleMusicWs === 'function') handleMusicWs(m.type, p);
      break;
    case 'caps': setCaps(p); loadPlanComparison(true); break;
    case 'badges':
      try {
        if (Array.isArray(p.badges)) renderHomeBadges(p.badges);
        else if (Array.isArray(p)) renderHomeBadges(p);
      } catch { /* ignore */ }
      break;
    case 'keyAction': onKeyAction(p); break;
    case 'actionTts': onActionTts(p); break;
    case 'localExec': onLocalExec(p); break;
    case 'playLevelVideo':
      if (IS_DESKTOP) testLevelVideoLocal(Number(p?.level) || 1, { quiet: true });
      break;
    case 'playMedia': {
      // Prueba de video de nivel en relay: ya lo reprodujimos por la API local;
      // ignorar el eco de la nube para no verlo dos veces.
      const mark = window.__localLevelTestMark;
      if (mark && p?.id && p.id === mark.id && Date.now() - mark.at < 10000) {
        window.__localLevelTestMark = null;
        break;
      }
      if (IS_DESKTOP && (relayActive() || desktopRelayOn())) postLocalMedia('media', { media: p });
      try { window.__overlayStudioMedia?.(p); } catch {}
      break;
    }
    case 'stopMediaLocal':
      if (IS_DESKTOP && (relayActive() || desktopRelayOn())) postLocalMedia('stop', { screen: Number(p?.screen) || 1 });
      try { window.__overlayStudioStop?.(Number(p?.screen) || 1); } catch {}
      break;
    case 'panicLocal':
      if (typeof bumpLocalGamePanic === 'function') bumpLocalGamePanic();
      if (IS_DESKTOP && (relayActive() || desktopRelayOn())) postLocalMedia('panic');
      break;
    case 'localReady': break; // canal relay listo (no requiere acción en la UI)
    case 'profiles': onProfiles(p); break;
    case 'profilesFull': onProfilesFull(p); break;
    case 'baileRondaState':
    case 'baileRondaStart':
      try { window.__onBaileSnap?.(p); } catch {}
      break;
    case 'emoteCatalog':
      emoteCatalog = p.results || [];
      if (!$('emoteModal').classList.contains('hidden')) renderEmoteGrid();
      if ($('accEmoteMenu') && !$('accEmoteMenu').hidden) {
        emoteTarget = 'acc';
        renderEmoteGrid();
      }
      // Refresca los iconos solo si hay alertas/videos con sticker (para que ahora
      // muestren la imagen del sticker en vez del emoji), sin re-render innecesario.
      if (settings) {
        if ((settings.soundAlerts || []).some((a) => isEmoteEvent(a.trigger) && !a.emoteImage)) renderSoundAlerts();
        if ((settings.videos || []).some((v) => isEmoteEvent(v.trigger) && !v.emoteImage)) renderVideos();
      }
      if ($('saTrigMenu') && !$('saTrigMenu').hidden && saTrigMenuAlertId) {
        fillSaTrigMenu(saTrigMenuAlertId, $('saTrigMenuQ')?.value || '');
      }
      break;
    case 'communityGiftCatalog':
      communityGiftCatalog = p.results || [];
      giftCommunityFetchedAt = Date.now();
      if (!$('giftModal').classList.contains('hidden')) {
        giftCatalog = mergeGiftCatalogWithCommunity(giftCatalog, communityGiftCatalog);
        giftCommunityMerged = true;
        indexGiftCatalog();
        renderGiftGrid($('gift-q').value.trim());
      }
      break;
  }
}

/* ====================== Sonido en el panel ====================== */
// Con la cola activada, los sonidos del panel se reproducen uno tras otro (no se solapan).
const panelSounds = new Set();
let panelSoundQueue = [];
let panelSoundBusy = false;
/** Audios de Juegos en modo «Reiniciar en racha»: un Audio reutilizado por id (seek a 0 = corte al instante). */
const gameRestartAudios = new Map();

function playGameRestartSound(s) {
  if (!s?.sound) return;
  const key = String(s.id != null && s.id !== '' ? s.id : s.sound);
  const src = mediaUrl(s.sound);
  let audio = gameRestartAudios.get(key);
  if (!audio || audio._lcSrc !== src) {
    try { audio?.pause(); } catch {}
    audio = new Audio();
    audio.preload = 'auto';
    audio._lcSrc = src;
    audio.src = src;
    try { audio.load(); } catch {}
    gameRestartAudios.set(key, audio);
  }
  applyMediaVolume(audio, s.volume ?? 100);
  // Sacarlo de la cola normal por si había copias encoladas del mismo id.
  if (s.id != null && s.id !== '') {
    const want = String(s.id);
    panelSoundQueue = panelSoundQueue.filter((x) => String(x?.id || '') !== want);
    for (const a of [...panelSounds]) {
      if (String(a.dataset?.soundId || '') !== want) continue;
      try { a.pause(); a.currentTime = 0; } catch {}
      if (typeof a._panelFinish === 'function') a._panelFinish();
      else panelSounds.delete(a);
    }
  }
  try {
    audio.pause();
    audio.currentTime = 0;
  } catch {}
  const p = audio.play();
  if (p && typeof p.catch === 'function') {
    p.catch(() => {
      addEvent('🔇 El navegador bloqueó el audio. Haz clic en cualquier parte del panel para activarlo.', 'error');
    });
  }
}

function stopGameRestartSounds(id) {
  if (id == null || id === '') {
    for (const a of gameRestartAudios.values()) {
      try { a.pause(); a.currentTime = 0; } catch {}
    }
    return;
  }
  const want = String(id);
  const a = gameRestartAudios.get(want);
  if (!a) return;
  try { a.pause(); a.currentTime = 0; } catch {}
}

function playPanelSound(s) {
  if (!s?.sound) return;
  // Sonidos de Juegos con «Reiniciar en racha»: mismo clip, seek a 0 (como Streamtoearn).
  // No encola. No afecta alertas de Sonidos.
  if (s.restart) {
    playGameRestartSound(s);
    return;
  }
  const queueOn = settings?.playback?.playQueue !== false && s.playQueue !== false && !s.webhookToggle;
  if (!queueOn) { startPanelSound(s, null); return; }
  panelSoundQueue.push(s);
  pumpPanelSound();
}
/** Encola sonidos sí o sí (prueba de racha en Juegos), sin mirar la cola global. */
function enqueuePanelSounds(list) {
  if (!Array.isArray(list) || !list.length) return;
  for (const s of list) {
    if (s?.sound) panelSoundQueue.push(s);
  }
  pumpPanelSound();
}
function pumpPanelSound() {
  if (panelSoundBusy) return;
  const s = panelSoundQueue.shift();
  if (!s) return;
  panelSoundBusy = true;
  startPanelSound(s, () => { panelSoundBusy = false; pumpPanelSound(); });
}
function reportSoundEnded(id) {
  if (!id) return;
  const msg = JSON.stringify({ action: 'soundEnded', id });
  try {
    if (localWs?.readyState === WebSocket.OPEN) localWs.send(msg);
    else if (ws?.readyState === WebSocket.OPEN) ws.send(msg);
  } catch {}
}
function startPanelSound(s, done) {
  const audio = new Audio();
  applyMediaVolume(audio, s.volume ?? 100);
  audio.src = mediaUrl(s.sound);
  if (s.id != null) audio.dataset.soundId = String(s.id);
  panelSounds.add(audio);
  let finished = false;
  let safety = null;
  const finish = () => {
    if (finished) return;
    finished = true;
    if (safety) { clearTimeout(safety); safety = null; }
    panelSounds.delete(audio);
    if (s?.id) reportSoundEnded(s.id);
    done?.();
  };
  // Cierre limpio desde stopPanelSoundById/stopPanelSounds: marca terminado y
  // cancela el timer de seguridad (si quedara vivo, 20 s después re-bombea la cola
  // y puede solapar el siguiente sonido).
  audio._panelFinish = finish;
  audio.onended = finish;
  audio.onerror = () => { addEvent(`⚠️ No se pudo reproducir: ${s.name || s.sound}`, 'error'); finish(); };
  safety = setTimeout(finish, 20000);
  // Con la duración real, ajustar el tope: un audio de >20 s ya no se corta en la
  // cola (antes el timer fijo avanzaba la cola y solapaba el siguiente sonido).
  audio.onloadedmetadata = () => {
    try {
      const d = Number(audio.duration);
      if (Number.isFinite(d) && d > 0) {
        if (safety) clearTimeout(safety);
        safety = setTimeout(finish, d * 1000 + 2000);
      }
    } catch {}
  };
  audio.play().catch(() => {
    addEvent('🔇 El navegador bloqueó el audio. Haz clic en cualquier parte del panel para activarlo.', 'error');
    finish();
  });
}
function stopPanelSoundById(id) {
  if (id == null || id === '') { stopPanelSounds(); return; }
  const want = String(id);
  stopGameRestartSounds(want);
  panelSoundQueue = panelSoundQueue.filter((s) => String(s?.id || '') !== want);
  let stoppedPlaying = false;
  for (const a of [...panelSounds]) {
    if (String(a.dataset?.soundId || '') !== want) continue;
    try { a.pause(); a.currentTime = 0; } catch {}
    stoppedPlaying = true;
    if (typeof a._panelFinish === 'function') a._panelFinish();
    else panelSounds.delete(a);
  }
  // Si solo estaba en cola (no sonando), el finish no corrió: reportamos aquí.
  if (!stoppedPlaying) reportSoundEnded(want);
  if (!panelSounds.size) panelSoundBusy = false;
  pumpPanelSound();
}
function stopPanelSounds() {
  panelSoundQueue = [];
  try { window.__stopGameAudioTest?.(); } catch {}
  stopGameRestartSounds();
  panelSounds.forEach((a) => {
    try { a.pause(); a.currentTime = 0; } catch {}
    try { if (typeof a._panelFinish === 'function') a._panelFinish(); } catch {}
  });
  panelSounds.clear();
  panelSoundBusy = false;
}

/** Detiene videos, sonidos, TTS, cola MC y acciones de Acciones y Eventos en curso. */
function triggerAlertPanic() {
  try { previewAudio?.pause(); } catch {}
  stopPanelSounds();
  if (typeof ttsHardStop === 'function') ttsHardStop();
  if (typeof bumpLocalGamePanic === 'function') bumpLocalGamePanic();
  if (IS_DESKTOP && window.desktopAPI?.bumpMcPanic) {
    window.desktopAPI.bumpMcPanic().catch(() => {});
  }
  send({ action: 'panic' });
  toast('⛔ Pánico: Minecraft, videos, sonidos, TTS y acciones detenidos', 'warn');
}

/* ====================== Lazy embed previews (overlays) ====================== */
/** Evita cargar ~40 iframes embed al abrir el panel; se hidratan al entrar a la pestaña
 *  y se DESCARGAN al salir (Matter.js + imágenes dejan de comer RAM).
 *  Perf: 1 iframe a la vez + gap mayor + rootMargin corto = entrar a Overlays más fluido. */
const embedLoadQueue = [];
let embedLoadBusy = false;
const EMBED_LOAD_GAP_MS = 160;
const EMBED_HYDRATE_DELAY_MS = 120;
const EMBED_IO_ROOT_MARGIN = '48px 0px';
const EMBED_UNLOAD_IDLE_MS = 1600;

function embedWantSrc(fr) {
  return (fr && (fr.dataset.src || fr.getAttribute('data-src'))) || '';
}

/** Previews que no deben auto-descargarse (Matter.js / tinte-arcoíris parpadean al rehidratar). */
function embedKeepAlive(fr) {
  if (!fr) return false;
  const id = String(fr.id || '');
  if (id.startsWith('tk-preview')) return true;
  if (fr.classList?.contains('tk-preview') || fr.closest?.('.tk-preview')) return true;
  if (/^(jar|vaq|mar|perr|ghl|pel)-preview$/.test(id)) return true;
  if (/^(brk|brd|bco)-preview$/.test(id)) return true;
  if (id === 'yt-overlay-preview' || id === 'sp-overlay-preview') return true;
  return false;
}

/** Previews pesados: no hidratar al scrollear; solo al pulsar Test. */
function embedSkipAutoHydrate(fr) {
  if (!fr) return false;
  if (fr.dataset.embedManual === '1') return true;
  return String(fr.id || '') === 'bgb-preview';
}

function unloadEmbed(fr) {
  if (!fr || !embedWantSrc(fr)) return;
  clearTimeout(fr._embedUnloadTimer);
  fr._embedUnloadTimer = null;
  const qi = embedLoadQueue.indexOf(fr);
  if (qi >= 0) embedLoadQueue.splice(qi, 1);
  try {
    fr.src = 'about:blank';
  } catch {}
  try { fr.removeAttribute('src'); } catch {}
  delete fr.dataset.embedReady;
  delete fr.dataset.embedQueued;
}

function unloadViewEmbeds(view) {
  if (!view) return;
  if (view._embedObs) {
    try { view._embedObs.disconnect(); } catch {}
    view._embedObs = null;
  }
  view.querySelectorAll('iframe[data-src]').forEach((fr) => {
    if (embedKeepAlive(fr)) return;
    unloadEmbed(fr);
  });
}

/** Libera previews de overlays que ya no están la vista activa. */
function releaseOverlayEmbedsForNav(nextViewId) {
  const nextId = String(nextViewId || '').startsWith('view-')
    ? String(nextViewId)
    : (nextViewId ? `view-${nextViewId}` : '');
  document.querySelectorAll('section.view[id^="view-ov-"], #view-editor-overlays').forEach((view) => {
    if (nextId && view.id === nextId) return;
    unloadViewEmbeds(view);
  });
}

function ensureEmbedLoaded(frOrId) {
  const fr = typeof frOrId === 'string' ? $(frOrId) : frOrId;
  return new Promise((resolve) => {
    if (!fr) { resolve(null); return; }
    const want = embedWantSrc(fr);
    if (!want) { resolve(fr); return; }
    if (fr.dataset.embedReady === '1' && fr.getAttribute('src') && fr.getAttribute('src') !== 'about:blank') {
      resolve(fr);
      return;
    }
    const finish = () => {
      fr.dataset.embedReady = '1';
      resolve(fr);
    };
    const cur = fr.getAttribute('src');
    if (cur && cur !== 'about:blank') {
      try {
        if (fr.contentDocument?.readyState === 'complete') { finish(); return; }
      } catch { /* cross-origin or empty */ }
      fr.addEventListener('load', finish, { once: true });
      setTimeout(finish, 8000);
      return;
    }
    const onLoad = () => {
      fr.removeEventListener('load', onLoad);
      finish();
    };
    fr.addEventListener('load', onLoad);
    fr.src = want;
    setTimeout(() => { fr.removeEventListener('load', onLoad); finish(); }, 8000);
  });
}

function pumpEmbedLoadQueue() {
  if (embedLoadBusy) return;
  const fr = embedLoadQueue.shift();
  if (!fr) return;
  // Si ya no está en una vista activa, no cargar (evita trabajo al cambiar de pestaña rápido).
  const hostView = fr.closest?.('section.view');
  if (hostView && !hostView.classList.contains('active')) {
    delete fr.dataset.embedQueued;
    setTimeout(pumpEmbedLoadQueue, 0);
    return;
  }
  embedLoadBusy = true;
  ensureEmbedLoaded(fr).finally(() => {
    embedLoadBusy = false;
    setTimeout(pumpEmbedLoadQueue, EMBED_LOAD_GAP_MS);
  });
}

function queueEmbedLoad(fr) {
  if (!fr || fr.dataset.embedQueued === '1') return;
  fr.dataset.embedQueued = '1';
  embedLoadQueue.push(fr);
  pumpEmbedLoadQueue();
}

function hydrateViewEmbeds(view) {
  if (!view) return;
  let frames = view.querySelectorAll('iframe[data-src]');
  if (!frames.length) return;
  if (view.id === 'view-ov-baile') {
    if (typeof baileOverlayUnlocked === 'function' && !baileOverlayUnlocked()) return;
    const list = Array.from(frames).filter((fr) => !embedSkipAutoHydrate(fr));
    Promise.all(list.map((fr) => ensureEmbedLoaded(fr))).then(() => {
      try { window.__syncBailePeople?.(); } catch {}
    });
  }
  if (typeof IntersectionObserver !== 'function') {
    // Fallback: solo el primero visible-ish; el resto al hacer Testear (ensureEmbedLoaded).
    const list = Array.from(frames);
    list.filter((fr) => !embedSkipAutoHydrate(fr)).slice(0, 1).forEach((fr) => queueEmbedLoad(fr));
    return;
  }
  if (!view._embedObs) {
    view._embedObs = new IntersectionObserver((entries) => {
      for (const e of entries) {
        const fr = e.target;
        if (e.isIntersecting) {
          clearTimeout(fr._embedUnloadTimer);
          fr._embedUnloadTimer = null;
          if (!embedSkipAutoHydrate(fr)) queueEmbedLoad(fr);
          continue;
        }
        // Fuera de pantalla: liberar Matter/imágenes tras un momento (evita thrash al scrollear).
        // Excepciones: top kills + botes (jarrón/vaquita/…) — al rehidratar parpadeaba tinte/arcoíris y escala.
        if (embedKeepAlive(fr)) continue;
        if (!(fr.dataset.embedReady === '1' || (fr.getAttribute('src') && fr.getAttribute('src') !== 'about:blank'))) continue;
        clearTimeout(fr._embedUnloadTimer);
        fr._embedUnloadTimer = setTimeout(() => {
          fr._embedUnloadTimer = null;
          if (!fr.isConnected || !view.classList.contains('active')) return;
          const r = fr.getBoundingClientRect();
          const margin = 120;
          if (r.bottom < -margin || r.top > window.innerHeight + margin) {
            unloadEmbed(fr);
            try { view._embedObs.observe(fr); } catch {}
          }
        }, EMBED_UNLOAD_IDLE_MS);
      }
    }, { root: null, rootMargin: EMBED_IO_ROOT_MARGIN, threshold: 0.02 });
  }
  frames.forEach((fr) => {
    try { view._embedObs.observe(fr); } catch {}
  });
}

function onOverlayNavShown(viewSlugOrId) {
  const id = String(viewSlugOrId || '').startsWith('view-')
    ? viewSlugOrId
    : `view-${viewSlugOrId}`;
  releaseOverlayEmbedsForNav(id);
  if (id === 'view-editor-overlays') {
    if (typeof overlayStudioUnlocked === 'function' && !overlayStudioUnlocked()) return;
    requestAnimationFrame(() => {
      setTimeout(() => {
        try { window.__overlayStudioHydrate?.(); } catch {}
      }, EMBED_HYDRATE_DELAY_MS);
    });
    return;
  }
  if (!String(id).startsWith('view-ov-')) return;
  // Pintar UI primero; luego hidratar embeds (1 a la vez).
    const delay = id === 'view-ov-baile' ? 0 : EMBED_HYDRATE_DELAY_MS;
    requestAnimationFrame(() => {
      setTimeout(() => hydrateViewEmbeds(document.getElementById(id)), delay);
    });
}

/* ====================== Navegación lateral ====================== */
function pulseDockNav(btn) {
  if (!btn) return;
  document.querySelectorAll('.nav-item.dock-bounce').forEach((b) => b.classList.remove('dock-bounce'));
  btn.classList.remove('dock-bounce');
  void btn.offsetWidth;
  btn.classList.add('dock-bounce');
  try { btn.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' }); } catch {}
  clearTimeout(pulseDockNav._t);
  pulseDockNav._t = setTimeout(() => btn.classList.remove('dock-bounce'), 480);
}

document.getElementById('dockLogo')?.addEventListener('click', (e) => {
  e.preventDefault();
  document.querySelector('.nav-item[data-view="panel"]')?.click();
});

document.querySelectorAll('.nav-item').forEach((btn) => {
  btn.onclick = () => {
    document.querySelectorAll('.nav-item').forEach((b) => b.classList.remove('active'));
    document.querySelectorAll('.view').forEach((v) => v.classList.remove('active'));
    btn.classList.add('active');
    const view = document.getElementById(`view-${btn.dataset.view}`);
    if (!view) { console.error('Vista no encontrada:', btn.dataset.view); return; }
    // CSS del juego + override moderno ANTES de pintar (evitar flash del diseño temático).
    const viewName = btn.dataset.view;
    if (String(viewName || '').startsWith('juego-')) {
      try {
        const gk = String(viewName).replace(/^juego-/, '');
        if (typeof window.__lcLoadGameProCssFor === 'function') window.__lcLoadGameProCssFor(gk);
        else if (typeof window.__lcLoadGameProCss === 'function') window.__lcLoadGameProCss();
      } catch {}
      try { loadDashboardGames(); } catch {}
    }
    if (viewName === 'acciones' || viewName === 'juegos') {
      try { loadDashboardGames(); } catch {}
    }
    if (viewName === 'editor-rapido') {
      try { ensureEditorRapidoUi(); } catch {}
    }
    if (viewName === 'editor-overlays') {
      try { ensureOverlayStudioUi(); } catch {}
    }
    if (viewName === 'editor') {
      try { ensureImageEditorUi(); } catch {}
    }
    view.classList.add('active');
    // Pintar la pestaña ya; el resto (pulse / init pesado) en el siguiente frame.
    const flyoutEl = btn.closest('.nav-flyout');
    requestAnimationFrame(() => {
      try { pulseDockNav(btn); } catch {}
      closeNavFlyouts({ suppressEl: flyoutEl });
      onOverlayNavShown(viewName);
      const runHeavy = async () => {
        if (viewName === 'juegos' || viewName === 'acciones' || String(viewName || '').startsWith('juego-')) {
          try { await loadDashboardGames(); } catch (e) { console.warn('dashboard-games', e); }
        }
        if (String(viewName || '').startsWith('juego-')) {
          const gk = String(viewName).replace(/^juego-/, '');
          try { await ensureGameUi(gk); } catch (e) { console.warn('ensureGameUi', gk, e); }
        }
        if (viewName === 'juegos') {
          try { preloadJuegosCatalogImages(); } catch {}
        }
        if (viewName === 'admin') { loadAdminUsers(); loadPlans(); loadAppVersion(); loadPcInstallLink(); loadAdminSpotify(); loadAdminBaileOverlay(); loadAdminGames(); loadAdminGameStatus(); }
        if (viewName === 'planes') { renderPlanView(); loadPlanComparison(true); }
        if (viewName === 'regalos') { try { initGiftCatalogView(); } catch (e) { console.error('Catálogo regalos:', e); } }
        if (viewName === 'editor') {
          try { await ensureImageEditorUi(); initImageEditorView(); } catch (e) { console.error('Editor:', e); }
        }
        if (viewName === 'editor-rapido') {
          try { applyEditorRapidoLock(); } catch {}
          if (typeof editorRapidoUnlocked === 'function' && !editorRapidoUnlocked()) {
            toast('Editor Pro es Solo Premium (VIP / Founder) ⭐', 'warn');
          } else {
            try { await ensureEditorRapidoUi(); initEditorRapidoView(); } catch (e) { console.error('Editor Pro:', e); }
          }
        }
        if (viewName === 'editor-overlays') {
          try { applyOverlayStudioLock(); } catch {}
          if (typeof overlayStudioUnlocked === 'function' && !overlayStudioUnlocked()) {
            toast('Editor de overlays es Solo Premium (VIP / Founder) ⭐', 'warn');
          } else {
            try { await ensureOverlayStudioUi(); window.__setupOverlayStudio?.(); } catch (e) { console.error('Editor overlays:', e); }
          }
        }
        if (viewName === 'ov-baile') {
          try { applyBaileOverlayLock(); } catch {}
          if (typeof baileOverlayUnlocked === 'function' && !baileOverlayUnlocked()) {
            toast('Agencia de baile es solo para cuentas autorizadas 🔒', 'warn');
          }
        }
        if (viewName === 'points') { send({ action: 'getPoints' }); renderPointsTable({ resetPage: true }); }
        if (viewName === 'spotify') { try { setupSpotifyUI(); applySpotifyLock(); refreshSpotifyStatus(); } catch (e) { console.error('Spotify UI:', e); } }
        if (viewName === 'youtube') { try { setupYoutubeUI(); } catch (e) { console.error('YouTube UI:', e); } }
        if (viewName === 'webhook') { try { setupWebhookUI(); } catch (e) { console.error('Webhook UI:', e); } }
        if (viewName === 'configuracion') {
          try { setupWebhookUI(); applyWebhookUI(); } catch (e) { console.error('Configuración UI:', e); }
          try { setupDiscordUI(); } catch (e) { console.error('Discord UI:', e); }
          try { setupAccountUsername(); } catch (e) { console.error('Cuenta:', e); }
        }
        if (viewName === 'acciones') {
          try { setupAccionesUI(); } catch (e) { console.error('Acciones UI:', e); }
          try { if (typeof wireGamePresetBar === 'function') wireGamePresetBar('acciones'); } catch (e) { console.error('[preset] acciones', e); }
          try { if (typeof wireAccInteractivePanel === 'function') wireAccInteractivePanel(); } catch (e) { console.error('[interactive] acciones', e); }
          try { if (typeof renderAcciones === 'function') renderAcciones(); } catch (e) { console.error('Acciones UI:', e); }
        }
      };
      if (typeof requestIdleCallback === 'function') requestIdleCallback(runHeavy, { timeout: 120 });
      else setTimeout(runHeavy, 0);
    });
  };
});

/* Flyouts (Overlays / Acciones y eventos): hover fiable, sin estados trabados */
function closeNavFlyouts(opts) {
  const except = opts && opts.except;
  const suppressEl = opts && opts.suppressEl;
  document.querySelectorAll('.nav-flyout').forEach((f) => {
    if (except && f === except) return;
    const st = f._flyoutState;
    if (st) {
      if (suppressEl && f === suppressEl) st.suppress = true;
      st.close();
    } else {
      f.classList.remove('is-open', 'is-forced-closed');
      f.querySelector('.nav-flyout-btn')?.setAttribute('aria-expanded', 'false');
    }
  });
}

document.querySelectorAll('.nav-flyout').forEach((fly) => {
  const btn = fly.querySelector('.nav-flyout-btn');
  const menu = fly.querySelector('.nav-flyout-menu');
  if (!btn) return;

  // Tooltip cuando el texto se oculta en pantallas chicas
  const label = btn.querySelector('span:not(.nav-flyout-caret)')?.textContent?.trim();
  if (label && !btn.title) btn.title = label;

  const placeMenu = () => {
    if (!menu) return;
    const r = btn.getBoundingClientRect();
    const mw = Math.max(menu.offsetWidth || 220, 220);
    const left = Math.max(8, Math.min(r.left, window.innerWidth - mw - 8));
    menu.classList.add('is-dock-fixed');
    menu.style.top = `${Math.round(r.bottom + 6)}px`;
    menu.style.left = `${Math.round(left)}px`;
  };
  const clearMenuPos = () => {
    if (!menu) return;
    menu.classList.remove('is-dock-fixed');
    menu.style.top = '';
    menu.style.left = '';
  };

  const state = {
    suppress: false,
    closeTimer: null,
    open() {
      if (state.suppress) return;
      if (state.closeTimer) {
        clearTimeout(state.closeTimer);
        state.closeTimer = null;
      }
      closeNavFlyouts({ except: fly });
      fly.classList.add('is-open');
      fly.classList.remove('is-forced-closed');
      btn.setAttribute('aria-expanded', 'true');
      requestAnimationFrame(placeMenu);
    },
    close() {
      if (state.closeTimer) {
        clearTimeout(state.closeTimer);
        state.closeTimer = null;
      }
      fly.classList.remove('is-open', 'is-forced-closed');
      btn.setAttribute('aria-expanded', 'false');
      clearMenuPos();
    },
    closeSoon() {
      if (state.closeTimer) clearTimeout(state.closeTimer);
      state.closeTimer = setTimeout(() => {
        state.closeTimer = null;
        if (!fly.matches(':hover')) state.close();
      }, 160);
    },
  };
  fly._flyoutState = state;

  btn.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (fly.classList.contains('is-open')) state.close();
    else state.open();
  });

  fly.addEventListener('mouseenter', () => {
    if (state.closeTimer) {
      clearTimeout(state.closeTimer);
      state.closeTimer = null;
    }
    if (state.suppress) return;
    state.open();
  });

  fly.addEventListener('mouseleave', () => {
    state.suppress = false;
    state.closeSoon();
  });

  window.addEventListener('resize', () => {
    if (fly.classList.contains('is-open')) placeMenu();
  }, { passive: true });
  document.querySelector('.nav')?.addEventListener('scroll', () => {
    if (fly.classList.contains('is-open')) placeMenu();
  }, { passive: true });
});

document.addEventListener('click', (ev) => {
  if (ev.target.closest('.nav-flyout')) return;
  closeNavFlyouts();
});

