function applyFeatureFlagsUi(caps) {
  const ff = (caps && caps.featureFlags) || {};
  const panel = document.getElementById('acc-ix-panel');
  if (!panel) return;
  // Solo oculta si el admin apagó el flag explícitamente (default = visible).
  if (ff.accInteractive === false) {
    panel.hidden = true;
    panel.setAttribute('data-flag-off', '1');
  } else if (panel.getAttribute('data-flag-off')) {
    panel.hidden = false;
    panel.removeAttribute('data-flag-off');
  }
}

// "hace X" en español a partir de un timestamp.
function timeAgo(ts) {
  if (!ts) return '—';
  const s = Math.max(0, Math.floor((Date.now() - ts) / 1000));
  if (s < 60) return s <= 5 ? 'unos segundos' : `${s} s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} h`;
  const d = Math.floor(h / 24);
  return `${d} día${d === 1 ? '' : 's'}`;
}

// Insignia de plan para la tabla de admin (con días restantes o "fijo").
function planBadge(u) {
  if (u.plan === 'founder') return '<span class="badge prem">👑 Founder</span>';
  if (u.plan !== 'premium') return '<span class="badge off">Gratis</span>';
  if (u.premiumUntil && u.premiumUntil > 0) {
    const days = Math.max(0, Math.ceil((u.premiumUntil - Date.now()) / 86400000));
    return `<span class="badge prem">⭐ Premium · ${days}d</span>`;
  }
  return '<span class="badge prem">⭐ Premium · fijo</span>';
}

