/** La contraseña actual no se puede ver (hash). Genera o define una nueva y la muestra una vez. */
async function setUserPasswordReq(id, username) {
  const ok = await askConfirm({
    title: 'Contraseña del usuario',
    message: `La contraseña actual de «${username || 'usuario'}» no se puede ver (está cifrada). ¿Generar o definir una nueva? Se cerrará su sesión y verás la clave una sola vez para copiarla.`,
    confirmText: 'Continuar',
  });
  if (!ok) return;
  const typed = window.prompt(
    'Escribe la nueva contraseña, o deja vacío para generar una aleatoria:',
    '',
  );
  if (typed === null) return;
  const password = String(typed).trim();
  try {
    const r = await fetch('/api/admin/set-password', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, password: password || undefined }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok || !data.ok) {
      toast(data.error || 'No se pudo cambiar la contraseña.', 'warn');
      return;
    }
    window.prompt(
      `Nueva contraseña de «${data.username || username}» (cópiala ahora; no se volverá a mostrar):`,
      data.password || '',
    );
    toast(`Contraseña actualizada para «${data.username || username}».`, 'ok');
  } catch {
    toast('Error de conexión.', 'warn');
  }
}

const adminRefreshBtn = document.getElementById('admin-refresh');
if (adminRefreshBtn) adminRefreshBtn.onclick = loadAdminUsers;

let adminSpotifyUsersCache = [];

async function setUserSpotifyReq(id, enabled) {
  const r = await fetch('/api/admin/userspotify', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ id, enabled: !!enabled }),
  });
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data.error || 'No se pudo actualizar Spotify');
  return data;
}

function userHasSpotifyAccess(u) {
  return !!(u && (u.isAdmin || u.spotifyEnabled === true));
}

function patchAdminSpotifyCache(id, enabled) {
  const u = adminSpotifyUsersCache.find((x) => String(x.id) === String(id));
  if (u && !u.isAdmin) u.spotifyEnabled = !!enabled;
}

function renderAdminSpotifyFromCache() {
  const tbody = document.getElementById('admin-spotify-tbody');
  const sel = document.getElementById('admin-spotify-user');
  const status = document.getElementById('admin-spotify-status');
  if (!tbody) return;
  const withAccess = adminSpotifyUsersCache.filter(userHasSpotifyAccess);
  const without = adminSpotifyUsersCache.filter((u) => !userHasSpotifyAccess(u));

  if (sel) {
    const prev = sel.value;
    sel.innerHTML = '<option value="">Elegir usuario…</option>' + without
      .slice()
      .sort((a, b) => String(a.username).localeCompare(String(b.username)))
      .map((u) => `<option value="${esc(u.id)}">${esc(u.username)}</option>`)
      .join('');
    if (prev && [...sel.options].some((o) => o.value === prev)) sel.value = prev;
  }

  if (!withAccess.length) {
    tbody.innerHTML = '<tr><td colspan="3" class="admin-empty">Nadie tiene acceso todavía.</td></tr>';
  } else {
    tbody.innerHTML = withAccess
      .slice()
      .sort((a, b) => String(a.username).localeCompare(String(b.username)))
      .map((u) => {
        const tag = u.isAdmin ? '<span class="u-admin">ADMIN</span>' : '';
        const st = u.online
          ? '<span class="badge on dot">En línea</span>'
          : '<span class="tts-sub">—</span>';
        const action = u.isAdmin
          ? '<span class="tts-sub">Siempre</span>'
          : `<button type="button" class="btn tiny admin-spotify-revoke" data-id="${esc(u.id)}">Quitar acceso</button>`;
        return `<tr>
          <td><span class="u-name">${esc(u.username)}</span>${tag}</td>
          <td>${st}</td>
          <td>${action}</td>
        </tr>`;
      }).join('');
    tbody.querySelectorAll('.admin-spotify-revoke').forEach((btn) => {
      btn.onclick = async () => {
        const id = btn.dataset.id;
        btn.disabled = true;
        try {
          const data = await setUserSpotifyReq(id, false);
          // Si el servidor sigue marcándolo activo, no lo borramos de la lista.
          if (data.spotifyEnabled === true) {
            throw new Error('El servidor no quitó el acceso.');
          }
          patchAdminSpotifyCache(id, false);
          renderAdminSpotifyFromCache();
          toast('Acceso a Spotify quitado.', 'ok');
          await loadAdminSpotify();
        } catch (e) {
          toast(e.message || 'Error', 'warn');
          btn.disabled = false;
          loadAdminSpotify();
        }
      };
    });
  }
  if (status) status.textContent = `${withAccess.length} con acceso · ${without.length} sin acceso`;
}

async function loadAdminSpotify() {
  const tbody = document.getElementById('admin-spotify-tbody');
  if (!tbody) return;
  try {
    const r = await fetch('/api/admin/users');
    if (!r.ok) {
      tbody.innerHTML = '<tr><td colspan="3" class="admin-empty">Sin acceso.</td></tr>';
      return;
    }
    const { users } = await r.json();
    adminSpotifyUsersCache = Array.isArray(users) ? users : [];
    renderAdminSpotifyFromCache();
  } catch {
    tbody.innerHTML = '<tr><td colspan="3" class="admin-empty">Error al cargar.</td></tr>';
  }
}

(function setupAdminSpotifyUI() {
  const grant = document.getElementById('admin-spotify-grant');
  const refresh = document.getElementById('admin-spotify-refresh');
  const sel = document.getElementById('admin-spotify-user');
  if (grant) {
    grant.onclick = async () => {
      const id = sel?.value || '';
      if (!id) { toast('Elige un usuario.', 'warn'); return; }
      grant.disabled = true;
      try {
        await setUserSpotifyReq(id, true);
        patchAdminSpotifyCache(id, true);
        // Si no estaba en caché (recién elegido del desplegable), forzar recarga.
        if (!adminSpotifyUsersCache.some((u) => String(u.id) === String(id))) {
          await loadAdminSpotify();
        } else {
          renderAdminSpotifyFromCache();
          loadAdminSpotify();
        }
        toast('Spotify desbloqueado. Si está en línea, le aparece ya.', 'ok');
      } catch (e) {
        toast(e.message || 'Error', 'warn');
      } finally {
        grant.disabled = false;
      }
    };
  }
  if (refresh) refresh.onclick = () => loadAdminSpotify();
})();

