function refreshGameActionsUiForKeys(touched) {
  const keys = (touched || []).filter((k) => GAME_ACTION_UI_BY_KEY[k]);
  if (!keys.length) return;
  const run = () => {
    const seen = new Set();
    for (const k of keys) {
      const fn = GAME_ACTION_UI_BY_KEY[k];
      if (!fn || seen.has(k)) continue;
      seen.add(k);
      fn();
    }
  };
  const typingQty = document.activeElement && document.activeElement.matches
    && document.activeElement.matches('input.mc-qty-n, input.mc-act-cfg-count');
  if (typingQty) return;
  if (window.__lcDashboardGamesReady) run();
  else loadDashboardGames().then(run).catch(() => {});
}

