/* ====================== Videos (pantallas múltiples) ====================== */
const TT_GIFTS = [
  { name: 'Rose', d: 1 }, { name: 'GG', d: 1 }, { name: 'TikTok', d: 1 },
  { name: 'Finger Heart', d: 5 }, { name: 'Mini Gamepad', d: 5 }, { name: 'Heart Me', d: 15 },
  { name: 'Perfume', d: 20 }, { name: 'Doughnut', d: 30 }, { name: 'Hand Hearts', d: 100 },
  { name: 'Sunglasses', d: 100 }, { name: 'Galaxy', d: 1000 }, { name: 'Whale diving', d: 2150 },
  { name: 'Drama Queen', d: 5000 }, { name: 'Lion', d: 29999 }, { name: 'Universe', d: 44999 },
];
let connectedScreens = new Set();
const screenSeenAt = new Map();
/** Tras redeploy/reinicio el Browser Source tarda en reaparecer; no marcar "Sin fuente" al instante. */
const SCREEN_PRESENCE_GRACE_MS = 60000;
let vidEditingId = null;
let vidPending = null; // { url, name } — primer clip (compat)
let vidPendingClips = []; // [{ url, name }, ...]

function videoClipPool(v) {
  const items = [];
  const seen = new Set();
  const add = (url, name) => {
    const u = String(url || '').trim();
    if (!u || seen.has(u)) return;
    seen.add(u);
    items.push({ url: u, name: String(name || 'video') });
  };
  if (Array.isArray(v?.clips)) {
    for (const c of v.clips) add(c?.url, c?.name || c?.fileName);
  }
  add(v?.url, v?.fileName);
  return items;
}
function addVidClip(clip) {
  if (!clip?.url) return false;
  if (vidPendingClips.some((c) => c.url === clip.url)) return false;
  vidPendingClips.push({ url: clip.url, name: clip.name || 'video' });
  renderVidClipList();
  return true;
}
function renderVidClipList() {
  const list = $('vid-cliplist');
  const fname = $('vid-fname');
  vidPending = vidPendingClips[0] || null;
  if (fname) {
    fname.textContent = !vidPendingClips.length
      ? 'Ningún archivo'
      : (vidPendingClips.length === 1
        ? (vidPendingClips[0].name || 'video')
        : `${vidPendingClips.length} videos · cada disparo uno al azar`);
  }
  if (!list) return;
  if (!vidPendingClips.length) { list.innerHTML = ''; return; }
  list.innerHTML = vidPendingClips.map((c, i) => `
    <div class="vid-clipchip" title="${esc(c.name)}">
      <span class="vid-clipchip-n">${i + 1}</span>
      <span class="vid-clipchip-name">${esc(c.name || 'video')}</span>
      <button type="button" class="vid-clipchip-x" data-i="${i}" title="Quitar">✕</button>
    </div>`).join('');
  list.querySelectorAll('.vid-clipchip-x').forEach((btn) => {
    btn.onclick = () => {
      const i = +btn.dataset.i;
      if (!Number.isFinite(i)) return;
      vidPendingClips.splice(i, 1);
      renderVidClipList();
    };
  });
}

function screenCopyUrl(screenId) {
  return IS_DESKTOP ? videoScreenUrl(screenId) : roomUrl(`/video.html?screen=${screenId}`);
}

function accScreenLiveHtml(n) {
  const on = connectedScreens.has(n);
  return `<span class="acc-screen-live ${on ? 'is-on' : 'is-off'}" data-screen="${n}" title="${on ? 'Fuente activa en OBS o Live Studio' : 'Sin fuente en OBS o Live Studio'}">
    <span class="acc-screen-dot" aria-hidden="true"></span>
    <span class="acc-screen-live-lbl">${on ? 'Online' : 'Offline'}</span>
  </span>`;
}

function copyAccScreenUrl(id, code) {
  const copyUrl = screenCopyUrl(id);
  if (!screenUrlHasRoom(copyUrl)) {
    toast && toast('Espera a que cargue la sesión y vuelve a copiar (falta room= en el link)', 'warn');
    return;
  }
  navigator.clipboard?.writeText(copyUrl);
  toast && toast('Link de Pantalla ' + id + ' copiado', 'ok');
  if (code) {
    code.classList.add('is-copied');
    setTimeout(() => code.classList.remove('is-copied'), 1200);
  }
}

function syncAccScreenLive() {
  const tb = $('acc-screen-urls');
  if (!tb) return;
  tb.querySelectorAll('.acc-screen-live').forEach((el) => {
    const n = Number(el.dataset.screen) || 1;
    const on = connectedScreens.has(n);
    el.classList.toggle('is-on', on);
    el.classList.toggle('is-off', !on);
    el.title = on ? 'Fuente activa en OBS o Live Studio' : 'Sin fuente en OBS o Live Studio';
    const lbl = el.querySelector('.acc-screen-live-lbl');
    if (lbl) lbl.textContent = on ? 'Online' : 'Offline';
  });
}

function renderAccScreenUrls() {
  const tb = $('acc-screen-urls');
  if (!tb) return;
  const rows = tb.querySelectorAll('tr');
  if (rows.length !== SCREEN_COUNT) {
    tb.innerHTML = Array.from({ length: SCREEN_COUNT }, (_, i) => {
      const n = i + 1;
      const url = screenCopyUrl(n);
      return `<tr data-screen="${n}">
        <td>Pantalla ${n}</td>
        <td><code class="acc-screen-url" data-screen="${n}" title="Clic para copiar">${esc(url)}</code></td>
        <td>${accScreenLiveHtml(n)}</td>
      </tr>`;
    }).join('');
    tb.querySelectorAll('.acc-screen-url').forEach((code) => {
      code.onclick = () => copyAccScreenUrl(Number(code.dataset.screen) || 1, code);
    });
  } else {
    tb.querySelectorAll('.acc-screen-url').forEach((code) => {
      const n = Number(code.dataset.screen) || 1;
      const url = screenCopyUrl(n);
      if (code.textContent !== url) code.textContent = url;
    });
    syncAccScreenLive();
  }
}

function screenUrlHasRoom(url) {
  try { return !!(new URL(url, location.origin).searchParams.get('room')); } catch { return /[?&]room=/.test(String(url || '')); }
}

function onScreens(p) {
  const next = new Set((p.connected || []).map((n) => Math.max(1, Number(n) || 0)).filter(Boolean));
  const now = Date.now();
  for (const id of next) screenSeenAt.set(id, now);

  const display = new Set(next);
  for (const [id, t] of screenSeenAt) {
    if (now - t < SCREEN_PRESENCE_GRACE_MS) display.add(id);
  }
  // Limpia pantallas que llevan mucho sin señal.
  for (const [id, t] of screenSeenAt) {
    if (now - t >= SCREEN_PRESENCE_GRACE_MS) screenSeenAt.delete(id);
  }

  connectedScreens = display;
  renderScreens();
  renderAccScreenUrls();
  refreshAccMediaScreenUrl();
  refreshLevelVideoScreenLink();
}

function renderScreens() {
  const el = $('screenList');
  const screens = ensureScreens();
  const lv = settings.levelVideos || {};
  const lvOn = lv.enabled !== false;
  const lvScr = Number(lv.screen) || 1;
  el.innerHTML = screens.map((s) => {
    const count = (settings.videos || []).filter((v) => (Number(v.screen) || 1) === s.id).length
      + (lvOn && lvScr === s.id ? 1 : 0);
    const on = connectedScreens.has(s.id);
    return `
    <div class="screen ${on ? 'is-on' : 'is-off'}" data-id="${s.id}">
      <div class="screen-top">
        <span class="st-badge">${s.id}</span>
        <div class="st-meta">
          <span class="st-name">Pantalla ${s.id}</span>
          <span class="st-count">${count ? count + (count === 1 ? ' evento' : ' eventos') : 'Sin eventos'}</span>
        </div>
      </div>
      <div class="screen-status ${on ? 'on' : 'off'}"><span class="sdot"></span>${on ? 'Conectada' : 'Sin fuente'}</div>
      <p class="screen-tip">${on
        ? 'Fuente activa — si Livecoins se reinicia, el overlay se reconecta solo (no hace falta volver a pegar el link)'
        : 'Pega el link una vez. Si se ve negro: abre Livecoins y pulsa Actualizar en la fuente (no la borres). El .exe debe estar abierto.'}</p>
      <div class="screen-btns">
        <button type="button" class="copy">Copiar link</button>
        <button type="button" class="test">Probar</button>
      </div>
      <div class="screen-size"><span>Tamaño <b>${s.size}%</b></span><input type="range" min="10" max="100" value="${s.size}" aria-label="Tamaño pantalla ${s.id}"></div>
      <div class="screen-vol"><span>Volumen <b>${s.volume ?? 100}%</b></span><input type="range" min="0" max="100" value="${s.volume ?? 100}" aria-label="Volumen pantalla ${s.id}"></div>
    </div>`;
  }).join('');

  el.querySelectorAll('.screen').forEach((card) => {
    const id = +card.dataset.id;
    const s = screens.find((x) => x.id === id);
    card.querySelector('.copy').onclick = (e) => {
      const copyUrl = screenCopyUrl(id);
      if (!screenUrlHasRoom(copyUrl)) {
        if (typeof toast === 'function') toast('Espera a que cargue la sesión y vuelve a copiar (falta room= en el link)', 'warn');
        e.target.textContent = 'Espera…';
        setTimeout(() => (e.target.textContent = 'Copiar link'), 1500);
        return;
      }
      navigator.clipboard?.writeText(copyUrl);
      e.target.textContent = '¡copiado!';
      setTimeout(() => (e.target.textContent = 'Copiar link'), 1200);
    };
    card.querySelector('.test').onclick = () => send({ action: 'testScreen', screen: id });
    const range = card.querySelector('.screen-size input');
    range.oninput = () => { s.size = +range.value; card.querySelector('.screen-size b').textContent = s.size + '%'; saveSettingsKeysPatch('screens'); };
    const volRange = card.querySelector('.screen-vol input');
    if (volRange) {
      const volCard = {
        dataset: { id: 'scr-' + s.id },
        querySelector(sel) { return sel === '.pct' ? card.querySelector('.screen-vol b') : null; },
      };
      bindCardVolumeSlider(volRange, volCard, 'screens', (n) => {
        s.volume = n;
      }, () => saveMediaVolumePatch('screens'));
    }
  });
}

function syncScreensVolumesInPlace() {
  const el = $('screenList');
  if (!el || !settings || !Array.isArray(settings.screens)) return;
  el.querySelectorAll('.screen').forEach((card) => {
    const id = +card.dataset.id;
    if (cardVolDragActive.has('scr-' + id)) return;
    const s = settings.screens.find((x) => Number(x.id) === id);
    if (!s) return;
    const vr = card.querySelector('.screen-vol input');
    const lab = card.querySelector('.screen-vol b');
    const v = Math.max(0, Math.min(100, Number(s.volume ?? 100)));
    if (vr) vr.value = String(v);
    if (lab) lab.textContent = v + '%';
  });
}

