function syncVidFirstMessageDelayUI(eventType = $('vid-event')?.value) {
  const isFirstMessage = eventType === 'firstMessage';
  const toggle = $('vid-firstmsg-delay-toggle');
  const useDelay = $('vid-use-joindelay');
  const input = $('vid-joindelay');
  if (toggle) toggle.hidden = !isFirstMessage;
  if (!input) return;
  if (isFirstMessage) {
    const enabled = !!useDelay?.checked;
    input.disabled = !enabled;
    if (!enabled) input.value = 0;
  } else {
    input.disabled = false;
  }
}

function fillCmdRoleChecks(prefix, a) {
  if ($(prefix + '-cmd-mods')) $(prefix + '-cmd-mods').checked = !!a?.cmdMods;
  if ($(prefix + '-cmd-superfans')) $(prefix + '-cmd-superfans').checked = !!a?.cmdSuperfans;
  if ($(prefix + '-cmd-fans')) $(prefix + '-cmd-fans').checked = !!a?.cmdFans;
}
function readCmdRoleChecks(prefix) {
  return {
    cmdMods: !!$(prefix + '-cmd-mods')?.checked,
    cmdSuperfans: !!$(prefix + '-cmd-superfans')?.checked,
    cmdFans: !!$(prefix + '-cmd-fans')?.checked,
  };
}

function setVidEventUI(value) {
  $('vid-event').value = value;
  $('vid-giftanyextra').hidden = value !== 'gift-any';
  $('vid-giftextra').hidden = value !== 'gift-name';
  $('vid-likeuserextra').hidden = value !== 'like';
  $('vid-likeextra').hidden = value !== 'likeGlobal';
  $('vid-emoteextra').hidden = !isEmoteEvent(value);
  const vidDelay = $('vid-eventdelayextra');
  if (vidDelay) vidDelay.hidden = !isEmoteEvent(value) && value !== 'chatCommand';
  const vidDelayLbl = document.querySelector('label[for="vid-eventdelay"]');
  if (vidDelayLbl) {
    vidDelayLbl.textContent = value === 'chatCommand'
      ? 'SEGUNDOS DE ESPERA por usuario (anti-spam del comando; 0 = sin límite)'
      : 'SEGUNDOS DE ESPERA por usuario (sticker: el mismo usuario no repite hasta pasar este tiempo; 0 = sin límite)';
  }
  if ($('vid-cmdroles')) $('vid-cmdroles').hidden = value !== 'chatCommand';
  $('vid-cmdextra').hidden = value !== 'chatCommand';
  $('vid-userextra').hidden = value !== 'chatCommand' && value !== 'firstMessage' && value !== 'userJoin';
  $('vid-joindelayextra').hidden = value !== 'userJoin' && value !== 'firstMessage';
  const jdLabel = document.querySelector('label[for="vid-joindelay"]');
  if (jdLabel) {
    jdLabel.textContent = value === 'firstMessage'
      ? 'SEGUNDOS DE DELAY'
      : 'SEGUNDOS DE DELAY (espera antes de repetir, anti-spam)';
  }
  syncVidFirstMessageDelayUI(value);
  const sd = $('vid-streamdeck-extra');
  if (sd) sd.hidden = value !== 'streamdeck';
  if (value === 'streamdeck') refreshVidStreamdeckUrl();
  const userInput = $('vid-user');
  if (userInput) userInput.placeholder = value === 'userJoin'
    ? 'Usuario @ (uniqueId), no el apodo. Si TikTok no avisa la entrada, dispara al primer chat'
    : 'Solo este usuario (sin @) — opcional';
  syncTrigSelectGrid('vid-trig-grid', 'vid-event', 'gift-any');
}

