// ¿La biblioteca debe mostrar la carpeta «niveles»? Solo en Videos y cuando el
// evento elegido es "Subió de nivel de miembro".
function libIsNiveles() {
  return false;
}

function currentVideoPackKind() {
  return libTarget === 'ba' ? 'batalla' : 'ai';
}

function canUseVideoPackAi() {
  return !!(window.desktopAPI && (
    typeof window.desktopAPI.videoPackStatus === 'function'
    || typeof window.desktopAPI.videoPackAiStatus === 'function'
  ) && (
    typeof window.desktopAPI.installVideoPack === 'function'
    || typeof window.desktopAPI.installVideoPackAi === 'function'
  ));
}

async function videoPackStatusCall(kind) {
  if (typeof window.desktopAPI.videoPackStatus === 'function') {
    return window.desktopAPI.videoPackStatus(kind);
  }
  if (kind === 'ai' && typeof window.desktopAPI.videoPackAiStatus === 'function') {
    return window.desktopAPI.videoPackAiStatus();
  }
  return { ok: false, installed: false, needsUpdate: false };
}

async function installVideoPackCall(kind) {
  if (typeof window.desktopAPI.installVideoPack === 'function') {
    return window.desktopAPI.installVideoPack(kind);
  }
  if (kind === 'ai' && typeof window.desktopAPI.installVideoPackAi === 'function') {
    return window.desktopAPI.installVideoPackAi();
  }
  return { ok: false, error: 'API de pack no disponible' };
}

let videoPackAiUi = { installed: false, needsUpdate: false, kind: 'ai' };
let videoPackPromptGen = 0;

function dismissVideoPackConfirms() {
  document.querySelectorAll('.confirm-modal.video-pack-confirm').forEach((el) => {
    try { el.remove(); } catch {}
  });
}

function packLabelArticle(kind) {
  return kind === 'batalla' ? 'Las Batallas AI' : 'Los Videos AI';
}

function applyVideoPackAiButtons() {
  const dl = $('vidlib-download-ai');
  const up = $('vidlib-update-ai');
  const kind = currentVideoPackKind();
  const inLib = (libTarget === 'vid' || libTarget === 'ba') && !libIsNiveles() && canUseVideoPackAi();
  const label = kind === 'batalla' ? 'Batallas AI' : 'Videos AI';
  if (dl) {
    const showDl = inLib && !videoPackAiUi.installed;
    dl.style.display = showDl ? '' : 'none';
    dl.disabled = !!videoPackAiBusy;
    dl.textContent = videoPackAiBusy && showDl ? 'Descargando…' : ('⬇ Descargar ' + label);
  }
  if (up) {
    const showUp = inLib && videoPackAiUi.installed && videoPackAiUi.needsUpdate;
    up.style.display = showUp ? '' : 'none';
    up.disabled = !!videoPackAiBusy;
    up.textContent = videoPackAiBusy && showUp ? 'Actualizando…' : '↻ Actualizar';
  }
}

async function refreshVideoPackAiUi() {
  if (!canUseVideoPackAi() || libIsNiveles() || (libTarget !== 'vid' && libTarget !== 'ba')) {
    videoPackAiUi = { installed: false, needsUpdate: false, kind: currentVideoPackKind() };
    applyVideoPackAiButtons();
    return videoPackAiUi;
  }
  const kind = currentVideoPackKind();
  try {
    const st = await videoPackStatusCall(kind);
    videoPackAiUi = {
      installed: !!(st && st.installed),
      needsUpdate: !!(st && st.needsUpdate),
      kind,
    };
  } catch {
    videoPackAiUi = { installed: false, needsUpdate: false, kind };
  }
  applyVideoPackAiButtons();
  return videoPackAiUi;
}

async function downloadVideoPackAi({ mode = 'install', fromButton = false, silent = false } = {}) {
  if (!canUseVideoPackAi() || videoPackAiBusy) return false;
  const kind = currentVideoPackKind();
  const label = kind === 'batalla' ? 'Batallas AI' : 'Videos AI';
  const isUpdate = mode === 'update';
  const myGen = videoPackPromptGen;

  // Por si acaban de instalar por otro camino (botón vacío, auto al abrir la app, etc.)
  try {
    const st0 = await videoPackStatusCall(kind);
    if (!isUpdate && st0 && st0.installed && !st0.needsUpdate) {
      videoPackAiUi = { installed: true, needsUpdate: false, kind };
      applyVideoPackAiButtons();
      return true;
    }
  } catch {}

  if (!silent && !fromButton && !isUpdate) {
    const ok = await askConfirm({
      icon: kind === 'batalla' ? '⚔️' : '🎬',
      title: 'Descargar ' + label,
      message: packLabelArticle(kind) + ' no están en la app (así el instalador pesa menos).<br><br>'
        + 'Se guardan en tu PC y <b>no se borran</b> al actualizar Livecoins.',
      confirmText: '⬇ Descargar',
      cancelText: 'Cancelar',
      danger: false,
      modalClass: 'video-pack-confirm',
    });
    if (myGen !== videoPackPromptGen) return false;
    if (!ok) return false;
    // Revalidar: pudieron instalarse mientras el aviso estaba abierto
    try {
      const st1 = await videoPackStatusCall(kind);
      if (st1 && st1.installed) {
        videoPackAiUi = { installed: true, needsUpdate: !!st1.needsUpdate, kind };
        applyVideoPackAiButtons();
        await loadLocalVideos();
        return true;
      }
    } catch {}
  }
  if (!silent && isUpdate && fromButton) {
    const ok = await askConfirm({
      icon: '↻',
      title: 'Actualizar ' + label,
      message: 'Se descargará el pack y se <b>añadirán los videos nuevos</b>. '
        + 'Los que ya tienes se actualizan si cambiaron; <b>no se borran</b> los demás.',
      confirmText: '↻ Actualizar',
      cancelText: 'Cancelar',
      danger: false,
      modalClass: 'video-pack-confirm',
    });
    if (myGen !== videoPackPromptGen) return false;
    if (!ok) return false;
  }
  if (myGen !== videoPackPromptGen) return false;

  videoPackAiBusy = true;
  applyVideoPackAiButtons();
  const box = $('vid-libgrid');
  const progressLabel = isUpdate ? ('Actualizando ' + label) : ('Descargando ' + label);
  if (box) box.innerHTML = '<div class="empty">' + progressLabel + '… 0%</div>';
  let unsub = null;
  try {
    const onProg = window.desktopAPI.onVideoPackProgress || window.desktopAPI.onVideoPackAiProgress;
    if (typeof onProg === 'function') {
      unsub = onProg((p) => {
        if (!p || !box) return;
        if (p.kind && p.kind !== kind) return;
        if (p.error) {
          box.innerHTML = '<div class="empty">Error: ' + esc(String(p.error)) + '</div>';
          return;
        }
        const pct = p.pct != null ? p.pct : 0;
        const lbl = p.phase === 'download' || p.started
          ? (isUpdate ? 'Descargando actualización' : 'Descargando')
          : (p.complete ? 'Listo' : 'Instalando');
        box.innerHTML = '<div class="empty">' + esc(lbl) + '… ' + pct + '%</div>';
      });
    }
    const r = await installVideoPackCall(kind);
    if (myGen !== videoPackPromptGen) return false;
    if (!r || !r.ok) {
      const err = (r && r.error) || 'No se pudo descargar';
      if (box) {
        box.innerHTML = '<div class="empty">' + esc(err)
          + '<br><button type="button" class="btn primary" id="vidlib-dl-retry">Reintentar</button></div>';
        const retry = $('vidlib-dl-retry');
        if (retry) retry.onclick = () => { void downloadVideoPackAi({ mode, fromButton: true }); };
      }
      try { toast && toast(err, 'err'); } catch {}
      return false;
    }
    const added = Number(r.added) || 0;
    const updated = Number(r.updated) || 0;
    try {
      toast && toast(
        isUpdate
          ? (label + ' actualizados (+' + added + ' nuevos, ' + updated + ' actualizados)')
          : (label + ' listos (' + (r.count || 0) + ' archivos)'),
        'ok'
      );
    } catch {}
    await loadLocalVideos();
    await refreshVideoPackAiUi();
    return true;
  } catch (e) {
    const err = String(e && e.message || e);
    if (box) box.innerHTML = '<div class="empty">' + esc(err) + '</div>';
    try { toast && toast(err, 'err'); } catch {}
    return false;
  } finally {
    videoPackAiBusy = false;
    await refreshVideoPackAiUi();
    try { if (typeof unsub === 'function') unsub(); } catch {}
  }
}

async function maybePromptVideoPackAi() {
  const myGen = videoPackPromptGen;
  if (libIsNiveles() || !canUseVideoPackAi() || (libTarget !== 'vid' && libTarget !== 'ba')) {
    videoPackAiUi = { installed: false, needsUpdate: false, kind: currentVideoPackKind() };
    applyVideoPackAiButtons();
    return;
  }
  // Si la grilla ya tiene clips, igual hay que actualizar el pack si cambió versión/URL.
  const st = await refreshVideoPackAiUi();
  if (myGen !== videoPackPromptGen) return;
  if (!st.installed) {
    await downloadVideoPackAi({ mode: 'install', silent: true });
  } else if (st.needsUpdate) {
    await downloadVideoPackAi({ mode: 'update', silent: true });
  }
}

function openVideoLib() {
  if ((libTarget === 'vid' || libTarget === 'ba') && !libIsNiveles() && isVideosAiLocked()) {
    toast('Videos AI es Solo Premium. Mejora tu plan para usarlo ⭐', 'warn');
    return;
  }
  // Ajusta los textos del modal según la carpeta (Videos / Batallas / Niveles).
  const niveles = libIsNiveles();
  const folder = libTarget === 'ba' ? 'public/video/batalla' : (niveles ? 'public/video/niveles' : 'public/video');
  const multiAnim = libTarget === 'vid' || libTarget === 'accAnim';
  const sub = document.querySelector('#videoLibModal .vidlib-sub');
  if (sub) {
    sub.textContent = multiAnim
      ? 'Clic para marcar varias. Luego pulsa Usar.'
      : 'Selecciona una animación de la biblioteca';
  }
  const rndWarn = $('vidlib-rnd-warn');
  if (rndWarn) rndWarn.hidden = !multiAnim;
  const credit = document.querySelector('#videoLibModal .modal-foot .credit');
  if (credit) {
    // Pack AI: sin texto de pie (no anunciar peso del instalador).
    if ((libTarget === 'ba' || (libTarget === 'vid' && !niveles))) {
      credit.innerHTML = '';
      credit.hidden = true;
    } else {
      credit.hidden = false;
      credit.innerHTML = 'Videos de la carpeta <code>' + folder + '</code>.';
    }
  }
  const titleEl = $('vidlib-title') || document.querySelector('#videoLibModal .create-modal-head h2');
  if (titleEl) {
    const actionName = libTarget === 'ba'
      ? (($('ba-name') && $('ba-name').value) || '').trim()
      : (($('vid-name') && $('vid-name').value) || '').trim();
    const base = libTarget === 'ba' ? 'Animación – Batallas' : (libTarget === 'accAnim' ? 'Animación – Acción' : 'Animación – Multimedia');
    titleEl.textContent = actionName ? (base + ' (' + actionName + ')') : base;
  }
  const openBtn = $('vidlib-openniveles');
  if (openBtn) openBtn.style.display = (niveles && window.desktopAPI && window.desktopAPI.openNivelesFolder) ? '' : 'none';
  dismissVideoPackConfirms();
  videoPackPromptGen += 1;
  applyVideoPackAiButtons();
  const behind = libTarget === 'ba' ? $('baModal') : (libTarget === 'accAnim' ? $('accModal') : $('vidModal'));
  if (behind) behind.classList.add('vidlib-behind');
  $('videoLibModal').classList.remove('hidden');
  const gen = videoPackPromptGen;
  loadLocalVideos().then(() => {
    if (gen !== videoPackPromptGen) return;
    return maybePromptVideoPackAi();
  });
}

function closeVideoLib() {
  videoPackPromptGen += 1;
  dismissVideoPackConfirms();
  $('videoLibModal').classList.add('hidden');
  document.querySelectorAll('.vidlib-behind').forEach((el) => el.classList.remove('vidlib-behind'));
  window._vidLibHover = null;
  window._vidLibPlaying = null;
  vidLibPicked = null;
  vidLibWarmGen += 1;
  const use = $('vidlib-use');
  if (use) use.disabled = true;
  vidLibStopShared();
}

function vidLibMuteLoop(v, className) {
  v.className = className;
  v.muted = true;
  v.defaultMuted = true;
  v.loop = true;
  v.playsInline = true;
  v.setAttribute('muted', '');
  v.setAttribute('playsinline', '');
  v.preload = 'auto';
  v.playbackRate = 1;
  v.defaultPlaybackRate = 1;
  try { v.disablePictureInPicture = true; } catch {}
  try { v.disableRemotePlayback = true; } catch {}
  v.addEventListener('playing', () => { v.playbackRate = 1; });
  v.addEventListener('ratechange', () => { if (v.playbackRate !== 1) v.playbackRate = 1; });
  return v;
}

function vidLibDetachVideo(v) {
  if (!v) return;
  try { v.pause(); } catch {}
  try { delete v.dataset.playUrl; v.removeAttribute('src'); v.load(); } catch {}
}

function vidLibPauseHover() {
  if (window._vidLibPlaying) window._vidLibPlaying.classList.remove('is-playing');
  const v = window._vidLibPlayer;
  if (v) try { v.pause(); } catch {}
  const c = window._vidLibCanvas;
  if (c && window._vidLibCtx) {
    try { window._vidLibCtx.clearRect(0, 0, c.width, c.height); } catch {}
  }
  if (c && c.parentNode) c.parentNode.removeChild(c);
}

function vidLibStopShared() {
  vidLibPauseHover();
  vidLibDetachVideo(window._vidLibPlayer);
}

function vidLibEnsureStage() {
  if (!window._vidLibPlayer) {
    const v = vidLibMuteLoop(document.createElement('video'), 'vid-lib-player');
    v.width = 240;
    v.height = 426;
    document.body.appendChild(v);
    window._vidLibPlayer = v;
  }
  if (!window._vidLibCanvas) {
    const c = document.createElement('canvas');
    c.className = 'vid-lib-canvas';
    c.width = 240;
    c.height = 426;
    window._vidLibCanvas = c;
    window._vidLibCtx = c.getContext('2d', { alpha: true });
  }
  if (!window._vidLibRaf) {
    const draw = () => {
      const v = window._vidLibPlayer;
      const c = window._vidLibCanvas;
      const ctx = window._vidLibCtx;
      if (v && c && ctx && !v.paused && v.readyState >= 2) {
        ctx.clearRect(0, 0, c.width, c.height);
        try { ctx.drawImage(v, 0, 0, c.width, c.height); } catch {}
      }
    };
    const loop = () => {
      window._vidLibRaf = requestAnimationFrame(loop);
      draw();
    };
    window._vidLibDraw = draw;
    loop();
  }
  return { v: window._vidLibPlayer, c: window._vidLibCanvas };
}

function vidLibIsVideoCell(cell) {
  const u = cell && cell.dataset.url;
  return !!(u && !/\.(gif|png|jpe?g|webp)(\?|$)/i.test(u));
}

function vidLibPreviewSrc(url) {
  return url || '';
}

function vidLibPosterSrc(url) {
  if (!url || /\.(gif|png|jpe?g|webp)(\?|$)/i.test(url)) return url;
  return '/api/video-lib-preview?v=4&poster=1&src=' + encodeURIComponent(url);
}

function vidLibPosterFallback(el) {
  if (!el || el.dataset.fallbackDone === '1') return;
  el.dataset.fallbackDone = '1';
  const url = el.dataset.fallback || '';
  if (!url) return;
  const vid = vidLibMuteLoop(document.createElement('video'), 'vid-lib-poster');
  vid.src = url;
  vid.preload = 'metadata';
  vid.loop = false;
  try { el.replaceWith(vid); } catch {}
}
window.vidLibPosterFallback = vidLibPosterFallback;

let vidLibWarmGen = 0;
function vidLibWarmPreviews(box) {
  vidLibWarmGen += 1;
  if (!box) return;
  [...box.querySelectorAll('img.vid-lib-poster')].slice(0, 10).forEach((img, i) => {
    setTimeout(() => {
      if (!img.isConnected || img.complete) return;
      const pre = new Image();
      pre.src = img.src;
    }, i * 90);
  });
}

function vidLibAllowsMulti() {
  return libTarget === 'vid' || libTarget === 'accAnim';
}

function vidLibSyncUseBtn() {
  const use = $('vidlib-use');
  if (!use) return;
  if (vidLibAllowsMulti()) {
    const n = vidLibPickedList.length;
    use.disabled = n < 1;
    use.textContent = n > 1 ? `✓ Usar ${n} animaciones` : '✓ Usar esta animación';
    return;
  }
  use.disabled = !vidLibPicked;
  use.textContent = '✓ Usar esta animación';
}

function vidLibSetPicked(cell) {
  if (vidLibAllowsMulti()) {
    if (!cell) {
      vidLibPickedList = [];
      document.querySelectorAll('#vid-libgrid .vid-cell').forEach((c) => c.classList.remove('is-on'));
      vidLibSyncUseBtn();
      return;
    }
    const item = { url: cell.dataset.url, name: cell.dataset.name };
    const i = vidLibPickedList.findIndex((x) => x.url === item.url);
    if (i >= 0) vidLibPickedList.splice(i, 1);
    else vidLibPickedList.push(item);
    document.querySelectorAll('#vid-libgrid .vid-cell').forEach((c) => {
      c.classList.toggle('is-on', vidLibPickedList.some((x) => x.url === c.dataset.url));
    });
    vidLibSyncUseBtn();
    return;
  }
  vidLibPicked = cell ? { url: cell.dataset.url, name: cell.dataset.name } : null;
  document.querySelectorAll('#vid-libgrid .vid-cell').forEach((c) => c.classList.toggle('is-on', c === cell));
  vidLibSyncUseBtn();
}

function vidLibUsePicked() {
  if (libTarget === 'ba') {
    if (!vidLibPicked) return;
    baPending = vidLibPicked;
    if ($('ba-fname')) $('ba-fname').textContent = vidLibPicked.name;
    closeVideoLib();
    return;
  }
  if (libTarget === 'accAnim') {
    const batch = vidLibPickedList.length
      ? vidLibPickedList.slice()
      : (vidLibPicked ? [vidLibPicked] : []);
    if (!batch.length) return;
    accPendingAnimClips = batch.map((c) => ({ url: c.url, name: c.name || 'video' }));
    accPendingAnim = accPendingAnimClips[0] || null;
    accPendingGif = null;
    if ($('acc-gif-on')) $('acc-gif-on').checked = true;
    syncAccAnimChosenLabel();
    closeVideoLib();
    if (batch.length > 1) toast && toast(`${batch.length} videos. Cada disparo sale uno al azar.`, 'ok');
    return;
  }
  const batch = vidLibPickedList.length
    ? vidLibPickedList.slice()
    : (vidLibPicked ? [vidLibPicked] : []);
  if (!batch.length) return;
  let added = 0;
  for (const c of batch) {
    if (addVidClip(c)) added += 1;
  }
  closeVideoLib();
  if (added > 1) toast && toast(`${added} videos. Cada vez que disparen saldrá uno al azar.`, 'ok');
  else if (!added) toast && toast('Esos videos ya estaban en la lista.', 'warn');
}

function vidLibSyncPlay(box) {
  if (!box) return;
  const hovered = window._vidLibHover && box.contains(window._vidLibHover) ? window._vidLibHover : null;
  if (!hovered) {
    vidLibPauseHover();
    window._vidLibPlaying = null;
    return;
  }
  const host = hovered.querySelector('.vid-prev-media') || hovered.querySelector('.vid-prev');
  if (!host) return;
  if (!vidLibIsVideoCell(hovered)) {
    vidLibPauseHover();
    window._vidLibPlaying = hovered;
    hovered.classList.add('is-playing');
    return;
  }
  const url = hovered.dataset.url || '';
  const { v: player, c: canvas } = vidLibEnsureStage();
  if (
    window._vidLibPlaying === hovered
    && canvas.parentNode === host
    && player.dataset.playUrl === url
    && !player.paused
  ) return;

  if (window._vidLibPlaying && window._vidLibPlaying !== hovered) {
    window._vidLibPlaying.classList.remove('is-playing');
  }
  if (canvas.parentNode !== host) host.appendChild(canvas);
  if (player.dataset.playUrl !== url) {
    player.dataset.playUrl = url;
    player.src = url;
  }
  player.muted = true;
  player.playbackRate = 1;
  hovered.classList.add('is-playing');
  window._vidLibPlaying = hovered;
  if (player.paused) {
    try { if (player.currentTime > 0.05) player.currentTime = 0; } catch {}
    player.play().catch(() => {});
  }
}

function bindVidLibGrid(box) {
  window._vidLibHover = null;
  window._vidLibPlaying = null;
  const keepMulti = vidLibAllowsMulti() ? vidLibPickedList.slice() : null;
  if (!vidLibAllowsMulti()) vidLibSetPicked(null);
  vidLibStopShared();

  box.querySelectorAll('.vid-cell').forEach((cell) => {
    cell.addEventListener('mouseenter', () => { window._vidLibHover = cell; vidLibSyncPlay(box); });
    cell.addEventListener('mouseleave', () => {
      if (window._vidLibHover === cell) window._vidLibHover = null;
      vidLibSyncPlay(box);
    });
    cell.onclick = () => vidLibSetPicked(cell);
    cell.ondblclick = () => {
      if (vidLibAllowsMulti()) {
        if (!vidLibPickedList.some((x) => x.url === cell.dataset.url)) vidLibSetPicked(cell);
        vidLibUsePicked();
      } else {
        vidLibSetPicked(cell);
        vidLibUsePicked();
      }
    };
  });
  if (keepMulti) {
    vidLibPickedList = keepMulti;
    box.querySelectorAll('.vid-cell').forEach((c) => {
      c.classList.toggle('is-on', vidLibPickedList.some((x) => x.url === c.dataset.url));
    });
    vidLibSyncUseBtn();
  }
  vidLibWarmPreviews(box);
}

const isImageFile = (u) => /\.(gif|png|jpe?g|webp)(\?|$)/i.test(u || '');

async function loadLocalVideos() {
  const box = $('vid-libgrid');
  box.innerHTML = '<div class="empty">Cargando…</div>';
  // Batallas → «video/batalla»; Videos con evento "subió de nivel" → «niveles»; resto → «video».
  const endpoint = libTarget === 'ba'
    ? '/api/local-videos-batalla'
    : (libIsNiveles() ? '/api/local-videos-niveles' : '/api/local-videos');
  try {
    const res = await fetch(endpoint);
    const data = await res.json();
    localVideos = data.results || [];
    renderLocalVideos($('vid-libq').value.trim());
  } catch {
    box.innerHTML = '<div class="empty">No se pudo leer la carpeta de videos</div>';
  }
}

const VIDLIB_CATS = ['quiereme', 'taptap', 'cofre', 'x2', 'x3', 'snipe', 'guante', 'varios'];
const VIDLIB_NAMED_CATS = VIDLIB_CATS.filter((c) => c !== 'varios');

function vidLibNameInCat(name, cat) {
  const n = String(name || '').toLowerCase().replace(/[_-]+/g, ' ');
  const c = String(cat || 'quiereme').toLowerCase();
  if (c === 'varios') return !VIDLIB_NAMED_CATS.some((k) => vidLibNameInCat(name, k));
  if (c === 'taptap') return /tap\s*tap|taptap/.test(n);
  if (c === 'x2') return /(^|[^a-z0-9])x\s*2([^a-z0-9]|$)/.test(n);
  if (c === 'x3') return /(^|[^a-z0-9])x\s*3([^a-z0-9]|$)/.test(n);
  return n.includes(c);
}

function vidLibActiveCat() {
  const sel = $('vidlib-cat');
  const v = sel && sel.value ? String(sel.value).toLowerCase() : 'quiereme';
  return VIDLIB_CATS.includes(v) ? v : 'quiereme';
}

function renderLocalVideos(filter) {
  const box = $('vid-libgrid');
  const cat = vidLibActiveCat();
  const f = (filter || '').toLowerCase();
  let list = localVideos.filter((v) => vidLibNameInCat(v.name, cat));
  if (f) list = list.filter((v) => v.name.toLowerCase().includes(f));
  const countEl = $('vidlib-count');
  if (countEl) countEl.textContent = list.length + (list.length === 1 ? ' animación' : ' animaciones');
  if (!list.length) {
    const folder = libTarget === 'ba' ? 'video/batalla' : (libIsNiveles() ? 'video/niveles' : 'video');
    const needPack = (libTarget === 'vid' || libTarget === 'ba') && !libIsNiveles() && canUseVideoPackAi() && !localVideos.length && !videoPackAiUi.installed;
    applyVideoPackAiButtons();
    const packLabel = libTarget === 'ba' ? 'Batallas AI' : 'Videos AI';
    box.innerHTML = localVideos.length
      ? (f ? '<div class="empty">Ningún video coincide</div>' : `<div class="empty">No hay videos en «${cat}»</div>`)
      : needPack
        ? `<div class="empty">Aún no tienes ${packLabel} descargados.<br>
            <button type="button" class="btn primary" id="vidlib-dl-empty">⬇ Descargar pack</button></div>`
        : `<div class="empty">No hay videos en la carpeta «${folder}».<br>Copia tus .mp4 ahí y pulsa ↻</div>`;
    const emptyBtn = $('vidlib-dl-empty');
    if (emptyBtn) emptyBtn.onclick = () => { void downloadVideoPackAi({ mode: 'install', fromButton: true }); };
    if (!vidLibAllowsMulti()) vidLibSetPicked(null);
    else vidLibSyncUseBtn();
    return;
  }
  applyVideoPackAiButtons();
  const niceName = (n) => n.replace(/\.[^.]+$/, '');
  box.innerHTML = list.map((v) => {
    const media = isImageFile(v.url)
      ? `<img src="${esc(v.url)}" loading="lazy" decoding="async">`
      : `<img class="vid-lib-poster" src="${esc(vidLibPosterSrc(v.url))}" data-fallback="${esc(v.url)}" loading="lazy" decoding="async" alt="" onerror="vidLibPosterFallback(this)">`;
    return `
    <div class="vid-cell" data-url="${esc(v.url)}" data-name="${esc(v.name)}" title="${esc(niceName(v.name))}">
      <div class="vid-prev"><div class="vid-prev-media">${media}</div></div>
      <div class="vid-cell-name">${esc(niceName(v.name))}</div>
    </div>`;
  }).join('');
  bindVidLibGrid(box);
}

$('vid-save').onclick = async () => {
  const name = $('vid-name').value.trim();
  if (!name) { $('vid-status').textContent = '⚠️ Escribe un nombre.'; return; }
  if (!vidPendingClips.length) { $('vid-status').textContent = '⚠️ Elige o sube al menos un video.'; return; }
  const ev = $('vid-event').value;
  const id = ensureVidEditId();
  const data = {
    name,
    trigger: ev === 'gift-any' || ev === 'gift-name' ? 'gift' : ev,
    giftName: ev === 'gift-name' ? $('vid-gift').value.trim() : '',
    giftId: ev === 'gift-name' ? ($('vid-giftid').value || '') : '',
    minDiamonds: 0,
    rangeMin: ev === 'gift-any' ? (+$('vid-rangemin').value || 0) : 0,
    rangeMax: ev === 'gift-any' ? (+$('vid-rangemax').value || 0) : 0,
    likeMin: ev === 'like' ? Math.max(1, +$('vid-likemin').value || 1) : 0,
    likeGoal: ev === 'likeGlobal' ? Math.max(1, +$('vid-likegoal').value || 100) : 0,
    emoteId: isEmoteEvent(ev) ? $('vid-emoteid').value.trim() : '',
    emoteImage: isEmoteEvent(ev) ? emoteImgById($('vid-emoteid').value.trim()) : '',
    eventDelay: (isEmoteEvent(ev) || ev === 'chatCommand') ? Math.max(0, parseInt($('vid-eventdelay')?.value, 10) || 0) : 0,
    command: ev === 'chatCommand' ? $('vid-command').value.trim() : '',
    user: (ev === 'chatCommand' || ev === 'firstMessage' || ev === 'userJoin') ? $('vid-user').value.trim().replace(/^@/, '') : '',
    ...(ev === 'chatCommand' ? readCmdRoleChecks('vid') : { cmdMods: false, cmdSuperfans: false, cmdFans: false }),
    joinDelay: ev === 'firstMessage'
      ? ($('vid-use-joindelay')?.checked ? Math.max(1, parseInt($('vid-joindelay').value, 10) || 30) : 0)
      : (ev === 'userJoin' ? Math.max(0, parseInt($('vid-joindelay').value, 10) || 0) : 0),
    level: 0,
    url: vidPendingClips[0].url,
    fileName: vidPendingClips[0].name || 'video',
    clips: vidPendingClips.length > 1 ? vidPendingClips.map((c) => ({ url: c.url, name: c.name || 'video' })) : [],
    volume: +$('vid-vol').value,
    screen: clampScreenId(+$('vid-screen').value || 1),
  };
  if (ev === 'chatCommand' && !data.command) { $('vid-status').textContent = '⚠️ Escribe el comando (ej. !video).'; return; }
  if (ev === 'userJoin' && !data.user) { $('vid-status').textContent = '⚠️ Escribe el usuario que al entrar reproduce el video.'; return; }
  if (!settings.videos) settings.videos = [];
  const existing = settings.videos.find((x) => x.id === id);
  if (existing) Object.assign(existing, data);
  else settings.videos.push({ id, enabled: true, ...data });
  vidEditingId = id;
  flushSaveSettings();
  await syncDesktopWebhookSettings();
  renderVideos();
  renderScreens();
  closeVidModal();
  if (ev === 'streamdeck') {
    toast && toast('Guardado. Usa 🔗 en la tarjeta para copiar el webhook a Stream Deck.', 'ok');
  }
};

/* ---- Animaciones de batalla PK (video por acción) ---- */
let baEditingId = null;
let baPending = null;

const BA_TRIGGER_LABELS = {
  critical: '⚡ Golpe crítico x2',
  critical3: '⚡ Golpe crítico x3',
  battleGift: '🥊 Potenciador guante',
  battleGiftAny: '🎁 Cualquier regalo',
  battleStart: '🟢 Inicio batalla',
  battleLast10: '⏱ Quedan 10 segundos',
  battleEnd: '🔴 Fin batalla',
  streamdeck: '🎛️ Stream Deck',
};
function baTriggerLabel(b) {
  const t = b.trigger || ((b.giftName || b.giftId) ? 'battleGift' : 'battleGiftAny');
  if (t === 'battleGift') return '🥊 Potenciador guante';
  return BA_TRIGGER_LABELS[t] || t;
}

function ensureBaEditId() {
  if (baEditingId) return baEditingId;
  baEditingId = 'ba' + Date.now();
  return baEditingId;
}

function refreshBaStreamdeckUrl() {
  const code = $('ba-streamdeck-url');
  if (!code) return;
  code.textContent = baStreamdeckWebhookUrl(ensureBaEditId());
}

function renderBattleAlerts() {
  if (cardVolDragActive.size || mediaVolRecent()) { mediaListRenderDeferred.battleAlerts = true; return; }
  const el = $('battleCards');
  if (!el) return;
  wireMapViewControls('lc_ba_view', renderBattleAlerts, 'ba-search');
  const mode = getMapViewMode('lc_ba_view');
  applyMapGridClass(el, mode);
  const list = settings.battleAlerts || [];
  if (!list.length) {
    el.innerHTML = lcEmptyGuideHTML({
      title: 'Aún no tienes animaciones de batalla',
      steps: ['Conecta TikTok', 'Elige trigger PK', 'Probar en pantalla'],
      hint: 'Pulsa <b>Añadir animación</b> para crear la primera.',
      className: 'empty',
    });
    syncBaMasterUI();
    return;
  }
  const q = String($('ba-search')?.value || '').trim().toLowerCase();
  const filtered = list.filter((b) => entityMatchesSearch(b, q));
  if (!filtered.length) { el.innerHTML = '<div class="empty">Ninguna animación coincide con la búsqueda.</div>'; syncBaMasterUI(); return; }

  el.innerHTML = filtered.map((b) => {
    const trigLbl = esc(baTriggerLabel(b));
    const showCombo = (b.trigger === 'battleGift' || b.trigger === 'battleGiftAny' || (!b.trigger && (b.giftName || b.giftId)));
    const combo = showCombo && (b.minCount || 1) > 1 ? ` ×${b.minCount}+` : '';
    if (mode === 'map') {
      const trig = giftTriggerVisualFromItem({
        ...b,
        trigger: (b.trigger === 'battleGift' || (!b.trigger && (b.giftName || b.giftId))) ? 'gift' : (b.trigger || 'gift'),
      }, '🥊');
      if (!(b.giftId || b.giftName)) {
        trig.emoji = '🥊';
        trig.label = baTriggerLabel(b);
      }
      const giftFace = trig.img
        ? `<img class="acc-map-gift-img" src="${esc(trig.img)}" alt="" loading="lazy" decoding="async" onerror="this.outerHTML='<span class=\\'acc-map-gift-emoji\\'>🥊</span>'">`
        : `<span class="acc-map-gift-emoji">${trig.emoji || '🥊'}</span>`;
      return `
      <div class="sa-card acc-map-card ${b.enabled !== false ? 'on' : ''}" data-id="${esc(b.id)}">
        <div class="acc-map-top">
          <span></span>
          <label class="toggle">
            <input type="checkbox" class="b-toggle" ${b.enabled !== false ? 'checked' : ''}>
            <span class="track"></span>
            <span class="state">${b.enabled !== false ? 'ON' : 'OFF'}</span>
          </label>
        </div>
        <div class="acc-map-trigger">
          <div class="acc-map-gift">${giftFace}</div>
          <div class="acc-map-trig-label" title="${trigLbl}${combo}">${trigLbl}${combo}</div>
        </div>
        <div class="acc-map-arrow" aria-hidden="true">↓</div>
        <div class="acc-map-body">
          <div class="sa-name">${esc(b.name || 'Animación')}</div>
          <div class="sa-file">📺 P${b.screen || 1}</div>
          <div class="sa-vol vid-card-vol acc-map-vol">
            <span>Vol</span>
            <input type="range" class="b-volrange" min="0" max="100" value="${b.volume ?? 100}">
            <span class="pct">${b.volume ?? 100}%</span>
          </div>
        </div>
        <div class="sa-card-btns acc-card-icons vid-card-btns acc-map-btns">
          <button type="button" class="acc-icon-btn sa-edit" title="Editar">${CARD_ICON.gear}</button>
          ${b.trigger === 'streamdeck' ? `<button type="button" class="acc-icon-btn sa-wh" title="Copiar webhook Stream Deck">🔗</button>` : ''}
          <button type="button" class="acc-icon-btn sa-play" title="Probar en pantalla">${CARD_ICON.play}</button>
          <button type="button" class="acc-icon-btn sa-stop" title="Detener video">${CARD_ICON.stop}</button>
          <button type="button" class="acc-icon-btn acc-dup sa-dup" title="Duplicar">${CARD_ICON.dup}</button>
          <button type="button" class="acc-icon-btn sa-del" title="Borrar">${CARD_ICON.trash}</button>
        </div>
      </div>`;
    }
    return `
    <div class="sa-card vid-card ${b.enabled !== false ? 'on' : ''}" data-id="${b.id}">
      <div class="vid-card-left">
        <label class="toggle">
          <input type="checkbox" class="b-toggle" ${b.enabled !== false ? 'checked' : ''}>
          <span class="track"></span>
          <span class="state">${b.enabled !== false ? 'ON' : 'OFF'}</span>
        </label>
        <span class="sa-corner" title="${trigLbl}${combo}">🥊</span>
      </div>
      <div class="vid-card-body sa-info">
        <div class="sa-name">${esc(b.name || 'Animación')}</div>
        <div class="sa-file">${trigLbl}${combo} · 📺 P${b.screen || 1}</div>
        <div class="sa-vol vid-card-vol">
          <span>Volumen</span>
          <input type="range" class="b-volrange" min="0" max="100" value="${b.volume ?? 100}">
          <span class="pct">${b.volume ?? 100}%</span>
        </div>
      </div>
      <div class="sa-card-btns acc-card-icons vid-card-btns">
        <button type="button" class="acc-icon-btn sa-edit" title="Editar">${CARD_ICON.gear}</button>
        ${b.trigger === 'streamdeck' ? `<button type="button" class="acc-icon-btn sa-wh" title="Copiar webhook Stream Deck">🔗</button>` : ''}
        <button type="button" class="acc-icon-btn sa-play" title="Probar en pantalla">${CARD_ICON.play}</button>
        <button type="button" class="acc-icon-btn sa-stop" title="Detener video">${CARD_ICON.stop}</button>
        <button type="button" class="acc-icon-btn acc-dup sa-dup" title="Duplicar">${CARD_ICON.dup}</button>
        <button type="button" class="acc-icon-btn sa-del" title="Borrar">${CARD_ICON.trash}</button>
      </div>
    </div>`;
  }).join('');

  el.querySelectorAll('.sa-card').forEach((card) => {
    const id = card.dataset.id;
    const b = list.find((x) => String(x.id) === String(id));
    if (!b) return;
    card.querySelector('.b-toggle').onchange = (e) => {
      b.enabled = e.target.checked;
      saveVideosBattlePatch('battleAlerts');
      syncBaMasterUI();
      renderBattleAlerts();
    };
    const vr = card.querySelector('.b-volrange');
    if (vr) bindCardVolumeSlider(vr, card, 'battleAlerts', (n) => { b.volume = n; }, () => saveMediaVolumePatch('battleAlerts'));
    card.querySelector('.sa-edit').onclick = () => openBaModal(b);
    const whBtn = card.querySelector('.sa-wh');
    if (whBtn) {
      whBtn.onclick = async () => {
        await syncDesktopWebhookSettings();
        const text = baStreamdeckWebhookUrl(b.id);
        const done = () => toast && toast('Webhook copiado — pégalo en Stream Deck', 'ok');
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
        else fallbackCopy(text, done);
      };
    }
    card.querySelector('.sa-play').onclick = () => send({ action: 'testVideo', video: { id: b.id, name: b.name, url: b.url, screen: b.screen || 1, volume: b.volume ?? 100 } });
    card.querySelector('.sa-stop').onclick = () => send({ action: 'stopVideo', screen: b.screen || 1 });
    const dup = card.querySelector('.sa-dup');
    if (dup) {
      dup.onclick = (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!ensureCanAdd('battleAlerts', 'battleAlerts', 'animaciones de batalla')) return;
        duplicateSettingsItem('battleAlerts', id, {
          idPrefix: 'ba',
          render: renderBattleAlerts,
          save: () => saveVideosBattlePatch('battleAlerts'),
          toastMsg: 'Animación duplicada.',
        });
      };
    }
    card.querySelector('.sa-del').onclick = async () => {
      const ok = await askConfirm({ title: 'Borrar animación', message: `Se eliminará la animación de batalla «${esc(b.name || 'animación')}».` });
      if (!ok) return;
      settings.battleAlerts = settings.battleAlerts.filter((x) => String(x.id) !== String(id));
      lastSlotMediaEditAt = Date.now();
      try { markAllowEmptySlotLists(); } catch { settings._allowEmptySlotLists = true; }
      flushSaveSettings();
      delete settings._allowEmptySlotLists;
      await syncDesktopWebhookSettings();
      renderBattleAlerts();
    };
  });
  if (!q) {
    bindSaCardLongPressReorder(el, (ids) => {
      if (!applySettingsListOrder('battleAlerts', ids)) return;
      saveVideosBattlePatch('battleAlerts');
    });
  }
  syncBaMasterUI();
}

function updateBaGiftBtn() {
  const name = $('ba-gift').value;
  const id = $('ba-giftid').value;
  $('ba-giftpick').textContent = name ? `🎁 ${name}${id ? ' (#' + id + ')' : ''}` : '🎁 Elegir regalo…';
}

function setBaTriggerUI(value) {
  $('ba-trigger').value = value;
  $('ba-giftextra').hidden = value !== 'battleGift';
  $('ba-countextra').hidden = !(value === 'battleGift' || value === 'battleGiftAny');
  const sd = $('ba-streamdeck-extra');
  if (sd) sd.hidden = value !== 'streamdeck';
  if (value === 'streamdeck') refreshBaStreamdeckUrl();
  const pkHint = $('ba-pk-hint');
  if (pkHint) {
    pkHint.hidden = false;
    pkHint.innerHTML = value === 'streamdeck'
      ? 'Se dispara <b>cuando pulsas el botón</b> en Stream Deck (no hace falta estar en PK).'
      : 'Solo se dispara <b>durante una batalla PK</b> de TikTok.';
  }
  const min = $('ba-mincount');
  if (min) {
    min.placeholder = value === 'battleGift'
      ? 'Multiplicador mínimo (1 = cualquier guante, 2 = x2+, 3 = solo x3+)'
      : 'A partir de cuántos envíos (1 = cualquiera, 5 = combo x5)';
  }
  syncTrigSelectGrid('ba-trig-grid', 'ba-trigger', 'critical');
}

function openBaModal(b = null) {
  baEditingId = b?.id || null;
  baPending = b?.url ? { url: b.url, name: b.fileName } : null;
  $('ba-name').value = b?.name || '';
  const trig = b?.trigger || ((b?.giftName || b?.giftId) ? 'battleGift' : 'critical');
  setBaTriggerUI(trig);
  $('ba-gift').value = b?.giftName || '';
  $('ba-giftid').value = b?.giftId || '';
  updateBaGiftBtn();
  $('ba-mincount').value = b?.minCount || 1;
  $('ba-vol').value = b?.volume ?? 100;
  fillScreenSelect($('ba-screen'), b?.screen || 1);
  $('ba-fname').textContent = b?.fileName || 'Ningún archivo';
  $('ba-status').textContent = trig === 'streamdeck'
    ? 'Guarda la animación y copia el webhook para Stream Deck.'
    : '';
  closeVideoLib();
  $('baModal').classList.remove('hidden');
}
function closeBaModal() { $('baModal').classList.add('hidden'); }
$('ba-trigger').addEventListener('change', () => setBaTriggerUI($('ba-trigger').value));
bindTrigSelectGrid('ba-trig-grid', 'ba-trigger');
if ($('ba-streamdeck-copy')) {
  $('ba-streamdeck-copy').onclick = () => {
    refreshBaStreamdeckUrl();
    const text = $('ba-streamdeck-url')?.textContent || '';
    if (!text || text.includes('…')) {
      toast && toast('Guarda la animación primero para fijar el ID.', 'warn');
      return;
    }
    const done = () => toast && toast('Webhook copiado — pégalo en Stream Deck', 'ok');
    if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
    else fallbackCopy(text, done);
  };
}

$('ba-create').onclick = () => { if (ensureCanAdd('battleAlerts', 'battleAlerts', 'animaciones de batalla')) openBaModal(null); };
$('ba-cancel').onclick = closeBaModal;
$('baModal').addEventListener('click', (e) => { if (e.target.id === 'baModal') closeBaModal(); });
$('ba-giftpick').onclick = () => openGiftModal('sa', (g) => {
  $('ba-gift').value = g.name || '';
  $('ba-giftid').value = g.id || '';
  updateBaGiftBtn();
});
$('ba-libbtn').onclick = () => {
  if (isVideosAiLocked()) {
    toast('Videos AI es Solo Premium. Mejora tu plan para usarlo ⭐', 'warn');
    return;
  }
  libTarget = 'ba';
  openVideoLib();
};
$('ba-upbtn').onclick = () => $('ba-file').click();
$('ba-file').addEventListener('change', async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const label = $('ba-fname');
  try {
    const data = await uploadMediaWithProgress(file, (msg) => { label.textContent = msg; });
    baPending = { url: data.url, name: file.name };
    label.textContent = file.name;
  } catch (err) { label.textContent = uploadErrLabel(err); }
  e.target.value = '';
});

$('ba-save').onclick = async () => {
  const name = $('ba-name').value.trim();
  const trig = $('ba-trigger').value;
  if (!name) { $('ba-status').textContent = '⚠️ Escribe un nombre.'; return; }
  if (!baPending?.url) { $('ba-status').textContent = '⚠️ Elige o sube un video.'; return; }
  const id = ensureBaEditId();
  const data = {
    name,
    trigger: trig,
    // Potenciador guante / Stream Deck: no usan regalo.
    giftName: '',
    giftId: '',
    minCount: (trig === 'battleGift' || trig === 'battleGiftAny') ? Math.max(1, +$('ba-mincount').value || 1) : 1,
    url: baPending.url,
    fileName: baPending.name || 'video',
    volume: +$('ba-vol').value,
    screen: clampScreenId(+$('ba-screen').value || 1),
  };
  if (!settings.battleAlerts) settings.battleAlerts = [];
  const existing = settings.battleAlerts.find((x) => x.id === id);
  if (existing) Object.assign(existing, data);
  else settings.battleAlerts.push({ id, enabled: true, ...data });
  baEditingId = id;
  flushSaveSettings();
  await syncDesktopWebhookSettings();
  renderBattleAlerts();
  closeBaModal();
  if (trig === 'streamdeck') {
    toast && toast('Guardado. Usa 🔗 en la tarjeta para copiar el webhook a Stream Deck.', 'ok');
  }
};

$('ba-master').addEventListener('change', () => {
  toggleAllBattleAlerts($('ba-master').checked);
});

