if ($('sa-streamdeck-copy')) {
  $('sa-streamdeck-copy').onclick = () => {
    refreshSaStreamdeckUrl();
    const text = $('sa-streamdeck-url')?.textContent || '';
    if (!text || text.includes('…')) {
      toast && toast('Guarda la alerta primero para fijar el ID.', 'warn');
      return;
    }
    const done = () => toast && toast('Webhook copiado — pégalo en Stream Deck', 'ok');
    if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
    else fallbackCopy(text, done);
  };
}

/* ----- Selector de regalos ----- */
let giftCatalog = [];
const giftCatalogById = new Map();
let communityGiftCatalog = [];

function giftCatalogFindByName(name) {
  const want = String(name || '').trim().toLowerCase();
  if (!want || !Array.isArray(giftCatalog)) return null;
  return giftCatalog.find((x) => String(x && x.name || '').toLowerCase() === want) || null;
}

function indexGiftCatalog() {
  giftCatalogById.clear();
  giftCatalogSorted = null;
  for (const g of giftCatalog) giftCatalogById.set(String(g.id), g);
}

/** Lista ordenada cacheada (evita sort O(n log n) en cada tecla / apertura). */
let giftCatalogSorted = null;
function getSortedGiftCatalog() {
  if (giftCatalogSorted) return giftCatalogSorted;
  giftCatalogSorted = [...giftCatalog].sort((a, b) =>
    (Number(a.diamonds) || 0) - (Number(b.diamonds) || 0) || String(a.name || '').localeCompare(String(b.name || ''))
  );
  return giftCatalogSorted;
}

function mergeGiftCatalogWithCommunity(base, community) {
  const byId = new Map();
  for (const g of [...(community || []), ...(base || [])]) {
    const id = String(g?.id ?? '');
    if (!id) continue;
    byId.set(id, { ...byId.get(id), ...g });
  }
  return [...byId.values()].sort((a, b) =>
    (Number(a.diamonds) || 0) - (Number(b.diamonds) || 0) || String(a.name || '').localeCompare(String(b.name || ''))
  );
}

let giftCatalogLoading = false;
async function preloadGiftCatalog(attempt = 0) {
  if (giftCatalog.length) return;
  if (giftCatalogLoading) return;
  giftCatalogLoading = true;
  try {
    const res = await fetch('/api/gifts');
    const data = await res.json();
    giftCatalog = data.results || [];
    indexGiftCatalog();
    giftCatalogLoading = false;
    // Una vez cargado el catálogo, volvemos a dibujar TODAS las secciones que muestran
    // iconos de regalo, por si sus fichas se dibujaron antes (entonces salía el emoji).
    if (giftCatalog.length) refreshGiftCards();
  } catch {
    giftCatalogLoading = false;
    // Reintenta: la primera carga puede fallar si el servidor está "despertando" o la
    // red parpadea. Así las fichas SIEMPRE terminan mostrando el regalo configurado.
    if (attempt < 6) setTimeout(() => preloadGiftCatalog(attempt + 1), 2000);
  }
}

// Re-dibuja las secciones con iconos de regalo (cuando ya hay catálogo y ajustes).
function refreshGiftCards() {
  if (!settings) return;
  if (typeof renderSoundAlerts === 'function') { try { refreshSoundAlertsFromSettings(); } catch {} }
  if (typeof renderVideos === 'function') { try { refreshVideosFromSettings(); } catch {} }
  if (typeof renderBattleAlerts === 'function') { try { refreshBattleAlertsFromSettings(); } catch {} }
  if (typeof renderAcciones === 'function') { try { renderAcciones(); } catch {} }
  if (typeof pushGiftShowcasePreview === 'function') { try { pushGiftShowcasePreview(settings?.giftShowcase); } catch {} }
  if (typeof pushGiftGoalsPreview === 'function') { try { pushGiftGoalsPreview(settings?.giftGoals); } catch {} }
  if (typeof syncGgmScaleUi === 'function') {
    try { syncGgmScaleUi(settings?.giftGoals?.scale || 67); } catch {}
  }
}

function isEmoteEvent(ev) {
  return ev === 'emote' || ev === 'emoteFan';
}
function normEmoteClub(v) {
  const s = String(v || '').toLowerCase();
  if (s === 'fan' || s === 'fanclub' || s === 'fansclub') return 'fan';
  if (s === 'superfan' || s === 'super' || s === 'superfanclub') return 'superfan';
  return '';
}

const EVENT_EMOJI = {
  like: '❤️', likeGlobal: '❤️', follow: '➕', share: '🔁',
  subscribe: '⭐', superFan: '🌟', superFanJoin: '🌟', fan: '💛', levelUp: '⬆️', emote: '😀', emoteFan: '😀', gift: '🎁',
  'gift-all': '🎁', join: '🚪', chatAny: '💬',
  chatCommand: '💬', firstMessage: '🙋', streamdeck: '🎛️',
  battleStart: '🟢', battleLast10: '⏱', battleEnd: '🔴',
  battleWin: '🏆', battleLose: '💔',
};
const TRIG_ICON = {
  'gift-all': '/img/trig/gift.png?v=2',
  'gift-any': '/img/trig/diamonds.png?v=2',
  gift: '/img/trig/gift.png?v=2',
  'gift-name': '/img/trig/gift.png?v=2',
  'gift-diamonds': '/img/trig/diamonds.png?v=2',
  like: '/img/trig/like.png?v=2',
  likeGlobal: '/img/trig/like-global.png?v=2',
  share: '/img/trig/share.png?v=2',
  subscribe: '/img/trig/subscribe.png?v=2',
  fan: '/img/trig/subscribe.png?v=2',
  superFan: '/img/trig/superfan.png?v=2',
  superFanJoin: '/img/trig/superfan-join.png?v=2',
  follow: '/img/trig/follow.png?v=2',
  join: '/img/trig/firstmsg.png?v=2',
  levelUp: '/img/trig/levelup.png?v=2',
  emote: '/img/trig/emote.png?v=2',
  emoteFan: '/img/trig/emote.png?v=2',
  chatAny: '/img/trig/chat.png?v=2',
  chatCommand: '/img/trig/chat.png?v=2',
  chatUser: '/img/trig/chat.png?v=2',
  firstMessage: '/img/trig/firstmsg.png?v=2',
  streamdeck: '/img/trig/streamdeck.png?v=2',
};
function trigIconChip(key) {
  const src = TRIG_ICON[key];
  if (!src) return null;
  return `<span class="acc-chip-ico"><img class="acc-chip-trig" src="${src}" alt=""></span>`;
}
function trigIconImg(key, cls = 'sa-ic-img') {
  const src = TRIG_ICON[key];
  if (!src) return '';
  return `<img class="${cls}" src="${src}" alt="" loading="lazy" decoding="async">`;
}
/** Icono HTML para disparadores de juegos (MC / Mario / SFX…). gift-any = regalo, no diamantes. */
function gameTrigIconHtml(key, cls = 'mc-trig-img') {
  let src = TRIG_ICON[key];
  if (key === 'gift-any') src = '/img/trig/gift.png?v=2';
  if (!src) return `<span class="mc-trig-emoji">⚡</span>`;
  return `<img class="${cls}" src="${src}" alt="" loading="lazy" decoding="async">`;
}
/** Precarga iconos de disparadores en idle para que modales abran al instante. */
(function prefetchTrigIcons() {
  const run = () => {
    try {
      const seen = new Set();
      Object.values(TRIG_ICON).forEach((src) => {
        if (!src || seen.has(src)) return;
        seen.add(src);
        const img = new Image();
        img.decoding = 'async';
        img.src = src;
      });
    } catch {}
  };
  if (typeof requestIdleCallback === 'function') requestIdleCallback(run, { timeout: 2000 });
  else setTimeout(run, 800);
})();

// Busca la imagen de un sticker/emote por su id en el catálogo cargado.
function emoteImgById(id) {
  if (!id) return '';
  const e = emoteCatalog.find((x) => String(x.id) === String(id));
  return e?.image || '';
}

// Devuelve el HTML del icono de la alerta (regalo real, sticker, imagen propia o emoji)
function alertIconHTML(a) {
  if (a.image) return `<img class="sa-ic-img" src="${esc(a.image)}" loading="lazy" decoding="async">`;
  const trig = a.trigger || 'gift';
  if (trig === 'gift' && a.giftId) {
    const g = giftCatalogById.get(String(a.giftId));
    if (g?.image) return `<img class="sa-ic-img" src="${esc(g.image)}" loading="lazy" decoding="async">`;
  }
  if (trig === 'gift' && a.giftName) {
    const g = giftCatalogFindByName(a.giftName);
    if (g?.image) return `<img class="sa-ic-img" src="${esc(g.image)}" loading="lazy" decoding="async">`;
  }
  if (trig === 'emote' || trig === 'emoteFan') {
    const img = a.emoteImage || emoteImgById(a.emoteId);
    if (img) return `<img class="sa-ic-img" src="${esc(img)}" loading="lazy" decoding="async">`;
  }
  const trigImg = trigIconImg(trig === 'gift' && (a.rangeMin || a.rangeMax) ? 'gift-any' : trig, 'sa-ic-img');
  if (trigImg) return trigImg;
  return `<span class="sa-ic-emoji">${EVENT_EMOJI[trig] || '🔔'}</span>`;
}

// Versión pequeña para la esquina de las tarjetas
function alertIconSmall(a) {
  const trig = a.trigger || 'gift';
  let img = '';
  if (a.image) img = a.image;
  else if (trig === 'gift' && a.giftId) img = giftCatalogById.get(String(a.giftId))?.image || '';
  else if (trig === 'gift' && a.giftName) img = giftCatalogFindByName(a.giftName)?.image || '';
  else if (trig === 'emote' || trig === 'emoteFan') img = a.emoteImage || emoteImgById(a.emoteId);
  if (img) return `<img class="sa-ic-mini" src="${esc(img)}" loading="lazy" decoding="async">`;
  const trigImg = trigIconImg(trig === 'gift' && (a.rangeMin || a.rangeMax) ? 'gift-any' : trig, 'sa-ic-mini');
  if (trigImg) return trigImg;
  return `<span class="sa-ic-mini-emoji">${EVENT_EMOJI[trig] || '🔔'}</span>`;
}

/* ----- Selector de stickers / emotes (compartido sa/vid/acc) ----- */
let emoteCatalog = [];
let emoteTarget = 'vid';
let emoteFilterClub = '';

function emoteTargetEvent() {
  if (emoteTarget === 'acc') return $('acc-event')?.value || '';
  if (emoteTarget === 'sa') return $('sa-event')?.value || '';
  if (emoteTarget === 'vid') return $('vid-event')?.value || '';
  return '';
}
function emoteDefaultClubFromTarget() {
  const ev = emoteTargetEvent();
  if (ev === 'emoteFan') return 'fan';
  if (ev === 'emote') return 'superfan';
  return '';
}
function emoteAddClub() {
  return emoteFilterClub || emoteDefaultClubFromTarget() || 'fan';
}
function syncEmoteClubTabs() {
  document.querySelectorAll('#emote-club-tabs .gift-tab').forEach((btn) => {
    btn.classList.toggle('active', String(btn.dataset.club || '') === String(emoteFilterClub || ''));
  });
  const addBtn = $('emote-add-btn');
  if (addBtn) {
    addBtn.textContent = emoteAddClub() === 'superfan' ? '＋ Subir sticker Super Fan' : '＋ Subir sticker Fan Club';
  }
}

function updateEmotePickBtn(target) {
  const t = target || emoteTarget;
  const btn = $(t + '-emotepick');
  if (!btn) return;
  const id = $(t + '-emoteid').value;
  const e = emoteCatalog.find((x) => String(x.id) === String(id));
  if (id && e?.image) btn.innerHTML = `<img class="sa-ic-mini" src="${esc(e.image)}"> Sticker elegido`;
  else if (id) btn.textContent = `🙂 Sticker #${id}`;
  else btn.textContent = '🙂 Elegir sticker…';
}

function closeAccEmoteMenu() {
  const menu = $('accEmoteMenu');
  const btn = $('acc-emotepick');
  if (menu) {
    menu.hidden = true;
    menu.classList.remove('is-up');
    menu.style.maxHeight = '';
  }
  if (btn) {
    btn.classList.remove('is-open');
    btn.setAttribute('aria-expanded', 'false');
  }
}
function placeAccEmoteMenu() {
  const menu = $('accEmoteMenu');
  const btn = $('acc-emotepick');
  if (!menu || !btn || menu.hidden) return;
  const boxEl = document.querySelector('#accModal .acc-modal-body') || $('accModal');
  if (!boxEl) return;
  const br = btn.getBoundingClientRect();
  const box = boxEl.getBoundingClientRect();
  const gap = 8;
  const spaceBelow = Math.max(0, box.bottom - br.bottom - gap);
  const spaceAbove = Math.max(0, br.top - box.top - gap);
  const openUp = spaceAbove > spaceBelow && spaceBelow < 180;
  const avail = Math.floor(openUp ? spaceAbove : spaceBelow);
  menu.classList.toggle('is-up', openUp);
  menu.style.maxHeight = `${Math.max(120, Math.min(280, avail || 220))}px`;
}
function closeEmoteModal() {
  const modal = $('emoteModal');
  if (modal) {
    modal.classList.add('hidden');
    modal.classList.remove('emote-pick-pop');
  }
  document.querySelectorAll('.gift-pick-btn.is-open').forEach((b) => {
    if (b.id === 'acc-emotepick') return;
    b.classList.remove('is-open');
  });
  closeAccEmoteMenu();
}
function emotePickAnchor() {
  return $(String(emoteTarget || 'acc') + '-emotepick');
}
function placeEmotePickPop() {
  const modal = $('emoteModal');
  const box = modal && modal.querySelector('.emote-pick-box');
  const anchor = emotePickAnchor();
  if (!modal || !box || modal.classList.contains('hidden')) return;
  modal.classList.add('emote-pick-pop');
  const gap = 6;
  const r = anchor && typeof anchor.getBoundingClientRect === 'function' ? anchor.getBoundingClientRect() : null;
  const w = Math.min(Math.max(r ? r.width : 320, 280), window.innerWidth - 16);
  box.style.width = w + 'px';
  box.style.maxWidth = w + 'px';
  let left = 8;
  let top = 8;
  if (r) {
    left = r.left;
    if (left + w > window.innerWidth - 8) left = window.innerWidth - w - 8;
    if (left < 8) left = 8;
    const spaceBelow = Math.max(0, window.innerHeight - r.bottom - gap - 8);
    const spaceAbove = Math.max(0, r.top - gap - 8);
    const openUp = spaceAbove > spaceBelow && spaceBelow < 220;
    const avail = Math.floor(openUp ? spaceAbove : spaceBelow);
    const h = Math.max(160, Math.min(420, avail || 320));
    box.style.maxHeight = h + 'px';
    if (openUp) top = Math.max(8, r.top - h - gap);
    else top = r.bottom + gap;
  }
  box.style.left = left + 'px';
  box.style.top = top + 'px';
}
function bindEmotePickPlace() {
  if (document.documentElement.dataset.emotePickPlace === '1') return;
  document.documentElement.dataset.emotePickPlace = '1';
  const relayout = () => {
    if ($('emoteModal')?.classList.contains('hidden')) return;
    placeEmotePickPop();
  };
  window.addEventListener('resize', relayout);
  document.addEventListener('scroll', relayout, true);
}

async function openEmoteModal(target = 'vid') {
  emoteTarget = target;
  emoteFilterClub = emoteDefaultClubFromTarget();
  syncEmoteClubTabs();
  if (target === 'acc') {
    const menu = $('accEmoteMenu');
    const btn = $('acc-emotepick');
    if (!menu || !btn) return;
    if (!menu.hidden) {
      closeAccEmoteMenu();
      return;
    }
    try { closeAccMsMenus(); } catch {}
    const qEl = $('acc-emote-q');
    if (qEl) qEl.value = '';
    menu.hidden = false;
    btn.classList.add('is-open');
    btn.setAttribute('aria-expanded', 'true');
    const list = $('acc-emote-list');
    if (list) list.innerHTML = '<div class="empty">Cargando…</div>';
    placeAccEmoteMenu();
    try { seedEmoteCatalogFromImport(collectEmotesFromLivecoinsSettings(settings)); } catch {}
    if (!emoteCatalog.length) {
      try {
        const apiUrl = (relayActive() || desktopRelayOn()) ? '/api/desktop/emotes' : '/api/emotes';
        const res = await fetch(apiUrl);
        const data = await res.json();
        seedEmoteCatalogFromImport(data.results || []);
      } catch {}
    }
    renderEmoteGrid();
    placeAccEmoteMenu();
    requestAnimationFrame(() => {
      placeAccEmoteMenu();
      try { qEl?.focus(); } catch {}
    });
    return;
  }
  const modal = $('emoteModal');
  if (!modal) return;
  const already = !modal.classList.contains('hidden') && modal.classList.contains('emote-pick-pop');
  if (already) {
    closeEmoteModal();
    return;
  }
  try {
    if (modal.parentElement !== document.body) document.body.appendChild(modal);
  } catch {}
  bindEmotePickPlace();
  const qEl = $('emote-q');
  if (qEl) qEl.value = '';
  modal.classList.add('emote-pick-pop');
  modal.classList.remove('hidden');
  document.querySelectorAll('.gift-pick-btn.is-open').forEach((b) => b.classList.remove('is-open'));
  emotePickAnchor()?.classList.add('is-open');
  const grid = $('emote-grid');
  if (grid) grid.innerHTML = '<div class="empty">Cargando…</div>';
  placeEmotePickPop();
  try { seedEmoteCatalogFromImport(collectEmotesFromLivecoinsSettings(settings)); } catch {}
  const cached = emoteCatalog.slice();
  try {
    const apiUrl = (relayActive() || desktopRelayOn()) ? '/api/desktop/emotes' : '/api/emotes';
    const res = await fetch(apiUrl);
    const data = await res.json();
    const fresh = data.results || [];
    seedEmoteCatalogFromImport([...(fresh || []), ...cached]);
  } catch {
    emoteCatalog = cached;
  }
  renderEmoteGrid();
  placeEmotePickPop();
  requestAnimationFrame(() => {
    placeEmotePickPop();
    try { qEl?.focus(); } catch {}
  });
}

function emoteSearchNeedle() {
  if (emoteTarget === 'acc') return String($('acc-emote-q')?.value || '').trim().toLowerCase();
  return String($('emote-q')?.value || '').trim().toLowerCase();
}
function emotePickListEl() {
  if (emoteTarget === 'acc') return $('acc-emote-list');
  return $('emote-grid');
}
function emotePickGroups() {
  const pref = emoteDefaultClubFromTarget() || emoteFilterClub;
  if (pref === 'fan') return [{ club: 'fan', label: 'Fan Club' }];
  if (pref === 'superfan') return [{ club: 'superfan', label: 'Super Fan Club' }];
  return [
    { club: 'fan', label: 'Fan Club' },
    { club: 'superfan', label: 'Super Fan Club' },
  ];
}
function emoteMatchesSearch(e, q) {
  if (!q) return true;
  const name = String(e.name || '').toLowerCase();
  const id = String(e.id || '').toLowerCase();
  return name.includes(q) || id.includes(q);
}
function applyPickedEmoteId(id) {
  const eid = String(id || '').trim();
  if (!eid) return;
  const idEl = $(emoteTarget + '-emoteid');
  if (idEl) idEl.value = eid;
  updateEmotePickBtn(emoteTarget);
  if (emoteTarget === 'acc') closeAccEmoteMenu();
  else closeEmoteModal();
}

function renderEmoteGrid() {
  const grid = emotePickListEl();
  if (!grid) return;
  const q = emoteSearchNeedle();
  const curId = $(emoteTarget + '-emoteid')?.value || '';
  const groups = emotePickGroups();
  const rowHtml = (e) => {
    const label = esc(e.name || 'Sticker');
    const thumb = e.image
      ? `<img src="${esc(e.image)}" alt="" loading="lazy">`
      : `<span class="emote-ph">🙂</span>`;
    return `<button type="button" class="emote-pick-opt ${String(e.id) === curId ? 'is-on' : ''}" data-id="${esc(e.id)}" data-club="${esc(normEmoteClub(e.club))}">${thumb}<span class="emote-pick-opt-lbl">${label}</span></button>`;
  };
  let html = '';
  let shown = 0;
  const onlyOne = groups.length === 1;
  for (const g of groups) {
    const rows = emoteCatalog.filter((e) => normEmoteClub(e.club) === g.club && emoteMatchesSearch(e, q));
    if (!rows.length) continue;
    if (!onlyOne) html += `<div class="emote-pick-sep">${esc(g.label)}</div>`;
    html += rows.map(rowHtml).join('');
    shown += rows.length;
  }
  const others = emoteCatalog.filter((e) => !normEmoteClub(e.club) && emoteMatchesSearch(e, q));
  if (others.length && (!onlyOne || shown === 0)) {
    if (!onlyOne) html += `<div class="emote-pick-sep">Otros</div>`;
    html += others.map(rowHtml).join('');
    shown += others.length;
  }
  if (!shown) {
    const pack = groups.length === 1 ? groups[0].label : '';
    grid.innerHTML = emoteCatalog.length
      ? (q ? '<div class="empty">Nada coincide.</div>' : `<div class="empty">Aún no hay stickers${pack ? ' de ' + pack : ''}.</div>`)
      : '<div class="empty">Pulsa Obtener Stickers en Inicio.</div>';
    if (emoteTarget === 'acc') placeAccEmoteMenu();
    else placeEmotePickPop();
    return;
  }
  grid.innerHTML = html;
  grid.querySelectorAll('.emote-pick-opt').forEach((btn) => {
    btn.onclick = () => applyPickedEmoteId(btn.dataset.id);
  });
  if (emoteTarget === 'acc') placeAccEmoteMenu();
  else placeEmotePickPop();
}

function addEmoteToCatalog({ id, image, name, club }) {
  const eid = String(id || '').trim();
  if (!eid) return 0;
  return seedEmoteCatalogFromImport([{ id: eid, image: image || '', name: name || '', club: club || emoteAddClub() }]);
}

async function uploadEmoteFromPc(file) {
  if (!file) throw new Error('sin archivo');
  const res = await fetch('/api/local-emotes?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
  const data = await res.json().catch(() => ({}));
  if (!data.url) throw new Error(data.error || 'error');
  return data;
}

async function addEmoteFromFile(file) {
  const club = emoteAddClub();
  let id = ($('emote-add-id')?.value || '').trim();
  const name = ($('emote-add-name')?.value || '').trim() || String(file.name || '').replace(/\.[^.]+$/, '');
  const up = await uploadEmoteFromPc(file);
  if (!id) id = 'custom_' + club + '_' + Date.now().toString(36);
  addEmoteToCatalog({ id, image: up.url, name, club });
  if ($('emote-add-id')) $('emote-add-id').value = '';
  if ($('emote-add-name')) $('emote-add-name').value = '';
  emoteFilterClub = club;
  syncEmoteClubTabs();
  renderEmoteGrid();
}

function addEmoteByIdOnly() {
  const id = ($('emote-add-id')?.value || '').trim();
  if (!id) return false;
  const club = emoteAddClub();
  const name = ($('emote-add-name')?.value || '').trim();
  addEmoteToCatalog({ id, image: emoteImgById(id) || '', name, club });
  if ($('emote-add-id')) $('emote-add-id').value = '';
  if ($('emote-add-name')) $('emote-add-name').value = '';
  emoteFilterClub = club;
  syncEmoteClubTabs();
  renderEmoteGrid();
  return true;
}

/** Stickers con trigger emote ya guardados en settings. */
function collectEmotesFromLivecoinsSettings(s) {
  const map = new Map();
  const add = (id, image, name, club) => {
    const eid = String(id || '').trim();
    if (!eid) return;
    const prev = map.get(eid) || { id: eid, image: '', name: '', club: '' };
    map.set(eid, {
      id: eid,
      image: prev.image || String(image || '').trim(),
      name: prev.name || String(name || '').trim(),
      club: prev.club || normEmoteClub(club),
    });
  };
  const fromTrig = (trig, ev) => {
    if (isEmoteEvent(trig) && ev.emoteId) add(ev.emoteId, ev.emoteImage, ev.name, trig === 'emoteFan' ? 'fan' : 'superfan');
  };
  for (const a of s?.soundAlerts || []) fromTrig(a?.trigger, a);
  for (const v of s?.videos || []) fromTrig(v?.trigger, v);
  for (const a of s?.actions || []) fromTrig(a?.trigger || a?.event, a);
  for (const ev of s?.actionEvents || []) fromTrig(ev?.event, ev);
  return [...map.values()];
}

/** Une stickers al catálogo local y pide al servidor persistirlos. */
function seedEmoteCatalogFromImport(list) {
  if (!Array.isArray(list) || !list.length) return 0;
  const map = new Map(emoteCatalog.map((e) => [String(e.id), { ...e }]));
  let added = 0;
  for (const e of list) {
    const id = String(e?.id || e?.emoteId || '').trim();
    if (!id) continue;
    const img = String(e.image || e.emoteImage || '').trim();
    const name = String(e.name || e.nombre || '').trim();
    const club = normEmoteClub(e.club);
    const prev = map.get(id);
    if (!prev) {
      map.set(id, { id, image: img, name, club });
      added += 1;
    } else {
      map.set(id, {
        id,
        image: prev.image || img,
        name: prev.name || name,
        club: club || prev.club || '',
      });
    }
  }
  emoteCatalog = [...map.values()];
  try { send({ action: 'importEmotes', emotes: emoteCatalog }); } catch {}
  return added;
}

// Contenido del botón "Elegir regalo": muestra el icono real del regalo (no el emoji)
// cuando hay uno seleccionado. Se usa en alertas, videos y acciones.
function giftBtnHTML(name, id, fallback = '🎁 Elegir regalo…') {
  if (!name && !id) return fallback;
  const g = id ? giftCatalogById.get(String(id))
    : giftCatalogFindByName(name);
  const label = name || g?.name || '';
  const icon = g?.image ? `<img class="gift-pick-ic" src="${esc(g.image)}" onerror="this.outerHTML='🎁'">` : '🎁';
  return `${icon} ${esc(label)}`;
}

