const LC_TT_ACCOUNT_KEY = 'lcTikTokAccount';
let ttAccountLoggedIn = false;
let ttAccountName = '';
function paintTikTokAccountBtn(loggedIn, uniqueId) {
  if (typeof loggedIn === 'boolean') ttAccountLoggedIn = !!loggedIn;
  if (arguments.length > 1) ttAccountName = String(uniqueId || '').replace(/^@/, '').trim();
  const btn = $('btnTikTokAccount');
  if (!btn) return;
  btn.classList.remove('is-on', 'is-live');
  if (!ttAccountLoggedIn) {
    btn.textContent = 'Conectar cuenta de TikTok';
    return;
  }
  btn.textContent = ttAccountName ? ('Cuenta @' + ttAccountName) : 'Cuenta conectada';
}
function syncTikTokAccountLive(on) {
  window.__lcTiktokLive = !!on;
  const chip = document.getElementById('user-chip');
  if (chip) chip.classList.toggle('is-live', !!on);
  const corner = document.getElementById('ttLiveCorner');
  const txt = document.getElementById('ttLiveCornerTxt');
  if (!corner) return;
  corner.classList.toggle('live', !!on);
  corner.classList.toggle('off', !on);
  if (txt) txt.textContent = on ? 'En live' : 'Desconectado';
}
async function refreshTikTokAccountBtn() {
  const api = window.desktopAPI;
  if (!api?.tiktokSession) {
    paintTikTokAccountBtn(false);
    return;
  }
  try {
    const s = await api.tiktokSession();
    const fromFile = String(s?.uniqueId || '').replace(/^@/, '').trim();
    let saved = fromFile;
    if (!saved) {
      try { saved = String(localStorage.getItem(LC_TT_ACCOUNT_KEY) || '').replace(/^@/, '').trim(); } catch {}
    }
    if (saved) {
      try { localStorage.setItem(LC_TT_ACCOUNT_KEY, saved); } catch {}
      applyTikTokAccountToUsername(saved);
    }
    paintTikTokAccountBtn(!!s?.loggedIn, saved);
  } catch {
    paintTikTokAccountBtn(false);
  }
}
function applyTikTokAccountToUsername(name) {
  const n = String(name || '').replace(/^@/, '').trim();
  if (!n) return;
  const inp = $('username');
  if (inp) inp.value = n;
  try { setLastTikTokUserPref(n); } catch {}
  try { updateConnectAvatar({ username: n }); } catch {}
}
function setupTikTokAccountBtn() {
  const btn = $('btnTikTokAccount');
  if (!btn || btn.dataset.ttAccountWired === '1') return;
  btn.dataset.ttAccountWired = '1';
  btn.addEventListener('click', () => { connectTikTokAccount(); });
  refreshTikTokAccountBtn();
}
async function connectTikTokAccount() {
  const api = window.desktopAPI;
  const btn = $('btnTikTokAccount');
  if (!api?.loginTikTok) {
    toast && toast(
      api?.isDesktop
        ? 'Cierra Livecoins del todo y ábrela otra vez (F5 no basta).'
        : 'Iniciar sesión en TikTok solo funciona en el .exe de Livecoins.',
      'warn'
    );
    return;
  }
  if (btn) { btn.disabled = true; btn.textContent = 'Inicia sesión…'; }
  try {
    let session = null;
    try { session = await api.tiktokSession?.(); } catch {}
    if (session?.loggedIn) {
      const already = String(session.uniqueId || '').replace(/^@/, '').trim();
      if (already) {
        try { localStorage.setItem(LC_TT_ACCOUNT_KEY, already); } catch {}
        applyTikTokAccountToUsername(already);
      }
      paintTikTokAccountBtn(true, already);
      toast && toast('La cuenta de TikTok ya está conectada.', 'ok');
      return;
    }
    const login = await api.loginTikTok({ purpose: 'account', fresh: true });
    if (login?.busy) return;
    if (!login?.ok) {
      toast && toast(login?.cancelled ? 'Login cancelado.' : (login?.error || 'No se inició sesión.'), 'warn');
      await refreshTikTokAccountBtn();
      return;
    }
    const name = String(login.uniqueId || '').replace(/^@/, '').trim();
    try { if (name) localStorage.setItem(LC_TT_ACCOUNT_KEY, name); } catch {}
    paintTikTokAccountBtn(true, name);
    applyTikTokAccountToUsername(name);
    toast && toast(name ? ('Cuenta @' + name + ' conectada') : 'Cuenta de TikTok conectada', 'success');
  } catch (err) {
    toast && toast(String(err && err.message || err), 'error');
    await refreshTikTokAccountBtn();
  } finally {
    if (btn) btn.disabled = false;
  }
}

const LC_TT_EMOTE_OWNER_KEY = 'lcTikTokEmotesOwner';
function currentLcUserKey() {
  return String(window.MY_USER_ID || window.MY_USER || '').trim().toLowerCase();
}
function savedEmoteOwner() {
  try { return String(localStorage.getItem(LC_TT_EMOTE_OWNER_KEY) || '').trim().toLowerCase(); } catch { return ''; }
}
function markEmotesOwnedByCurrentUser() {
  const k = currentLcUserKey() || 'local';
  try { localStorage.setItem(LC_TT_EMOTE_OWNER_KEY, k); } catch {}
}
async function ensureEmoteCatalogLoaded() {
  try { seedEmoteCatalogFromImport(collectEmotesFromLivecoinsSettings(settings)); } catch {}
  if (emoteCatalog.length) return;
  try {
    const apiUrl = (relayActive() || desktopRelayOn()) ? '/api/desktop/emotes' : '/api/emotes';
    const res = await fetch(apiUrl);
    const data = await res.json();
    seedEmoteCatalogFromImport(data.results || []);
  } catch {}
}
function thisUserAlreadyHasEmotes() {
  if (!emoteCatalog.length) return false;
  const me = currentLcUserKey();
  const owner = savedEmoteOwner();
  if (!owner) return false;
  if (owner === 'local') {
    if (me) markEmotesOwnedByCurrentUser();
    return true;
  }
  if (me && owner !== me) return false;
  return true;
}

function applyFetchedTikTokEmotes(list) {
  seedEmoteCatalogFromImport(Array.isArray(list) ? list : []);
  try { send({ action: 'importEmotes', emotes: emoteCatalog }); } catch {}
  try {
    if ($('accEmoteMenu') && !$('accEmoteMenu').hidden) emoteTarget = 'acc';
    renderEmoteGrid();
  } catch {}
  markEmotesOwnedByCurrentUser();
  toast && toast('Lista de stickers actualizados', 'success');
}

async function fetchTikTokEmotesFromApp() {
  const api = window.desktopAPI;
  if (!api?.fetchTikTokEmotes) {
    toast && toast(
      api?.isDesktop
        ? 'Cierra Livecoins del todo y ábrela otra vez (F5 no basta).'
        : 'Obtener Stickers solo funciona en el .exe de Livecoins, no en el navegador.',
      'warn'
    );
    return;
  }
  await ensureEmoteCatalogLoaded();
  const btn = $('emoteFetchDockBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Cargando…'; }
  try {
    let session = null;
    try { session = await api.tiktokSession?.(); } catch {}
    let saved = '';
    try { saved = localStorage.getItem(LC_TT_ACCOUNT_KEY) || ''; } catch {}
    if (!session?.loggedIn) {
      toast && toast('Primero inicia sesión con Conectar cuenta de TikTok.', 'warn');
      return;
    }
    const r = await api.fetchTikTokEmotes({ uniqueId: saved });
    if (r?.needLogin) {
      try { await api.logoutTikTok?.(); } catch {}
      paintTikTokAccountBtn(false, saved);
      toast && toast('La sesión de TikTok caducó. Vuelve a entrar con Conectar cuenta de TikTok.', 'warn');
      return;
    }
    if (!r?.ok) {
      toast && toast(r?.error || 'No se pudieron cargar los emotes.', 'error');
      return;
    }
    applyFetchedTikTokEmotes(r.emotes);
    const who = r.uniqueId || saved;
    if (who) {
      try { localStorage.setItem(LC_TT_ACCOUNT_KEY, String(who).replace(/^@/, '')); } catch {}
      applyTikTokAccountToUsername(who);
      paintTikTokAccountBtn(true, who);
    }
  } catch (err) {
    toast && toast(String(err && err.message || err), 'error');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = emoteFetchDockHtml();
    }
  }
}
