async function uploadFile(file, kind) {
  if (!file) return;
  const label = $('sa-soundname');
  label.textContent = 'Subiendo…';
  try {
    const res = await fetch('/api/upload?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
    const data = await res.json();
    if (!data.url) throw new Error(data.error || 'error');
    pendingSound = { url: data.url, name: file.name }; label.textContent = file.name;
  } catch (err) {
    label.textContent = uploadErrLabel(err);
  }
}

/* Biblioteca de sonidos: lee la carpeta local /audios */
let libAudio = null;
let localSounds = [];
// A dónde va el sonido elegido: 'alert', 'action' o 'mc' (tarjeta Minecraft).
let soundPickTarget = 'alert';
let mcSoundPickUid = null;
let mcAudioUploadUid = null;

function applyPickedSound(url, name) {
  if (soundPickTarget === 'action') {
    accPendingSound = { url, name };
    const el = $('acc-soundname'); if (el) el.textContent = name;
    const vr = $('acc-volrow'); if (vr) vr.hidden = false;
  } else if (soundPickTarget === 'mc' && mcSoundPickUid) {
    const hit = (typeof findAnyGameAction === 'function' && findAnyGameAction(mcSoundPickUid))
      || (typeof findMcFamilyAction === 'function' && findMcFamilyAction(mcSoundPickUid));
    if (hit?.action) {
      hit.action.sound = url;
      hit.action.soundName = name;
      hit.action.audioOn = true;
      if (hit.action.soundVolume == null) hit.action.soundVolume = 100;
      flushSaveSettings();
      if (typeof hit.render === 'function') hit.render();
    }
  } else if (soundPickTarget === 'alert-row' && saSoundPickId) {
    const hit = (settings.soundAlerts || []).find((x) => String(x.id) === String(saSoundPickId));
    if (hit) {
      hit.sound = url;
      hit.soundName = name;
      if (!hit.name || hit.name === 'Alerta') hit.name = String(name || 'audio').replace(/\.[^.]+$/, '');
      saveSettingsKeysPatch('soundAlerts');
      syncDesktopWebhookSettings();
      renderSoundAlerts();
    }
  } else {
    pendingSound = { url, name };
    const el = $('sa-soundname'); if (el) el.textContent = name;
  }
}

async function uploadSoundFromPc(file) {
  if (!file) throw new Error('sin archivo');
  const res = await fetch('/api/local-sounds?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
  const data = await res.json().catch(() => ({}));
  if (!data.url) throw new Error(data.error || 'error');
  return { url: data.url, name: data.name || file.name };
}

function saLibDisplayName(name) {
  return String(name || '').replace(/\.[^.]+$/, '').replace(/[_]+/g, ' ') || name;
}

function ensureLibPcPicker() {
  let inp = $('sa-lib-pcfile');
  if (!inp) {
    inp = document.createElement('input');
    inp.type = 'file';
    inp.id = 'sa-lib-pcfile';
    inp.accept = 'audio/*,.mp3,.wav,.ogg,.m4a,.aac,.flac';
    inp.hidden = true;
    inp.addEventListener('change', async (e) => {
      const file = e.target.files && e.target.files[0];
      e.target.value = '';
      if (!file) return;
      try {
        toast && toast('Guardando en tu PC…');
        const picked = await uploadSoundFromPc(file);
        const q = $('sa-libq');
        if (q) q.value = '';
        await loadLocalSounds();
        const row = $('sa-libresults')?.querySelector(`[data-file="${(typeof CSS !== 'undefined' && CSS.escape) ? CSS.escape(picked.name) : String(picked.name).replace(/"/g, '\\"')}"]`);
        if (row) {
          row.classList.add('is-new');
          row.scrollIntoView({ block: 'nearest' });
        }
        toast && toast('Sonido guardado en tu PC.', 'ok');
      } catch {
        toast && toast('No se pudo guardar el audio.', 'error');
      }
    });
    document.body.appendChild(inp);
  }
  return inp;
}

function openSoundLib() {
  $('soundLibModal').classList.remove('hidden');
  const pcBtn = $('sa-lib-frompc');
  if (pcBtn) pcBtn.hidden = false;
  loadLocalSounds();
}
function closeSoundLib() {
  $('soundLibModal').classList.add('hidden');
  try { libAudio?.pause(); } catch {}
}
$('sa-libbtn').onclick = () => { soundPickTarget = 'alert'; openSoundLib(); };
$('lib-close').onclick = closeSoundLib;
if ($('sa-lib-frompc')) {
  $('sa-lib-frompc').onclick = () => ensureLibPcPicker().click();
}
$('soundLibModal').addEventListener('click', (e) => { if (e.target.id === 'soundLibModal') closeSoundLib(); });
$('sa-librefresh').onclick = () => loadLocalSounds();
$('sa-libq').addEventListener('input', () => renderLocalSounds($('sa-libq').value.trim()));

async function loadLocalSounds() {
  const box = $('sa-libresults');
  box.innerHTML = '<div class="sa-lib-empty">Cargando…</div>';
  try {
    const res = await fetch('/api/local-sounds');
    const data = await res.json();
    localSounds = data.results || [];
    renderLocalSounds($('sa-libq').value.trim());
  } catch {
    box.innerHTML = '<div class="sa-lib-empty">No se pudo leer la carpeta de audios</div>';
  }
}

function renderLocalSounds(filter) {
  const box = $('sa-libresults');
  const f = (filter || '').toLowerCase();
  const list = f ? localSounds.filter((s) => String(s && s.name || '').toLowerCase().includes(f)) : localSounds;
  if (!list.length) {
    box.innerHTML = localSounds.length
      ? '<div class="sa-lib-empty">Ningún audio coincide</div>'
      : '<div class="sa-lib-empty">No hay sonidos aún.<br>Pulsa <b>Subir sonido</b> para guardarlo en tu PC.</div>';
    return;
  }
  box.innerHTML = list.map((s) => `
    <div class="sa-lib-row" data-file="${esc(s.name)}">
      <span class="sa-lib-name" title="${esc(s.name)}">${esc(saLibDisplayName(s.name))}</span>
      <div class="sa-lib-acts">
        <button type="button" class="sa-lib-play lr-play" data-url="${esc(s.url)}" title="Escuchar">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M8 5v14l11-7z"/></svg>
          Play
        </button>
        <button type="button" class="sa-lib-apply lr-pick" data-url="${esc(s.url)}" data-name="${esc(s.name)}">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M9 16.2 4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4z"/></svg>
          Aplicar
        </button>
      </div>
    </div>`).join('');
  box.querySelectorAll('.lr-play').forEach((b) => b.onclick = () => {
    try { libAudio?.pause(); } catch {}
    libAudio = new Audio(b.dataset.url); libAudio.play().catch(() => {});
  });
  box.querySelectorAll('.lr-pick').forEach((b) => b.onclick = () => {
    applyPickedSound(b.dataset.url, b.dataset.name);
    closeSoundLib();
  });
}

$('sa-save').onclick = async () => {
  const name = $('sa-name').value.trim();
  if (!name) { $('sa-status').textContent = '⚠️ Escribe un nombre.'; return; }
  if (!pendingSound?.url) { $('sa-status').textContent = '⚠️ Elige un sonido (biblioteca o subir propio).'; return; }

  const ev = $('sa-event').value;
  const id = ensureSaEditId();
  const data = {
    name,
    trigger: ev === 'gift-any' || ev === 'gift-name' ? 'gift' : ev,
    giftName: ev === 'gift-name' ? $('sa-gift').value.trim() : '',
    giftId: ev === 'gift-name' ? ($('sa-giftid').value || '') : '',
    minDiamonds: ev === 'gift-name' ? (+$('sa-mindia').value || 0) : 0,
    rangeMin: ev === 'gift-any' ? (+$('sa-rangemin').value || 0) : 0,
    rangeMax: ev === 'gift-any' ? (+$('sa-rangemax').value || 0) : 0,
    likeMin: ev === 'like' ? Math.max(1, +$('sa-likemin').value || 1) : 0,
    likeGoal: ev === 'likeGlobal' ? Math.max(1, +$('sa-likegoal').value || 100) : 0,
    likeN: ev === 'like'
      ? Math.max(1, +$('sa-likemin').value || 1)
      : (ev === 'likeGlobal' ? Math.max(1, +$('sa-likegoal').value || 100) : 0),
    emoteId: isEmoteEvent(ev) ? $('sa-emoteid').value.trim() : '',
    emoteImage: isEmoteEvent(ev) ? emoteImgById($('sa-emoteid').value.trim()) : '',
    command: ev === 'chatCommand' ? ($('sa-command')?.value || '').trim() : '',
    user: ev === 'chatCommand' ? ($('sa-user')?.value || '').trim().replace(/^@/, '') : '',
    eventDelay: (ev === 'follow' || ev === 'share' || isEmoteEvent(ev) || ev === 'chatCommand') ? Math.max(0, parseInt($('sa-eventdelay').value, 10) || 0) : 0,
    eventGlobalDelay: (ev === 'follow' || ev === 'share' || isEmoteEvent(ev) || ev === 'chatCommand')
      ? Math.max(0, parseInt($('sa-eventglobaldelay')?.value, 10) || 0)
      : 0,
    ...(ev === 'chatCommand' ? readCmdRoleChecks('sa') : { cmdMods: false, cmdSuperfans: false, cmdFans: false }),
    sound: pendingSound.url,
    soundName: pendingSound.name || 'audio',
    image: '',
    volume: +$('sa-vol').value,
    enabled: $('sa-active').checked,
  };
  if (ev === 'chatCommand' && !data.command) { $('sa-status').textContent = '⚠️ Escribe el comando (ej. !video).'; return; }
  if (!Array.isArray(settings.soundAlerts)) settings.soundAlerts = [];
  const existing = settings.soundAlerts.find((x) => x && sameEntityId(x.id, id));
  if (existing) Object.assign(existing, data);
  else settings.soundAlerts.push({ id, ...data });
  editingId = id;
  flushSaveSettings();
  await syncDesktopWebhookSettings();
  renderSoundAlerts();
  closeSaModal();
  if (ev === 'streamdeck') {
    toast && toast('Guardado. Usa 🔗 en la tarjeta para copiar el webhook a Stream Deck.', 'ok');
  }
};

$('sa-delsel').onclick = async () => {
  if (!selected.size) return;
  const ok = await askConfirm({ title: 'Borrar seleccionadas', message: `Se eliminarán ${selected.size} alerta(s) sonora(s).` });
  if (!ok) return;
  settings.soundAlerts = (Array.isArray(settings.soundAlerts) ? settings.soundAlerts : []).filter((a) => a && !setHasEntityId(selected, a.id));
  selected.clear();
  lastSoundAlertEditAt = Date.now();
  try { markAllowEmptySoundAlerts(); } catch { settings._allowEmptySoundAlerts = true; }
  flushSaveSettings();
  delete settings._allowEmptySoundAlerts;
  await syncDesktopWebhookSettings();
  renderSoundAlerts();
};

$('sa-panic').onclick = () => triggerAlertPanic();

/* ====================== Overlays ====================== */
document.querySelectorAll('.subtab').forEach((btn) => {
  btn.onclick = () => {
    const host = btn.closest('.view');
    if (!host) return;
    host.querySelectorAll('.subtab').forEach((b) => b.classList.remove('active'));
    host.querySelectorAll('.subview').forEach((v) => v.classList.remove('active'));
    btn.classList.add('active');
    const targetId = btn.dataset.subView || ('sub-' + btn.dataset.sub);
    const target = host.querySelector('#' + targetId);
    if (target) target.classList.add('active');
  };
});

document.querySelectorAll('.overlay-item').forEach((item) => {
  const code = item.querySelector('.ov-url');
  code.textContent = roomUrl(code.dataset.path);
  const link = item.querySelector('a');
  if (link && !link.href) link.href = roomUrl(code.dataset.path);
  item.querySelector('.ov-copy').onclick = (e) => {
    if (isOverlayUrlLocked(code)) { toast('Disponible solo en Premium ⭐', 'warn'); return; }
    navigator.clipboard?.writeText(roomUrl(code.dataset.path));
    e.target.textContent = '¡copiado!';
    setTimeout(() => (e.target.textContent = 'copiar'), 1200);
  };
});

/* ====================== Tarjetas PRO: Jarrón y Vaquita ====================== */
const DEFAULT_JAR_SIZES = [
  { t: 5000, sz: 88 }, { t: 1000, sz: 70 }, { t: 100, sz: 56 }, { t: 30, sz: 40 }, { t: 0, sz: 32 },
];

// Configuración de cada overlay tipo "bote" (mismo comportamiento, distinta tarjeta)
const POT_OVERLAYS = {
  perrito: { previewId: 'perr-preview', testAction: 'testPerrito', resetAction: 'resetPerrito', dropAction: 'dropPerrito',
             btnTest: 'perr-test', btnReset: 'perr-reset', btnConfig: 'perr-config', btnSimGift: 'perr-simgift', btnDrop1: 'perr-drop1', copyBtnIdx: 0 },
  jarron: { previewId: 'jar-preview', testAction: 'testJarron', resetAction: 'resetJarron', dropAction: 'dropJarron',
            btnTest: 'jar-test', btnReset: 'jar-reset', btnConfig: 'jar-config', btnSimGift: 'jar-simgift', btnDrop1: 'jar-drop1', copyBtnIdx: 0 },
  vaquita: { previewId: 'vaq-preview', testAction: 'testVaquita', resetAction: 'resetVaquita', dropAction: 'dropVaquita',
             btnTest: 'vaq-test', btnReset: 'vaq-reset', btnConfig: 'vaq-config', btnSimGift: 'vaq-simgift', btnDrop1: 'vaq-drop1', copyBtnIdx: 1 },
  marranito: { previewId: 'mar-preview', testAction: 'testMarranito', resetAction: 'resetMarranito', dropAction: 'dropMarranito',
               btnTest: 'mar-test', btnReset: 'mar-reset', btnConfig: 'mar-config', btnSimGift: 'mar-simgift', btnDrop1: 'mar-drop1', copyBtnIdx: 2 },
  corazonLava: { previewId: 'ghl-preview', testAction: 'testCorazonLava', resetAction: 'resetCorazonLava', dropAction: 'dropCorazonLava',
                 btnTest: 'ghl-test', btnReset: 'ghl-reset', btnConfig: 'ghl-config', btnSimGift: 'ghl-simgift', btnDrop1: 'ghl-drop1', copyBtnIdx: 3 },
};

const potSimGift = { perrito: null, jarron: null, vaquita: null, marranito: null, corazonLava: null };

function renderPotSimGiftBtn(key) {
  const cfg = POT_OVERLAYS[key]; if (!cfg) return;
  const btn = $(cfg.btnSimGift); if (!btn) return;
  const g = potSimGift[key];
  if (!g) {
    btn.innerHTML = 'Selecciona…';
    btn.title = 'Elegir regalo para soltar de uno en uno';
    return;
  }
  const img = g.image ? `<img src="${String(g.image).replace(/"/g, '&quot;')}" alt="" referrerpolicy="no-referrer">` : '🎁';
  const name = String(g.name || 'Regalo').replace(/</g, '&lt;');
  btn.innerHTML = `${img}<span class="ovpro-simgift-name">${name}</span>`;
  btn.title = `${g.name || 'Regalo'} · ${g.diamonds || 0} coins · ID ${g.id || ''}`;
}

(function setupPotCards() {
  document.querySelectorAll('.ovpro-card').forEach((card) => {
    const code = card.querySelector('.ov-url');
    if (!code) return;
    code.textContent = roomUrl(code.dataset.path);
    card.querySelector('.ovpro-copy')?.addEventListener('click', (e) => {
      if (isOverlayUrlLocked(code)) { toast('Disponible solo en Premium ⭐', 'warn'); return; }
      navigator.clipboard?.writeText(roomUrl(code.dataset.path));
      const t = e.target; t.textContent = '¡Copiado!';
      setTimeout(() => (t.textContent = 'Copiar enlace'), 1200);
    });
  });

  for (const [key, cfg] of Object.entries(POT_OVERLAYS)) {
    const test = $(cfg.btnTest), reset = $(cfg.btnReset), config = $(cfg.btnConfig);
    if (!test) continue;
    const toPreview = (msg) => $(cfg.previewId)?.contentWindow?.postMessage({ kind: key, ...msg }, '*');
    const pushTintLook = () => {
      const tint = String(settings?.[key]?.tint ?? '').trim();
      const msg = { type: 'config', tint: tint || '', tintRainbow: !!settings?.[key]?.tintRainbow };
      if (key === 'jarron') msg.skin = settings?.[key]?.skin || 'classic';
      toPreview(msg);
    };
    const fr = $(cfg.previewId);
    if (fr && !fr.dataset.potTintLoadHook) {
      fr.dataset.potTintLoadHook = '1';
      fr.addEventListener('load', () => {
        if (!fr.getAttribute('src') || fr.getAttribute('src') === 'about:blank') return;
        // Reaplicar tinte/arcoíris tras (re)carga del iframe
        setTimeout(pushTintLook, 40);
      });
    }
    test.onclick = () => {
      if (key === 'corazonLava') {
        const c = settings?.corazonLava || {};
        const payload = {
          type: 'test',
          count: 36,
          filterGiftId: c.filterGiftId || '7934',
          filterGiftName: c.filterGiftName || 'Heart Me',
          filterGiftImage: c.filterGiftImage || '',
          filterGiftDiamonds: Number(c.filterGiftDiamonds) || 15,
          giftId: c.filterGiftId || '7934',
          giftName: c.filterGiftName || 'Heart Me',
          image: c.filterGiftImage || '',
          diamonds: Number(c.filterGiftDiamonds) || 15,
        };
        toPreview(payload);
        send({ action: cfg.testAction, count: 36, ...payload });
        return;
      }
      toPreview({ type: 'test', count: 40 });
      toPreview({ type: 'topDemo' });
      // OBS/live: menos que 200 para no tumbar la PC; la preview del panel ya va en 40
      send({ action: cfg.testAction, count: 80 });
    };
    reset.onclick = () => {
      toPreview({ type: 'reset' });
      send({ action: cfg.resetAction });
      // Reset no debe tocar el look: reafirma tinte/arcoíris por si el iframe parpadeó
      setTimeout(pushTintLook, 30);
    };
    if (config) config.onclick = () => openPotConfig(key);

    const dropPayload = () => {
      let g = potSimGift[key];
      if (key === 'corazonLava') {
        const c = settings?.corazonLava || {};
        g = g || {
          id: c.filterGiftId || '7934',
          name: c.filterGiftName || 'Heart Me',
          image: c.filterGiftImage || '',
          diamonds: Number(c.filterGiftDiamonds) || 15,
        };
      }
      return {
        image: g?.image || '',
        diamonds: Math.max(0, Number(g?.diamonds) || 1),
        giftId: g?.id != null ? String(g.id) : '',
        giftName: g?.name || '',
      };
    };
    if ($(cfg.btnSimGift)) {
      $(cfg.btnSimGift).onclick = () => {
        openGiftModalCb((g) => {
          potSimGift[key] = {
            id: g.id, name: g.name, image: g.image || '',
            diamonds: Number(g.diamonds) || Number(g.diamond_count) || 1,
          };
          renderPotSimGiftBtn(key);
        });
      };
      renderPotSimGiftBtn(key);
    }
    if ($(cfg.btnDrop1)) {
      $(cfg.btnDrop1).onclick = () => {
        const payload = dropPayload();
        toPreview({ type: 'dropOne', ...payload });
        send({ action: cfg.dropAction, ...payload });
      };
    }
  }

  // Top donador (misma tarjeta PRO, pero con su propia config)
  const topPrev = () => $('top-preview')?.contentWindow;
  const toTopPreview = (msg) => topPrev()?.postMessage({ kind: 'topdonor', ...msg }, '*');
  if ($('top-test')) {
    $('top-test').onclick = () => { toTopPreview({ type: 'test' }); send({ action: 'testTopDonor' }); };
    $('top-reset').onclick = () => { toTopPreview({ type: 'reset' }); send({ action: 'stopTopDonor' }); };
    $('top-config').onclick = openTopConfig;
  }
})();

window.__syncTopDonorSkin = () => {
  try {
    const cfg = { ...(settings?.topDonor || {}) };
    delete cfg.skin;
    ensureEmbedLoaded('top-preview').then((fr) => {
      try { fr?.contentWindow?.postMessage({ kind: 'topdonor', type: 'config', config: cfg }, '*'); } catch {}
    });
  } catch {}
};

(function setupGhlSkins() {
  const GHL_SKINS = [
    { id: 'heart', name: 'Corazón' },
    { id: 'hongo', name: 'Hongo' },
    { id: 'panda', name: 'Panda' },
    { id: 'orbe', name: 'Orbe cósmico' },
    { id: 'alado', name: 'Corazón alado' },
  ];
  const idxOf = (id) => {
    const i = GHL_SKINS.findIndex((s) => s.id === id);
    return i < 0 ? 0 : i;
  };
  let localId = 'heart';
  let swapUntil = 0;
  let saveTimer = null;
  const syncUi = (id) => {
    const skin = GHL_SKINS[idxOf(id)];
    if ($('ghl-skin-name')) $('ghl-skin-name').textContent = skin.name;
    if ($('ghl-skin-idx')) $('ghl-skin-idx').textContent = `${idxOf(skin.id) + 1} / ${GHL_SKINS.length}`;
    if ($('jarcfg-skin')) $('jarcfg-skin').value = skin.id;
  };
  const pushPreviewSkin = (skin) => {
    try { $('ghl-preview')?.contentWindow?.postMessage({ kind: 'corazonLava', type: 'config', skin }, '*'); } catch {}
  };
  const apply = (id, persist) => {
    const skin = GHL_SKINS[idxOf(id)].id;
    localId = skin;
    swapUntil = Date.now() + 1600;
    if (settings) {
      if (!settings.corazonLava) settings.corazonLava = {};
      settings.corazonLava.skin = skin;
    }
    syncUi(skin);
    pushPreviewSkin(skin);
    if (!persist) return;
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => {
      saveTimer = null;
      const run = () => {
        try {
          if (typeof saveSettingsKeysPatch === 'function') saveSettingsKeysPatch('corazonLava');
          else saveSettings();
        } catch {}
      };
      if (typeof applyingSettings !== 'undefined' && applyingSettings) setTimeout(run, 80);
      else run();
    }, 280);
  };
  if ($('ghl-skin-prev')) {
    $('ghl-skin-prev').onclick = () => {
      apply(GHL_SKINS[(idxOf(localId) - 1 + GHL_SKINS.length) % GHL_SKINS.length].id, true);
    };
  }
  if ($('ghl-skin-next')) {
    $('ghl-skin-next').onclick = () => {
      apply(GHL_SKINS[(idxOf(localId) + 1) % GHL_SKINS.length].id, true);
    };
  }
  try {
    localId = settings?.corazonLava?.skin || 'heart';
    if (!GHL_SKINS.some((s) => s.id === localId)) localId = 'heart';
    syncUi(localId);
  } catch {}
  window.__ghlSkinId = () => localId;
  window.__syncGhlSkin = (id, persist) => {
    if (id != null) apply(id, !!persist);
    else {
      try {
        if (Date.now() < swapUntil) {
          if (settings) {
            if (!settings.corazonLava) settings.corazonLava = {};
            settings.corazonLava.skin = localId;
          }
          syncUi(localId);
          pushPreviewSkin(localId);
          return;
        }
        localId = settings?.corazonLava?.skin || localId || 'heart';
        if (!GHL_SKINS.some((s) => s.id === localId)) localId = 'heart';
        syncUi(localId);
      } catch {}
    }
  };
})();

