/* ---- Gift VS (versus de regalos) ---- */
function gvsPreviewWin() { return $('gvs-preview')?.contentWindow; }
function gvsToPreview(msg) { gvsPreviewWin()?.postMessage({ kind: 'giftvs', ...msg }, '*'); }

/* ---- Batalla VS (PK azul / amarillo) ---- */
function bvsToPreview(msg) {
  return ensureEmbedLoaded('bvs-preview').then((fr) => {
    try { fr?.contentWindow?.postMessage({ kind: 'batallaVs', ...msg }, '*'); } catch {}
    return fr;
  });
}
function syncBvsCfgLabels() {
  const c = $('bvscfg-circle');
  const cl = $('bvscfg-circle-lbl');
  if (c && cl) cl.textContent = Math.max(35, Math.min(140, parseInt(c.value, 10) || 100)) + '%';
  const t = $('bvscfg-text');
  const tl = $('bvscfg-text-lbl');
  if (t && tl) tl.textContent = Math.max(70, Math.min(150, parseInt(t.value, 10) || 100)) + '%';
}
function syncBvsRingClearedFromSettings() {
  const data = settings?.batallaVs || {};
  const sync = (id, val, fallback) => {
    const el = $(id);
    if (!el) return;
    const v = String(val || '').trim();
    if (/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(v)) {
      el.value = v;
      el.dataset.cleared = '';
    } else {
      el.value = fallback;
      el.dataset.cleared = '1';
    }
  };
  sync('bvscfg-ringhost', data.ringHostColor, '#ffe566');
  sync('bvscfg-ringrival', data.ringRivalColor, '#4da3ff');
}
function pushBvsStylePreview(extra) {
  const base = readForm({
    'bvscfg-winshost': 'winsHostColor', 'bvscfg-winsrival': 'winsRivalColor',
    'bvscfg-ptshost': 'pointsHostColor', 'bvscfg-ptsrival': 'pointsRivalColor',
    'bvscfg-namehost': 'nameHostColor', 'bvscfg-namerival': 'nameRivalColor',
    'bvscfg-ringhost': 'ringHostColor', 'bvscfg-ringrival': 'ringRivalColor',
    'bvscfg-circle': 'circleScale', 'bvscfg-text': 'textScale',
  }, { circleScale: 'int', textScale: 'int' });
  if ($('bvscfg-ringhost')?.dataset.cleared === '1') base.ringHostColor = '';
  if ($('bvscfg-ringrival')?.dataset.cleared === '1') base.ringRivalColor = '';
  bvsToPreview({ type: 'config', config: { ...(settings?.batallaVs || {}), ...base, ...(extra || {}) } });
}
(function setupBatallaVsRingClears() {
  const bind = (btnId, inputId, key, fallback) => {
    const btn = $(btnId);
    const input = $(inputId);
    if (!btn || !input) return;
    btn.onclick = () => {
      input.value = fallback;
      input.dataset.cleared = '1';
      syncBvsCfgLabels();
      pushBvsStylePreview({ [key]: '' });
    };
    input.addEventListener('input', () => { input.dataset.cleared = ''; });
  };
  bind('bvscfg-ringhost-clear', 'bvscfg-ringhost', 'ringHostColor', '#ffe566');
  bind('bvscfg-ringrival-clear', 'bvscfg-ringrival', 'ringRivalColor', '#4da3ff');
})();

(function patchBatallaVsStylePreview() {
  const ids = [
    'bvscfg-winshost', 'bvscfg-winsrival', 'bvscfg-ptshost', 'bvscfg-ptsrival',
    'bvscfg-namehost', 'bvscfg-namerival', 'bvscfg-ringhost', 'bvscfg-ringrival',
    'bvscfg-circle', 'bvscfg-text',
  ];
  const wire = () => {
    ids.forEach((id) => {
      const el = $(id);
      if (!el) return;
      el.oninput = () => { syncBvsCfgLabels(); pushBvsStylePreview(); };
      el.onchange = () => { syncBvsCfgLabels(); pushBvsStylePreview(); };
    });
    const btn = $('bvs-config');
    if (!btn || btn._bvsPatched) return;
    btn._bvsPatched = true;
    const prev = btn.onclick;
    btn.onclick = async function (ev) {
      if (typeof prev === 'function') await prev.call(this, ev);
      syncBvsRingClearedFromSettings();
      syncBvsCfgLabels();
      pushBvsStylePreview();
    };
  };
  // Tras STYLE_OVERLAYS (definido más abajo) se vuelve a llamar.
  window.__patchBatallaVsStylePreview = wire;
})();

let gvsRowsDraft = [];

function defaultGiftVsCfg() {
  return {
    meta: 100,
    goalStep: 100,
    onGoal: 'reset',
    countdown: 2,
    cdWhen: 'start',
    cdRestart: false,
    vsStyle: 1,
    rows: [
      {
        leftId: '13651',
        leftName: 'Go Popular',
        leftImg: 'https://p16-webcast.tiktokcdn.com/img/alisg/webcast-sg/resource/b342e28d73dac6547e0b3e2ad57f6597.png~tplv-obj.webp',
        leftDiamonds: 1,
        rightId: '231955',
        rightName: 'Good Job',
        rightImg: 'https://p16-webcast.tiktokcdn.com/img/alisg/webcast-sg/resource/047bfa2dcc6813c72fd2d8f649ee8ee2.png~tplv-obj.webp',
        rightDiamonds: 1,
      },
    ],
  };
}

function giftVsHasConfiguredRows(cfg) {
  return Array.isArray(cfg?.rows) && cfg.rows.some((r) =>
    String(r?.leftId || r?.leftName || r?.leftImg || '').trim() ||
    String(r?.rightId || r?.rightName || r?.rightImg || '').trim()
  );
}

function resolveGiftVsCfg(cfg) {
  return giftVsHasConfiguredRows(cfg) ? cfg : defaultGiftVsCfg();
}

function currentGvsCfg() {
  return {
    meta: Math.max(1, parseInt($('gvscfg-meta').value, 10) || 100),
    goalStep: Math.max(1, parseInt($('gvscfg-goalstep').value, 10) || 100),
    onGoal: $('gvscfg-ongoal').value || 'reset',
    countdown: Math.max(0, parseInt($('gvscfg-countdown').value, 10) || 0),
    cdWhen: $('gvscfg-cdwhen').value === 'start' ? 'start' : 'goal',
    cdRestart: $('gvscfg-cdrestart').checked,
    vsStyle: Math.max(1, Math.min(3, parseInt($('gvscfg-vsstyle').value, 10) || 1)),
    rows: gvsRowsDraft.map((r) => ({ ...r })),
  };
}

function pushGiftVsPreview(cfg) {
  gvsToPreview({ type: 'config', config: resolveGiftVsCfg(cfg || settings?.giftVs) });
}

if ($('gvs-test')) {
  const gvsControl = (action) => {
    gvsToPreview({ type: 'action', action });
    send({ action: 'giftVsControl', gvsAction: action });
  };
  if ($('gvs-start')) $('gvs-start').onclick = () => gvsControl('start');
  if ($('gvs-stop')) $('gvs-stop').onclick = () => gvsControl('stop');
  if ($('gvs-end')) $('gvs-end').onclick = () => gvsControl('end');
  $('gvs-test').onclick = () => { gvsToPreview({ type: 'test' }); send({ action: 'testGiftVs' }); };
  $('gvs-reset').onclick = () => { gvsToPreview({ type: 'reset' }); send({ action: 'resetGiftVs' }); };
  $('gvs-config').onclick = openGvsConfig;
}

function openGvsConfig() {
  const c = resolveGiftVsCfg(settings?.giftVs);
  $('gvscfg-meta').value = c.meta || 100;
  $('gvscfg-goalstep').value = c.goalStep || 100;
  $('gvscfg-ongoal').value = c.onGoal || 'reset';
  $('gvscfg-countdown').value = c.countdown != null ? c.countdown : 2;
  $('gvscfg-cdwhen').value = c.cdWhen === 'start' ? 'start' : 'goal';
  $('gvscfg-cdrestart').checked = !!c.cdRestart;
  if ($('gvscfg-vsstyle')) $('gvscfg-vsstyle').value = String(Math.max(1, Math.min(3, parseInt(c.vsStyle, 10) || 1)));
  syncBatVsPick('gvscfg-vs-pick', 'gvscfg-vsstyle');
  gvsRowsDraft = (c.rows || []).map((r) => ({
    leftId: r.leftId || '', leftName: r.leftName || '', leftImg: r.leftImg || '', leftDiamonds: r.leftDiamonds || 0,
    rightId: r.rightId || '', rightName: r.rightName || '', rightImg: r.rightImg || '', rightDiamonds: r.rightDiamonds || 0,
  }));
  if (!gvsRowsDraft.length) gvsRowsDraft.push(emptyGvsRow());
  renderGvsRows();
  $('gvsConfigModal').classList.remove('hidden');
}
function closeGvsConfig() { $('gvsConfigModal').classList.add('hidden'); }
function emptyGvsRow() { return { leftId: '', leftName: '', leftImg: '', leftDiamonds: 0, rightId: '', rightName: '', rightImg: '', rightDiamonds: 0 }; }

function gvsGiftBtn(side, i, r) {
  const id = r[side + 'Id'], name = r[side + 'Name'], img = r[side + 'Img'];
  if (id) {
    return `<button type="button" class="gvs-giftbtn picked" data-side="${side}" data-i="${i}">
      ${img ? `<img src="${esc(img)}">` : ''}<span>${esc(name || ('#' + id))}</span></button>`;
  }
  return `<button type="button" class="gvs-giftbtn" data-side="${side}" data-i="${i}">＋ Elegir regalo</button>`;
}

function renderGvsRows() {
  const wrap = $('gvscfg-rows');
  wrap.innerHTML = gvsRowsDraft.map((r, i) => `
    <div class="gvs-row" data-i="${i}">
      <button type="button" class="jarcfg-del gvs-del" title="Quitar">✕</button>
      <div class="gvs-row-head">PAREJA ${i + 1}</div>
      <div class="gvs-row-grid">
        <div class="gvs-side-box">
          <label>Bando izquierdo</label>
          ${gvsGiftBtn('left', i, r)}
          <input type="number" min="0" class="gvs-dl" placeholder="💎 auto" value="${r.leftDiamonds || ''}">
        </div>
        <div class="gvs-vs">VS</div>
        <div class="gvs-side-box">
          <label>Bando derecho</label>
          ${gvsGiftBtn('right', i, r)}
          <input type="number" min="0" class="gvs-dr" placeholder="💎 auto" value="${r.rightDiamonds || ''}">
        </div>
      </div>
    </div>`).join('');

  wrap.querySelectorAll('.gvs-row').forEach((row) => {
    const i = Number(row.dataset.i);
    row.querySelector('.gvs-del').onclick = () => { gvsRowsDraft.splice(i, 1); if (!gvsRowsDraft.length) gvsRowsDraft.push(emptyGvsRow()); renderGvsRows(); };
    row.querySelector('.gvs-dl').onchange = (e) => { gvsRowsDraft[i].leftDiamonds = Math.max(0, parseInt(e.target.value, 10) || 0); pushGiftVsPreview(currentGvsCfg()); };
    row.querySelector('.gvs-dr').onchange = (e) => { gvsRowsDraft[i].rightDiamonds = Math.max(0, parseInt(e.target.value, 10) || 0); pushGiftVsPreview(currentGvsCfg()); };
    row.querySelectorAll('.gvs-giftbtn').forEach((btn) => {
      btn.onclick = () => {
        const side = btn.dataset.side;
        openGiftModalCb((g) => {
          gvsRowsDraft[i][side + 'Id'] = g.id;
          gvsRowsDraft[i][side + 'Name'] = g.name;
          gvsRowsDraft[i][side + 'Img'] = g.image;
          renderGvsRows();
          pushGiftVsPreview(currentGvsCfg());
        });
      };
    });
  });
  pushGiftVsPreview(currentGvsCfg());
}

['gvscfg-meta', 'gvscfg-goalstep', 'gvscfg-ongoal', 'gvscfg-countdown', 'gvscfg-cdwhen', 'gvscfg-cdrestart', 'gvscfg-vsstyle'].forEach((id) => {
  const el = $(id);
  if (el) { el.oninput = () => pushGiftVsPreview(currentGvsCfg()); el.onchange = () => pushGiftVsPreview(currentGvsCfg()); }
});
if ($('gvscfg-add')) $('gvscfg-add').onclick = () => { gvsRowsDraft.push(emptyGvsRow()); renderGvsRows(); };
if ($('gvscfg-close')) $('gvscfg-close').onclick = closeGvsConfig;
if ($('gvsConfigModal')) $('gvsConfigModal').addEventListener('click', (e) => { if (e.target.id === 'gvsConfigModal') closeGvsConfig(); });
if ($('gvscfg-save')) $('gvscfg-save').onclick = () => {
  settings.giftVs = currentGvsCfg();
  saveSettings();
  pushGiftVsPreview(settings.giftVs);
  closeGvsConfig();
};

