// Contador de meta: regalo / meta / valor viven en el modal Configurar.
(function setupGiftCounterCard() {
  const prev = () => $('gct-preview')?.contentWindow;
  const toPrev = () => prev()?.postMessage({ kind: 'gcounter', type: 'config', config: settings?.giftCounter || {} }, '*');
  const ensure = () => { if (!settings) return {}; if (!settings.giftCounter) settings.giftCounter = {}; return settings.giftCounter; };

  if ($('gct-giftpick')) $('gct-giftpick').onclick = () => openGiftModal('sa', (g) => {
    const c = ensure();
    c.giftId = String(g.id || '');
    c.giftName = g.name || '';
    c.image = g.image || '';
    refreshGiftCounterCardUI();
    saveSettings(); toPrev();
  });
  if ($('gct-giftany')) $('gct-giftany').onclick = () => {
    const c = ensure();
    c.giftId = ''; c.giftName = ''; c.image = '';
    refreshGiftCounterCardUI();
    saveSettings(); toPrev();
  };
  if ($('gct-goal')) $('gct-goal').addEventListener('input', () => {
    const c = ensure(); c.goal = Math.max(1, parseInt($('gct-goal').value, 10) || 1);
    saveSettings(); toPrev();
  });
  if ($('gct-set')) $('gct-set').onclick = () => {
    const v = Math.max(0, parseInt($('gct-value').value, 10) || 0);
    send({ action: 'setGiftCounter', value: v });
    toast('Contador puesto en ' + v + '.');
  };
})();

function refreshGiftCounterCardUI() {
  const c = settings?.giftCounter || {};
  const nameEl = $('gct-giftname');
  if (nameEl) nameEl.textContent = c.giftName ? c.giftName : 'Cualquier regalo';
  if ($('gct-goal')) $('gct-goal').value = c.goal ?? 50;
}

function gpfKindTable() {
  return {
    hype: { title: 'META HYPE', icon: '✨', suffix: '✨', goal: 'META (PUNTOS)' },
    likes: { title: 'META DE LIKES', icon: '❤️', suffix: '❤️', goal: 'META (LIKES)' },
    follow: { title: 'META DE SEGUIDORES', icon: '👤', suffix: '👤', goal: 'META (SEGUIDORES)' },
    share: { title: 'META DE COMPARTIDOS', icon: '↪️', suffix: '↪️', goal: 'META (COMPARTIDOS)' },
    gift: { title: 'META DE REGALOS', icon: '🎁', suffix: '💎', goal: 'META (DIAMANTES)' },
    member: { title: 'META DE MIEMBROS', icon: '⭐', suffix: '⭐', goal: 'META (MIEMBROS)' },
    viewers: { title: 'META DE ESPECTADORES', icon: '👁', suffix: '👁', goal: 'META (ESPECTADORES)' },
  };
}
function gpfKindMeta(kind) {
  const table = gpfKindTable();
  return table[String(kind || 'gift').toLowerCase()] || table.gift;
}
function gpfBareTitle(t) {
  return String(t || '').replace(/^[^\wÁÉÍÓÚÑáéíóúñ]+/u, '').trim().toUpperCase();
}
function gpfIsDefaultTitle(t) {
  const b = gpfBareTitle(t);
  return !b || Object.values(gpfKindTable()).some((d) => gpfBareTitle(d.title) === b);
}

function giftPhotoGoalFileLabel(url) {
  const raw = String(url || '').trim();
  if (!raw) return 'Ningún archivo seleccionado';
  try {
    const name = decodeURIComponent(new URL(raw, location.origin).pathname.split('/').pop() || '');
    return name || 'Foto cargada';
  } catch {
    return 'Foto cargada';
  }
}

function refreshGiftPhotoGoalUI() {
  const c = settings?.giftPhotoGoal || {};
  const nameEl = $('gpfcfg-photoname');
  if (nameEl) nameEl.textContent = giftPhotoGoalFileLabel(c.bgUrl);
  const goalEl = $('gpfcfg-goal');
  const modalOpen = !$('gpfConfigModal')?.classList.contains('hidden');
  if (goalEl && document.activeElement !== goalEl && !modalOpen) {
    goalEl.value = c.goal ?? 50000;
  }
  const perEl = $('gpfcfg-period');
  if (perEl && document.activeElement !== perEl) {
    const p = c.resetPeriod;
    perEl.value = ['live', 'week', 'month'].includes(p) ? p : 'live';
  }
  const barH = $('gpfcfg-barh');
  if (barH && document.activeElement !== barH) barH.value = Math.max(8, Math.min(48, parseInt(c.barHeight, 10) || 22));
  const barW = $('gpfcfg-barw');
  if (barW && document.activeElement !== barW) barW.value = Math.max(40, Math.min(100, parseInt(c.barWidth, 10) || 88));
  const boxW = $('gpfcfg-boxw');
  if (boxW && document.activeElement !== boxW) boxW.value = Math.max(50, Math.min(100, parseInt(c.boxWidth, 10) || 100));
  const boxH = $('gpfcfg-boxh');
  if (boxH && document.activeElement !== boxH) boxH.value = Math.max(50, Math.min(100, parseInt(c.boxHeight, 10) || 100));
  const boxR = $('gpfcfg-boxr');
  if (boxR && document.activeElement !== boxR) boxR.value = Math.max(0, Math.min(48, parseInt(c.boxRadius, 10) || 28));
  const boxB = $('gpfcfg-boxb');
  if (boxB && document.activeElement !== boxB) boxB.value = Math.max(1, Math.min(8, parseInt(c.boxBorder, 10) || 2));
  syncGiftPhotoGoalBarLabels();
  paintGiftPhotoGoalLive();
}

function giftPhotoGoalFormCfg() {
  const cur = settings?.giftPhotoGoal || {};
  const kind = ($('gpfcfg-kind')?.value || cur.goalKind || 'gift').toLowerCase();
  const meta = gpfKindMeta(kind);
  const title = ($('gpfcfg-title')?.value || cur.title || meta.title).trim();
  const goalRaw = parseInt($('gpfcfg-goal')?.value, 10);
  const periodRaw = $('gpfcfg-period')?.value || cur.resetPeriod || 'live';
  const resetPeriod = ['live', 'week', 'month'].includes(periodRaw) ? periodRaw : 'live';
  const barH = parseInt($('gpfcfg-barh')?.value, 10);
  const barW = parseInt($('gpfcfg-barw')?.value, 10);
  const boxW = parseInt($('gpfcfg-boxw')?.value, 10);
  const boxH = parseInt($('gpfcfg-boxh')?.value, 10);
  const boxR = parseInt($('gpfcfg-boxr')?.value, 10);
  const boxB = parseInt($('gpfcfg-boxb')?.value, 10);
  return {
    ...cur,
    goalKind: kind,
    title: title || meta.title,
    goal: Number.isFinite(goalRaw) && goalRaw >= 1 ? goalRaw : (cur.goal || 50000),
    titleColor: $('gpfcfg-titlecolor')?.value || cur.titleColor || '#ffffff',
    counterColor: $('gpfcfg-countercolor')?.value || cur.counterColor || '#ffffff',
    barColor: $('gpfcfg-barcolor')?.value || cur.barColor || '#5ad4ff',
    glowColor: $('gpfcfg-glow')?.value || cur.glowColor || '#5ad4ff',
    bgUrl: cur.bgUrl || '',
    resetPeriod,
    barHeight: Number.isFinite(barH) ? Math.max(8, Math.min(48, barH)) : Math.max(8, Math.min(48, parseInt(cur.barHeight, 10) || 22)),
    barWidth: Number.isFinite(barW) ? Math.max(40, Math.min(100, barW)) : Math.max(40, Math.min(100, parseInt(cur.barWidth, 10) || 88)),
    boxWidth: Number.isFinite(boxW) ? Math.max(50, Math.min(100, boxW)) : Math.max(50, Math.min(100, parseInt(cur.boxWidth, 10) || 100)),
    boxHeight: Number.isFinite(boxH) ? Math.max(50, Math.min(100, boxH)) : Math.max(50, Math.min(100, parseInt(cur.boxHeight, 10) || 100)),
    boxRadius: Number.isFinite(boxR) ? Math.max(0, Math.min(48, boxR)) : Math.max(0, Math.min(48, parseInt(cur.boxRadius, 10) || 28)),
    boxBorder: Number.isFinite(boxB) ? Math.max(1, Math.min(8, boxB)) : Math.max(1, Math.min(8, parseInt(cur.boxBorder, 10) || 2)),
  };
}

function syncGiftPhotoGoalBarLabels() {
  const h = $('gpfcfg-barh'); const hl = $('gpfcfg-barh-lbl');
  if (h && hl) hl.textContent = Math.max(8, Math.min(48, parseInt(h.value, 10) || 22)) + 'px';
  const w = $('gpfcfg-barw'); const wl = $('gpfcfg-barw-lbl');
  if (w && wl) wl.textContent = Math.max(40, Math.min(100, parseInt(w.value, 10) || 88)) + '%';
  const bxw = $('gpfcfg-boxw'); const bxwl = $('gpfcfg-boxw-lbl');
  if (bxw && bxwl) bxwl.textContent = Math.max(50, Math.min(100, parseInt(bxw.value, 10) || 100)) + '%';
  const bxh = $('gpfcfg-boxh'); const bxhl = $('gpfcfg-boxh-lbl');
  if (bxh && bxhl) bxhl.textContent = Math.max(50, Math.min(100, parseInt(bxh.value, 10) || 100)) + '%';
  const bxr = $('gpfcfg-boxr'); const bxrl = $('gpfcfg-boxr-lbl');
  if (bxr && bxrl) bxrl.textContent = Math.max(0, Math.min(48, parseInt(bxr.value, 10) || 28)) + 'px';
  const bxb = $('gpfcfg-boxb'); const bxbl = $('gpfcfg-boxb-lbl');
  if (bxb && bxbl) bxbl.textContent = Math.max(1, Math.min(8, parseInt(bxb.value, 10) || 2)) + 'px';
}

function paintGiftPhotoGoalLive() {
  const banner = $('gpf-live-banner');
  if (!banner) return;
  const cfg = giftPhotoGoalFormCfg();
  const count = Math.max(0, parseInt($('gpfcfg-value')?.value, 10) || 0);
  const goal = Math.max(1, Number(cfg.goal) || 50000);
  const pct = Math.max(0, Math.min(100, (count / goal) * 100));
  const meta = gpfKindMeta(cfg.goalKind);
  const title = String(cfg.title || meta.title).trim();
  banner.style.setProperty('--title-color', cfg.titleColor || '#ffffff');
  banner.style.setProperty('--counter-color', cfg.counterColor || '#ffffff');
  banner.style.setProperty('--bar-color', cfg.barColor || '#5ad4ff');
  banner.style.setProperty('--glow', cfg.glowColor || '#5ad4ff');
  banner.style.setProperty('--bar-h', (cfg.barHeight || 22) + 'px');
  banner.style.setProperty('--bar-w', (cfg.barWidth || 88) + '%');
  banner.style.setProperty('--box-w', (cfg.boxWidth || 100) + '%');
  banner.style.setProperty('--box-h', Math.round(118 * ((cfg.boxHeight || 100) / 100)) + 'px');
  banner.style.setProperty('--box-r', (cfg.boxRadius ?? 28) + 'px');
  banner.style.setProperty('--box-bw', (cfg.boxBorder || 2) + 'px');
  const url = String(cfg.bgUrl || '').trim();
  banner.style.setProperty('--bg-img', url ? 'url("' + url.replace(/"/g, '\\"') + '")' : 'none');
  const t = $('gpf-live-title');
  if (t) t.textContent = (/^[🎁✨❤❤️👤↪️⭐🌟👁💎🪙]/.test(title) ? title : (meta.icon + ' ' + title));
  const fill = $('gpf-live-fill');
  if (fill) fill.style.width = pct + '%';
  const n = $('gpf-live-count');
  if (n) n.textContent = count.toLocaleString('en-US') + ' / ' + goal.toLocaleString('en-US') + ' ' + meta.suffix;
  const gl = $('gpfcfg-goal-lbl');
  if (gl) gl.textContent = meta.goal;
}

function pushGiftPhotoGoalPreview(cfg) {
  const payload = cfg || settings?.giftPhotoGoal || {};
  const sendMsg = (fr) => {
    try { fr?.contentWindow?.postMessage({ kind: 'giftbanner', type: 'config', config: payload }, '*'); } catch {}
  };
  const fr = $('gpf-preview');
  if (typeof ensureEmbedLoaded === 'function' && fr) ensureEmbedLoaded(fr).then(sendMsg);
  else sendMsg(fr);
}

function commitGiftPhotoGoalFromForm(persist) {
  if (!settings) return settings?.giftPhotoGoal;
  if (!settings.giftPhotoGoal) settings.giftPhotoGoal = {};
  Object.assign(settings.giftPhotoGoal, giftPhotoGoalFormCfg());
  paintGiftPhotoGoalLive();
  pushGiftPhotoGoalPreview(settings.giftPhotoGoal);
  if (persist !== false) saveSettings();
  return settings.giftPhotoGoal;
}

(function setupGiftPhotoGoalCard() {
  const ensure = () => { if (!settings) return {}; if (!settings.giftPhotoGoal) settings.giftPhotoGoal = {}; return settings.giftPhotoGoal; };

  if ($('gpfcfg-kind')) $('gpfcfg-kind').addEventListener('change', () => {
    const kind = $('gpfcfg-kind').value;
    const meta = gpfKindMeta(kind);
    const titleEl = $('gpfcfg-title');
    if (titleEl && gpfIsDefaultTitle(titleEl.value)) titleEl.value = meta.title;
    commitGiftPhotoGoalFromForm(true);
  });
  ['gpfcfg-period', 'gpfcfg-title', 'gpfcfg-goal', 'gpfcfg-titlecolor', 'gpfcfg-countercolor', 'gpfcfg-barcolor', 'gpfcfg-glow', 'gpfcfg-barh', 'gpfcfg-barw', 'gpfcfg-boxw', 'gpfcfg-boxh', 'gpfcfg-boxr', 'gpfcfg-boxb', 'gpfcfg-value'].forEach((id) => {
    const el = $(id);
    if (!el) return;
    el.addEventListener('input', () => {
      syncGiftPhotoGoalBarLabels();
      if (id === 'gpfcfg-value') { paintGiftPhotoGoalLive(); return; }
      commitGiftPhotoGoalFromForm(true);
    });
    el.addEventListener('change', () => {
      syncGiftPhotoGoalBarLabels();
      if (id === 'gpfcfg-value') { paintGiftPhotoGoalLive(); return; }
      commitGiftPhotoGoalFromForm(true);
    });
  });

  if ($('gpfcfg-photobtn')) $('gpfcfg-photobtn').onclick = () => $('gpfcfg-photo')?.click();
  if ($('gpfcfg-photo')) $('gpfcfg-photo').addEventListener('change', async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!file) return;
    const nameEl = $('gpfcfg-photoname');
    if (nameEl) nameEl.textContent = 'Subiendo…';
    try {
      const res = await fetch('/api/upload?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
      const data = await res.json().catch(() => ({}));
      if (!data.url) throw new Error(data.error || 'error');
      const c = ensure();
      c.bgUrl = data.url;
      refreshGiftPhotoGoalUI();
      commitGiftPhotoGoalFromForm(true);
      try { if (typeof toast === 'function') toast('Foto de fondo subida.', 'ok'); } catch {}
    } catch {
      if (nameEl) nameEl.textContent = 'Error al subir';
      try { if (typeof toast === 'function') toast('No se pudo subir la foto.', 'err'); } catch {}
    }
  });
  if ($('gpfcfg-photoclear')) $('gpfcfg-photoclear').onclick = () => {
    const c = ensure();
    c.bgUrl = '';
    refreshGiftPhotoGoalUI();
    commitGiftPhotoGoalFromForm(true);
  };
  if ($('gpfcfg-set')) $('gpfcfg-set').onclick = () => {
    const v = Math.max(0, parseInt($('gpfcfg-value').value, 10) || 0);
    send({ action: 'setGiftPhotoGoal', value: v });
    paintGiftPhotoGoalLive();
    try { if (typeof toast === 'function') toast('Meta puesta en ' + v + '.'); } catch {}
  };
})();


