(function setupSorteosControls() {
  const soFrame = () => $('so-preview');
  const toPrev = async (msg) => {
    const fr = await ensureEmbedLoaded(soFrame());
    try { fr?.contentWindow?.postMessage({ kind: 'sorteos', ...msg }, '*'); } catch {}
  };
  const pushCfg = () => {
    const cfg = settings?.sorteosOverlay || {};
    toPrev({ type: 'config', config: cfg });
  };
  function syncSorteosSlowBtn() {
    const btn = $('so-slow');
    if (!btn) return;
    const on = !!(settings?.sorteosOverlay?.slowCountdown);
    btn.classList.toggle('primary', on);
    btn.classList.toggle('is-on', on);
    btn.textContent = on ? '🐢 Tiempo lento ON' : '🐢 Tiempo lento OFF';
    btn.title = on
      ? 'Cuenta regresiva lenta activa · pulsa para apagar'
      : 'Cuenta regresiva lenta apagada · pulsa para activar';
  }
  window.refreshSorteosGiftBtn = refreshSorteosGiftBtn;
  if ($('socfg-giftpick')) $('socfg-giftpick').onclick = () => openGiftModalCb((g) => {
    const diamonds = Math.max(1, Number(g.diamonds) || Number(g.diamond_count) || 1);
    if ($('socfg-entry')) $('socfg-entry').value = String(diamonds);
    if ($('socfg-giftimg')) $('socfg-giftimg').value = g.image || '';
    if ($('socfg-giftid')) $('socfg-giftid').value = String(g.id || '');
    if ($('socfg-giftname')) $('socfg-giftname').value = g.name || '';
    refreshSorteosGiftBtn();
    // Preview en vivo (igual que el resto del modal)
    const cfg = {
      ...(settings?.sorteosOverlay || {}),
      entryCost: diamonds,
      entryGiftImage: g.image || '',
      entryGiftId: String(g.id || ''),
      entryGiftName: g.name || '',
    };
    toPrev({ type: 'config', config: cfg });
  });
  if ($('socfg-giftclear')) $('socfg-giftclear').onclick = () => {
    if ($('socfg-giftimg')) $('socfg-giftimg').value = '';
    if ($('socfg-giftid')) $('socfg-giftid').value = '';
    if ($('socfg-giftname')) $('socfg-giftname').value = '';
    refreshSorteosGiftBtn();
    const cfg = {
      ...(settings?.sorteosOverlay || {}),
      entryGiftImage: '',
      entryGiftId: '',
      entryGiftName: '',
      entryCost: Math.max(1, parseInt($('socfg-entry')?.value, 10) || 30),
    };
    toPrev({ type: 'config', config: cfg });
  };
  if ($('socfg-entry')) $('socfg-entry').addEventListener('input', () => refreshSorteosGiftBtn());
  if ($('so-start')) $('so-start').onclick = () => {
    toPrev({ type: 'action', action: 'start', forceInitial: true });
    send({ action: 'sorteos', sorteosAction: 'start', forceInitial: true });
    try { toast('Sorteos · Iniciar', 'ok'); } catch {}
  };
  if ($('so-spin')) $('so-spin').onclick = () => {
    toPrev({ type: 'action', action: 'spin' });
    send({ action: 'sorteos', sorteosAction: 'spin' });
    try { toast('Sorteos · Giro manual', 'ok'); } catch {}
  };
  if ($('so-lock')) $('so-lock').onclick = () => {
    toPrev({ type: 'action', action: 'lock' });
    send({ action: 'sorteos', sorteosAction: 'lock' });
    try { toast('Sorteos · Lock entradas', 'ok'); } catch {}
  };
  if ($('so-unlock')) $('so-unlock').onclick = () => {
    toPrev({ type: 'action', action: 'unlock' });
    send({ action: 'sorteos', sorteosAction: 'unlock' });
    try { toast('Sorteos · Unlock', 'ok'); } catch {}
  };
  if ($('so-slow')) $('so-slow').onclick = () => {
    if (!settings.sorteosOverlay) settings.sorteosOverlay = {};
    const next = !settings.sorteosOverlay.slowCountdown;
    settings.sorteosOverlay.slowCountdown = next;
    if ($('socfg-slow')) $('socfg-slow').checked = next;
    saveSettingsKeysPatch('sorteosOverlay');
    toPrev({ type: 'action', action: next ? 'slowOn' : 'slowOff' });
    send({ action: 'sorteos', sorteosAction: next ? 'slowOn' : 'slowOff' });
    syncSorteosSlowBtn();
    try { toast(next ? 'Sorteos · Tiempo lento ON' : 'Sorteos · Tiempo lento OFF', 'ok'); } catch {}
  };
  if ($('so-reset')) $('so-reset').onclick = () => {
    toPrev({ type: 'reset' });
    send({ action: 'sorteos', sorteosAction: 'reset' });
    try { toast('Sorteos · Reset', 'ok'); } catch {}
  };
  // Cuando el iframe avisa que cargó, reenviar config (evita preview gigante con scale por defecto)
  window.addEventListener('message', (ev) => {
    const d = ev?.data;
    if (!d || d.kind !== 'sorteos') return;
    if (d.type === 'ready') {
      pushCfg();
      syncSorteosSlowBtn();
      return;
    }
    if (d.type === 'vouch' && Number.isFinite(Number(d.count))) {
      if (!settings.sorteosOverlay) settings.sorteosOverlay = {};
      const n = Math.max(0, parseInt(d.count, 10) || 0);
      const cur = Math.max(0, parseInt(settings.sorteosOverlay.vouchCount, 10) || 0);
      if (n !== cur) {
        settings.sorteosOverlay.vouchCount = Math.max(cur, n);
        saveSettingsKeysPatch('sorteosOverlay');
      }
    }
  });
  const soFr = soFrame();
  if (soFr) {
    soFr.addEventListener('load', () => { pushCfg(); syncSorteosSlowBtn(); setTimeout(pushCfg, 200); });
  }
  syncSorteosSlowBtn();
  window.__soSyncSlowBtn = syncSorteosSlowBtn;
  refreshSorteosGiftBtn();
})();

