(function setupSorteosVidasControls() {
  const sovFrame = () => $('sov-preview');
  const toPrev = async (msg) => {
    const fr = await ensureEmbedLoaded(sovFrame());
    try { fr?.contentWindow?.postMessage({ kind: 'sorteosVidas', ...msg }, '*'); } catch {}
  };
  const sendSov = (sorteosVidasAction, extra) => {
    send({ action: 'sorteosVidas', sorteosVidasAction, ...(extra || {}) });
  };
  const pushCfg = () => {
    const cfg = settings?.sorteosVidasOverlay || {};
    toPrev({ type: 'config', config: cfg });
    syncSorteosVidasBulkTargetUi();
  };
  function syncSorteosVidasBulkTargetUi() {
    const target = Math.max(1, parseInt(settings?.sorteosVidasOverlay?.bulkElimTarget, 10) || 50);
    const per = Math.max(1, parseInt(settings?.sorteosVidasOverlay?.bulkElimPerRound, 10) || 10);
    const inpT = $('sov-bulk-target');
    const inpP = $('sov-bulk-per');
    if (inpT && document.activeElement !== inpT) inpT.value = String(target);
    if (inpP && document.activeElement !== inpP) inpP.value = String(per);
    const cfgInp = $('sovcfg-bulk');
    const cfgPer = $('sovcfg-bulk-per');
    if (cfgInp && document.activeElement !== cfgInp) cfgInp.value = String(target);
    if (cfgPer && document.activeElement !== cfgPer) cfgPer.value = String(per);
  }
  function parseSovUser(raw) {
    const s = String(raw || '').trim();
    if (!s) return '';
    const m = s.match(/tiktok\.com\/@([^/?#]+)/i);
    if (m) return decodeURIComponent(m[1]).replace(/^@+/, '').trim();
    return s.replace(/^@+/, '').split(/[/?#]/)[0].trim();
  }
  async function lookupSovProfile(user) {
    try {
      const r = await fetch('/api/tiktok-profile?' + new URLSearchParams({ url: user }));
      const data = await r.json().catch(() => ({}));
      if (!r.ok) return { username: user, nickname: user, avatar: '', error: data.error };
      return data;
    } catch {
      return { username: user, nickname: user, avatar: '', error: 'No se pudo buscar' };
    }
  }
  let sovPeopleLocal = [];
  function sovPersonKey(p) {
    if (!p) return '';
    const uid = String(p.userId || '').trim();
    if (uid && uid !== '0') return 'uid:' + uid;
    const id = String(p.id || '').trim().toLowerCase();
    if (id) return 'id:' + id;
    return '';
  }
  function findSovPersonLocal(ref) {
    const key = sovPersonKey(ref);
    if (!key) return null;
    return sovPeopleLocal.find((x) => sovPersonKey(x) === key) || null;
  }
  function sovHasStake(p) {
    return Math.max(0, Number(p?.lives) || 0) > 0 || Math.max(0, Number(p?.bank) || 0) > 0;
  }
  function mergeSovPeopleFromRemote(payload) {
    const remote = Array.isArray(payload?.players) ? payload.players : [];
    const isSnapshot = !!(payload && (
      Number.isFinite(Number(payload.totalLives))
      || (payload.hud && typeof payload.hud === 'object')
    ));
    if (isSnapshot) {
      sovPeopleLocal = remote
        .filter((p) => p && p.id && sovHasStake(p))
        .map((p) => ({
          id: String(p.id),
          userId: String(p.userId || '').trim(),
          name: p.name || p.id,
          pic: p.pic || '',
          lives: Math.max(0, Number(p.lives) || 0),
          bank: Math.max(0, Number(p.bank) || 0),
          seq: Number(p.seq) || 0,
          alive: Math.max(0, Number(p.lives) || 0) > 0,
        }));
      return sovPeopleLocal;
    }
    if (!remote.length) {
      sovPeopleLocal = [];
      return sovPeopleLocal;
    }
    const map = new Map();
    for (const p of sovPeopleLocal) {
      const k = sovPersonKey(p);
      if (k) map.set(k, { ...p });
    }
    for (const p of remote) {
      const k = sovPersonKey(p);
      if (!k) continue;
      const prev = map.get(k);
      const lives = Math.max(0, Number(p.lives) || 0);
      const bank = Math.max(0, Number(p.bank) || 0);
      if (prev) {
        map.set(k, {
          ...prev,
          ...p,
          id: p.id || prev.id,
          userId: p.userId || prev.userId,
          name: p.name || prev.name,
          pic: p.pic || prev.pic,
          lives,
          bank,
          alive: lives > 0,
          seq: Number.isFinite(Number(p.seq)) && Number(p.seq) > 0
            ? Math.min(Number(prev.seq) || Number(p.seq), Number(p.seq))
            : (prev.seq || p.seq),
        });
      } else if (lives > 0 || bank > 0) {
        map.set(k, { ...p, lives, bank, alive: lives > 0 });
      }
    }
    sovPeopleLocal = Array.from(map.values()).filter((p) => sovHasStake(p));
    return sovPeopleLocal;
  }
  function patchSovPerson(id, patch, deltaLives) {
    const pid = String(id || '').trim();
    let p = findSovPersonLocal({ id: pid, userId: patch?.userId });
    if (!p && pid) p = sovPeopleLocal.find((x) => String(x.id || '').toLowerCase() === pid.toLowerCase());
    if (!p) {
      if (!pid) return null;
      p = {
        id: pid,
        userId: String(patch?.userId || '').trim(),
        name: patch?.name || pid,
        pic: patch?.pic || '',
        lives: 0,
        seq: Date.now(),
        alive: true,
      };
      sovPeopleLocal.push(p);
    }
    if (patch?.name) p.name = patch.name;
    if (patch?.pic) p.pic = patch.pic;
    if (patch?.userId) p.userId = String(patch.userId).trim();
    if (Number.isFinite(Number(deltaLives))) {
      p.lives = Math.max(0, (Number(p.lives) || 0) + Number(deltaLives));
    } else if (Number.isFinite(Number(patch?.lives))) {
      p.lives = Math.max(0, Number(patch.lives));
    }
    p.alive = p.lives > 0;
    return p;
  }
  function buildSovRow(p) {
    const pic = esc(p.pic || '');
    const id = String(p.id || '');
    const lives = Math.max(0, parseInt(p.lives, 10) || 0);
    const el = document.createElement('div');
    el.className = 'sov-prow';
    el.dataset.id = id;
    el.dataset.lives = String(lives);
    el.innerHTML = '<div class="sov-prow-av-wrap"></div>'
      + '<div class="sov-prow-name"></div>'
      + '<div class="sov-prow-lives"></div>'
      + '<button type="button" class="sov-prow-pm plus" data-op="add" title="+1 vida">+</button>'
      + '<button type="button" class="sov-prow-pm minus" data-op="rem" title="−1 vida">−</button>'
      + '<button type="button" class="sov-prow-pm out" data-op="out" title="Quitar todas las vidas">✕</button>';
    const avWrap = el.querySelector('.sov-prow-av-wrap');
    if (avWrap) {
      avWrap.innerHTML = pic
        ? '<img class="sov-prow-av" src="' + pic + '" alt="" referrerpolicy="no-referrer" />'
        : '<div class="sov-prow-av-ph">' + esc(String(p.name || '?').slice(0, 1).toUpperCase()) + '</div>';
    }
    const nameEl = el.querySelector('.sov-prow-name');
    if (nameEl) {
      nameEl.textContent = p.name || p.id || '?';
      nameEl.title = '@' + id;
    }
    const livesEl = el.querySelector('.sov-prow-lives');
    if (livesEl) livesEl.textContent = sovLivesLabel(p);
    return el;
  }
  function sovLivesLabel(p) {
    const lives = Math.max(0, parseInt(p?.lives, 10) || 0);
    const bank = Math.max(0, parseInt(p?.bank, 10) || 0);
    return bank > 0 ? (lives + ' · ' + bank + '🪙') : String(lives);
  }
  function updateSovRow(el, p) {
    if (!el || !p) return;
    const lives = Math.max(0, parseInt(p.lives, 10) || 0);
    el.dataset.lives = String(lives);
    const livesEl = el.querySelector('.sov-prow-lives');
    if (livesEl) livesEl.textContent = sovLivesLabel(p);
    const name = p.name || p.id || '?';
    const nameEl = el.querySelector('.sov-prow-name');
    if (nameEl) {
      nameEl.textContent = name;
      nameEl.title = '@' + (p.id || '');
    }
    const pic = String(p.pic || '').trim();
    const avWrap = el.querySelector('.sov-prow-av-wrap');
    if (avWrap) {
      const cur = avWrap.querySelector('img')?.getAttribute('src') || '';
      if (pic && cur !== pic) {
        avWrap.innerHTML = '<img class="sov-prow-av" src="' + esc(pic) + '" alt="" referrerpolicy="no-referrer" />';
      } else if (!pic && !avWrap.querySelector('.sov-prow-av-ph')) {
        avWrap.innerHTML = '<div class="sov-prow-av-ph">' + esc(String(name).slice(0, 1).toUpperCase()) + '</div>';
      }
    }
  }
  function syncSovPreviewMirror(payload) {
    if (!payload) return;
    toPrev({
      type: 'mirror',
      players: payload.players || [],
      slots: payload.slots || null,
      totalLives: payload.totalLives,
      hud: payload.hud || null,
    });
  }
  function renderSorteosVidasPeople(payload) {
    const rows = $('sov-people-rows');
    const empty = $('sov-people-empty');
    if (!rows) return;
    mergeSovPeopleFromRemote(payload || {});
    sovPeopleLocal = sovPeopleLocal.filter((p) => sovHasStake(p));
    const visible = sovPeopleLocal.slice();
    visible.sort((a, b) => (Number(a.seq) || 0) - (Number(b.seq) || 0) || String(a.id).localeCompare(String(b.id)));
    const totalLives = Number.isFinite(Number(payload?.totalLives))
      ? Math.max(0, parseInt(payload.totalLives, 10) || 0)
      : visible.reduce((n, p) => n + (Math.max(0, parseInt(p.lives, 10) || 0)), 0);
    const totalBank = visible.reduce((n, p) => n + (Math.max(0, parseInt(p.bank, 10) || 0)), 0);
    if ($('sov-total-lives')) $('sov-total-lives').textContent = totalLives + ' vidas';
    if ($('sov-total-bank')) $('sov-total-bank').textContent = totalBank > 0 ? (totalBank + ' 🪙 sobrante') : '';
    if ($('sov-total-players')) $('sov-total-players').textContent = visible.length + ' personas';
    if (empty) empty.classList.toggle('is-hidden', visible.length > 0);
    const existing = new Map([...rows.querySelectorAll('.sov-prow')].map((el) => [String(el.dataset.id || ''), el]));
    visible.forEach((p, i) => {
      const id = String(p.id || '');
      let el = existing.get(id);
      if (el) {
        updateSovRow(el, p);
        existing.delete(id);
      } else {
        el = buildSovRow(p);
      }
      if (rows.children[i] !== el) rows.insertBefore(el, rows.children[i] || null);
    });
    existing.forEach((el) => { try { el.remove(); } catch { /* ignore */ } });
    syncSovPreviewMirror(Object.assign({}, payload || {}, {
      players: visible,
      totalLives,
      slots: Array.isArray(payload?.slots) ? payload.slots : null,
    }));
  }
  window.renderSorteosVidasPeople = renderSorteosVidasPeople;
  function sovLifeOp(op, playerId, count) {
    const payload = { playerId, count: count || 1 };
    const cur = findSovPersonLocal({ id: playerId }) || sovPeopleLocal.find((p) => String(p.id) === String(playerId));
    const canonId = cur?.id || playerId;
    payload.playerId = canonId;
    if (op === 'add') {
      payload.uniqueId = canonId;
      if (cur?.userId) payload.userId = cur.userId;
      patchSovPerson(canonId, { name: cur?.name || canonId, pic: cur?.pic || '', userId: cur?.userId || '' }, payload.count);
      renderSorteosVidasPeople({ players: sovPeopleLocal });
      sendSov('addLife', payload);
      return;
    }
    const n = Math.min(payload.count, Number(cur?.lives) || payload.count);
    patchSovPerson(canonId, { userId: cur?.userId || '' }, -n);
    sovPeopleLocal = sovPeopleLocal.filter((p) => sovHasStake(p));
    renderSorteosVidasPeople({ players: sovPeopleLocal });
    sendSov('removeLife', { ...payload, count: n });
  }
  function syncSorteosVidasSlowBtn() {
    const btn = $('sov-slow');
    if (!btn) return;
    const on = !!(settings?.sorteosVidasOverlay?.slowCountdown);
    btn.classList.toggle('primary', on);
    btn.classList.toggle('is-on', on);
    btn.textContent = on ? '🐢 Tiempo lento ON' : '🐢 Tiempo lento OFF';
  }
  window.refreshSorteosVidasGiftBtn = refreshSorteosVidasGiftBtn;
  if ($('sovcfg-giftpick')) $('sovcfg-giftpick').onclick = () => openGiftModalCb((g) => {
    const diamonds = Math.max(1, Number(g.diamonds) || Number(g.diamond_count) || 1);
    if ($('sovcfg-entry')) $('sovcfg-entry').value = String(diamonds);
    if ($('sovcfg-giftimg')) $('sovcfg-giftimg').value = g.image || '';
    if ($('sovcfg-giftid')) $('sovcfg-giftid').value = String(g.id || '');
    if ($('sovcfg-giftname')) $('sovcfg-giftname').value = g.name || '';
    refreshSorteosVidasGiftBtn();
    toPrev({ type: 'config', config: {
      ...(settings?.sorteosVidasOverlay || {}),
      entryCost: diamonds,
      entryGiftImage: g.image || '',
      entryGiftId: String(g.id || ''),
      entryGiftName: g.name || '',
    } });
  });
  if ($('sovcfg-giftclear')) $('sovcfg-giftclear').onclick = () => {
    ['sovcfg-giftimg', 'sovcfg-giftid', 'sovcfg-giftname'].forEach((id) => { const el = $(id); if (el) el.value = ''; });
    refreshSorteosVidasGiftBtn();
    toPrev({ type: 'config', config: {
      ...(settings?.sorteosVidasOverlay || {}),
      entryGiftImage: '', entryGiftId: '', entryGiftName: '',
      entryCost: Math.max(1, parseInt($('sovcfg-entry')?.value, 10) || 30),
    } });
  };
  if ($('sovcfg-entry')) $('sovcfg-entry').addEventListener('input', () => refreshSorteosVidasGiftBtn());
  if ($('sov-start')) $('sov-start').onclick = () => {
    sendSov('start', { forceInitial: true });
    try { toast('Sorteos vidas · Iniciar', 'ok'); } catch {}
  };
  if ($('sov-spin')) $('sov-spin').onclick = () => {
    sendSov('spin');
    try { toast('Sorteos vidas · Giro manual', 'ok'); } catch {}
  };
  if ($('sov-bulk')) $('sov-bulk').onclick = () => {
    const target = Math.max(1, parseInt($('sov-bulk-target')?.value, 10) || settings?.sorteosVidasOverlay?.bulkElimTarget || 50);
    const perRound = Math.max(1, parseInt($('sov-bulk-per')?.value, 10) || settings?.sorteosVidasOverlay?.bulkElimPerRound || 10);
    sendSov('bulkSpin', { targetLives: target, perRound });
    try { toast('Sorteos vidas · −' + perRound + ' por ronda (objetivo ' + target + ')', 'ok'); } catch {}
  };
  const saveSovBulkField = (field, elId, cfgId) => {
    const n = Math.max(1, parseInt($(elId)?.value, 10) || (field === 'bulkElimPerRound' ? 10 : 50));
    if (!settings.sorteosVidasOverlay) settings.sorteosVidasOverlay = {};
    settings.sorteosVidasOverlay[field] = n;
    saveSettingsKeysPatch('sorteosVidasOverlay');
    const cfgEl = $(cfgId);
    if (cfgEl) cfgEl.value = String(n);
    syncSorteosVidasBulkTargetUi();
  };
  if ($('sov-bulk-target')) $('sov-bulk-target').addEventListener('change', () => saveSovBulkField('bulkElimTarget', 'sov-bulk-target', 'sovcfg-bulk'));
  if ($('sov-bulk-per')) $('sov-bulk-per').addEventListener('change', () => saveSovBulkField('bulkElimPerRound', 'sov-bulk-per', 'sovcfg-bulk-per'));
  if ($('sov-add-btn')) $('sov-add-btn').onclick = async () => {
    const uniqueId = parseSovUser($('sov-add-user')?.value);
    const st = $('sov-add-status');
    const count = Math.max(1, Math.min(999, parseInt($('sov-add-count')?.value, 10) || 1));
    if (!uniqueId) { toast('Pon un @ de TikTok', 'warn'); return; }
    if (st) st.textContent = 'Buscando @' + uniqueId + '…';
    const prof = await lookupSovProfile(uniqueId);
    const uid = String(prof.username || uniqueId).replace(/^@+/, '');
    const payload = {
      uniqueId: uid,
      nickname: prof.nickname || uid,
      photo: prof.avatar || '',
      userId: String(prof.userId || '').trim(),
      count,
    };
    sendSov('addLife', payload);
    patchSovPerson(uid, { name: prof.nickname || uid, pic: prof.avatar || '', userId: payload.userId }, count);
    renderSorteosVidasPeople({ players: sovPeopleLocal });
    if (st) st.textContent = prof.error ? ('Agregadas sin foto · @' + uid) : ('+' + count + ' vidas · @' + uid);
    toast('+' + count + ' vidas · @' + uid, 'ok');
    if ($('sov-add-user')) $('sov-add-user').value = '';
  };
  const host = $('sov-people-rows');
  if (host) {
    host.addEventListener('click', (e) => {
      const btn = e.target?.closest?.('.sov-prow-pm');
      if (!btn) return;
      const row = btn.closest('.sov-prow');
      const id = row?.dataset?.id;
      if (!id) return;
      const op = btn.dataset.op;
      if (op === 'out') {
        const n = Math.max(1, parseInt(row.dataset.lives, 10) || 1);
        sovLifeOp('rem', id, n);
        return;
      }
      sovLifeOp(op === 'add' ? 'add' : 'rem', id, 1);
    });
  }
  if ($('sov-add-user')) {
    $('sov-add-user').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); $('sov-add-btn')?.click(); }
    });
  }
  if ($('sov-lock')) $('sov-lock').onclick = () => { sendSov('lock'); };
  if ($('sov-unlock')) $('sov-unlock').onclick = () => { sendSov('unlock'); };
  if ($('sov-slow')) $('sov-slow').onclick = () => {
    if (!settings.sorteosVidasOverlay) settings.sorteosVidasOverlay = {};
    const next = !settings.sorteosVidasOverlay.slowCountdown;
    settings.sorteosVidasOverlay.slowCountdown = next;
    if ($('sovcfg-slow')) $('sovcfg-slow').checked = next;
    saveSettingsKeysPatch('sorteosVidasOverlay');
    sendSov(next ? 'slowOn' : 'slowOff');
    syncSorteosVidasSlowBtn();
  };
  if ($('sov-reset')) $('sov-reset').onclick = () => {
    sendSov('reset');
    try { toast('Sorteos vidas · Reset (sobrante se guarda)', 'ok'); } catch {}
  };
  window.addEventListener('message', (ev) => {
    const d = ev?.data;
    if (!d || d.kind !== 'sorteosVidas') return;
    if (d.type === 'ready') { pushCfg(); syncSorteosVidasSlowBtn(); return; }
    // Lista de participantes: solo overlay en vivo (WS). La preview embed ya no empuja players.
    if (d.type === 'players') return;
    if (d.type === 'vouch' && Number.isFinite(Number(d.count))) {
      if (!settings.sorteosVidasOverlay) settings.sorteosVidasOverlay = {};
      const n = Math.max(0, parseInt(d.count, 10) || 0);
      const cur = Math.max(0, parseInt(settings.sorteosVidasOverlay.vouchCount, 10) || 0);
      if (n !== cur) {
        settings.sorteosVidasOverlay.vouchCount = Math.max(cur, n);
        saveSettingsKeysPatch('sorteosVidasOverlay');
      }
    }
  });
  const fr = sovFrame();
  if (fr) fr.addEventListener('load', () => { pushCfg(); syncSorteosVidasSlowBtn(); setTimeout(pushCfg, 200); });
  syncSorteosVidasSlowBtn();
  syncSorteosVidasBulkTargetUi();
  window.__sovSyncSlowBtn = syncSorteosVidasSlowBtn;
  window.__sovSyncBulkTarget = syncSorteosVidasBulkTargetUi;
  refreshSorteosVidasGiftBtn();
})();

(function setupCameraFrames() {
  const FRAMES = (typeof window !== 'undefined' && window.CAMERA_FRAMES) ? window.CAMERA_FRAMES : [];
  const grid = () => $('mcf-grid');
  const frame = () => $('mcf-preview');
  const ensure = () => {
    if (!settings) return { frame: 'vip-gold', scale: 100 };
    if (!settings.cameraFrame) settings.cameraFrame = { frame: 'vip-gold', scale: 100 };
    return settings.cameraFrame;
  };
  const frameOf = (id) => (typeof window.cameraFrameById === 'function' ? window.cameraFrameById(id) : FRAMES[0]);
  const pushPreview = (cfg) => {
    ensureEmbedLoaded(frame()).then((fr) => {
      fr?.contentWindow?.postMessage({ kind: 'marcocamara', type: 'config', config: cfg || ensure() }, '*');
    });
  };
  const syncActive = () => {
    const id = ensure().frame || 'vip-gold';
    grid()?.querySelectorAll('.mcf-item').forEach((el) => {
      el.classList.toggle('is-active', el.dataset.frame === id);
    });
    const sc = $('mcf-scale');
    const lab = $('mcf-scale-val');
    const n = Math.max(60, Math.min(140, parseInt(ensure().scale, 10) || 100));
    if (sc && sc.value !== String(n)) sc.value = String(n);
    if (lab) lab.textContent = n + '%';
  };
  const selectFrame = (id) => {
    const f = frameOf(id);
    ensure().frame = f.id;
    syncActive();
    pushPreview(ensure());
    saveSettingsKeysPatch('cameraFrame', { flush: true });
  };
  const renderGrid = () => {
    const g = grid();
    if (!g || g._mcfReady) return;
    g._mcfReady = true;
    g.innerHTML = FRAMES.map((f) => (
      '<button type="button" class="mcf-item" data-frame="' + f.id + '" title="' + f.name + '">'
      + '<img src="' + f.img + '" alt="" loading="lazy" decoding="async">'
      + '<span>' + f.name + '</span></button>'
    )).join('');
    g.addEventListener('click', (e) => {
      const btn = e.target.closest('.mcf-item');
      if (!btn) return;
      selectFrame(btn.dataset.frame);
    });
  };
  $('mcf-scale')?.addEventListener('input', () => {
    const n = Math.max(60, Math.min(140, parseInt($('mcf-scale')?.value, 10) || 100));
    ensure().scale = n;
    if ($('mcf-scale-val')) $('mcf-scale-val').textContent = n + '%';
    pushPreview(ensure());
  });
  $('mcf-scale')?.addEventListener('change', () => {
    ensure().scale = Math.max(60, Math.min(140, parseInt($('mcf-scale')?.value, 10) || 100));
    saveSettings();
    pushPreview(ensure());
  });
  const fr = frame();
  if (fr) fr.addEventListener('load', () => { pushPreview(ensure()); syncActive(); });
  renderGrid();
  syncActive();
  window.__mcfPushPreview = () => { syncActive(); pushPreview(ensure()); };
})();

