/* ====================== Top Kills (manual) ====================== */
const TK_DEFAULT_RANK = { bg: '#1a3a5c', color: '#ffffff', size: 14, outline: '#000000', outlineW: 0, bold: true, italic: false };
const TK_MAX_RANKS = 20;
const TK_DEFAULT_RANKS = [
  '#1a3a5c', '#1e3558', '#223a5e', '#1c3354', '#1f385a',
  '#183250', '#203c5c', '#1a3050', '#1d3656', '#16304c',
  '#1b3452', '#1e3856', '#17304e', '#21405c', '#1a3250',
  '#1c3654', '#19324c', '#223a5a', '#15304a', '#1f3a58',
].map((bg) => ({ ...TK_DEFAULT_RANK, bg }));

function defaultTopKillsCfg() {
  try {
    return structuredClone(window.DEFAULT_SETTINGS?.topKills || { title: 'TOP KILLS', players: [], rankStyles: TK_DEFAULT_RANKS.slice() });
  } catch {
    return {
      title: 'TOP KILLS', nickTemplate: '{nickname}', nickMode: 'nickname',
      subtitle: 'Lleva {kills} Kills', textColor: '#39ff14',
      bold: true, italic: false, strike: false, underline: false,
      design: 'transparent', font: 'inter', scale: 100,
      rankStyles: TK_DEFAULT_RANKS.map((r) => ({ ...r })),
      players: [],
    };
  }
}

function ensureTopKillsCfg() {
  if (!settings || typeof settings !== 'object') return defaultTopKillsCfg();
  if (!settings.topKills || typeof settings.topKills !== 'object') settings.topKills = defaultTopKillsCfg();
  const c = settings.topKills;
  if (!Array.isArray(c.players)) c.players = [];
  else {
    const seen = new Set();
    c.players = c.players.filter((x) => {
      if (!x || typeof x !== 'object') return false;
      if (!x.id) x.id = 'tk_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
      if (seen.has(x.id)) return false;
      seen.add(x.id);
      return true;
    });
  }
  tkNormalizePlayerAvatars(c);
  if (!Array.isArray(c.rankStyles) || c.rankStyles.length !== TK_MAX_RANKS) {
    const base = (c.rankStyles || []).slice();
    while (base.length < TK_MAX_RANKS) base.push({ ...(TK_DEFAULT_RANKS[base.length] || TK_DEFAULT_RANK) });
    c.rankStyles = base.slice(0, TK_MAX_RANKS).map((r, i) => ({ ...(TK_DEFAULT_RANKS[i] || TK_DEFAULT_RANK), ...(r || {}) }));
  }
  return c;
}

function tkPlayerHandle(p) {
  return String(p?.username || p?.uniqueId || '').replace(/^@/, '').trim();
}

function tkStableAvatarUrl(p) {
  const h = tkPlayerHandle(p);
  if (!h) return String(p?.avatar || '');
  const av = String(p?.avatar || '');
  if (av.startsWith('/api/tt-avatar') || av.startsWith('/uploads/')) return av;
  return `/api/tt-avatar?user=${encodeURIComponent(h)}`;
}

function tkNormalizePlayerAvatars(cfg) {
  (cfg?.players || []).forEach((p) => {
    if (!p || typeof p !== 'object') return;
    const h = tkPlayerHandle(p);
    if (h) p.avatar = tkStableAvatarUrl(p);
  });
}

function tkAvatarFallback(p) {
  const remote = String(p?.avatarRemote || '').trim();
  if (!remote || remote.startsWith('/api/')) return '';
  return `/api/img-proxy?url=${encodeURIComponent(remote)}`;
}

function tkAvatarImgHtml(p) {
  const src = tkStableAvatarUrl(p);
  const fallback = tkAvatarFallback(p);
  const url = src || fallback;
  if (!url) return '<span class="tk-av-ph" aria-hidden="true"></span>';
  const retry = fallback && fallback !== url
    ? ` onerror="this.onerror=null;this.src='${fallback.replace(/'/g, '')}'"`
    : '';
  return `<img class="tk-av" src="${esc(url)}" alt="" referrerpolicy="no-referrer"${retry}>`;
}

function tkNewPlayer(partial) {
  return {
    id: 'tk_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7),
    username: '', nickname: '', uniqueId: '', avatar: '', kills: 0,
    ...(partial || {}),
  };
}

function tkSortedPlayers(cfg) {
  return (cfg.players || []).slice().sort((a, b) => (b.kills | 0) - (a.kills | 0)
    || String(a.username || '').localeCompare(String(b.username || '')));
}

function tkRankStyle(cfg, i) {
  return { ...TK_DEFAULT_RANK, ...(cfg.rankStyles?.[i] || TK_DEFAULT_RANKS[i] || {}) };
}

const TK_PREVIEW_IDS = ['tk-preview-lista', 'tk-preview-compact', 'tk-preview-neon', 'tk-preview-minecraft', 'tk-preview-gamer', 'tk-preview-pro'];
let tkPreviewDebounce = null;
let lastTopKillsEditAt = 0;
const TK_EDIT_ECHO_MS = 2500;
let tkClearPlayersIntent = false;

function preserveLocalTopKillsOnSettingsEcho(incoming) {
  if (!incoming || !settings?.topKills) return incoming;
  const localPlayers = settings.topKills.players;
  if (!Array.isArray(localPlayers) || !localPlayers.length) return incoming;
  // Reset explícito del usuario: dejar pasar players: []
  if (tkClearPlayersIntent) return incoming;
  const remote = incoming.topKills;
  const remotePlayers = remote?.players;
  // Nunca aceptar un eco vacío que borre tops (actualizaciones, merges, otros saves)
  if (!remote || !Array.isArray(remotePlayers) || remotePlayers.length === 0) {
    const out = { ...incoming };
    out.topKills = { ...(remote || {}), ...settings.topKills, players: localPlayers.slice() };
    return out;
  }
  const mergedPlayers = tkMergePlayerPhotos(remotePlayers, localPlayers);
  // Eco incompleto justo tras editar: preferir lo local si tiene más jugadores
  if (Date.now() - lastTopKillsEditAt < TK_EDIT_ECHO_MS && remotePlayers.length < localPlayers.length) {
    const out = { ...incoming };
    out.topKills = { ...remote, ...settings.topKills, players: localPlayers.slice() };
    return out;
  }
  const out = { ...incoming };
  out.topKills = { ...remote, players: mergedPlayers };
  return out;
}

function tkMergePlayerPhotos(remotePlayers, localPlayers) {
  const byId = new Map();
  const byUser = new Map();
  for (const p of localPlayers || []) {
    if (!p || typeof p !== 'object') continue;
    if (p.id) byId.set(p.id, p);
    const h = tkPlayerHandle(p).toLowerCase();
    if (h) byUser.set(h, p);
  }
  return (remotePlayers || []).map((p) => {
    if (!p || typeof p !== 'object') return p;
    const prev = byId.get(p.id) || byUser.get(tkPlayerHandle(p).toLowerCase());
    if (!prev) return p;
    return {
      ...p,
      avatar: p.avatar || prev.avatar || '',
      avatarRemote: p.avatarRemote || prev.avatarRemote || '',
    };
  });
}

function pushTopKillsPreview(cfg) {
  const config = cfg || (settings ? ensureTopKillsCfg() : defaultTopKillsCfg());
  const msg = { kind: 'top_kills', type: 'config', config };
  const viewActive = !!$('view-ov-topkills')?.classList?.contains('active');
  TK_PREVIEW_IDS.forEach((id) => {
    const fr = $(id);
    if (!fr) return;
    const ready = fr.dataset.embedReady === '1' && fr.getAttribute('src') && fr.getAttribute('src') !== 'about:blank';
    const sendMsg = (frame) => { try { frame?.contentWindow?.postMessage(msg, '*'); } catch {} };
    if (ready) sendMsg(fr);
    else if (viewActive) ensureEmbedLoaded(fr).then(sendMsg);
  });
}

function pushTopKillsPreviewSoon(cfg, ms = 60) {
  clearTimeout(tkPreviewDebounce);
  tkPreviewDebounce = setTimeout(() => {
    tkPreviewDebounce = null;
    pushTopKillsPreview(cfg);
  }, ms);
}

function pushTopKillsTest(previewId) {
  const ids = previewId ? [previewId] : TK_PREVIEW_IDS;
  ids.forEach((id) => {
    try { $(id)?.contentWindow?.postMessage({ kind: 'top_kills', type: 'test' }, '*'); } catch {}
  });
}

function saveTopKillsPatch(opts) {
  if (applyingSettings || !settings) return;
  ensureTopKillsCfg();
  lastTopKillsEditAt = Date.now();
  if (opts && opts.clearPlayers) {
    tkClearPlayersIntent = true;
    settings.topKills.clearPlayers = true;
  }
  saveSettingsKeysPatch('topKills');
  if (opts && opts.clearPlayers) {
    setTimeout(() => {
      tkClearPlayersIntent = false;
      if (settings?.topKills) delete settings.topKills.clearPlayers;
    }, 1500);
  }
  if (opts && opts.preview === false) return;
  if (opts && opts.previewSoon) pushTopKillsPreviewSoon(settings.topKills, opts.previewSoon);
  else pushTopKillsPreview(settings.topKills);
}

function refreshTopKills() {
  if (!settings) return;
  ensureTopKillsCfg();
  const active = document.activeElement;
  const typing = !!(active && active.classList?.contains('tk-name') && active.closest('#tk-rows'));
  if (!typing && typeof window.renderTopKillsRows === 'function') window.renderTopKillsRows();
  pushTopKillsPreview(settings.topKills);
}

(function setupTopKills() {
  try {
  let rankEditIdx = -1;
  let nameTimers = {};
  const pop = () => $('tkRankStylePop');

  function closeRankPop() {
    const p = pop();
    if (p) p.classList.add('hidden');
    rankEditIdx = -1;
  }

  function syncFmtBtn(id, on) {
    const el = $(id);
    if (!el) return;
    if (on) el.setAttribute('data-on', '1');
    else el.removeAttribute('data-on');
  }

  function openRankPop(idx, anchor) {
    const cfg = ensureTopKillsCfg();
    const st = tkRankStyle(cfg, idx);
    rankEditIdx = idx;
    if ($('tkrs-bg')) $('tkrs-bg').value = st.bg || '#1a3a5c';
    if ($('tkrs-outline')) $('tkrs-outline').value = st.outline || '#000000';
    if ($('tkrs-outlinew')) $('tkrs-outlinew').value = String(st.outlineW | 0);
    if ($('tkrs-size-lbl')) $('tkrs-size-lbl').textContent = String(st.size || 14);
    syncFmtBtn('tkrs-bold', !!st.bold);
    syncFmtBtn('tkrs-italic', !!st.italic);
    const p = pop();
    if (!p || !anchor) return;
    p.classList.remove('hidden');
    const r = anchor.getBoundingClientRect();
    const pw = 240;
    let left = r.right - pw;
    let top = r.bottom + 8;
    if (left < 8) left = 8;
    if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
    if (top + 220 > window.innerHeight) top = Math.max(8, r.top - 228);
    p.style.left = left + 'px';
    p.style.top = top + 'px';
  }

  function patchRankStyle(mut) {
    if (rankEditIdx < 0) return;
    const cfg = ensureTopKillsCfg();
    cfg.rankStyles[rankEditIdx] = { ...tkRankStyle(cfg, rankEditIdx), ...mut };
    saveTopKillsPatch();
    renderTopKillsRows();
  }

  function findOrCreateAtSlot(rankIdx) {
    const cfg = ensureTopKillsCfg();
    const sorted = tkSortedPlayers(cfg);
    let p = sorted[rankIdx];
    if (p) return p;
    p = tkNewPlayer();
    cfg.players.push(p);
    return p;
  }

  function playerFromRow(row, rankIdx) {
    const cfg = ensureTopKillsCfg();
    const id = row?.dataset?.id;
    if (id) {
      const byId = cfg.players.find((x) => x && x.id === id);
      if (byId) return byId;
    }
    return findOrCreateAtSlot(rankIdx);
  }

  function orderKey(cfg) {
    return tkSortedPlayers(cfg).map((p) => p.id).join('|');
  }

  function bumpKillsFromRow(row, delta) {
    if (!row || !settings) return;
    const rank = Number(row.dataset.rank);
    if (!Number.isFinite(rank) || rank < 0) return;
    const cfg = ensureTopKillsCfg();
    const before = orderKey(cfg);
    const p = playerFromRow(row, rank);
    p.kills = Math.max(0, (p.kills | 0) + delta);
    row.dataset.id = p.id || '';
    const killsEl = row.querySelector('.tk-kills');
    if (killsEl) killsEl.textContent = String(p.kills | 0);
    const after = orderKey(cfg);
    saveTopKillsPatch({ previewSoon: 70 });
    if (before !== after) window.renderTopKillsRows();
  }

  async function resolvePlayerAvatar(p, raw) {
    const q = String(raw || '').trim();
    if (!q) {
      p.avatar = '';
      p.username = '';
      p.nickname = '';
      p.uniqueId = '';
      return;
    }
    const handle = q.replace(/^@/, '').replace(/^https?:\/\/(www\.)?tiktok\.com\/@?/i, '').split(/[/?#]/)[0];
    const query = handle ? ('@' + handle) : q;
    const prof = await resolveFlwTiktokProfile(query);
    if (prof?.error) {
      if (handle) {
        const same = tkPlayerHandle(p).toLowerCase() === handle.toLowerCase();
        p.username = handle;
        p.uniqueId = handle;
        if (!p.nickname) p.nickname = handle;
        if (!same) p.avatarRemote = '';
        p.avatar = `/api/tt-avatar?user=${encodeURIComponent(handle)}`;
      } else {
        p.avatar = '';
        p.avatarRemote = '';
        p.username = '';
        p.nickname = '';
        p.uniqueId = '';
      }
      return;
    }
    if (prof) {
      p.username = prof.username || p.username || handle;
      p.uniqueId = prof.username || p.uniqueId || handle;
      p.nickname = prof.nickname || prof.username || p.nickname || handle;
      if (prof.avatarRemote) p.avatarRemote = prof.avatarRemote;
      p.avatar = tkStableAvatarUrl({ ...p, avatar: prof.avatar || p.avatar || '' });
    }
  }

  function setRowAvatar(row, p) {
    const oldAv = row.querySelector('.tk-av, .tk-av-ph');
    if (!oldAv) return;
    const avatarUrl = tkStableAvatarUrl(p);
    const fallback = tkAvatarFallback(p);
    const url = avatarUrl || fallback;
    if (url) {
      const img = document.createElement('img');
      img.className = 'tk-av';
      img.src = url;
      img.alt = '';
      img.referrerPolicy = 'no-referrer';
      if (fallback && fallback !== url) {
        img.onerror = () => { img.onerror = null; img.src = fallback; };
      }
      oldAv.replaceWith(img);
    } else if (!oldAv.classList.contains('tk-av-ph')) {
      const ph = document.createElement('span');
      ph.className = 'tk-av-ph';
      ph.setAttribute('aria-hidden', 'true');
      oldAv.replaceWith(ph);
    }
  }

  async function resolveRowName(row, rank, nameInp, { rerender } = {}) {
    if (!row?.isConnected || !nameInp || !settings) return;
    const p = playerFromRow(row, rank);
    if (p?.id) row.dataset.id = p.id;
    const raw = nameInp.value.trim();
    const handle = raw.replace(/^@/, '').replace(/^https?:\/\/(www\.)?tiktok\.com\/@?/i, '').split(/[/?#]/)[0];
    let removed = false;
    const avGen = (p._avGen = (p._avGen | 0) + 1);
    if (handle) {
      p.username = handle;
      p.uniqueId = handle;
      if (!p.nickname) p.nickname = handle;
      row.classList.add('tk-loading-av');
      await resolvePlayerAvatar(p, '@' + handle);
      if (p._avGen !== avGen || !row.isConnected) return;
      row.classList.remove('tk-loading-av');
    } else {
      p.username = '';
      p.uniqueId = '';
      p.nickname = '';
      p.avatar = '';
      const cfg = ensureTopKillsCfg();
      if (!(p.kills | 0)) {
        cfg.players = cfg.players.filter((x) => x.id !== p.id);
        removed = true;
      }
    }
    if (!row.isConnected) return;
    // Si el jugador ya no está (borrado mientras resolvíamos), no recrear
    const still = ensureTopKillsCfg().players.some((x) => x && x.id === p.id);
    if (!still && !removed) return;
    saveTopKillsPatch(removed && !ensureTopKillsCfg().players.length ? { clearPlayers: true } : undefined);
    if (removed) {
      window.renderTopKillsRows();
      return;
    }
    setRowAvatar(row, p);
    if (document.activeElement !== nameInp && p.username) {
      nameInp.value = '@' + String(p.username).replace(/^@/, '');
    }
    if (rerender && document.activeElement?.classList?.contains('tk-name') === false) {
      window.renderTopKillsRows();
    }
  }

  window.renderTopKillsRows = function renderTopKillsRows() {
    const wrap = $('tk-rows');
    if (!wrap) return;
    const cfg = ensureTopKillsCfg();
    const sorted = tkSortedPlayers(cfg);
    const slots = [];
    for (let i = 0; i < TK_MAX_RANKS; i++) slots.push(sorted[i] || null);
    wrap.innerHTML = slots.map((p, i) => {
      const st = tkRankStyle(cfg, i);
      const nameVal = p ? (p.username ? '@' + String(p.username).replace(/^@/, '') : (p.nickname || '')) : '';
      const kills = p ? (p.kills | 0) : 0;
      const av = p ? tkAvatarImgHtml(p) : '<span class="tk-av-ph" aria-hidden="true"></span>';
      return `<div class="tk-row" data-rank="${i}" data-id="${esc(p?.id || '')}" style="--tk-row-bg:${esc(st.bg)};--tk-swatch:${esc(st.bg)}">
        <span class="tk-rank">#${i + 1}</span>
        ${av}
        <input type="text" class="tk-name" value="${esc(nameVal)}" placeholder="Nombre" spellcheck="false" autocomplete="off">
        <span class="tk-row-spacer" aria-hidden="true"></span>
        <span class="tk-kills">${kills}</span>
        <button type="button" class="tk-pm plus" title="+1 kill">+</button>
        <button type="button" class="tk-pm minus" title="-1 kill">−</button>
        <button type="button" class="tk-stylebtn" title="Color / estilo del puesto #${i + 1}" aria-label="Estilo puesto"></button>
        <button type="button" class="tk-del" title="Quitar">${CARD_ICON.trash}</button>
      </div>`;
    }).join('');

    wrap.querySelectorAll('.tk-row').forEach((row) => {
      const rank = Number(row.dataset.rank);
      const nameInp = row.querySelector('.tk-name');
      if (!nameInp) return;
      nameInp.oninput = () => {
        const p = playerFromRow(row, rank);
        if (p?.id) row.dataset.id = p.id;
        const raw = nameInp.value.trim();
        const handle = raw.replace(/^@/, '').replace(/^https?:\/\/(www\.)?tiktok\.com\/@?/i, '').split(/[/?#]/)[0];
        if (handle) {
          p.username = handle;
          p.uniqueId = handle;
          if (!p.nickname) p.nickname = handle;
        } else {
          p.username = '';
          p.uniqueId = '';
          p.nickname = '';
          p.avatar = '';
        }
        clearTimeout(nameTimers[rank]);
        nameTimers[rank] = setTimeout(() => {
          resolveRowName(row, rank, nameInp, { rerender: false });
        }, 500);
      };
      nameInp.onblur = (e) => {
        clearTimeout(nameTimers[rank]);
        const toBtn = e.relatedTarget?.closest?.('.tk-pm, .tk-del, .tk-stylebtn');
        // Si el foco va a +/- u otro botón de la fila, no re-renderizar (se comía el clic)
        nameTimers[rank] = setTimeout(() => {
          resolveRowName(row, rank, nameInp, { rerender: !toBtn });
        }, 50);
      };
    });
  };

  // Delegación: +/- en pointerdown (antes del blur del input) para que el 1er clic cuente
  const tkRowsHost = $('tk-rows');
  if (tkRowsHost && !tkRowsHost.dataset.tkBound) {
    tkRowsHost.dataset.tkBound = '1';
    tkRowsHost.addEventListener('pointerdown', (e) => {
      if (e.button != null && e.button !== 0) return;
      const btn = e.target.closest?.('.tk-pm');
      if (!btn || !tkRowsHost.contains(btn)) return;
      const row = btn.closest('.tk-row');
      if (!row) return;
      e.preventDefault();
      e.stopPropagation();
      if (btn.classList.contains('plus')) bumpKillsFromRow(row, 1);
      else if (btn.classList.contains('minus')) bumpKillsFromRow(row, -1);
    });
    tkRowsHost.addEventListener('click', (e) => {
      const btn = e.target.closest?.('.tk-del, .tk-stylebtn');
      if (!btn || !tkRowsHost.contains(btn)) return;
      const row = btn.closest('.tk-row');
      if (!row) return;
      e.preventDefault();
      e.stopPropagation();
      const rank = Number(row.dataset.rank);
      if (btn.classList.contains('tk-del')) {
        clearTimeout(nameTimers[rank]);
        delete nameTimers[rank];
        const cfg = ensureTopKillsCfg();
        const id = row.dataset.id;
        if (id) cfg.players = cfg.players.filter((x) => x.id !== id);
        else {
          const sorted = tkSortedPlayers(cfg);
          if (sorted[rank]) cfg.players = cfg.players.filter((x) => x.id !== sorted[rank].id);
        }
        const cleared = !cfg.players.length;
        saveTopKillsPatch({ previewSoon: 70, clearPlayers: cleared });
        window.renderTopKillsRows();
        return;
      }
      if (btn.classList.contains('tk-stylebtn')) openRankPop(rank, btn);
    });
  }

  function fillConfigForm() {
    const c = ensureTopKillsCfg();
    if ($('tkcfg-title')) $('tkcfg-title').value = c.title || 'TOP KILLS';
    if ($('tkcfg-nick')) $('tkcfg-nick').value = c.nickTemplate || '{nickname}';
    if ($('tkcfg-nickmode')) $('tkcfg-nickmode').value = c.nickMode === 'username' ? 'username' : 'nickname';
    if ($('tkcfg-subtitle')) $('tkcfg-subtitle').value = c.subtitle || 'Lleva {kills} Kills';
    if ($('tkcfg-textcolor')) $('tkcfg-textcolor').value = c.textColor || '#39ff14';
    if ($('tkcfg-font')) $('tkcfg-font').value = c.font || 'inter';
    if ($('tkcfg-scale')) $('tkcfg-scale').value = String(c.scale ?? 100);
    if ($('tkcfg-scale-lbl')) $('tkcfg-scale-lbl').textContent = (c.scale ?? 100) + '%';
    syncFmtBtn('tkcfg-bold', c.bold !== false);
    syncFmtBtn('tkcfg-italic', !!c.italic);
    syncFmtBtn('tkcfg-strike', !!c.strike);
    syncFmtBtn('tkcfg-underline', !!c.underline);
  }

  function readConfigForm() {
    const c = ensureTopKillsCfg();
    c.title = ($('tkcfg-title')?.value || 'TOP KILLS').trim().slice(0, 48) || 'TOP KILLS';
    c.nickMode = $('tkcfg-nickmode')?.value === 'username' ? 'username' : 'nickname';
    c.nickTemplate = ($('tkcfg-nick')?.value || (c.nickMode === 'username' ? '{username}' : '{nickname}')).trim();
    c.subtitle = ($('tkcfg-subtitle')?.value || 'Lleva {kills} Kills').trim();
    c.textColor = $('tkcfg-textcolor')?.value || '#39ff14';
    c.font = $('tkcfg-font')?.value || 'inter';
    c.scale = Math.max(50, Math.min(140, parseInt($('tkcfg-scale')?.value, 10) || 100));
    c.bold = $('tkcfg-bold')?.getAttribute('data-on') === '1';
    c.italic = $('tkcfg-italic')?.getAttribute('data-on') === '1';
    c.strike = $('tkcfg-strike')?.getAttribute('data-on') === '1';
    c.underline = $('tkcfg-underline')?.getAttribute('data-on') === '1';
    return c;
  }

  if ($('tk-config')) $('tk-config').onclick = () => {
    try {
      if (settings) fillConfigForm();
      pushTopKillsPreview(settings ? ensureTopKillsCfg() : defaultTopKillsCfg());
    } catch (err) { console.error('Top Kills config:', err); }
    const m = $('tkConfigModal');
    if (m) m.classList.remove('hidden');
    else if (typeof toast === 'function') toast('No se encontró el modal de Top kills', 'warn');
  };
  const closeCfg = () => $('tkConfigModal')?.classList.add('hidden');
  if ($('tkcfg-close')) $('tkcfg-close').onclick = closeCfg;
  $('tkConfigModal')?.addEventListener('click', (e) => { if (e.target.id === 'tkConfigModal') closeCfg(); });
  if ($('tkcfg-save')) $('tkcfg-save').onclick = () => { readConfigForm(); saveTopKillsPatch(); closeCfg(); };

  ['tkcfg-bold', 'tkcfg-italic', 'tkcfg-strike', 'tkcfg-underline'].forEach((id) => {
    $(id)?.addEventListener('click', () => {
      const el = $(id);
      if (el.getAttribute('data-on') === '1') el.removeAttribute('data-on');
      else el.setAttribute('data-on', '1');
      readConfigForm();
      pushTopKillsPreview();
    });
  });
  ['tkcfg-title', 'tkcfg-nick', 'tkcfg-subtitle', 'tkcfg-textcolor', 'tkcfg-font', 'tkcfg-scale', 'tkcfg-nickmode'].forEach((id) => {
    const el = $(id);
    if (!el) return;
    const sync = () => {
      if (id === 'tkcfg-nickmode') {
        const mode = el.value === 'username' ? 'username' : 'nickname';
        if ($('tkcfg-nick')) $('tkcfg-nick').value = mode === 'username' ? '{username}' : '{nickname}';
      }
      if (id === 'tkcfg-scale' && $('tkcfg-scale-lbl')) $('tkcfg-scale-lbl').textContent = (parseInt(el.value, 10) || 100) + '%';
      readConfigForm();
      pushTopKillsPreview();
    };
    el.oninput = sync;
    el.onchange = sync;
  });

  if ($('tk-reset')) $('tk-reset').onclick = () => {
    const c = ensureTopKillsCfg();
    c.players = [];
    saveTopKillsPatch({ clearPlayers: true });
    window.renderTopKillsRows();
  };
  // (sin botón Test: la preview se actualiza sola al cambiar jugadores)

  $('tkrs-bg')?.addEventListener('input', () => patchRankStyle({ bg: $('tkrs-bg').value }));
  $('tkrs-outline')?.addEventListener('input', () => patchRankStyle({ outline: $('tkrs-outline').value }));
  $('tkrs-outlinew')?.addEventListener('input', () => patchRankStyle({ outlineW: parseInt($('tkrs-outlinew').value, 10) || 0 }));
  $('tkrs-bold')?.addEventListener('click', () => {
    const on = $('tkrs-bold').getAttribute('data-on') !== '1';
    syncFmtBtn('tkrs-bold', on);
    patchRankStyle({ bold: on });
  });
  $('tkrs-italic')?.addEventListener('click', () => {
    const on = $('tkrs-italic').getAttribute('data-on') !== '1';
    syncFmtBtn('tkrs-italic', on);
    patchRankStyle({ italic: on });
  });
  $('tkrs-size-up')?.addEventListener('click', () => {
    const n = Math.min(32, (parseInt($('tkrs-size-lbl')?.textContent, 10) || 14) + 1);
    if ($('tkrs-size-lbl')) $('tkrs-size-lbl').textContent = String(n);
    patchRankStyle({ size: n });
  });
  $('tkrs-size-dn')?.addEventListener('click', () => {
    const n = Math.max(8, (parseInt($('tkrs-size-lbl')?.textContent, 10) || 14) - 1);
    if ($('tkrs-size-lbl')) $('tkrs-size-lbl').textContent = String(n);
    patchRankStyle({ size: n });
  });
  document.addEventListener('click', (e) => {
    const p = pop();
    if (!p || p.classList.contains('hidden')) return;
    if (p.contains(e.target) || e.target.closest?.('.tk-stylebtn')) return;
    closeRankPop();
  });

  if (settings) window.renderTopKillsRows();
  } catch (err) {
    console.error('Top Kills setup:', err);
  }
})();

/* ---- Efectos pantalla (App PC): regalo → negro / rayos / DVD ---- */
const SFX_EFFECTS = [
  { id: 'black', label: 'Pantalla negra' },
  { id: 'lightning', label: 'Rayos' },
  { id: 'dvd', label: 'DVD rebotando' },
  { id: 'glitch', label: 'Glitch' },
  { id: 'matrix', label: 'Matrix' },
  { id: 'static', label: 'Estática TV' },
  { id: 'flash', label: 'Flash / strobe' },
];

function defaultScreenFxCfg() {
  try {
    return structuredClone(window.DEFAULT_SETTINGS?.screenFx || { enabled: true, rules: [] });
  } catch {
    return { enabled: true, rules: [] };
  }
}

function ensureScreenFxCfg() {
  if (!settings) return defaultScreenFxCfg();
  if (!settings.screenFx || typeof settings.screenFx !== 'object') settings.screenFx = defaultScreenFxCfg();
  if (!Array.isArray(settings.screenFx.rules)) settings.screenFx.rules = [];
  if (settings.screenFx.enabled == null) settings.screenFx.enabled = true;
  if (settings.screenFx.allowInteract == null) settings.screenFx.allowInteract = true;
  const allowed = new Set(SFX_EFFECTS.map((e) => e.id));
  for (const r of settings.screenFx.rules) {
    if (!r) continue;
    if (!r.uid) r.uid = r.id || ('sfx' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6));
    if (!r.id) r.id = r.uid;
    if (!r.trigger) r.trigger = 'gift';
    if (r.effect && !allowed.has(String(r.effect))) r.effect = 'lightning';
  }
  return settings.screenFx;
}

function saveScreenFxPatch() {
  ensureScreenFxCfg();
  saveSettingsKeysPatch('screenFx');
}

function runScreenFxLocal(payload) {
  if (!IS_DESKTOP || !window.desktopAPI?.showScreenFx) {
    try { toast('Efectos pantalla solo en App PC (.exe)', 'warn'); } catch {}
    return;
  }
  const effect = String(payload?.effect || 'black').toLowerCase();
  let durationSec = Number(payload?.durationSec);
  if (!Number.isFinite(durationSec) || durationSec < 1) durationSec = 10;
  let sound = String(payload?.sound || '').trim();
  if (sound) sound = mediaUrl(sound);
  let soundVol = Number(payload?.soundVol);
  if (!Number.isFinite(soundVol)) soundVol = 80;
  const cfg = ensureScreenFxCfg();
  const allowInteract = payload?.allowInteract != null
    ? payload.allowInteract !== false
    : cfg.allowInteract !== false;
  const opts = { effect, durationSec, sound, soundVol, allowInteract };
  const tryShow = () => window.desktopAPI.showScreenFx(opts);
  Promise.resolve()
    .then(() => tryShow())
    .then((r) => {
      if (r && r.ok === false) throw new Error(r.error || 'fail');
      return r;
    })
    .catch(() => new Promise((res) => setTimeout(res, 280)).then(() => tryShow()))
    .catch(() => {
      try { toast('No se pudo abrir el efecto — reintenta', 'warn'); } catch {}
    });
}

function stopScreenFxLocal() {
  if (IS_DESKTOP && window.desktopAPI?.closeScreenFx) {
    window.desktopAPI.closeScreenFx().catch(() => {});
  }
  send({ action: 'stopScreenFx' });
}

function onScreenFxEvent(p) {
  runScreenFxLocal(p || {});
}

(function setupScreenFx() {
  const host = $('sfx-rules');
  if (!host) return;

  function uid() {
    return 'sfx' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  }

  function soundLabel(r) {
    if (!r?.sound) return 'Audio';
    try {
      const u = String(r.sound);
      const name = u.split('/').pop() || 'audio';
      return decodeURIComponent(name).slice(0, 22);
    } catch {
      return 'Audio';
    }
  }

  function renderRules() {
    const cfg = ensureScreenFxCfg();
    if ($('sfx-enabled')) $('sfx-enabled').checked = cfg.enabled !== false;
    if ($('sfx-allow-interact')) $('sfx-allow-interact').checked = cfg.allowInteract !== false;
    const warn = $('sfx-pc-warn');
    if (warn) warn.hidden = !!IS_DESKTOP;
    const conn = $('sfx-conn');
    if (conn) conn.innerHTML = IS_DESKTOP
      ? '<span class="cdot"></span> APP PC'
      : '<span class="cdot" style="background:#fbbf24"></span> SOLO .EXE';
    const rules = cfg.rules || [];
    if (!rules.length) {
      host.innerHTML = '<div class="empty" style="padding:18px;opacity:.75">Sin efectos. Pulsa <b>Agregar efecto</b>.</div>';
      return;
    }
    host.innerHTML = rules.map((r, idx) => {
      const effectOpts = SFX_EFFECTS.map((e) =>
        `<option value="${e.id}" ${r.effect === e.id ? 'selected' : ''}>${e.label}</option>`
      ).join('');
      if (!r.uid) r.uid = r.id || ('sfx' + idx);
      const trigBtn = (typeof mcTrigCardBtnHtml === 'function')
        ? mcTrigCardBtnHtml(r)
        : `<button type="button" class="mc-trig-icon-btn" data-uid="${esc(r.uid)}" title="Elegir disparador">🎁</button>`;
      const hasSound = !!r.sound;
      const vol = Math.max(0, Math.min(100, Number(r.soundVol) || 80));
      return `<div class="sfx-row" data-idx="${idx}" data-uid="${esc(r.uid)}">
        <label class="toggle sfx-tog" title="Activar regla">
          <input type="checkbox" class="sfx-on" ${r.on !== false ? 'checked' : ''}>
          <span class="track"></span>
        </label>
        ${trigBtn}
        <select class="sfx-effect">${effectOpts}</select>
        <label class="sfx-sec">Seg <input type="number" class="sfx-dur" min="1" max="120" value="${Math.max(1, Math.min(120, Number(r.durationSec) || 10))}"></label>
        <div class="sfx-audio">
          <button type="button" class="ovpro-btn sfx-sound-btn" title="Subir audio propio">${hasSound ? '🔊' : '🎵'} ${esc(soundLabel(r))}</button>
          ${hasSound ? '<button type="button" class="ovpro-btn sfx-sound-clear" title="Quitar audio">✕</button>' : ''}
          <label class="sfx-vol" title="Volumen">Vol <input type="range" class="sfx-vol-range" min="0" max="100" value="${vol}"></label>
        </div>
        <button type="button" class="ovpro-btn sfx-test" title="Probar">▶</button>
        <button type="button" class="ovpro-btn sfx-del" title="Quitar">✕</button>
      </div>`;
    }).join('');
  }
  window.refreshScreenFxUi = renderRules;

  function patchRule(idx, patch) {
    const cfg = ensureScreenFxCfg();
    if (!cfg.rules[idx]) return;
    Object.assign(cfg.rules[idx], patch);
    saveScreenFxPatch();
    renderRules();
  }

  async function uploadSoundForRule(idx, file) {
    if (!file) return;
    try {
      toast('Subiendo audio…', 'ok');
      const res = await fetch('/api/upload?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
      const data = await res.json();
      if (!data.url) throw new Error(data.error || 'error');
      patchRule(idx, { sound: data.url, soundName: file.name });
      try { toast('Audio listo', 'ok'); } catch {}
    } catch (err) {
      try { toast('No se pudo subir el audio', 'warn'); } catch {}
    }
  }

  host.addEventListener('click', (e) => {
    const row = e.target.closest?.('.sfx-row');
    if (!row) return;
    const idx = Number(row.dataset.idx);
    const cfg = ensureScreenFxCfg();
    const r = cfg.rules[idx];
    if (!r) return;
    if (e.target.closest?.('.mc-trig-icon-btn') || e.target.closest?.('.sfx-gift-btn')) {
      if (!r.uid) {
        r.uid = 'sfx' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
        r.id = r.uid;
        saveScreenFxPatch();
      }
      if (typeof openMcTrigPop === 'function') openMcTrigPop(r.uid, 'screenFx');
      return;
    }
    if (e.target.closest?.('.sfx-sound-btn')) {
      const inp = $('sfx-soundfile');
      if (!inp) return;
      inp.value = '';
      inp.onchange = async () => {
        const f = inp.files && inp.files[0];
        inp.onchange = null;
        await uploadSoundForRule(idx, f);
      };
      inp.click();
      return;
    }
    if (e.target.closest?.('.sfx-sound-clear')) {
      patchRule(idx, { sound: '', soundName: '' });
      return;
    }
    if (e.target.closest?.('.sfx-test')) {
      const payload = {
        effect: r.effect || 'black',
        durationSec: Math.max(1, Math.min(120, Number(r.durationSec) || 10)),
        giftId: r.giftId || '',
        giftName: r.giftName || '',
        sound: r.sound || '',
        soundVol: Math.max(0, Math.min(100, Number(r.soundVol) || 80)),
        allowInteract: ensureScreenFxCfg().allowInteract !== false,
      };
      runScreenFxLocal(payload);
      if (!IS_DESKTOP) send({ action: 'testScreenFx', ...payload });
      try { toast('Efecto pantalla · prueba', 'ok'); } catch {}
      return;
    }
    if (e.target.closest?.('.sfx-del')) {
      cfg.rules.splice(idx, 1);
      saveScreenFxPatch();
      renderRules();
    }
  });

  host.addEventListener('change', (e) => {
    const row = e.target.closest?.('.sfx-row');
    if (!row) return;
    const idx = Number(row.dataset.idx);
    const cfg = ensureScreenFxCfg();
    const r = cfg.rules[idx];
    if (!r) return;
    if (e.target.classList.contains('sfx-on')) {
      r.on = !!e.target.checked;
      saveScreenFxPatch();
      return;
    }
    if (e.target.classList.contains('sfx-effect')) {
      r.effect = e.target.value || 'black';
      saveScreenFxPatch();
      return;
    }
    if (e.target.classList.contains('sfx-dur')) {
      r.durationSec = Math.max(1, Math.min(120, parseInt(e.target.value, 10) || 10));
      saveScreenFxPatch();
      return;
    }
    if (e.target.classList.contains('sfx-vol-range')) {
      r.soundVol = Math.max(0, Math.min(100, parseInt(e.target.value, 10) || 80));
      saveScreenFxPatch();
    }
  });

  $('sfx-enabled')?.addEventListener('change', () => {
    const cfg = ensureScreenFxCfg();
    cfg.enabled = !!$('sfx-enabled').checked;
    saveScreenFxPatch();
  });
  $('sfx-allow-interact')?.addEventListener('change', () => {
    const cfg = ensureScreenFxCfg();
    cfg.allowInteract = !!$('sfx-allow-interact').checked;
    saveScreenFxPatch();
  });
  $('sfx-add')?.addEventListener('click', () => {
    const cfg = ensureScreenFxCfg();
    if (cfg.rules.length >= 30) {
      try { toast('Máximo 30 efectos', 'warn'); } catch {}
      return;
    }
    cfg.rules.push({
      id: uid(),
      uid: '',
      on: true,
      trigger: 'gift',
      giftId: '',
      giftName: '',
      giftImage: '',
      effect: 'black',
      durationSec: 10,
      sound: '',
      soundName: '',
      soundVol: 80,
    });
    const last = cfg.rules[cfg.rules.length - 1];
    last.uid = last.id;
    saveScreenFxPatch();
    renderRules();
  });
  $('sfx-stop')?.addEventListener('click', () => {
    stopScreenFxLocal();
    try { toast('Efecto pantalla detenido', 'ok'); } catch {}
  });

  renderRules();
})();

function applyWinsHotkeyByCombo(combo) {
  if (!combo) return false;
  let acted = false;
  WINS_COUNTERS.forEach((o) => {
    eachWinsHotkeyBinding(o.key, (b) => {
      if (!b.on || !b.key) return;
      if (String(b.key).toLowerCase() !== combo.toLowerCase()) return;
      o._adjust(b.delta);
      acted = true;
    });
  });
  return acted;
}

function applyWinsHotkeyAction({ counterKey, delta } = {}) {
  const o = WINS_COUNTERS.find((x) => x.key === counterKey);
  if (!o?._adjust || !delta) return;
  o._adjust(delta);
}

function syncWinsHotkeysToDesktop() {
  if (!IS_DESKTOP || !window.desktopAPI?.syncWinsHotkeys) return;
  const bindings = [];
  WINS_COUNTERS.forEach((o) => {
    eachWinsHotkeyBinding(o.key, (b) => {
      if (!b.on || !b.key) return;
      bindings.push({ counterKey: o.key, key: b.key, delta: b.delta });
    });
  });
  window.desktopAPI.syncWinsHotkeys(bindings).catch(() => {});
}

// Atajos locales (panel enfocado). En el .exe los mismos atajos también van globales.
document.addEventListener('keydown', (e) => {
  const t = e.target;
  if (t && (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.isContentEditable)) return;
  if (document.querySelector('.wc-hk-key.capturing')) return;
  const combo = formatCombo(e);
  if (!combo) return;
  if (applyWinsHotkeyByCombo(combo)) e.preventDefault();
});

if (window.desktopAPI?.onWinsHotkey) {
  window.desktopAPI.onWinsHotkey((act) => applyWinsHotkeyAction(act));
}

/* ---- Barra de meta (Hype) — config con selector de diseño (skin) ---- */
(function setupHypeOverlay() {
  const frame = () => $('hyp-preview');
  const toPrev = (msg) => frame()?.contentWindow?.postMessage({ kind: 'hype', ...msg }, '*');
  const MAP = {
    'hypcfg-skin': 'skin', 'hypcfg-kind': 'goalKind', 'hypcfg-title': 'title', 'hypcfg-meta': 'meta',
    'hypcfg-reach': 'whenReach', 'hypcfg-scale': 'scale', 'hypcfg-plike': 'pointsLike', 'hypcfg-pfollow': 'pointsFollow',
    'hypcfg-pshare': 'pointsShare', 'hypcfg-pgift': 'pointsGift', 'hypcfg-pmember': 'pointsMember',
    'hypcfg-font': 'font', 'hypcfg-titlecolor': 'titleColor', 'hypcfg-textcolor': 'textColor',
    'hypcfg-accent': 'accent', 'hypcfg-bar1': 'bar1', 'hypcfg-bar2': 'bar2', 'hypcfg-bar3': 'bar3',
  };
  const TYPES = { meta: 'int', scale: 'int', pointsLike: 'int', pointsFollow: 'int', pointsShare: 'int', pointsGift: 'int', pointsMember: 'int' };
  const build = () => readForm(MAP, TYPES);
  const HYPE_SKINS = [
    { id: 'default', name: 'Clásico' },
    { id: 'meta2', name: 'Meta 2' },
    { id: 'meta3', name: 'Meta 3' },
    { id: 'meta4', name: 'Meta 4' },
    { id: 'meta5', name: 'Meta 5' },
    { id: 'meta6', name: 'Meta 6' },
    { id: 'meta7', name: 'Meta 7' },
    { id: 'meta8', name: 'Meta 8' },
    { id: 'meta9', name: 'Meta 9' },
    { id: 'meta10', name: 'Meta 10' },
    { id: 'meta11', name: 'Meta 11' },
    { id: 'meta12', name: 'Meta 12' },
    { id: 'meta13', name: 'Meta 13' },
    { id: 'meta14', name: 'Meta 14' },
  ];
  const hypSkinIndex = (id) => {
    const i = HYPE_SKINS.findIndex((s) => s.id === id);
    return i < 0 ? 0 : i;
  };
  const modalOpen = () => {
    const m = $('hypConfigModal');
    return !!(m && !m.classList.contains('hidden'));
  };
  const activeCfg = () => {
    if (modalOpen()) return { ...(settings?.hypeBar || {}), ...build() };
    return { ...(settings?.hypeBar || {}) };
  };

  function refreshSkinChrome(skinId) {
    const skin = HYPE_SKINS[hypSkinIndex(skinId)] || HYPE_SKINS[0];
    if ($('hyp-skin-name')) $('hyp-skin-name').textContent = skin.name;
    if ($('hyp-skin-idx')) $('hyp-skin-idx').textContent = `${hypSkinIndex(skin.id) + 1} / ${HYPE_SKINS.length}`;
    if ($('hypcfg-skin')) $('hypcfg-skin').value = skin.id;
  }

  let hypSkinSaveTimer = null;
  let hypSkinSwapUntil = 0;
  let hypSkinToken = 0;

  function applySkin(skin) {
    const f = frame();
    const skinId = skin || 'default';
    const skinQ = skinId !== 'default' ? '&skin=' + skinId : '';
    const want = '/meta.html?embed=1' + skinQ;
    refreshSkinChrome(skinId);
    const path = '/meta.html' + (skinId !== 'default' ? '?skin=' + skinId : '');
    const code = document.querySelector('#hyp-card .ov-url');
    if (code) { code.dataset.path = path; code.textContent = roomUrl(path); }

    if (!f) return;
    const cur = f.getAttribute('src') || '';
    if (cur === want) {
      toPrev({ type: 'config', config: { ...activeCfg(), skin: skinId } });
      return;
    }

    // Cambio de diseño: oculta el iframe viejo y no empujes config al documento anterior
    hypSkinToken += 1;
    const token = hypSkinToken;
    hypSkinSwapUntil = Date.now() + 900;
    f.classList.add('is-skin-swap');
    f.dataset.src = want;
    f.dataset.embedReady = '';
    f.onload = () => {
      if (token !== hypSkinToken) return;
      f.dataset.embedReady = '1';
      f.classList.remove('is-skin-swap');
      toPrev({ type: 'config', config: { ...activeCfg(), skin: skinId } });
    };
    f.src = want;
  }
  function pushPreview(cfg) { toPrev({ type: 'config', config: cfg || activeCfg() }); }

  function stepSkin(dir) {
    if (!settings.hypeBar) settings.hypeBar = {};
    const cur = hypSkinIndex(settings.hypeBar.skin || 'default');
    const next = HYPE_SKINS[(cur + dir + HYPE_SKINS.length) % HYPE_SKINS.length];
    settings.hypeBar.skin = next.id;
    if (modalOpen() && $('hypcfg-skin')) $('hypcfg-skin').value = next.id;
    applySkin(next.id);
    clearTimeout(hypSkinSaveTimer);
    hypSkinSaveTimer = setTimeout(() => {
      try { saveSettingsKeysPatch('hypeBar'); } catch { try { saveSettings(); } catch {} }
    }, 280);
  }

  if ($('hyp-test')) $('hyp-test').onclick = async () => {
    await ensureEmbedLoaded(frame());
    toPrev({ type: 'test' });
    send({ action: 'testHype' });
  };
  if ($('hyp-reset')) $('hyp-reset').onclick = async () => {
    await ensureEmbedLoaded(frame());
    toPrev({ type: 'reset' });
    send({ action: 'resetHype' });
  };
  if ($('hyp-config')) $('hyp-config').onclick = async () => {
    await ensureEmbedLoaded(frame());
    const styleDefaults = {
      font: 'inter', titleColor: '#ffffff', textColor: '#f8fafc',
      accent: '#38bdf8', bar1: '#ff0f8f', bar2: '#38bdf8', bar3: '#c084fc',
    };
    fillForm(MAP, { ...styleDefaults, ...(settings?.hypeBar || {}) });
    applySkin((settings?.hypeBar || {}).skin || 'default');
    pushPreview(build());
    $('hypConfigModal').classList.remove('hidden');
  };
  const close = () => $('hypConfigModal')?.classList.add('hidden');
  if ($('hypcfg-close')) $('hypcfg-close').onclick = close;
  if ($('hypConfigModal')) $('hypConfigModal').addEventListener('click', (e) => { if (e.target.id === 'hypConfigModal') close(); });
  Object.keys(MAP).forEach((id) => {
    const el = $(id);
    if (!el) return;
    el.oninput = () => { const c = build(); if (id === 'hypcfg-skin') applySkin(c.skin); else pushPreview(c); };
    el.onchange = el.oninput;
  });
  if ($('hypcfg-save')) $('hypcfg-save').onclick = () => { settings.hypeBar = build(); saveSettings(); applySkin(settings.hypeBar.skin); pushPreview(settings.hypeBar); close(); };

  if ($('hyp-skin-prev')) $('hyp-skin-prev').onclick = () => stepSkin(-1);
  if ($('hyp-skin-next')) $('hyp-skin-next').onclick = () => stepSkin(1);

  window.pushHypePreview = () => {
    const skin = (settings?.hypeBar || {}).skin || 'default';
    // Durante el cambio con flechas, no re-disparar reload/config (evita parpadeo de otro diseño)
    if (Date.now() < hypSkinSwapUntil) {
      refreshSkinChrome(skin);
      return;
    }
    applySkin(skin);
  };
  try { refreshSkinChrome((settings?.hypeBar || {}).skin || 'default'); } catch {}
})();

