function edgeVoiceLabel(v) {
  const region = TTS_EDGE_REGIONS[v.locale] || v.locale;
  const sex = v.gender === 'm' ? 'hombre' : 'mujer';
  return `${region} — ${v.name} (${sex})`;
}
function isEdgeTtsVoiceId(v) {
  return TTS_EDGE_VOICES.some((x) => x.id === String(v || '').trim());
}
function isTtsLangEdgeSpanish(lang) {
  const l = String(lang || '').trim().toLowerCase();
  return !!l && Object.keys(TTS_EDGE_REGIONS).some((k) => k.toLowerCase() === l);
}
/** Compat: Colombia sigue funcionando con el flag viejo. */
function isTtsLangColombia(lang) {
  return String(lang || '').toLowerCase().startsWith('es-co');
}
function edgeVoicesForLocale(lang) {
  const l = String(lang || '').trim().toLowerCase();
  return TTS_EDGE_VOICES.filter((v) => v.locale.toLowerCase() === l)
    .map((v) => ({ ...v, label: edgeVoiceLabel(v) }));
}
function defaultEdgeVoiceIdForLocale(lang) {
  const list = edgeVoicesForLocale(lang);
  if (!list.length) return TTS_EDGE_VOICES[0]?.id || '';
  const female = list.find((v) => v.gender === 'f');
  return (female || list[0]).id;
}
function edgeLocaleLabel(code) {
  const key = Object.keys(TTS_EDGE_REGIONS).find((k) => k.toLowerCase() === String(code || '').toLowerCase());
  if (!key) return langLabel(code);
  return `Español (${TTS_EDGE_REGIONS[key]}) · Edge`;
}
function langLabel(code) {
  if (isTtsLangEdgeSpanish(code)) return edgeLocaleLabel(code);
  const base = String(code || '').split('-')[0].toLowerCase();
  const name = LANG_NAMES[base] || base.toUpperCase();
  return String(code || '').includes('-') ? `${name} (${code})` : name;
}

function loadVoices() {
  if (!TTS_HAS) return;
  ttsVoices = speechSynthesis.getVoices() || [];
  const t = settings?.tts || {};
  // Idiomas del SO + locales Edge español (siempre, aunque el SO no los traiga)
  const langSel = $('tts-lang');
  if (langSel) {
    const seen = new Map();
    ttsVoices.forEach((v) => { if (v.lang && !seen.has(v.lang)) seen.set(v.lang, true); });
    Object.keys(TTS_EDGE_REGIONS).forEach((loc) => {
      if (!seen.has(loc)) seen.set(loc, true);
    });
    const langs = Array.from(seen.keys()).sort((a, b) => {
      const ae = isTtsLangEdgeSpanish(a) ? 0 : 1;
      const be = isTtsLangEdgeSpanish(b) ? 0 : 1;
      if (ae !== be) return ae - be;
      return a.localeCompare(b, 'es');
    });
    const cur = t.lang || 'es';
    langSel.innerHTML = '<option value="">Todos los idiomas</option>' +
      langs.map((l) => {
        const on = l === cur || (cur && (l.toLowerCase() === String(cur).toLowerCase() || (!isTtsLangEdgeSpanish(cur) && cur.length <= 2 && l.toLowerCase().startsWith(String(cur).toLowerCase() + '-'))));
        return `<option value="${esc(l)}" ${on ? 'selected' : ''}>${esc(langLabel(l))}</option>`;
      }).join('');
    // Forzar valor exacto de locale Edge (evitar que startsWith('es') gane).
    if (isTtsLangEdgeSpanish(cur)) {
      const exact = Object.keys(TTS_EDGE_REGIONS).find((k) => k.toLowerCase() === String(cur).toLowerCase());
      if (exact) langSel.value = exact;
    }
  }
  fillVoiceOptions();
  fillTtsUvLangOptions();
  fillTtsUvVoiceOptions();
}
function fillVoiceOptions() {
  const sel = $('tts-voice');
  if (!sel) return;
  const t = settings?.tts || {};
  const langFilter = (t.lang || '').toLowerCase();
  if (isTtsLangEdgeSpanish(langFilter)) {
    const voices = edgeVoicesForLocale(langFilter);
    const cur = t.voice || defaultEdgeVoiceIdForLocale(langFilter);
    sel.innerHTML = voices.map((v) =>
      `<option value="${esc(v.id)}" ${v.id === cur ? 'selected' : ''}>${esc(v.label)}</option>`
    ).join('');
    if (!voices.some((v) => v.id === t.voice) && settings?.tts) {
      const def = defaultEdgeVoiceIdForLocale(langFilter);
      settings.tts.voice = def;
      sel.value = def;
    }
    return;
  }
  const list = ttsVoices.filter((v) => !langFilter || (v.lang || '').toLowerCase().startsWith(langFilter));
  const voices = list.length ? list : ttsVoices;
  sel.innerHTML = '<option value="">(voz por defecto)</option>' +
    voices.map((v) => `<option value="${esc(v.name)}" ${v.name === t.voice ? 'selected' : ''}>${esc(v.name)} — ${esc(v.lang)}</option>`).join('');
}

let ttsUvEditingId = null;

function applyTtsUI(t) {
  const set = (id, v) => { const el = $(id); if (el) el.checked = !!v; };
  const val = (id, v) => { const el = $(id); if (el) el.value = v; };
  set('tts-enabled', t.enabled);
  set('tts-readname', t.readName);
  set('tts-name-emojis', t.nameEmojis !== false);
  syncTtsNameEmojisUI();
  val('tts-tiktok-voice', t.tiktokVoice || '');
  // Casilla «Leer en español»: marcada salvo que se haya desactivado a propósito.
  set('tts-tiktok-translate', t.tiktokTranslateEs !== true);
  // ElevenLabs retirado del panel: no usarlo aunque quede en ajustes viejos.
  if (t.elevenlabs && typeof t.elevenlabs === 'object') t.elevenlabs.enabled = false;
  const piper = (t.piper && typeof t.piper === 'object') ? t.piper : {};
  set('tts-piper-enabled', !!piper.enabled);
  val('tts-piper-voice', piper.voiceId || 'es_ES-davefx-medium');
  set('tts-piper-translate', piper.translate !== false);
  try { ttsPiperProbe(); } catch { /* ignore */ }
  try { syncTtsPiperTranslateUI(); } catch { /* ignore */ }
  if (!ttsSliderDrag && Date.now() - lastTtsSliderEditAt > 1500) {
    val('tts-rate', t.rate ?? 1.2); const rv = $('tts-rate-val'); if (rv) rv.textContent = (+(t.rate ?? 1.2)).toFixed(1);
    val('tts-pitch', t.pitch ?? 1); const pv = $('tts-pitch-val'); if (pv) pv.textContent = (+(t.pitch ?? 1)).toFixed(1);
    val('tts-vol', t.volume ?? 1); const vv = $('tts-vol-val'); if (vv) vv.textContent = Math.round((t.volume ?? 1) * 100);
  }
  // Si quedó el preset agresivo del fix anterior (4 / 10 s), volver a “leer todos”.
  if (Number(t.maxQueue) === 4 && Number(t.maxLagSec) === 10) {
    t.maxQueue = 50;
    t.maxLagSec = 0;
  }
  val('tts-max-queue', t.maxQueue != null ? t.maxQueue : 50);
  val('tts-max-lag', t.maxLagSec != null ? t.maxLagSec : 0);
  loadVoices();
  const uvFormBusy = ttsUvEditingId
    || ['tts-uv-engine', 'tts-uv-lang', 'tts-uv-voice', 'tts-uv-user-manual'].includes(document.activeElement?.id);
  if (!uvFormBusy) {
    fillTtsUvLangOptions();
    fillTtsUvVoiceOptions();
  }
  // permitidos
  if (t.allowGiftPass && t.allowWhitelist) t.allowWhitelist = false;
  const exclusiveWho = !!(t.allowWhitelist || t.allowGiftPass);
  set('tts-allow-all', t.allowAll !== false && !exclusiveWho);
  set('tts-allow-followers', t.allowFollowers && !exclusiveWho);
  set('tts-allow-subs', t.allowSubs && !exclusiveWho);
  set('tts-allow-mods', t.allowMods && !exclusiveWho);
  set('tts-allow-team', t.allowTeam && !exclusiveWho);
  set('tts-allow-whitelist', !!t.allowWhitelist && !t.allowGiftPass);
  renderTtsWhitelist();
  set('tts-allow-giftpass', !!t.allowGiftPass);
  ttsEnsureGiftPassCfg();
  val('tts-gp-minutes', Math.max(1, Number(t.giftPass?.minutes) || 5));
  if ($('tts-gp-giftid')) $('tts-gp-giftid').value = t.giftPass?.giftId || '';
  if ($('tts-gp-giftname')) $('tts-gp-giftname').value = t.giftPass?.giftName || '';
  if ($('tts-gp-giftimg')) $('tts-gp-giftimg').value = t.giftPass?.giftImage || '';
  paintTtsGiftPassBtn();
  set('tts-use-blacklist', !!t.useBlacklist);
  renderTtsBlacklist();
  val('tts-min-level', t.minMemberLevel ?? 0);
  // Compatibilidad: si no existe el flag, se considera activo cuando ya había un nivel > 0.
  const requireLvl = !exclusiveWho && (t.requireMinLevel ?? (Number(t.minMemberLevel || 0) > 0));
  set('tts-require-level', requireLvl);
  syncTtsMinLevelUI();
  syncTtsAllowUI();
  syncTtsGiftPassUI();
  // trigger
  const trig = t.trigger || 'all';
  document.querySelectorAll('input[name="tts-trigger"]').forEach((r) => { r.checked = r.value === trig; });
  val('tts-command', t.command || '!tts');
  // monetización
  document.querySelectorAll('input[name="tts-charge"]').forEach((r) => { r.checked = r.value === (t.charge ? '1' : '0'); });
  val('tts-cost', t.cost ?? 5);
  // moderación
  set('tts-block-spam', t.blockSpam);
  set('tts-block-alpha', t.blockAlpha);
  set('tts-block-prof', t.blockProfanity);
  set('tts-block-susp', t.blockSuspicious);
  set('tts-block-replies', t.blockReplies);
  set('tts-strip-emojis', t.stripEmojis);
  val('tts-blocked-words', t.blockedWords || '');
  // seguidores
  set('tts-read-follow', t.readFollow);
  val('tts-follow-msg', t.followMsg || 'Hola {user}, gracias por seguirme');
  // eventos
  set('tts-read-share', t.readShare);
  set('tts-read-taptap', t.readTaptap);
  val('tts-taptap-min', t.taptapMin ?? 100);
  set('tts-read-gifts', t.readGifts);
  applyTtsCaracolaUI();
  applyTtsPasarUI();
  renderTtsCommands();
  renderTtsUserVoices();
  refreshTtsUvUserSelect();
  updateTtsSummary();
}

const TTS_CARACOLA_ANSWERS = [
  'Sí', 'No', 'Tal vez', 'Pregunta otra vez',
];
function ttsCaracolaDefaults() {
  const def = window.TTS_CARACOLA_DEFAULT_ANSWERS;
  if (Array.isArray(def) && def.length) return def.slice();
  return TTS_CARACOLA_ANSWERS.slice();
}
function ttsParseCaracolaAnswers(raw) {
  return String(raw || '')
    .split(/\r?\n/)
    .map((s) => s.trim())
    .filter(Boolean)
    .slice(0, 250)
    .map((s) => s.slice(0, 180));
}
function ttsCaracolaAnswerList() {
  const raw = settings?.tts?.caracola?.answers;
  const list = Array.isArray(raw) ? raw.map((s) => String(s || '').trim()).filter(Boolean) : [];
  return list.length ? list : ttsCaracolaDefaults();
}
function ttsPickCaracolaAnswer() {
  const list = ttsCaracolaAnswerList();
  return list[Math.floor(Math.random() * list.length)] || 'Pregunta otra vez';
}
function ttsNormFunCmd(raw, fallback = '!caracola') {
  let t = String(raw || '').trim();
  if (!t) return fallback;
  if (!/^[!./]/.test(t)) t = '!' + t;
  return t;
}
function ttsEnsureCaracola() {
  if (!settings) return { enabled: false, command: '!caracola', cooldownSec: 5, answers: ttsCaracolaDefaults() };
  if (!settings.tts) settings.tts = {};
  if (!settings.tts.caracola || typeof settings.tts.caracola !== 'object') {
    settings.tts.caracola = { enabled: false, command: '!caracola', cooldownSec: 5, answers: ttsCaracolaDefaults() };
  }
  const c = settings.tts.caracola;
  if (!Array.isArray(c.answers) || !c.answers.length) c.answers = ttsCaracolaDefaults();
  return c;
}
function ttsCommentIsCaracola(comment) {
  const c = settings?.tts?.caracola;
  if (!c || !c.enabled) return false;
  const cmd = ttsNormFunCmd(c.command || '!caracola').toLowerCase();
  const first = String(comment || '').trim().toLowerCase().split(/\s+/)[0] || '';
  return first === cmd;
}
function syncTtsCaracolaCard() {
  const card = $('tts-caracola-card');
  const on = $('tts-caracola-on');
  if (card) card.classList.toggle('is-on', !!on?.checked);
}
function applyTtsCaracolaUI() {
  const c = ttsEnsureCaracola();
  const on = $('tts-caracola-on');
  if (on && on !== document.activeElement) on.checked = !!c.enabled;
  const cmd = $('tts-caracola-cmd');
  if (cmd && cmd !== document.activeElement) cmd.value = ttsNormFunCmd(c.command || '!caracola');
  const cd = $('tts-caracola-cd');
  if (cd && cd !== document.activeElement) cd.value = Math.max(1, Math.min(60, Number(c.cooldownSec) || 5));
  const ta = $('tts-caracola-answers');
  if (ta && ta !== document.activeElement) ta.value = ttsCaracolaAnswerList().join('\n');
  syncTtsCaracolaCard();
}
function ttsEnsurePasar() {
  if (!settings) return { enabled: false, command: '!pasar', cooldownSec: 8, minAmount: 1, maxAmount: 10000 };
  if (!settings.tts) settings.tts = {};
  if (!settings.tts.pasar || typeof settings.tts.pasar !== 'object') {
    settings.tts.pasar = { enabled: false, command: '!pasar', cooldownSec: 8, minAmount: 1, maxAmount: 10000 };
  }
  return settings.tts.pasar;
}
function ttsCommentIsPasar(comment) {
  const c = settings?.tts?.pasar;
  if (!c || !c.enabled) return false;
  const cmd = ttsNormFunCmd(c.command || '!pasar', '!pasar').toLowerCase();
  const first = String(comment || '').trim().toLowerCase().split(/\s+/)[0] || '';
  return first === cmd;
}
function syncTtsPasarCard() {
  const card = $('tts-pasar-card');
  const on = $('tts-pasar-on');
  if (card) card.classList.toggle('is-on', !!on?.checked);
}
function applyTtsPasarUI() {
  const c = ttsEnsurePasar();
  const on = $('tts-pasar-on');
  if (on && on !== document.activeElement) on.checked = !!c.enabled;
  const cmd = $('tts-pasar-cmd');
  if (cmd && cmd !== document.activeElement) cmd.value = ttsNormFunCmd(c.command || '!pasar', '!pasar');
  const cd = $('tts-pasar-cd');
  if (cd && cd !== document.activeElement) cd.value = Math.max(1, Math.min(60, Number(c.cooldownSec) || 8));
  const mn = $('tts-pasar-min');
  if (mn && mn !== document.activeElement) mn.value = Math.max(1, Number(c.minAmount) || 1);
  const mx = $('tts-pasar-max');
  if (mx && mx !== document.activeElement) mx.value = Math.max(1, Number(c.maxAmount) || 10000);
  syncTtsPasarCard();
}

/* ---- Comandos personalizados (respuestas automáticas por voz) ---- */
function renderTtsCommands() {
  const box = $('tts-cmd-list');
  if (!box) return;
  const cmds = (settings?.tts?.commands) || [];
  if (!cmds.length) {
    box.innerHTML = '<div class="cmd-empty">Aún no hay comandos. Añade uno abajo.</div>';
    return;
  }
  box.innerHTML = cmds.map((c) => `
    <div class="cmd-item ${c.enabled === false ? 'off' : ''}" data-id="${esc(c.id)}">
      <label class="cmd-toggle"><input type="checkbox" ${c.enabled === false ? '' : 'checked'} data-act="toggle"> </label>
      <span class="cmd-trigger">${esc(c.command)}</span>
      <span class="cmd-arrow">→</span>
      <span class="cmd-response" title="${esc(c.response)}">${esc(c.response)}</span>
      <button class="cmd-del" data-act="del" title="Eliminar">✕</button>
    </div>`).join('');
  box.querySelectorAll('.cmd-item').forEach((row) => {
    const id = row.dataset.id;
    row.querySelector('[data-act="toggle"]').onchange = (e) => {
      const c = (settings.tts.commands || []).find((x) => String(x.id) === String(id));
      if (c) { c.enabled = e.target.checked; saveTtsCommands(); }
    };
    row.querySelector('[data-act="del"]').onclick = async () => {
      const ok = await askConfirm({ title: 'Eliminar comando', message: '¿Seguro que quieres borrar este comando?', confirmText: 'Eliminar' });
      if (!ok) return;
      settings.tts.commands = (settings.tts.commands || []).filter((x) => String(x.id) !== String(id));
      saveTtsCommands();
      renderTtsCommands();
    };
  });
}

function saveTtsCommands() {
  if (!settings.tts) settings.tts = {};
  saveSettings(); // envía settings completo (incluye tts.commands)
}

function syncTtsServerVoicePlanUi() {
  const tkRow = document.getElementById('tts-tiktok-voices-wrap');
  if (tkRow) tkRow.style.display = '';
  const sel = document.getElementById('tts-tiktok-voice');
  if (!sel) return;
  const allowTk = capFeature('tts_tiktok');
  sel.querySelectorAll('optgroup').forEach((og) => {
    const label = String(og.label || '').toLowerCase();
    const isEdge = label.includes('edge') || label.includes('colombia');
    og.hidden = !isEdge && !allowTk;
    og.querySelectorAll('option').forEach((opt) => { opt.disabled = !isEdge && !allowTk; });
  });
  if (!allowTk && sel.value && !isEdgeTtsVoiceId(sel.value)) {
    sel.value = '';
    if (settings?.tts) settings.tts.tiktokVoice = '';
  }
  const eng = document.getElementById('tts-uv-engine');
  if (eng) {
    eng.querySelectorAll('option[value="tiktok"], option[value="disney"]').forEach((opt) => {
      opt.hidden = !allowTk;
      opt.disabled = !allowTk;
    });
    if (!allowTk && (eng.value === 'tiktok' || eng.value === 'disney')) {
      eng.value = 'edge';
      try { fillTtsUvLangOptions(); fillTtsUvVoiceOptions(); } catch {}
    }
  }
}

