function ttsPiperFillSelect(sel, voices, selectedId) {
  if (!sel || !Array.isArray(voices) || !voices.length) return;
  const cur = selectedId || sel.value || voices[0].id;
  const groups = [];
  const map = new Map();
  for (const v of voices) {
    const g = v.group || 'Otras';
    if (!map.has(g)) { map.set(g, []); groups.push(g); }
    map.get(g).push(v);
  }
  sel.innerHTML = groups.map((g) => {
    const opts = map.get(g).map((v) => {
      const mark = v.ready ? ' ✓' : '';
      return `<option value="${esc(v.id)}" ${v.id === cur ? 'selected' : ''}>${esc(v.label)}${mark}</option>`;
    }).join('');
    return `<optgroup label="${esc(g)}">${opts}</optgroup>`;
  }).join('');
  if (voices.some((v) => v.id === cur)) sel.value = cur;
}

function ttsTrackChatUser(p) {
  const uid = String(p?.uniqueId || '').trim();
  if (!uid) return;
  ttsChatUsers.set(uid.toLowerCase(), { uniqueId: uid, nickname: p.nickname || uid });
  refreshTtsUvUserSelect();
  refreshTtsWlDrop();
  refreshTtsBlDrop();
}

function ttsUvNormId(id) {
  return String(id || '').trim().toLowerCase().replace(/^@/, '');
}

function getTikTokVoiceCatalog() {
  const sel = $('tts-tiktok-voice');
  if (!sel) return [];
  const out = [];
  sel.querySelectorAll('option[value]').forEach((opt) => {
    const id = String(opt.value || '').trim();
    if (!id || isEdgeTtsVoiceId(id)) return;
    out.push({ id, label: (opt.textContent || id).trim() });
  });
  return out;
}

function getDisneyVoiceCatalog() {
  const sel = $('tts-tiktok-voice');
  if (!sel) return [];
  const out = [];
  sel.querySelectorAll('optgroup').forEach((og) => {
    const label = String(og.label || '').toLowerCase();
    if (!label.includes('disney') && !label.includes('personaje')) return;
    og.querySelectorAll('option[value]').forEach((opt) => {
      const id = String(opt.value || '').trim();
      if (id) out.push({ id, label: (opt.textContent || id).trim() });
    });
  });
  return out;
}

function getEdgeVoiceCatalog() {
  return TTS_EDGE_VOICES.map((v) => ({ id: v.id, label: edgeVoiceLabel(v), locale: v.locale }));
}

function ttsVoiceLangFromId(voiceId) {
  const v = String(voiceId || '').toLowerCase();
  if (!v) return 'en';
  if (v.startsWith('es_') || v.startsWith('es-')) return 'es';
  if (v.startsWith('fr_')) return 'fr';
  if (v.startsWith('de_')) return 'de';
  if (v.startsWith('it_')) return 'it';
  if (v.startsWith('id_')) return 'id';
  if (v.startsWith('jp_')) return 'jp';
  if (v.startsWith('kr_')) return 'kr';
  if (v.startsWith('pt_') || v.startsWith('br_')) return 'pt';
  return 'en';
}

function ttsVoiceLabel(engine, voice, lang) {
  if (!voice) return '—';
  if (engine === 'elevenlabs') {
    const hit = (typeof ttsElVoicesCache !== 'undefined' ? ttsElVoicesCache : [])
      .find((x) => String(x.id) === String(voice));
    return hit ? hit.name : voice;
  }
  if (engine === 'piper') {
    const hit = TTS_PIPER_VOICES.find((x) => x.id === voice);
    return hit ? hit.label : voice;
  }
  if (engine === 'edge') {
    const hit = getEdgeVoiceCatalog().find((x) => x.id === voice);
    return hit ? hit.label : voice;
  }
  if (engine === 'tiktok' || engine === 'disney') {
    const catalog = engine === 'disney' ? getDisneyVoiceCatalog() : getTikTokVoiceCatalog();
    const hit = catalog.find((x) => x.id === voice) || getTikTokVoiceCatalog().find((x) => x.id === voice);
    return hit ? hit.label : voice;
  }
  const hit = ttsVoices.find((v) => v.name === voice);
  return hit ? `${hit.name}` : voice;
}

function ttsEngineLabel(engine) {
  if (engine === 'disney') return 'Disney';
  if (engine === 'edge') return 'Edge (español)';
  if (engine === 'elevenlabs') return 'ElevenLabs';
  if (engine === 'piper') return 'Piper (gratis)';
  return engine === 'tiktok' ? 'TikTok (Server)' : 'Sistema';
}

function ttsUvLangLabel(code) {
  const c = String(code || '').toLowerCase();
  if (c === 'multi') return 'Multilingüe';
  if (isTtsLangEdgeSpanish(c)) return edgeLocaleLabel(c).replace(' · Edge', '');
  const hit = (TTS_UV_LANGS.tiktok || []).find((x) => x.code === c)
    || (TTS_UV_LANGS.disney || []).find((x) => x.code === c)
    || (TTS_UV_LANGS.edge || []).find((x) => String(x.code).toLowerCase() === c);
  if (hit) return hit.label;
  return langLabel(c);
}

function syncTtsUvDisneyTranslateUI() {
  const disney = ($('tts-uv-engine')?.value || '') === 'disney';
  const wrap = $('tts-uv-disney-translate-wrap');
  const hint = $('tts-uv-disney-translate-hint');
  if (wrap) wrap.style.display = disney ? '' : 'none';
  if (hint) hint.style.display = disney ? '' : 'none';
}

function ttsUvMatchesIds(x, ids) {
  if (!x || !ids?.length) return false;
  const a = ttsUvNormId(x.userId);
  const b = ttsUvNormId(x.nickname);
  const a2 = a.replace(/[^\w.]+/g, '');
  const b2 = b.replace(/[^\w.]+/g, '');
  return ids.includes(a) || ids.includes(a2) || (b && ids.includes(b)) || (b2 && ids.includes(b2));
}

/** Todas las voces asignadas a un usuario (puede haber varias → aleatorio al hablar). */
function ttsFindUserVoices(userId, nickname) {
  const raw = [userId, nickname].map((x) => ttsUvNormId(x)).filter(Boolean);
  const extra = raw.map((id) => id.replace(/[^\w.]+/g, '')).filter(Boolean);
  const ids = [...new Set([...raw, ...extra])];
  if (!ids.length) return [];
  const list = settings?.tts?.userVoices || [];
  const hits = list.filter((x) => ttsUvMatchesIds(x, ids));
  if (hits.length) return hits;
  try {
    for (const u of ttsChatUsers.values()) {
      const uid = ttsUvNormId(u.uniqueId);
      const nick = ttsUvNormId(u.nickname);
      if (!ids.includes(uid) && !ids.includes(nick)) continue;
      const byUid = list.filter((x) => ttsUvNormId(x.userId) === uid);
      if (byUid.length) return byUid;
    }
  } catch {}
  return [];
}

/** Una voz del usuario. Si tiene varias, elige al azar (misma API que antes). */
function ttsFindUserVoice(userId, nickname) {
  const all = ttsFindUserVoices(userId, nickname);
  if (!all.length) return null;
  if (all.length === 1) return all[0];
  return all[Math.floor(Math.random() * all.length)] || all[0];
}

function refreshTtsUvUserSelect() {
  const sel = $('tts-uv-user-sel');
  if (!sel) return;
  const counts = new Map();
  for (const x of (settings?.tts?.userVoices || [])) {
    const k = ttsUvNormId(x.userId);
    if (!k) continue;
    counts.set(k, (counts.get(k) || 0) + 1);
  }
  const users = Array.from(ttsChatUsers.values());
  users.sort((a, b) => (a.nickname || '').localeCompare(b.nickname || '', 'es'));
  if (!users.length) {
    sel.innerHTML = '<option value="">— Sin usuarios en el chat —</option>';
    return;
  }
  sel.innerHTML = '<option value="">— Elegir usuario —</option>' +
    users.map((u) => {
      const n = counts.get(ttsUvNormId(u.uniqueId)) || 0;
      const tag = n > 0 ? ` · ${n} voz${n === 1 ? '' : 'es'}` : '';
      return `<option value="${esc(u.uniqueId)}">${esc(u.nickname || u.uniqueId)} (@${esc(u.uniqueId)})${esc(tag)}</option>`;
    }).join('');
}

function fillTtsUvLangOptions() {
  const sel = $('tts-uv-lang');
  const engine = $('tts-uv-engine')?.value || 'tiktok';
  if (!sel) return;
  syncTtsUvDisneyTranslateUI();
  if (engine === 'elevenlabs') {
    sel.innerHTML = '<option value="multi">Multilingüe (ElevenLabs)</option>';
    sel.value = 'multi';
    return;
  }
  if (engine === 'piper') {
    sel.innerHTML = '<option value="es">Español</option>';
    sel.value = 'es';
    return;
  }
  if (engine === 'disney') {
    sel.innerHTML = TTS_UV_LANGS.disney.map((l) => `<option value="${esc(l.code)}">${esc(l.label)}</option>`).join('');
    sel.value = 'en';
    return;
  }
  if (engine === 'edge') {
    const langs = TTS_UV_LANGS.edge;
    // Compat: UV antiguas guardaban `es` para Colombia
    let cur = sel.value || 'es-CO';
    if (String(cur).toLowerCase() === 'es') cur = 'es-CO';
    sel.innerHTML = langs.map((l) => `<option value="${esc(l.code)}" ${l.code === cur ? 'selected' : ''}>${esc(l.label)}</option>`).join('');
    if (!langs.some((l) => l.code === cur || l.code.toLowerCase() === String(cur).toLowerCase())) sel.value = 'es-CO';
    else sel.value = cur;
    return;
  }
  if (engine === 'tiktok') {
    const langs = TTS_UV_LANGS.tiktok;
    const cur = sel.value || 'es';
    sel.innerHTML = langs.map((l) => `<option value="${esc(l.code)}" ${l.code === cur ? 'selected' : ''}>${esc(l.label)}</option>`).join('');
    if (!langs.some((l) => l.code === cur)) sel.value = 'es';
    return;
  }
  const seen = new Map();
  ttsVoices.forEach((v) => {
    const code = (v.lang || '').split('-')[0].toLowerCase();
    if (code && !seen.has(code)) seen.set(code, v.lang);
  });
  const langs = Array.from(seen.entries()).sort((a, b) => a[0].localeCompare(b[0], 'es'));
  const cur = (sel.value || 'es').split('-')[0].toLowerCase();
  sel.innerHTML = langs.length
    ? langs.map(([code, full]) => `<option value="${esc(full)}" ${code === cur ? 'selected' : ''}>${esc(langLabel(full))}</option>`).join('')
    : '<option value="es">Español</option>';
}

function fillTtsUvVoiceOptions() {
  const sel = $('tts-uv-voice');
  const engine = $('tts-uv-engine')?.value || 'tiktok';
  const langSel = $('tts-uv-lang');
  if (!sel || !langSel) return;
  const lang = String(langSel.value || 'es').toLowerCase();
  const langBase = lang.split('-')[0];

  if (engine === 'elevenlabs') {
    const list = (typeof ttsElVoicesCache !== 'undefined' && ttsElVoicesCache.length)
      ? ttsElVoicesCache
      : [];
    const cur = sel.value;
    if (!list.length) {
      const savedId = String(settings?.tts?.elevenlabs?.voiceId || '').trim();
      const savedName = String(settings?.tts?.elevenlabs?.voiceName || savedId).trim();
      if (savedId) {
        sel.innerHTML = `<option value="${esc(savedId)}" selected>${esc(savedName || savedId)}</option>`;
      } else {
        sel.innerHTML = '<option value="">— Primero pulsa «Cargar voces» en ElevenLabs —</option>';
      }
      return;
    }
    sel.innerHTML = list.map((v) => {
      const id = String(v.id || '');
      const label = `${v.name || id}${v.category ? ` (${v.category})` : ''}`;
      return `<option value="${esc(id)}" ${id === cur ? 'selected' : ''}>${esc(label)}</option>`;
    }).join('');
    if (!list.some((v) => String(v.id) === cur) && list[0]) sel.value = list[0].id;
    return;
  }

  if (engine === 'piper') {
    const list = TTS_PIPER_VOICES.length ? TTS_PIPER_VOICES : [];
    const cur = sel.value;
    ttsPiperFillSelect(sel, list, cur);
    return;
  }

  if (engine === 'edge') {
    const voices = getEdgeVoiceCatalog().filter((v) => String(v.locale || '').toLowerCase() === lang
      || (lang === 'es' && String(v.locale || '').toLowerCase().startsWith('es-')));
    const list = voices.length ? voices : getEdgeVoiceCatalog();
    const cur = sel.value;
    sel.innerHTML = list.map((v) => `<option value="${esc(v.id)}" ${v.id === cur ? 'selected' : ''}>${esc(v.label)}</option>`).join('');
    if (!list.some((v) => v.id === cur) && list[0]) sel.value = list[0].id;
    return;
  }

  if (engine === 'disney') {
    const voices = getDisneyVoiceCatalog();
    const list = voices.length ? voices : getTikTokVoiceCatalog().filter((v) => /^en[_-]/i.test(v.id));
    const cur = sel.value;
    sel.innerHTML = list.length
      ? list.map((v) => `<option value="${esc(v.id)}" ${v.id === cur ? 'selected' : ''}>${esc(v.label)}</option>`).join('')
      : '<option value="">— Sin voces Disney —</option>';
    if (!list.some((v) => v.id === cur) && list[0]) sel.value = list[0].id;
    return;
  }

  if (engine === 'tiktok') {
    const voices = getTikTokVoiceCatalog().filter((v) => ttsVoiceLangFromId(v.id) === langBase);
    const cur = sel.value;
    sel.innerHTML = voices.length
      ? voices.map((v) => `<option value="${esc(v.id)}" ${v.id === cur ? 'selected' : ''}>${esc(v.label)}</option>`).join('')
      : '<option value="">— Sin voces para este idioma —</option>';
    if (!voices.some((v) => v.id === cur) && voices[0]) sel.value = voices[0].id;
    return;
  }

  const list = ttsVoices.filter((v) => (v.lang || '').toLowerCase().startsWith(langBase));
  const voices = list.length ? list : ttsVoices;
  const cur = sel.value;
  sel.innerHTML = voices.length
    ? voices.map((v) => `<option value="${esc(v.name)}" ${v.name === cur ? 'selected' : ''}>${esc(v.name)}</option>`).join('')
    : '<option value="">— Sin voces —</option>';
  if (!voices.some((v) => v.name === cur) && voices[0]) sel.value = voices[0].name;
}

function renderTtsUserVoices() {
  const body = $('tts-uv-tbody');
  if (!body) return;
  const list = settings?.tts?.userVoices || [];
  if (!list.length) {
    body.innerHTML = '<tr class="tts-uv-empty"><td colspan="5">Sin asignaciones</td></tr>';
    return;
  }
  const voiceCountByUser = new Map();
  for (const uv of list) {
    const k = ttsUvNormId(uv.userId);
    voiceCountByUser.set(k, (voiceCountByUser.get(k) || 0) + 1);
  }
  body.innerHTML = list.map((uv) => {
    const langCell = uv.engine === 'disney'
      ? (uv.translate === false ? 'Español (sin traducir)' : 'Inglés (traduce)')
      : ttsUvLangLabel(uv.lang);
    const editing = ttsUvEditingId && String(uv.id) === String(ttsUvEditingId);
    const multi = (voiceCountByUser.get(ttsUvNormId(uv.userId)) || 0) > 1;
    return `
    <tr data-id="${esc(uv.id)}" class="${editing ? 'is-editing' : ''}${multi ? ' tts-uv-has-multi' : ''}">
      <td><div class="tts-uv-user">${esc(uv.nickname || uv.userId)}${multi ? '<span class="tts-uv-rand-tag" title="Este usuario tiene varias voces: en el chat se elige una al azar">aleatorio</span>' : ''}<small>@${esc(uv.userId)}</small></div></td>
      <td>${esc(ttsEngineLabel(uv.engine))}</td>
      <td>${esc(langCell)}</td>
      <td>${esc(uv.voiceLabel || ttsVoiceLabel(uv.engine, uv.voice, uv.lang))}</td>
      <td class="tts-uv-actions">
        <button type="button" class="tts-uv-test" data-act="test" title="Probar esta voz">▶</button>
        <button type="button" class="tts-uv-edit" data-act="edit" title="Editar voz">✎</button>
        <button type="button" class="tts-uv-del" data-act="del" title="Quitar esta voz">✕</button>
      </td>
    </tr>`;
  }).join('');
  body.querySelectorAll('[data-act="test"]').forEach((btn) => {
    btn.onclick = () => {
      const row = btn.closest('tr');
      const id = row?.dataset?.id;
      if (!id) return;
      const uv = (settings?.tts?.userVoices || []).find((x) => String(x.id) === String(id));
      if (!uv) return;
      // Probar ESTA fila (no aleatorio entre las del usuario).
      ttsSpeakTextForUser('Hola, esta es mi voz asignada', uv.userId, uv.nickname, { force: true, uv });
      toast('Probando voz de @' + (uv.userId || ''), 'ok');
    };
  });
  body.querySelectorAll('[data-act="edit"]').forEach((btn) => {
    btn.onclick = () => {
      const row = btn.closest('tr');
      const id = row?.dataset?.id;
      if (!id) return;
      const uv = (settings?.tts?.userVoices || []).find((x) => String(x.id) === String(id));
      if (uv) loadTtsUserVoiceIntoForm(uv);
    };
  });
  body.querySelectorAll('[data-act="del"]').forEach((btn) => {
    btn.onclick = async () => {
      const row = btn.closest('tr');
      const id = row?.dataset?.id;
      if (!id) return;
      const ok = await askConfirm({ title: 'Quitar voz', message: '¿Eliminar esta asignación de voz?', confirmText: 'Eliminar' });
      if (!ok) return;
      if (ttsUvEditingId && String(id) === String(ttsUvEditingId)) clearTtsUvEditMode();
      settings.tts.userVoices = (settings.tts.userVoices || []).filter((x) => String(x.id) !== String(id));
      try { saveSettingsKeysPatch('tts', { flush: true }); } catch { saveSettings(); }
      renderTtsUserVoices();
      refreshTtsUvUserSelect();
    };
  });
}

function updateTtsUvFormMode() {
  const panel = $('tts-uv-form-panel');
  const btn = $('tts-uv-add');
  const banner = $('tts-uv-edit-banner');
  const title = $('tts-uv-form-title');
  const userFields = $('tts-uv-user-fields');
  const userSel = $('tts-uv-user-sel');
  const manual = $('tts-uv-user-manual');
  const editing = !!ttsUvEditingId;
  if (panel) panel.classList.toggle('is-editing', editing);
  if (btn) btn.textContent = editing ? 'Guardar cambios' : 'Asignar +';
  if (banner) banner.hidden = !editing;
  if (title) title.hidden = editing;
  if (userFields) userFields.hidden = editing;
  if (userSel) userSel.disabled = editing;
  if (manual) {
    manual.readOnly = editing;
    if (!editing) manual.value = '';
  }
}

function clearTtsUvEditMode() {
  ttsUvEditingId = null;
  const userSel = $('tts-uv-user-sel');
  if (userSel) userSel.value = '';
  updateTtsUvFormMode();
  refreshTtsUvUserSelect();
  renderTtsUserVoices();
}

function loadTtsUserVoiceIntoForm(uv) {
  if (!uv) return;
  ttsUvEditingId = uv.id;
  const nickEl = $('tts-uv-edit-nick');
  const handleEl = $('tts-uv-edit-handle');
  if (nickEl) nickEl.textContent = uv.nickname || uv.userId || '—';
  if (handleEl) handleEl.textContent = `@${uv.userId || ''}`;
  const engineEl = $('tts-uv-engine');
  const langEl = $('tts-uv-lang');
  const voiceEl = $('tts-uv-voice');
  const disneyTranslateEl = $('tts-uv-disney-translate');
  if (engineEl) engineEl.value = uv.engine === 'system' ? 'system' : (uv.engine || 'tiktok');
  fillTtsUvLangOptions();
  if (langEl) {
    if (uv.engine === 'disney') langEl.value = uv.translate === false ? 'es' : 'en';
    else if (uv.engine === 'edge') langEl.value = uv.lang || 'es-CO';
    else langEl.value = uv.lang || 'es';
  }
  if (disneyTranslateEl) disneyTranslateEl.checked = uv.translate !== false;
  syncTtsUvDisneyTranslateUI();
  fillTtsUvVoiceOptions();
  if (voiceEl && uv.voice) voiceEl.value = uv.voice;
  updateTtsUvFormMode();
  renderTtsUserVoices();
  $('tts-uv-form-panel')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function addTtsUserVoice() {
  const manual = $('tts-uv-user-manual');
  const userSel = $('tts-uv-user-sel');
  const engineEl = $('tts-uv-engine');
  const langEl = $('tts-uv-lang');
  const voiceEl = $('tts-uv-voice');
  if (!engineEl || !langEl || !voiceEl) return;

  let userId = '';
  let nickname = '';
  let editingEntry = null;
  if (ttsUvEditingId) {
    editingEntry = (settings?.tts?.userVoices || []).find((x) => String(x.id) === String(ttsUvEditingId));
    if (!editingEntry) {
      clearTtsUvEditMode();
      toast('Asignación no encontrada', 'warn');
      return;
    }
    userId = editingEntry.userId;
    nickname = editingEntry.nickname || userId;
  } else {
    userId = String(manual?.value || '').trim().replace(/^@/, '');
    nickname = userId;
    if (!userId && userSel?.value) {
      userId = userSel.value;
      const u = ttsChatUsers.get(ttsUvNormId(userId));
      nickname = u?.nickname || userId;
    }
    userId = userId.replace(/^@/, '');
    if (!userId) {
      toast('Escribe el ID del usuario o elígelo del chat', 'warn');
      return;
    }
  }

  const engineRaw = engineEl.value;
  const engine = engineRaw === 'system' ? 'system' : engineRaw;
  if ((engine === 'tiktok' || engine === 'disney') && !capFeature('tts_tiktok')) {
    toast('Las voces TikTok / Disney no están disponibles en tu plan', 'warn');
    return;
  }
  if (engine === 'elevenlabs') {
    toast('ElevenLabs ya no está en Chat TTS. Elige otra voz.', 'warn');
    return;
  }

  if (engine === 'piper') {
    if (!IS_DESKTOP) {
      toast('Piper solo está en la app de escritorio (.exe).', 'warn');
      return;
    }
  }

  const voice = String(voiceEl.value || '').trim();
  if (!voice) {
    if (engine === 'elevenlabs' && !ttsElVoicesCache.length) {
      toast('Pulsa «Cargar voces» en ElevenLabs y luego elige una voz.', 'warn');
    } else {
      toast('Elige una voz', 'warn');
    }
    return;
  }

  const lang = engine === 'disney' ? 'en'
    : engine === 'elevenlabs' ? 'multi'
    : engine === 'piper' ? 'es'
    : String(langEl.value || 'es');
  const disneyTranslateEl = $('tts-uv-disney-translate');
  const translate = engine === 'disney'
    ? !!(disneyTranslateEl ? disneyTranslateEl.checked : true)
    : engine === 'piper'
      ? (editingEntry ? editingEntry.translate !== false : ttsEnsurePiper().translate !== false)
    : (engine === 'tiktok' && ttsVoiceLangFromId(voice) === 'en');

  if (!settings.tts) settings.tts = {};
  if (!Array.isArray(settings.tts.userVoices)) settings.tts.userVoices = [];

  const key = ttsUvNormId(userId);
  // Editar = actualizar esa fila. Nueva = añadir otra voz al usuario (varias → aleatorio).
  const existing = editingEntry || null;
  const voiceOpt = voiceEl.selectedOptions && voiceEl.selectedOptions[0];
  const entry = {
    id: existing?.id || Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    userId,
    nickname: nickname || userId,
    engine,
    lang: engine === 'edge' ? lang : lang.split('-')[0],
    voice,
    voiceLabel: voiceOpt ? String(voiceOpt.textContent || '').trim() : '',
    translate,
  };

  const wasEdit = !!ttsUvEditingId;
  if (existing) {
    Object.assign(existing, entry);
    toast(`Voz actualizada para @${userId}`, 'ok');
  } else {
    const dup = settings.tts.userVoices.find((x) =>
      ttsUvNormId(x.userId) === key
      && String(x.engine || '') === String(engine)
      && String(x.voice || '') === String(voice));
    if (dup) {
      toast('Ese usuario ya tiene esa misma voz. Elige otra o edítala.', 'warn');
      return;
    }
    settings.tts.userVoices.push(entry);
    const n = settings.tts.userVoices.filter((x) => ttsUvNormId(x.userId) === key).length;
    toast(n > 1
      ? `Voz añadida a @${userId} (${n} voces · aleatorio en chat)`
      : `Voz asignada a @${userId}`, 'ok');
  }

  if (wasEdit) clearTtsUvEditMode();
  else {
    if (manual) manual.value = '';
    if (userSel) userSel.value = '';
    refreshTtsUvUserSelect();
  }
  try { saveSettingsKeysPatch('tts', { flush: true }); } catch { saveSettings(); }
  renderTtsUserVoices();
}

function ttsConfigForUser(userId, nickname, uvOpt) {
  const base = settings?.tts || {};
  const uv = uvOpt !== undefined ? uvOpt : ttsFindUserVoice(userId, nickname);
  if (!uv || uv.engine === 'elevenlabs') return base;
  if (uv.engine === 'piper') {
    return {
      ...base,
      tiktokVoice: '',
      voice: '',
      elevenlabs: { ...(base.elevenlabs || {}), enabled: false },
      piper: {
        enabled: true,
        voiceId: uv.voice || 'es_ES-davefx-medium',
        translate: uv.translate !== false,
      },
    };
  }
  if (uv.engine === 'tiktok' || uv.engine === 'disney' || uv.engine === 'edge') {
    return {
      ...base,
      tiktokVoice: uv.voice,
      tiktokTranslateEs: uv.engine === 'edge' ? false : (uv.translate !== false),
      voice: '',
      elevenlabs: { ...(base.elevenlabs || {}), enabled: false },
      piper: { ...(base.piper || {}), enabled: false },
    };
  }
  return {
    ...base,
    lang: uv.lang || base.lang,
    voice: uv.voice || '',
    tiktokVoice: '',
    piper: { ...(base.piper || {}), enabled: false },
  };
}

function ttsSpeakTextForUser(text, userId, nickname, opts = {}) {
  try { ttsSyncElevenlabsFromDom(); } catch { /* ignore */ }
  try { ttsSyncPiperFromDom(); } catch { /* ignore */ }
  try { ttsSyncVoiceFromDom(); } catch { /* ignore */ }
  try { ttsSyncSlidersFromDom(); } catch { /* ignore */ }
  const phrase = ttsReadableText(String(text || '')).trim();
  if (!phrase) return;
  const force = !!(opts && opts.force);
  if (!ttsAcceptPhrase(phrase, userId || nickname, force)) return;
  // Una sola elección por frase (si hay varias voces, aleatorio aquí; opts.uv fuerza una fila).
  const uvRaw = (opts && opts.uv) ? opts.uv : ttsFindUserVoice(userId, nickname);
  const cfg = ttsConfigForUser(userId, nickname, uvRaw);
  const uv = (uvRaw && uvRaw.engine !== 'elevenlabs') ? uvRaw : null;
  if (uv?.engine === 'system') {
    ttsSpeakSystem(phrase, cfg);
    return;
  }
  if (uv?.engine === 'piper') {
    if (ttsPiperReady(cfg)) { ttsSpeakPiper(phrase, cfg); return; }
    toast('Piper no está listo en este panel (solo .exe).', 'warn');
    ttsSpeakSystem(phrase, settings?.tts || {});
    return;
  }
  // Override de usuario TikTok/Disney/Edge: cfg ya trae esa voz.
  const tkChosen = String(cfg.tiktokVoice || '').trim();
  if (tkChosen) { ttsSpeakTikTok(phrase, { ...cfg, tiktokVoice: tkChosen }); return; }
  const sv = ttsServerVoiceFromSettings(cfg);
  if (sv) { ttsSpeakTikTok(phrase, sv); return; }
  // Sin Edge/TikTok: Piper si está activo; si no, voz del sistema.
  if (!uv && ttsPiperReady(cfg)) { ttsSpeakPiper(phrase, cfg); return; }
  ttsSpeakSystem(phrase, cfg);
}

function addTtsCommand() {
  const tEl = $('tts-cmd-trigger'); const rEl = $('tts-cmd-response');
  let cmd = (tEl?.value || '').trim();
  const resp = (rEl?.value || '').trim();
  if (!cmd || !resp) { toast('Escribe el comando y la respuesta.', 'warn'); return; }
  if (!cmd.startsWith('!') && !cmd.startsWith('/') && !cmd.startsWith('.')) cmd = '!' + cmd;
  if (!settings.tts) settings.tts = {};
  if (!Array.isArray(settings.tts.commands)) settings.tts.commands = [];
  settings.tts.commands.push({ id: Date.now().toString(36), command: cmd, response: resp, enabled: true });
  saveTtsCommands();
  renderTtsCommands();
  if (tEl) tEl.value = ''; if (rEl) rEl.value = '';
  toast('Comando añadido.');
}

function updateTtsSummary() {
  const t = settings?.tts || {};
  const el = $('tts-summary');
  if (!el) return;
  if (!t.enabled) { el.textContent = 'El Chat TTS está desactivado.'; return; }
  let who = 'de todos los usuarios';
  if (t.allowGiftPass) {
    const gp = t.giftPass || {};
    const gName = gp.giftName || (gp.giftId ? ('#' + gp.giftId) : '');
    const mins = Math.max(1, Number(gp.minutes) || 5);
    who = gName
      ? `solo quien envíe ${gName} (acceso ${mins} min por cada uno)`
      : `solo quien envíe el regalo configurado (acceso ${mins} min — elige un regalo)`;
  } else if (t.allowWhitelist) {
    const n = Array.isArray(t.whitelist) ? t.whitelist.filter(Boolean).length : 0;
    who = n ? `solo de la lista blanca (${n} ${n === 1 ? 'usuario' : 'usuarios'})` : 'solo de la lista blanca (vacía: nadie)';
  } else if (t.allowAll === false) {
    const roles = [];
    if (t.allowFollowers) roles.push('seguidores');
    if (t.allowSubs) roles.push('suscriptores');
    if (t.allowMods) roles.push('moderadores');
    if (t.allowTeam) roles.push('miembros del equipo');
    who = roles.length ? 'de ' + roles.join(', ') : 'de nadie (elige al menos un grupo)';
  }
  let banNote = '';
  if (t.useBlacklist) {
    const bn = Array.isArray(t.blacklist) ? t.blacklist.filter(Boolean).length : 0;
    banNote = bn
      ? ` Lista negra: ${bn} ${bn === 1 ? 'usuario bloqueado' : 'usuarios bloqueados'}.`
      : ' Lista negra activa (vacía).';
  }
  const trig = { all: 'cualquier comentario', dot: 'comentarios que empiezan con punto', slash: 'comentarios que empiezan con /', command: `comentarios con "${t.command || '!tts'}"` }[t.trigger || 'all'];
  const money = t.charge ? `Cobra ${t.cost} monedas por mensaje.` : 'El uso es gratuito.';
  const elVoice = ttsPiperReady(t)
    ? ` Voz: Piper (${ttsVoiceLabel('piper', t.piper?.voiceId || '')}).`
    : '';
  const requireLvl = !t.allowWhitelist && !t.allowGiftPass && !!(t.requireMinLevel ?? (Number(t.minMemberLevel || 0) > 0));
  const minLvl = Number(t.minMemberLevel || 0);
  if (requireLvl && minLvl > 0) {
    el.textContent = `Se leerá ${trig} solo de miembros del club de fans nivel ${minLvl} o más (Nv.${minLvl}+).${banNote} ${money}${elVoice}`;
    return;
  }
  el.textContent = `Se leerá ${trig} ${who}.${banNote} ${money}${elVoice}`;
}

/* ---- Filtros de moderación ---- */
const PROFANITY = ['puta', 'puto', 'mierda', 'pendejo', 'cabron', 'cabrón', 'verga', 'coño', 'joto', 'culero', 'chinga', 'perra', 'zorra', 'maricon', 'maricón', 'pinche', 'fuck', 'shit', 'bitch', 'asshole'];
// Detecta CUALQUIER emoji/pictograma para poder quitarlos del nombre y leer solo el texto.
// Usa \p{Extended_Pictographic} (cubre ⭐ ⌚ ➡️ ❤ ☀ y casi todos los símbolos), más los
// modificadores de tono de piel, banderas (regional indicators), el combinador de teclas
// (1️⃣), el selector de variación (FE0F) y el "zero width joiner" (200D) de emojis combinados.
const EMOJI_RE = /[\p{Extended_Pictographic}\p{Emoji_Modifier}\u{1F1E6}-\u{1F1FF}\u{20E3}\u{FE0F}\u{200D}]/gu;

// Emojis que el TTS nunca lee (ni como palabra ni en voz): se quitan siempre.
const TTS_SILENT_EMOJIS = ['👹'];

function stripSilentEmojis(text) {
  let s = String(text || '');
  for (const emo of TTS_SILENT_EMOJIS) s = s.split(emo).join('');
  return s;
}

