const ACC_OBS_LABELS = {
  scene: 'Escena',
  toggleSource: 'Toggle fuente',
  showSource: 'Mostrar fuente',
  hideSource: 'Ocultar fuente',
  startRecord: 'Iniciar grabación',
  stopRecord: 'Detener grabación',
  startStream: 'Iniciar stream',
  stopStream: 'Detener stream',
};
function accShortText(s, max = 26) {
  const t = String(s || '');
  return t.length > max ? `${t.slice(0, max - 1)}…` : t;
}
function accChipHTML(ico, text, extraClass = '') {
  const icoPart = (typeof ico === 'string' && ico.includes('<'))
    ? ico
    : `<span class="acc-chip-ico" aria-hidden="true">${ico}</span>`;
  return `<span class="acc-chip ${extraClass}">${icoPart}<span class="acc-chip-txt">${text}</span></span>`;
}
function accEventChipHTML(a) {
  const ev = a.event || 'gift-any';
  if (ev === 'gift' && (a.giftName || a.giftId)) {
    const g = a.giftId ? giftCatalogById.get(String(a.giftId))
      : giftCatalogFindByName(a.giftName);
    const img = g?.image || a.giftImage || '';
    const ico = img
      ? `<span class="acc-chip-ico"><img class="acc-chip-img" src="${esc(img)}" alt=""></span>`
      : '🎁';
    return accChipHTML(ico, esc(a.giftName || g?.name || 'Regalo'), 'ev');
  }
  if (ev === 'gift-any' && (a.rangeMin || a.rangeMax)) {
    return accChipHTML(trigIconChip('gift-any') || '💎', esc(`${a.rangeMin || 0}${a.rangeMax ? ` – ${a.rangeMax}` : '+'}`), 'ev');
  }
  if (ev === 'like') {
    const n = Math.max(1, Number(a.likeN ?? a.likeMin) || 1);
    if (n > 1) return accChipHTML(trigIconChip('like') || '❤️', esc(`Cada ${n} likes`), 'ev');
  }
  if (ev === 'likeGlobal') {
    const n = Math.max(1, Number(a.likeN ?? a.likeGoal) || 100);
    return accChipHTML(trigIconChip('likeGlobal') || '❤️', esc(`Cada ${n} likes`), 'ev');
  }
  if (isEmoteEvent(ev) && a.emoteId) {
    const delay = Number(a.eventDelay) > 0 ? ` · ${a.eventDelay}s` : '';
    const pack = ev === 'emoteFan' ? 'Fan Club' : 'Super Fan';
    return accChipHTML(trigIconChip(ev) || '😀', esc(`${pack} ${a.emoteId}`) + delay, 'ev');
  }
  if (ev === 'chatAny') {
    const delay = Number(a.eventDelay) > 0 ? ` · ${a.eventDelay}s` : '';
    return accChipHTML(trigIconChip('chatAny') || '💬', esc('Cualquier comentario') + delay, 'ev');
  }
  if (ev === 'chatCommand' && a.command) {
    const delay = Number(a.eventDelay) > 0 ? ` · ${a.eventDelay}s` : '';
    return accChipHTML(trigIconChip('chatCommand') || '💬', esc(a.command) + delay, 'ev');
  }
  if (ev === 'join') return accChipHTML(trigIconChip('join') || '🚪', 'Join', 'ev');
  if (ev === 'userPoints') {
    const n = Math.max(1, Number(a.pointsCost) || 1);
    let cmd = String(a.pointsCommand || '!usar').trim().toLowerCase();
    if (!cmd.startsWith('!')) cmd = '!' + cmd.replace(/^!+/, '');
    return accChipHTML('🪙', esc(cmd + ' · ' + n + ' puntos'), 'ev');
  }
  if (ev === 'levelUp' && a.level) return accChipHTML(trigIconChip('levelUp') || '⬆️', esc(`Nivel ${a.level}`), 'ev');
  const meta = ACC_EVENT_META[ev] || { ico: '⚡', label: ev };
  return accChipHTML(meta.ico, esc(meta.label), 'ev');
}
function accAudienceChipHTML(a) {
  const aud = String(a?.audience || 'all');
  if (!aud || aud === 'all') return '';
  const labels = {
    followers: 'Followers',
    subscribers: 'Subscribers',
    mods: 'Moderadores',
    topGifters: 'Top Gifters',
    user: a.audienceUser ? `@${a.audienceUser}` : 'Usuario',
  };
  return accChipHTML('👤', esc(labels[aud] || aud), 'aud');
}
function accShowEventChip(a) {
  if (a.image) return false;
  const ev = a.event || 'gift-any';
  if (ev === 'gift' && (a.giftId || a.giftName)) {
    const g = a.giftId ? giftCatalogById.get(String(a.giftId))
      : giftCatalogFindByName(a.giftName);
    if (g?.image || a.giftImage) return false;
  }
  return true;
}
function accObsChipText(ob) {
  const t = ob?.type || 'scene';
  const lbl = ACC_OBS_LABELS[t] || t;
  const needsSource = t === 'toggleSource' || t === 'showSource' || t === 'hideSource';
  if (needsSource && ob?.scene && ob?.source) return `${lbl}: ${ob.scene} → ${ob.source}`;
  const detail = ob?.source || ob?.scene || '';
  return detail ? `${lbl}: ${detail}` : lbl;
}
function accOutputChipsHTML(a) {
  const out = [];
  if (a.keys) {
    let txt = esc(a.keys);
    if (a.keyRepeatOn && (parseInt(a.keyRepeat, 10) || 1) > 1) txt += ` ×${parseInt(a.keyRepeat, 10) || 1}`;
    if (a.keyStaggerOn) txt += ` · 1×1 ${Math.max(50, parseInt(a.keyStaggerMs, 10) || 300)}ms`;
    out.push(accChipHTML('⌨️', txt, 'key'));
  }
  if (a.webhookCmd?.on && a.webhookCmd?.url) {
    const method = String(a.webhookCmd.method || 'GET').toUpperCase();
    let whTxt = `${method} ${accShortText(a.webhookCmd.url, 22)}`;
    if (a.webhookCmd.staggerOn) whTxt += ` · 1×1 ${Math.max(50, parseInt(a.webhookCmd.staggerMs, 10) || 300)}ms`;
    out.push(accChipHTML('🪝', esc(whTxt), 'wh'));
  }
  if (a.obsCmd?.on) out.push(accChipHTML('📡', esc(accObsChipText(a.obsCmd)), 'obs'));
  if (a.sbCmd?.on && a.sbCmd?.action) {
    let sbTxt = a.sbCmd.action;
    if (a.sbCmd.staggerOn) sbTxt += ` · 1×1 ${Math.max(50, parseInt(a.sbCmd.staggerMs, 10) || 300)}ms`;
    out.push(accChipHTML('🤖', esc(sbTxt), 'sb'));
  }
  if (a.mcCmd?.on && String(a.mcCmd.cmd || '').trim()) {
    const n = Math.max(1, parseInt(a.mcCmd.count, 10) || 1);
    const ms = Math.max(0, parseInt(a.mcCmd.delayEach, 10) || 0);
    let mcTxt = accShortText(a.mcCmd.cmd, 22);
    if (n > 1) mcTxt += ` ×${n}`;
    if (ms > 0) mcTxt += ` · ${ms}ms`;
    out.push(accChipHTML('🟩', esc(mcTxt), 'mc'));
  }
  if (a.gameCmd?.on && a.gameCmd.game && Array.isArray(a.gameCmd.cmds) && a.gameCmd.cmds.length) {
    const spec = ACC_MINIGAME_GAMES[a.gameCmd.game];
    const labels = a.gameCmd.cmds.map((c) => c.label || c.thing || c.cmd).filter(Boolean);
    const txt = `${spec?.label || a.gameCmd.game}${labels.length ? ': ' + labels.slice(0, 2).join(', ') : ''}${labels.length > 2 ? '…' : ''}`;
    out.push(accChipHTML('🎮', esc(accShortText(txt, 28)), 'game'));
  }
  if (a.mediaShow?.on && a.mediaShow?.url) {
    const name = a.mediaShow.name || accShortText(String(a.mediaShow.url).split('/').pop(), 18);
    const scr = a.mediaShow.screen ? ` · P${a.mediaShow.screen}` : '';
    out.push(accChipHTML('🎬', esc(name + scr), 'media'));
  }
  if (a.marioSpawn?.npcId != null) {
    const qty = a.marioSpawn.quantity > 1 ? ` ×${a.marioSpawn.quantity}` : '';
    out.push(accChipHTML('🍄', esc(`#${a.marioSpawn.npcId}${qty}`), 'mario'));
  }
  if (a.sound) out.push(accChipHTML('🔊', esc(accShortText(a.soundName || 'Audio', 20)), 'sound'));
  if (a.ttsCmd?.on && String(a.ttsCmd.text || '').trim()) {
    out.push(accChipHTML('🗣️', esc(accShortText(a.ttsCmd.text, 22)), 'tts'));
  }
  if (a.alertText?.on && String(a.alertText.text || '').trim()) {
    out.push(accChipHTML('⚡', esc(accShortText(a.alertText.text, 22)), 'alert'));
  }
  if (a.animShow?.on && (a.animShow?.url || (Array.isArray(a.animShow.clips) && a.animShow.clips.length))) {
    const n = Array.isArray(a.animShow.clips) ? a.animShow.clips.filter((c) => c && c.url).length : 0;
    const label = n > 1
      ? `${n} videos · al azar`
      : (a.animShow.name || 'Videos AI');
    out.push(accChipHTML('✨', esc(accShortText(label, 22) + (a.animShow.screen ? ` · P${a.animShow.screen}` : '')), 'anim'));
  }
  if (a.gifShow?.on && a.gifShow?.url) {
    out.push(accChipHTML('🖼️', esc(accShortText(a.gifShow.name || 'GIF', 20)), 'gif'));
  }
  if (a.levelUpShow?.on) {
    const n = Math.max(0, Number(a.levelUpShow.level) || 0);
    const scr = Math.max(1, Number(a.levelUpShow.screen) || 1);
    out.push(accChipHTML('⬆️', esc((n > 0 ? `Nivel ${n}` : 'Subió de nivel') + ` · P${scr}`), 'levelup'));
  }
  if (!out.length) out.push(accChipHTML('⌨️', 'Sin salida', 'empty'));
  return out.join('');
}
// Miniatura de la tarjeta: imagen subida si la hay; si no, el icono del regalo (para
// eventos de regalo) o un emoji acorde al evento (likes, seguidor, super fan…).
const ACC_THUMB_EMOJI = {
  'gift-all': '🎁', 'gift-any': '🎁', gift: '🎁', like: '❤️', likeGlobal: '❤️',
  share: '🔁', subscribe: '⭐', fan: '💛', superFan: '🌟', superFanJoin: '🌟', follow: '➕', join: '🚪',
  levelUp: '⬆️', emote: '😀', emoteFan: '😀', chatAny: '💬', chatCommand: '💬', firstMessage: '🙋', streamdeck: '🎛️',
  battleStart: '🟢', battleLast10: '⏱', battleEnd: '🔴',
  battleWin: '🏆', battleLose: '💔',
};
function accIconSmall(a) {
  const ev = a.event || 'gift-any';
  if (a.image) return `<img class="sa-ic-mini" src="${esc(a.image)}" loading="lazy" decoding="async">`;
  if (ev === 'gift' && (a.giftId || a.giftName)) {
    const g = a.giftId ? giftCatalogById.get(String(a.giftId))
      : giftCatalogFindByName(a.giftName);
    const img = g?.image || a.giftImage || '';
    if (img) return `<img class="sa-ic-mini" src="${esc(img)}" loading="lazy" decoding="async">`;
  }
  if (isEmoteEvent(ev) && a.emoteId) {
    const img = a.emoteImage || emoteImgById(a.emoteId);
    if (img) return `<img class="sa-ic-mini" src="${esc(img)}" loading="lazy" decoding="async">`;
  }
  return `<span class="sa-ic-mini-emoji">${ACC_THUMB_EMOJI[ev] || '⚡'}</span>`;
}

function accThumbHTML(a) {
  if (a.image) return `<div class="acc-thumb" style="background-image:url('${esc(a.image)}')"></div>`;
  const ev = a.event || 'gift-any';
  if (ev === 'gift' && (a.giftId || a.giftName)) {
    const g = a.giftId ? giftCatalogById.get(String(a.giftId))
      : giftCatalogFindByName(a.giftName);
    const img = g?.image || a.giftImage || '';
    if (img) return `<div class="acc-thumb"><img class="acc-thumb-img" src="${esc(img)}" onerror="this.parentElement.textContent='🎁'"></div>`;
  }
  if (isEmoteEvent(ev) && a.emoteId) {
    const img = a.emoteImage || emoteImgById(a.emoteId);
    if (img) return `<div class="acc-thumb"><img class="acc-thumb-img" src="${esc(img)}" onerror="this.parentElement.textContent='😀'"></div>`;
  }
  return `<div class="acc-thumb">${ACC_THUMB_EMOJI[ev] || '⚡'}</div>`;
}

function getAccViewMode() {
  return getMapViewMode('lc_acc_view');
}
function setAccViewMode(mode) {
  setMapViewMode('lc_acc_view', mode);
  syncAccViewToggleUI();
  renderAcciones();
}
function syncAccViewToggleUI() {
  const mode = getAccViewMode();
  applyMapGridClass($('acc-grid'), mode);
  document.querySelectorAll('[data-map-view-for="lc_acc_view"]').forEach((btn) => {
    btn.classList.toggle('is-active', btn.getAttribute('data-map-view') === mode);
  });
  // compat botones viejos
  document.querySelectorAll('.acc-view-btn[data-acc-view]').forEach((btn) => {
    btn.classList.toggle('is-active', btn.getAttribute('data-acc-view') === mode);
  });
}
function getAccSearchQuery() {
  return String($('acc-search')?.value || '').trim().toLowerCase();
}
function accMatchesSearch(a, q) {
  return entityMatchesSearch(a, q, ['webhookCmd', 'sbCmd']);
}
function accTriggerVisual(a) {
  const base = giftTriggerVisualFromItem(a, '⚡');
  if (a?.event && !(a.giftId || a.giftName || a.image)) {
    const meta = (typeof ACC_EVENT_META !== 'undefined' && ACC_EVENT_META[a.event]) || null;
    if (meta) {
      base.emoji = meta.ico || base.emoji;
      base.label = meta.label || base.label;
    }
  }
  return base;
}
