const ACC_ROW_ICON = {
  play: '<img class="acc-ico-img" src="/img/acc-row/play.png" alt="">',
  edit: '<img class="acc-ico-img" src="/img/acc-row/edit.png" alt="">',
  dup: '<img class="acc-ico-img" src="/img/acc-row/dup.png" alt="">',
  trash: '<img class="acc-ico-img" src="/img/acc-row/trash.png" alt="">',
  up: '<img class="acc-ico-img" src="/img/acc-row/up.png" alt="">',
  down: '<img class="acc-ico-img" src="/img/acc-row/down.png" alt="">',
};
function accEnsureEventsList() {
  if (!settings) return [];
  if (!Array.isArray(settings.actionEvents)) settings.actionEvents = [];
  return settings.actionEvents;
}
function accPlainDesc(a) {
  const tmp = document.createElement('div');
  tmp.innerHTML = accOutputChipsHTML(a);
  return (tmp.textContent || '').replace(/\s+/g, ' ').trim() || '—';
}
function accActionScreens(a) {
  const out = [];
  const push = (bag) => {
    if (!(bag && bag.on && bag.url)) return;
    const n = Math.max(1, Math.min(SCREEN_COUNT, Number(bag.screen) || 1));
    if (!out.includes(n)) out.push(n);
  };
  push(a && a.mediaShow);
  push(a && a.animShow);
  push(a && a.gifShow);
  if (a && a.levelUpShow && a.levelUpShow.on) {
    const n = Math.max(1, Math.min(SCREEN_COUNT, Number(a.levelUpShow.screen) || 1));
    if (!out.includes(n)) out.push(n);
  }
  return out;
}
function accScreenLabel(a) {
  const screens = accActionScreens(a);
  if (!screens.length) return 'N/A';
  return screens.map((n) => 'Screen ' + n).join(', ');
}
function accDurationLabel(a) {
  const ms = a?.mediaShow;
  const g = Number(ms?.gifSec);
  if (Number.isFinite(g) && g > 0) return String(Math.round(g));
  const n = Number(ms?.durationSec);
  if (Number.isFinite(n) && n > 0) return String(Math.round(n));
  return '5';
}
function accPagerHTML(page, pages) {
  const n = Math.max(1, pages);
  const cur = Math.max(1, Math.min(n, page));
  let html = `<button type="button" data-page="${cur - 1}" ${cur <= 1 ? 'disabled' : ''} aria-label="Anterior">&lt;</button>`;
  for (let i = 1; i <= n; i++) {
    html += `<button type="button" data-page="${i}" class="${i === cur ? 'is-on' : ''}" ${i === cur ? 'disabled' : ''}>${i}</button>`;
  }
  html += `<button type="button" data-page="${cur + 1}" ${cur >= n ? 'disabled' : ''} aria-label="Siguiente">&gt;</button>`;
  return html;
}
function accBindPager(el, page, pages, setPage, render) {
  if (!el) return;
  el.innerHTML = accPagerHTML(page, pages);
  el.querySelectorAll('[data-page]').forEach((btn) => {
    btn.onclick = () => {
      const n = Number(btn.getAttribute('data-page')) || 1;
      setPage(Math.max(1, Math.min(pages, n)));
      render();
    };
  });
}
function accSlicePage(list, page) {
  const pages = Math.max(1, Math.ceil(list.length / ACC_PAGE_SIZE) || 1);
  const p = Math.max(1, Math.min(pages, page));
  const start = (p - 1) * ACC_PAGE_SIZE;
  return { page: p, pages, rows: list.slice(start, start + ACC_PAGE_SIZE) };
}
function accActionNameById(id) {
  const want = String(id || '');
  const a = ((settings && settings.actions) || []).find((x) => x && String(x.id) === want);
  return a ? (a.name || 'Acción') : '';
}
function accEventActionsLabel(ev) {
  const all = (ev.actionIds || []).map(accActionNameById).filter(Boolean);
  const rand = (ev.randomActionIds || []).map(accActionNameById).filter(Boolean).map((n) => `RANDOM(${n})`);
  const parts = all.concat(rand);
  return parts.length ? parts.join(', ') : '—';
}
function accEventTriggerLabel(ev) {
  const key = String(ev?.event || '').trim();
  if (!key) return 'Sin disparo';
  if (key === 'gift' && (ev.giftName || ev.giftId)) {
    const g = ev.giftId ? giftCatalogById.get(String(ev.giftId))
      : giftCatalogFindByName(ev.giftName);
    const name = ev.giftName || g?.name || ev.giftId;
    const coins = g?.diamond_count || g?.diamondCount || g?.coins || ev.minDiamonds;
    return coins ? `${name} - ${coins} coins` : String(name);
  }
  if (isEmoteEvent(key)) {
    const pack = key === 'emoteFan' ? 'Fan Club' : 'Super Fan Club';
    return ev.emoteId ? `${pack} ${ev.emoteId}` : ((ACC_EVENT_META[key] && ACC_EVENT_META[key].label) || pack);
  }
  if (key === 'like') {
    const n = Math.max(1, Number(ev.likeN ?? ev.likeMin) || 1);
    return n > 1 ? `Cada ${n} likes (usuario)` : 'Likes (taps)';
  }
  if (key === 'likeGlobal') {
    const n = Math.max(1, Number(ev.likeN ?? ev.likeGoal) || 100);
    return `Cada ${n} likes globales`;
  }
  if (key === 'chatCommand' && ev.command) return ev.command;
  if (key === 'levelUp') {
    const n = Math.max(0, Number(ev.level) || 0);
    return n > 0 ? `Subió de nivel (${n})` : 'Subió de nivel de miembro';
  }
  const meta = ACC_EVENT_META[key];
  return (meta && meta.label) || key;
}
function accEventTriggerCell(ev) {
  const vis = giftTriggerVisualFromItem(ev, ACC_THUMB_EMOJI[ev?.event] || '⚡');
  const label = accEventTriggerLabel(ev);
  let face = '';
  if (vis.img) {
    face = `<img class="acc-ev-trig-img" src="${esc(vis.img)}" alt="" loading="lazy" decoding="async">`;
  } else {
    const src = TRIG_ICON[ev?.event || ''] || '';
    face = src
      ? `<img class="acc-ev-trig-img" src="${esc(src)}" alt="" loading="lazy" decoding="async">`
      : `<span class="acc-ev-trig-emoji">${vis.emoji || '⚡'}</span>`;
  }
  return `<span class="acc-ev-trig">${face}<span class="acc-ev-trig-lbl">${esc(label)}</span></span>`;
}
function moveAccEvent(id, dir) {
  const list = accEnsureEventsList();
  const i = list.findIndex((x) => x && sameEntityId(x.id, id));
  const j = i + dir;
  if (i < 0 || j < 0 || j >= list.length) return;
  const tmp = list[i];
  list[i] = list[j];
  list[j] = tmp;
  try { markMcPresetDirty('acciones'); } catch {}
  saveSettingsKeysPatch('actionEvents');
  renderAccEventos();
}
function accAudienceLabel(ev) {
  const aud = String(ev?.audience || 'all');
  if (aud === 'user' && ev.audienceUser) return ev.audienceUser;
  if (aud === 'followers') return 'Seguidores';
  if (aud === 'subscribers') return 'Suscriptores';
  if (aud === 'mods') return 'Moderadores';
  if (aud === 'topGifters') return 'Top Gifters';
  return 'Todos';
}
function accEvMatchesSearch(ev, q) {
  if (!q) return true;
  if (!ev) return false;
  const blob = [
    accEventTriggerLabel(ev),
    accEventActionsLabel(ev),
    accAudienceLabel(ev),
    ev.event,
    ev.giftName,
    ev.command,
  ].join(' ').toLowerCase();
  return blob.includes(q);
}
function accPruneEventsForDeletedActions(deletedIds) {
  const drop = new Set((deletedIds || []).map(String));
  if (!drop.size) return;
  const list = accEnsureEventsList();
  for (const ev of list) {
    if (!ev) continue;
    ev.actionIds = (ev.actionIds || []).filter((id) => !drop.has(String(id)));
    ev.randomActionIds = (ev.randomActionIds || []).filter((id) => !drop.has(String(id)));
  }
}

function renderAcciones() {
  renderAccScreenUrls();
  const grid = $('acc-grid');
  if (!grid) return;
  const list = ((settings && settings.actions) || []).filter((a) => a);
  for (const id of [...accSelected]) if (!list.find((a) => sameEntityId(a.id, id))) accSelected.delete(id);
  updateAccSelCount();
  const q = getAccSearchQuery();
  const filtered = list.filter((a) => accMatchesSearch(a, q));
  if (!filtered.length) {
    grid.innerHTML = `<tr><td colspan="7" class="acc-int-empty">${list.length ? 'Ninguna acción coincide con la búsqueda.' : 'Aún no tienes acciones. Pulsa Crear nueva acción.'}</td></tr>`;
    accBindPager($('acc-pager'), 1, 1, (n) => { accPage = n; }, renderAcciones);
    renderAccEventos();
    return;
  }
  const sliced = accSlicePage(filtered, accPage);
  accPage = sliced.page;
  grid.innerHTML = sliced.rows.map((a) => `
    <tr data-id="${esc(a.id)}" class="${a.enabled === false ? 'is-off' : ''}">
      <td class="acc-int-check"><input type="checkbox" class="sa-sel" ${setHasEntityId(accSelected, a.id) ? 'checked' : ''}></td>
      <td class="acc-int-ico">
        <button type="button" class="acc-try" title="Probar">${ACC_ROW_ICON.play}</button>
        <button type="button" class="acc-edit" title="Editar">${ACC_ROW_ICON.edit}</button>
        <button type="button" class="acc-dup" title="Duplicar">${ACC_ROW_ICON.dup}</button>
        <button type="button" class="acc-del-one" title="Eliminar">${ACC_ROW_ICON.trash}</button>
      </td>
      <td class="acc-int-on"><input type="checkbox" class="acc-on" title="Si está marcado, la acción se puede disparar" ${a.enabled === false ? '' : 'checked'}></td>
      <td>${esc(a.name || 'Acción')}</td>
      <td>${esc(accScreenLabel(a))}</td>
      <td>${esc(accDurationLabel(a))}</td>
      <td class="acc-int-desc">${esc(accPlainDesc(a))}</td>
    </tr>`).join('');

  grid.querySelectorAll('tr[data-id]').forEach((row) => {
    const id = row.dataset.id;
    const a = list.find((x) => x && String(x.id) === String(id));
    if (!a) return;
    const selCb = row.querySelector('.sa-sel');
    if (selCb) selCb.onchange = (e) => { e.target.checked ? accSelected.add(id) : accSelected.delete(id); updateAccSelCount(); };
    const onCb = row.querySelector('.acc-on');
    if (onCb) onCb.onchange = (e) => {
      e.stopPropagation();
      a.enabled = !!e.target.checked;
      row.classList.toggle('is-off', a.enabled === false);
      try { markMcPresetDirty('acciones'); } catch {}
      saveSettingsKeysPatch('actions');
    };
    const editBtn = row.querySelector('.acc-edit');
    if (editBtn) editBtn.onclick = () => openAccModal(a);
    const tryBtn = row.querySelector('.acc-try');
    if (tryBtn) tryBtn.onclick = () => testAccionFromRow(a);
    const dupBtn = row.querySelector('.acc-dup');
    if (dupBtn) dupBtn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (!ensureCanAdd('actions', 'actions', 'acciones')) return;
      duplicateSettingsItem('actions', id, {
        idPrefix: 'act',
        render: renderAcciones,
        save: (copy) => {
          try { accLinkCopiedActionToEvents(id, copy && copy.id); } catch {}
          try { markMcPresetDirty('acciones'); } catch {}
          saveSettingsKeysPatch('actions', 'actionEvents');
          syncDesktopWebhookSettings();
        },
        toastMsg: 'Acción duplicada.',
      });
    };
    const delBtn = row.querySelector('.acc-del-one');
    if (delBtn) delBtn.onclick = async () => {
      const ok = await askConfirm({ title: 'Eliminar acción', message: `¿Eliminar "${a.name || 'Acción'}"?` });
      if (!ok) return;
      settings.actions = (settings.actions || []).filter((x) => String(x.id) !== String(id));
      accSelected.delete(id);
      accPruneEventsForDeletedActions([id]);
      try { markMcPresetDirty('acciones'); } catch {}
      try { markAllowEmptyAcciones(); } catch {}
      try { saveGamePresetState('acciones', { flush: true, skipErSync: true }); }
      catch { saveSettingsKeysPatch('actions', 'actionEvents', { flush: true }); }
      renderAcciones();
    };
  });
  const selAll = $('acc-sel-all');
  if (selAll) selAll.checked = sliced.rows.length > 0 && sliced.rows.every((a) => setHasEntityId(accSelected, a.id));
  accBindPager($('acc-pager'), sliced.page, sliced.pages, (n) => { accPage = n; }, renderAcciones);
  renderAccEventos();
}

function renderAccEventos() {
  const grid = $('acc-ev-grid');
  if (!grid) return;
  const list = accEnsureEventsList().filter((ev) => ev);
  for (const id of [...accEvSelected]) if (!list.find((a) => a && sameEntityId(a.id, id))) accEvSelected.delete(id);
  updateAccEvSelCount();
  const q = String($('acc-ev-search')?.value || '').trim().toLowerCase();
  const filtered = list.filter((ev) => accEvMatchesSearch(ev, q));
  if (!filtered.length) {
    grid.innerHTML = `<tr><td colspan="7" class="acc-int-empty">${list.length ? 'Ningún evento coincide con la búsqueda.' : 'Aún no tienes eventos. Crea una acción y luego un evento que la dispare.'}</td></tr>`;
    accBindPager($('acc-ev-pager'), 1, 1, (n) => { accEvPage = n; }, renderAccEventos);
    return;
  }
  const sliced = accSlicePage(filtered, accEvPage);
  accEvPage = sliced.page;
  const full = accEnsureEventsList();
  grid.innerHTML = sliced.rows.map((ev) => {
    const idx = full.findIndex((x) => x && sameEntityId(x.id, ev.id));
    const canUp = idx > 0;
    const canDown = idx >= 0 && idx < full.length - 1;
    return `
    <tr data-id="${esc(ev.id)}" class="${ev.enabled === false ? 'is-off' : ''}">
      <td class="acc-int-check"><input type="checkbox" class="acc-ev-sel" ${setHasEntityId(accEvSelected, ev.id) ? 'checked' : ''}></td>
      <td class="acc-int-ico">
        <button type="button" class="acc-ev-up" title="Subir" ${canUp ? '' : 'disabled'}>${ACC_ROW_ICON.up}</button>
        <button type="button" class="acc-ev-down" title="Bajar" ${canDown ? '' : 'disabled'}>${ACC_ROW_ICON.down}</button>
        <button type="button" class="acc-ev-edit" title="Editar">${ACC_ROW_ICON.edit}</button>
        <button type="button" class="acc-ev-del-one" title="Eliminar">${ACC_ROW_ICON.trash}</button>
      </td>
      <td class="acc-int-on"><input type="checkbox" class="acc-ev-on" title="Si está marcado, el evento se dispara" ${ev.enabled === false ? '' : 'checked'}></td>
      <td class="acc-int-type">${ev.event === 'streamdeck' ? 'Stream Deck' : 'TikTok'}</td>
      <td>${esc(accAudienceLabel(ev))}</td>
      <td class="acc-ev-trig-td">${accEventTriggerCell(ev)}</td>
      <td>${esc(accEventActionsLabel(ev))}</td>
    </tr>`;
  }).join('');

  grid.querySelectorAll('tr[data-id]').forEach((row) => {
    const id = row.dataset.id;
    const ev = list.find((x) => x && String(x.id) === String(id));
    if (!ev) return;
    const selCb = row.querySelector('.acc-ev-sel');
    if (selCb) selCb.onchange = (e) => { e.target.checked ? accEvSelected.add(id) : accEvSelected.delete(id); updateAccEvSelCount(); };
    const onCb = row.querySelector('.acc-ev-on');
    if (onCb) onCb.onchange = (e) => {
      e.stopPropagation();
      ev.enabled = !!e.target.checked;
      row.classList.toggle('is-off', ev.enabled === false);
      try { markMcPresetDirty('acciones'); } catch {}
      saveSettingsKeysPatch('actionEvents');
    };
    const editBtn = row.querySelector('.acc-ev-edit');
    if (editBtn) editBtn.onclick = () => openAccEventModal(ev);
    const up = row.querySelector('.acc-ev-up');
    const down = row.querySelector('.acc-ev-down');
    if (up) up.onclick = () => moveAccEvent(id, -1);
    if (down) down.onclick = () => moveAccEvent(id, 1);
    const delBtn = row.querySelector('.acc-ev-del-one');
    if (delBtn) delBtn.onclick = async () => {
      const ok = await askConfirm({ title: 'Eliminar evento', message: '¿Eliminar este evento?' });
      if (!ok) return;
      settings.actionEvents = accEnsureEventsList().filter((x) => String(x.id) !== String(id));
      accEvSelected.delete(id);
      try { markMcPresetDirty('acciones'); } catch {}
      try { markAllowEmptyAcciones(); } catch {}
      try { saveGamePresetState('acciones', { flush: true, skipErSync: true }); }
      catch { saveSettingsKeysPatch('actionEvents', 'actions', { flush: true }); }
      renderAccEventos();
    };
  });
  const selAll = $('acc-ev-sel-all');
  if (selAll) selAll.checked = sliced.rows.length > 0 && sliced.rows.every((ev) => setHasEntityId(accEvSelected, ev.id));
  accBindPager($('acc-ev-pager'), sliced.page, sliced.pages, (n) => { accEvPage = n; }, renderAccEventos);
}

function updateAccSelCount() {
  const c = $('acc-selcount');
  if (c) c.textContent = accSelected.size;
  const del = $('acc-del');
  if (del) del.disabled = accSelected.size === 0;
}

function updateAccEvSelCount() {
  const c = $('acc-ev-selcount');
  if (c) c.textContent = accEvSelected.size;
  const del = $('acc-ev-del');
  if (del) del.disabled = accEvSelected.size === 0;
}

function accBind(id, fn, ev = 'onclick') {
  const el = $(id);
  if (!el) return false;
  if (ev === 'onchange') el.onchange = fn;
  else if (ev === 'oninput') el.oninput = fn;
  else el.onclick = fn;
  return true;
}

function syncAccKeyRepeatUI() {
  const keysOn = $('acc-keys-on') && $('acc-keys-on').checked;
  if ($('acc-keyrepeat-on-row')) $('acc-keyrepeat-on-row').hidden = !keysOn;
  const repeatOn = keysOn && $('acc-keyrepeat-on') && $('acc-keyrepeat-on').checked;
  if ($('acc-keyrepeat-wrap')) $('acc-keyrepeat-wrap').hidden = !repeatOn;
  if ($('acc-keystagger-on-row')) $('acc-keystagger-on-row').hidden = !keysOn;
  const staggerOn = keysOn && $('acc-keystagger-on') && $('acc-keystagger-on').checked;
  if ($('acc-keystagger-wrap')) $('acc-keystagger-wrap').hidden = !staggerOn;
}

function syncAccWhStaggerUI() {
  const on = !!$('acc-wh-stagger-on')?.checked;
  if ($('acc-wh-stagger-wrap')) $('acc-wh-stagger-wrap').hidden = !on;
}

function syncAccSbStaggerUI() {
  const on = !!$('acc-sb-stagger-on')?.checked;
  if ($('acc-sb-stagger-wrap')) $('acc-sb-stagger-wrap').hidden = !on;
}

function parseTikfinitySpawnUrlMeta(url) {
  const u = String(url || '');
  if (!/\/spawn\b/i.test(u)) return null;
  const idM = u.match(/[?&](?:id|npcId)=(\d+)/i);
  if (!idM) return null;
  const qM = u.match(/[?&](?:quantity|count)=(\d+)/i);
  return { npcId: Number(idM[1]), quantity: qM ? Math.max(1, parseInt(qM[1], 10) || 1) : 1 };
}

function migrateAccionesSpawnWebhooks(actions) {
  if (!Array.isArray(actions)) return false;
  let changed = false;
  for (const a of actions) {
    if (a._spawnWebhookMigrated) continue;
    const meta = parseTikfinitySpawnUrlMeta(a?.webhookCmd?.url);
    if (a.marioSpawn?.npcId == null && meta && !a.webhookCmd?.on) {
      a.marioSpawn = meta;
      changed = true;
    }
    a._spawnWebhookMigrated = true;
  }
  return changed;
}

function accLegacyTriggerOf(a) {
  const ev = String(a && a.event || '').trim();
  if (ev === 'none') return '';
  if (!ev) return 'gift-any';
  return ev;
}
function accLegacyNormDelay(spec, ev) {
  if (spec && spec.eventDelay != null && spec.eventDelay !== '') return Math.max(0, parseInt(spec.eventDelay, 10) || 0);
  if (ev === 'follow' || ev === 'share' || ev === 'emote' || ev === 'emoteFan') return 30;
  return 0;
}
function accLegacyEventKey(spec) {
  const ev = accLegacyTriggerOf(spec);
  if (!ev) return '';
  const aud = String(spec.audience || 'all').trim() || 'all';
  const giftEv = ev === 'gift' || ev === 'gift-any' || ev === 'gift-all';
  return JSON.stringify({
    e: ev,
    aud,
    au: aud === 'user' ? String(spec.audienceUser || '').replace(/^@/, '').trim().toLowerCase() : '',
    r0: +spec.rangeMin || 0,
    r1: +spec.rangeMax || 0,
    gid: String(spec.giftId || '').trim(),
    gn: ev === 'gift' ? String(spec.giftName || '').trim().toLowerCase() : '',
    md: +spec.minDiamonds || 0,
    lm: +spec.likeMin || 1,
    lg: +spec.likeGoal || 100,
    eid: String(spec.emoteId || '').trim(),
    cmd: ev === 'chatCommand' ? String(spec.command || '').trim().toLowerCase() : '',
    usr: (ev === 'chatCommand' || ev === 'firstMessage') ? String(spec.user || '').replace(/^@/, '').trim().toLowerCase() : '',
    cm: ev === 'chatCommand' && !!spec.cmdMods,
    cs: ev === 'chatCommand' && !!spec.cmdSuperfans,
    cf: ev === 'chatCommand' && !!spec.cmdFans,
    d: accLegacyNormDelay(spec, ev),
    gd: Math.max(0, parseInt(spec.eventGlobalDelay, 10) || 0),
    ci: giftEv ? spec.comboInstant !== false : false,
    lv: ev === 'levelUp' ? Math.max(0, Number(spec.level) || 0) : 0,
  });
}
function accLegacyEventIdFromKey(key) {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return 'acev_leg_' + (h >>> 0).toString(36);
}
function accLegacyEventFromAction(a, key) {
  const ev = accLegacyTriggerOf(a);
  const aud = String(a.audience || 'all').trim() || 'all';
  const giftEv = ev === 'gift' || ev === 'gift-any' || ev === 'gift-all';
  return {
    id: accLegacyEventIdFromKey(key),
    event: ev,
    audience: aud,
    audienceUser: aud === 'user' ? String(a.audienceUser || '').replace(/^@/, '').trim() : '',
    rangeMin: +a.rangeMin || 0,
    rangeMax: +a.rangeMax || 0,
    giftId: a.giftId || '',
    giftName: a.giftName || '',
    giftImage: a.giftImage || '',
    minDiamonds: +a.minDiamonds || 0,
    likeMin: +a.likeMin || 1,
    likeGoal: +a.likeGoal || 100,
    emoteId: a.emoteId || '',
    command: ev === 'chatCommand' ? String(a.command || '').trim() : '',
    user: (ev === 'chatCommand' || ev === 'firstMessage') ? String(a.user || '').replace(/^@/, '').trim() : '',
    eventDelay: accLegacyNormDelay(a, ev),
    eventGlobalDelay: Math.max(0, parseInt(a.eventGlobalDelay, 10) || 0),
    cmdMods: ev === 'chatCommand' && !!a.cmdMods,
    cmdSuperfans: ev === 'chatCommand' && !!a.cmdSuperfans,
    cmdFans: ev === 'chatCommand' && !!a.cmdFans,
    comboInstant: giftEv ? a.comboInstant !== false : false,
    level: ev === 'levelUp' ? Math.max(0, Number(a.level) || 0) : 0,
    enabled: true,
    actionIds: [],
    randomActionIds: [],
  };
}

function accActionLevelUpEvent(actionId) {
  const id = String(actionId || '');
  if (!id) return null;
  return accEnsureEventsList().find((ev) => {
    if (!ev || ev.event !== 'levelUp') return false;
    const all = [].concat(ev.actionIds || [], ev.randomActionIds || []).map(String);
    return all.includes(id);
  }) || null;
}
function accPruneEmptyActionEvents() {
  return false;
}
function accSyncLevelUpEventForAction(actionId, on, level) {
  const id = String(actionId || '');
  if (!id) return;
  const wantLevel = Math.max(0, Number(level) || 0);
  const list = accEnsureEventsList();
  const unlink = () => {
    for (const ev of list) {
      if (!ev || ev.event !== 'levelUp') continue;
      ev.actionIds = (ev.actionIds || []).filter((x) => String(x) !== id);
      ev.randomActionIds = (ev.randomActionIds || []).filter((x) => String(x) !== id);
    }
  };
  if (!on) {
    unlink();
    accPruneEmptyActionEvents();
    return;
  }
  unlink();
  let ev = accEnsureEventsList().find((x) => x && x.event === 'levelUp' && (Math.max(0, Number(x.level) || 0) === wantLevel));
  if (!ev) {
    ev = {
      id: 'acev_lv_' + id,
      event: 'levelUp',
      enabled: true,
      audience: 'all',
      audienceUser: '',
      level: wantLevel,
      actionIds: [id],
      randomActionIds: [],
    };
    accEnsureEventsList().push(ev);
  } else {
    if (!Array.isArray(ev.actionIds)) ev.actionIds = [];
    if (!ev.actionIds.some((x) => String(x) === id)) ev.actionIds.push(id);
  }
  accPruneEmptyActionEvents();
}

function accLinkCopiedActionToEvents(srcId, copyId) {
  const from = String(srcId || '');
  const to = String(copyId || '');
  if (!from || !to || from === to) return false;
  let changed = false;
  for (const ev of accEnsureEventsList()) {
    if (!ev) continue;
    if (!Array.isArray(ev.actionIds)) ev.actionIds = [];
    if (!Array.isArray(ev.randomActionIds)) ev.randomActionIds = [];
    if (ev.actionIds.some((id) => String(id) === from) && !ev.actionIds.some((id) => String(id) === to)) {
      ev.actionIds.push(to);
      changed = true;
    }
    if (ev.randomActionIds.some((id) => String(id) === from) && !ev.randomActionIds.some((id) => String(id) === to)) {
      ev.randomActionIds.push(to);
      changed = true;
    }
  }
  return changed;
}
function migrateAccionesLegacyEventsBag(bag, opts) {
  if (!bag || typeof bag !== 'object') return false;
  const actions = Array.isArray(bag.actions) ? bag.actions : [];
  if (!Array.isArray(bag.actionEvents)) bag.actionEvents = [];
  const events = bag.actionEvents;
  const linked = new Set();
  for (const ev of events) {
    if (!ev) continue;
    for (const id of [].concat(ev.actionIds || [], ev.randomActionIds || [])) {
      if (id) linked.add(String(id));
    }
  }
  let changed = false;
  if (opts && opts.noCreate) {
    for (const a of actions) {
      if (!a || !a.id) continue;
      if (linked.has(String(a.id)) && a.event !== 'none') {
        a.event = 'none';
        changed = true;
      }
    }
    return changed;
  }
  const groups = new Map();
  for (const a of actions) {
    if (!a || !a.id) continue;
    if (!accLegacyTriggerOf(a)) continue;
    const id = String(a.id);
    if (linked.has(id)) {
      if (a.event !== 'none') { a.event = 'none'; changed = true; }
      continue;
    }
    const key = accLegacyEventKey(a);
    if (!key) continue;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(a);
  }
  for (const [key, list] of groups) {
    const stableId = accLegacyEventIdFromKey(key);
    let evObj = events.find((ev) => ev && ev.id === stableId)
      || events.find((ev) => ev && accLegacyEventKey(ev) === key);
    if (!evObj) {
      evObj = accLegacyEventFromAction(list[0], key);
      evObj.enabled = list.some((a) => a && a.enabled !== false);
      events.push(evObj);
      changed = true;
    }
    if (!Array.isArray(evObj.actionIds)) evObj.actionIds = [];
    if (!Array.isArray(evObj.randomActionIds)) evObj.randomActionIds = [];
    const have = new Set([].concat(evObj.actionIds, evObj.randomActionIds).map(String));
    for (const a of list) {
      const id = String(a.id);
      if (!have.has(id)) {
        evObj.actionIds.push(id);
        have.add(id);
        changed = true;
      }
      if (a.event !== 'none') { a.event = 'none'; changed = true; }
    }
  }
  return changed;
}
function repairAccionesEventsBag(bag) {
  if (!bag || typeof bag !== 'object') return false;
  const actions = Array.isArray(bag.actions) ? bag.actions : [];
  const byId = new Map(actions.filter((a) => a && a.id).map((a) => [String(a.id), a]));
  let changed = false;
  for (const ev of (bag.actionEvents || [])) {
    if (!ev) continue;
    if (ev.event === 'firstMessage' && !String(ev.user || '').trim()) {
      const ids = [].concat(ev.actionIds || [], ev.randomActionIds || []);
      const from = ids.map((id) => byId.get(String(id))).find((a) => a && String(a.user || '').trim());
      if (from) {
        ev.user = String(from.user || '').replace(/^@/, '').trim();
        changed = true;
      }
    }
    if (ev.event === 'like') {
      const n = Math.max(1, parseInt(ev.likeN ?? ev.likeMin, 10) || 1);
      if (Number(ev.likeN) !== n || Number(ev.likeMin) !== n) {
        ev.likeN = n;
        ev.likeMin = n;
        changed = true;
      }
    }
    if (ev.event === 'likeGlobal') {
      const n = Math.max(1, parseInt(ev.likeN ?? ev.likeGoal ?? ev.likeMin, 10) || 100);
      if (Number(ev.likeN) !== n) {
        ev.likeN = n;
        changed = true;
      }
    }
  }
  return changed;
}
function migrateAccionesLegacyEvents(cfg) {
  if (!cfg || typeof cfg !== 'object') return false;
  const ix = cfg.mcPresetBanks && cfg.mcPresetBanks.acciones;
  const noCreate = !!(ix && typeof ix === 'object' && (Array.isArray(ix.presets) || ix.general));
  let changed = migrateAccionesLegacyEventsBag(cfg, { noCreate });
  const bank = cfg.mcPresetBanks && cfg.mcPresetBanks.acciones;
  if (bank && Array.isArray(bank.presets)) {
    for (const p of bank.presets) {
      if (migrateAccionesLegacyEventsBag(p, { noCreate })) changed = true;
      if (repairAccionesEventsBag(p)) changed = true;
    }
  }
  if (bank && bank.general && typeof bank.general === 'object') {
    if (migrateAccionesLegacyEventsBag(bank.general, { noCreate })) changed = true;
    if (repairAccionesEventsBag(bank.general)) changed = true;
  }
  if (repairAccionesEventsBag(cfg)) changed = true;
  return changed;
}

function tikfinityTypeToEvent(type) {
  if (type === 'gift') return 'gift';
  if (type === 'likes-person') return 'like';
  if (type === 'likes-total' || type === 'likes-global') return 'likeGlobal';
  if (type === 'follow') return 'follow';
  if (type === 'share') return 'share';
  if (type === 'subscribe') return 'subscribe';
  return null;
}

function tikfinityWebhookActionName(trig) {
  const gift = String(trig?.giftName || '').trim().toLowerCase();
  const clean = (s) => String(s || '').trim().replace(/^Gift\s+/i, '').trim();
  const candidates = [trig?.functionName, trig?.name, trig?.webhook?.name]
    .map(clean)
    .filter(Boolean);
  for (const c of candidates) {
    if (!gift || c.toLowerCase() !== gift) return c;
  }
  return candidates[0] || 'Acción TikFinity';
}

