function accMgPlaceOpenMenu() {
  const menu = document.querySelector('#acc-mg-editor .acc-mg-menu:not([hidden])');
  const btn = document.querySelector('#acc-mg-editor .acc-mg-pick-btn.is-open');
  if (!menu || !btn) return;
  const boxEl = document.querySelector('#accModal .acc-modal-body')
    || document.querySelector('#accModal .acc-modal-shell')
    || $('accModal');
  if (!boxEl) return;
  const br = btn.getBoundingClientRect();
  const box = boxEl.getBoundingClientRect();
  const gap = 8;
  const spaceBelow = Math.max(0, box.bottom - br.bottom - gap);
  const spaceAbove = Math.max(0, br.top - box.top - gap);
  const openUp = spaceAbove > spaceBelow && spaceBelow < 180;
  const avail = Math.floor(openUp ? spaceAbove : spaceBelow);
  menu.classList.toggle('is-up', openUp);
  menu.style.maxHeight = `${Math.max(1, Math.min(320, avail))}px`;
}
