  if (spec.kind === 'keys') {
    toast('Roblox se dispara con Teclas en Acciones Generales.', 'warn');
    return;
  }
  accMgState.game = game;
  accMgState.cmds = [accMgBlankCmd()];
  if (thumb && !accMgCoverSrc(game)) { /* cover from thumb img already in grid */ }
  accMgSetView();
  await accMgEnsureCatalog(game);
