function bindAccMiniGames() {
  const body = $('acc-fold-games-body');
  if (!body || body.dataset.mgBound === '1') return;
  body.dataset.mgBound = '1';
  body.addEventListener('click', (e) => {
    const thumb = e.target.closest('.acc-tf-thumb[data-game]');
    if (thumb && body.contains(thumb)) {
      e.preventDefault();
      accMgSelectGame(thumb.dataset.game, thumb);
      return;
    }
    const close = e.target.closest('#acc-mg-close');
    if (close) { accMgReset(); return; }
    const add = e.target.closest('#acc-mg-add');
    if (add) {
      accMgSyncFromDom();
      if ((accMgState.cmds || []).length >= ACC_MG_MAX) return;
      accMgState.cmds.push(accMgBlankCmd());
      accMgRenderCmds();
      const last = $('acc-mg-cmds')?.querySelector('.acc-mg-cmd:last-of-type');
      try { last?.scrollIntoView({ block: 'nearest' }); } catch {}
      return;
    }
    const del = e.target.closest('[data-mg="del"]');
    if (del) {
      accMgSyncFromDom();
      const i = Number(del.dataset.i);
      if (accMgState.cmds.length <= 1) return;
      accMgState.cmds.splice(i, 1);
      accMgRenderCmds();
      return;
    }
    const open = e.target.closest('[data-mg="open"]');
    if (open) {
      const i = Number(open.dataset.i);
      const menu = open.parentElement?.querySelector('.acc-mg-menu');
      const was = menu && !menu.hidden;
      accMgCloseMenus();
      if (menu && !was) {
        menu.hidden = false;
        open.classList.add('is-open');
        accMgPlaceOpenMenu();
        accMgEnsureCatalog(accMgState.game).then(() => {
          accMgFillOpts(i, '');
          accMgPlaceOpenMenu();
          menu.querySelector('.acc-mg-search')?.focus();
        });
      }
      return;
    }
    const pick = e.target.closest('[data-mg="pick"]');
    if (pick) {
      accMgSyncFromDom();
      const i = Number(pick.dataset.i);
      const packed = accMgPackPick(accMgState.game, pick.dataset.id);
      const prev = accMgState.cmds[i] || accMgBlankCmd();
      accMgState.cmds[i] = {
        ...prev,
        ...packed,
        count: accMgCountVal(prev.count),
        interval: Math.max(0, parseInt(prev.interval, 10) || 0),
        delay: Math.max(0, parseInt(prev.delay, 10) || 0),
      };
      accMgCloseMenus();
      accMgRenderCmds();
    }
  });
  body.addEventListener('input', (e) => {
    const el = e.target;
    const i = Number(el.dataset.i);
    const cmd = accMgState.cmds[i];
    if (!cmd) return;
    if (el.dataset.mg === 'search') { accMgFillOpts(i, el.value); accMgPlaceOpenMenu(); return; }
    if (el.dataset.mg === 'delay') cmd.delay = Math.max(0, parseInt(el.value, 10) || 0);
    if (el.dataset.mg === 'count') cmd.count = accMgCountVal(el.value);
    if (el.dataset.mg === 'interval') cmd.interval = Math.max(0, Math.min(10000, parseInt(el.value, 10) || 0));
    if (el.dataset.mg === 'cmd') {
      cmd.cmd = String(el.value || '').trim();
      cmd.thing = cmd.cmd;
      cmd.label = cmd.cmd;
    }
  });
  document.addEventListener('click', (e) => {
    if (!e.target.closest('#acc-mg-editor .acc-mg-pick')) accMgCloseMenus();
  });
  const modalBody = document.querySelector('#accModal .acc-modal-body');
  if (modalBody && modalBody.dataset.mgScroll !== '1') {
    modalBody.dataset.mgScroll = '1';
    modalBody.addEventListener('scroll', () => {
      accMgPlaceOpenMenu();
      accMsPlaceOpenMenu();
    }, { passive: true });
  }
}
