  const pitch = accTtsSliderToFactor($('acc-tts-pitch')?.value);
  if ($('acc-tts-rateval')) $('acc-tts-rateval').textContent = rate.toFixed(2) + '×';
  if ($('acc-tts-pitchval')) $('acc-tts-pitchval').textContent = pitch.toFixed(2);
