function accModalOutputError() {
  const keys = $('acc-keys-on')?.checked ? $('acc-keys').value.trim() : '';
  const webhookCmd = readAccWebhookCmd();
  const obsCmd = readAccObsCmd();
  const sbCmd = readAccSbCmd();
  const mcCmd = readAccMcCmd();
  const gameCmd = readAccGameCmd();
  const mediaShow = readAccMediaShow();
  const ttsCmd = readAccTtsCmd();
  const alertText = readAccAlertText();
  const animShow = readAccAnimShow();
  const gifShow = readAccGifShow();
  const hasOutput = (webhookCmd.on && webhookCmd.url) || obsCmd.on || (sbCmd.on && sbCmd.action);
  const hasMc = !!(mcCmd.on && mcCmd.cmd);
  const hasGame = !!(gameCmd.on && gameCmd.cmds && gameCmd.cmds.some((c) => typeof accMgHasOutput === 'function' ? accMgHasOutput(c) : (c && String(c.thing || c.cmd || '').trim())));
  const hasMedia = mediaShow.on && accMediaHasFile(mediaShow);
  const hasTts = !!(ttsCmd.on && ttsCmd.text);
  const hasAlert = !!(alertText.on && alertText.text);
  const hasAnim = !!(animShow.on && (animShow.url || (Array.isArray(animShow.clips) && animShow.clips.length)))
    || !!(gifShow.on && gifShow.url);
  const hasSound = !!( $('acc-soundon')?.checked && accPendingSound?.url);
  if (ttsCmd.on && !ttsCmd.text) return 'Escribe el texto que debe leer la voz.';
  if ($('acc-soundon')?.checked && !accPendingSound?.url) return 'Elige o sube un audio.';
  if (alertText.on && !alertText.text) return 'Escribe el texto de la alerta.';
  if (animShow.on && !(animShow.url || (Array.isArray(animShow.clips) && animShow.clips.length))) return 'Elige un video de Videos AI o súbelo desde el PC.';
  if (gifShow.on && !gifShow.url) return 'Elige un video de Videos AI o súbelo desde el PC.';
  if (mcCmd.on && !mcCmd.cmd) return 'Escribe el comando de Minecraft.';
  if (accMgState.game && !hasGame) return 'Elige una opción del mini-juego o quita el juego con la X.';
  if (obsCmd.on) {
    const ot = obsCmd.type || 'scene';
    if (ot === 'scene' && !obsCmd.scene) return 'Escribe el nombre exacto de la escena en OBS.';
    if ((ot === 'toggleSource' || ot === 'showSource' || ot === 'hideSource') && !obsCmd.source) {
      return 'Escribe el nombre exacto de la fuente en OBS.';
    }
    if ((ot === 'toggleSource' || ot === 'showSource' || ot === 'hideSource') && !obsCmd.scene) {
      return 'Escribe la escena donde está la fuente (ej. LIVE BATALLAS).';
    }
  }
  if (!keys && !hasOutput && !hasMc && !hasGame && !hasMedia && !hasTts && !hasAlert && !hasAnim && !hasSound && !$('acc-levelup-on')?.checked) {
    return 'Elige un mini-juego, una tecla/clic, un texto TTS, una alerta, una animación, un medio, un sonido, un comando de Minecraft o activa una salida (WebHook, OBS o Streamer.bot).';
  }
  if (mediaShow.on && !accMediaHasFile(mediaShow)) return 'Sube un archivo IMG, GIF o VIDEO.';
  return '';
}

