  if (view) view.classList.toggle('is-sp-locked', locked);
  if (wrap) wrap.classList.toggle('is-locked', locked);
  if (lock) lock.hidden = !locked;
  if (input) {
    input.readOnly = locked;
    input.tabIndex = locked ? -1 : 0;
  }
  // Con settings: applyLiveCoinSongUI ya hace lock + persist OFF + sync checkbox/ping.
  // Sin settings (boot temprano): solo el candado visual.
