/** Sin Premium: no se puede activar el puente LiveCoinSong (igual que Spotify). */
function applyLiveCoinSongLock(locked) {
  const card = document.getElementById('sp-lcs-card');
  const el = document.getElementById('sp-lcs-enabled');
  const lock = document.getElementById('sp-lcs-premium-lock');
  const isLocked = locked === undefined ? (IS_DESKTOP && !spotifyUnlocked()) : !!locked;
  if (card) card.classList.toggle('is-lcs-locked', isLocked);
  if (lock) lock.hidden = !isLocked;
  if (el) {
    el.disabled = isLocked;
    if (isLocked) el.checked = false;
  }
  // Persistir OFF aunque el checkbox ya se haya desmarcado en UI
  // (si no, settings.livecoinsong.enabled queda true y el estado/ping mienten).
  if (isLocked && settings?.livecoinsong?.enabled === true) {
    try {
      settings.livecoinsong = { ...liveCoinSongSettings(), enabled: false };
      saveSettings();
    } catch {}
  }
  if (isLocked) {
    stopLiveCoinSongPing();
    paintLiveCoinSongStatus();
  }
}
